insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('1b14d7ff-693c-544d-8584-0bcee506238e','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Bilangan sampai 20','belajar-matematika-kelas-1-unit-1',1,'A','Bab 1','dasar','draft',8,'{"summary":"Bilangan sampai 20. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan bilangan sampai 20 dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas I","url":"https://buku.kemendikdasmen.go.id/katalog/Matematika-untuk-SDMI-Kelas-I","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan bilangan sampai 20 dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar bilangan sampai 20. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Bilangan. Menyatakan banyak atau urutan. Contoh: Ada 12 biji di mangkuk"},{"type":"text","body":"2. Nilai tempat. Nilai angka bergantung posisinya. Contoh: Pada 24, angka 2 bernilai 20"},{"type":"text","body":"3. Membandingkan. Menentukan lebih banyak, lebih sedikit, atau sama. Contoh: 8 lebih banyak daripada 5"},{"type":"text","body":"4. Mengurutkan. Menyusun bilangan menurut nilainya. Contoh: 3, 5, 9 berurutan dari kecil"},{"type":"text","body":"5. Memeriksa hasil. Menghitung kembali dengan cara lain. Contoh: Cocokkan 10 biji dengan dua kelompok lima"},{"type":"text","body":"Contoh dan penalaran: Tunjuk setiap benda sekali sambil menyebut satu bilangan. Pada dua kelompok berisi 2 dan 2 benda, urutan hitungnya 1, 2, 3, 4. Bilangan terakhir menyatakan jumlah seluruhnya: empat."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Susun sampai 20 benda kecil yang aman. Hitung satu per satu sambil menunjuk setiap benda."},{"type":"text","body":"Rangkuman: Bilangan: Menyatakan banyak atau urutan; Nilai tempat: Nilai angka bergantung posisinya; Membandingkan: Menentukan lebih banyak, lebih sedikit, atau sama; Mengurutkan: Menyusun bilangan menurut nilainya; Memeriksa hasil: Menghitung kembali dengan cara lain."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('72e7c15f-79e1-5d94-9f31-7f62d744df32','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Membandingkan dan mengurutkan','belajar-matematika-kelas-1-unit-2',1,'A','Bab 2','dasar','draft',8,'{"summary":"Membandingkan dan mengurutkan. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan membandingkan dan mengurutkan dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas I","url":"https://buku.kemendikdasmen.go.id/katalog/Matematika-untuk-SDMI-Kelas-I","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan membandingkan dan mengurutkan dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar membandingkan dan mengurutkan. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Bilangan. Menyatakan banyak atau urutan. Contoh: Ada 12 biji di mangkuk"},{"type":"text","body":"2. Nilai tempat. Nilai angka bergantung posisinya. Contoh: Pada 24, angka 2 bernilai 20"},{"type":"text","body":"3. Membandingkan. Menentukan lebih banyak, lebih sedikit, atau sama. Contoh: 8 lebih banyak daripada 5"},{"type":"text","body":"4. Mengurutkan. Menyusun bilangan menurut nilainya. Contoh: 3, 5, 9 berurutan dari kecil"},{"type":"text","body":"5. Memeriksa hasil. Menghitung kembali dengan cara lain. Contoh: Cocokkan 10 biji dengan dua kelompok lima"},{"type":"text","body":"Contoh dan penalaran: Pasangkan benda dari dua kelompok satu-satu. Jika kelompok pertama masih memiliki benda yang belum mendapat pasangan, kelompok itu lebih banyak. Pada 4 dan 6 benda, empat pasangan terbentuk dan dua benda tersisa di kelompok enam, sehingga 4 lebih kecil daripada 6."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat dua baris benda. Pasangkan satu-satu untuk membandingkan jumlahnya."},{"type":"text","body":"Rangkuman: Bilangan: Menyatakan banyak atau urutan; Nilai tempat: Nilai angka bergantung posisinya; Membandingkan: Menentukan lebih banyak, lebih sedikit, atau sama; Mengurutkan: Menyusun bilangan menurut nilainya; Memeriksa hasil: Menghitung kembali dengan cara lain."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('1de6b616-f86c-5494-8384-a49c711fc4cd','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Penjumlahan dengan benda','belajar-matematika-kelas-1-unit-3',1,'A','Bab 3','dasar','draft',8,'{"summary":"Penjumlahan dengan benda. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan penjumlahan dengan benda dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas I","url":"https://buku.kemendikdasmen.go.id/katalog/Matematika-untuk-SDMI-Kelas-I","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan penjumlahan dengan benda dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar penjumlahan dengan benda. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Penjumlahan. Menggabungkan dua banyak benda. Contoh: 3 apel dan 2 apel menjadi 5 apel"},{"type":"text","body":"2. Pengurangan. Mengambil atau mencari selisih. Contoh: 7 biji dikurangi 2 tersisa 5"},{"type":"text","body":"3. Perkalian. Menghitung kelompok sama banyak. Contoh: 3 kelompok berisi 4 benda berjumlah 12"},{"type":"text","body":"4. Pembagian. Membagi rata atau menentukan banyak kelompok. Contoh: 12 benda dibagi untuk 3 anak, masing-masing 4"},{"type":"text","body":"5. Kalimat matematika. Lambang yang menyatakan hubungan bilangan. Contoh: 3 + 2 = 5 menyatakan hasil penjumlahan"},{"type":"text","body":"Contoh dan penalaran: Penjumlahan menggabungkan dua kelompok. Untuk 4 + 3, mulai dari empat lalu maju tiga langkah: lima, enam, tujuh. Hasilnya tujuh; periksa dengan menghitung semua benda."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Gunakan dua warna benda untuk membuat penjumlahan yang hasilnya sampai 20."},{"type":"text","body":"Rangkuman: Penjumlahan: Menggabungkan dua banyak benda; Pengurangan: Mengambil atau mencari selisih; Perkalian: Menghitung kelompok sama banyak; Pembagian: Membagi rata atau menentukan banyak kelompok; Kalimat matematika: Lambang yang menyatakan hubungan bilangan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('2ef09359-9206-510a-9fae-bfd2b7202314','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Pengurangan dengan benda','belajar-matematika-kelas-1-unit-4',1,'A','Bab 4','sedang','draft',8,'{"summary":"Pengurangan dengan benda. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan pengurangan dengan benda dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas I","url":"https://buku.kemendikdasmen.go.id/katalog/Matematika-untuk-SDMI-Kelas-I","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan pengurangan dengan benda dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar pengurangan dengan benda. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Penjumlahan. Menggabungkan dua banyak benda. Contoh: 3 apel dan 2 apel menjadi 5 apel"},{"type":"text","body":"2. Pengurangan. Mengambil atau mencari selisih. Contoh: 7 biji dikurangi 2 tersisa 5"},{"type":"text","body":"3. Perkalian. Menghitung kelompok sama banyak. Contoh: 3 kelompok berisi 4 benda berjumlah 12"},{"type":"text","body":"4. Pembagian. Membagi rata atau menentukan banyak kelompok. Contoh: 12 benda dibagi untuk 3 anak, masing-masing 4"},{"type":"text","body":"5. Kalimat matematika. Lambang yang menyatakan hubungan bilangan. Contoh: 3 + 2 = 5 menyatakan hasil penjumlahan"},{"type":"text","body":"Contoh dan penalaran: Pengurangan dapat diperagakan dengan mengambil benda. Dari 6 benda, ambil 2. Benda yang tetap tinggal berjumlah 4, sehingga 6 − 2 = 4. Jangan menghitung benda yang sudah diambil sebagai sisa."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Siapkan 10 benda. Ambil sebagian, lalu hitung yang masih tinggal."},{"type":"text","body":"Rangkuman: Penjumlahan: Menggabungkan dua banyak benda; Pengurangan: Mengambil atau mencari selisih; Perkalian: Menghitung kelompok sama banyak; Pembagian: Membagi rata atau menentukan banyak kelompok; Kalimat matematika: Lambang yang menyatakan hubungan bilangan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('967ff1b3-ff22-5d1d-8819-dd6ea5da152a','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Pola dan bentuk di sekitar','belajar-matematika-kelas-1-unit-5',1,'A','Bab 5','sedang','draft',8,'{"summary":"Pola dan bentuk di sekitar. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan pola dan bentuk di sekitar dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas I","url":"https://buku.kemendikdasmen.go.id/katalog/Matematika-untuk-SDMI-Kelas-I","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan pola dan bentuk di sekitar dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar pola dan bentuk di sekitar. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Pola berulang. Susunan yang mengulang bagian tetap. Contoh: Merah-biru lalu merah-biru lagi"},{"type":"text","body":"2. Sisi. Ruas pembatas pada bangun datar bersisi lurus. Contoh: Persegi memiliki empat sisi"},{"type":"text","body":"3. Sudut. Daerah pertemuan dua sinar atau sisi. Contoh: Pojok buku membentuk sudut"},{"type":"text","body":"4. Segitiga. Bangun datar dengan tiga sisi lurus. Contoh: Potongan kertas bersisi tiga"},{"type":"text","body":"5. Persegi. Bangun datar bersisi empat sama panjang dengan empat sudut siku-siku. Contoh: Satu petak pada papan catur"},{"type":"text","body":"Contoh dan penalaran: Cari bagian pola yang berulang, bukan hanya warna paling akhir. Pada pola kuning-hijau-kuning-hijau, satu bagiannya kuning-hijau. Bangun juga dapat dikenali dari sisinya: segitiga memiliki tiga sisi lurus, sedangkan persegi memiliki empat sisi sama panjang dan empat sudut siku-siku."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Susun pola merah-biru-merah-biru dengan kertas. Cari bentuk segitiga dan persegi di sekitar."},{"type":"text","body":"Rangkuman: Pola berulang: Susunan yang mengulang bagian tetap; Sisi: Ruas pembatas pada bangun datar bersisi lurus; Sudut: Daerah pertemuan dua sinar atau sisi; Segitiga: Bangun datar dengan tiga sisi lurus; Persegi: Bangun datar bersisi empat sama panjang dengan empat sudut siku-siku."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('f4a44dac-a07e-5382-8e9d-41535cd775f1','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Panjang dan waktu sederhana','belajar-matematika-kelas-1-unit-6',1,'A','Bab 6','sedang','draft',8,'{"summary":"Panjang dan waktu sederhana. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan panjang dan waktu sederhana dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas I","url":"https://buku.kemendikdasmen.go.id/katalog/Matematika-untuk-SDMI-Kelas-I","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan panjang dan waktu sederhana dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar panjang dan waktu sederhana. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Panjang. Ukuran dari satu ujung ke ujung lain. Contoh: Pita diukur dari tanda nol penggaris"},{"type":"text","body":"2. Massa. Besaran yang diukur menggunakan neraca atau timbangan. Contoh: Massa tepung dicatat dalam gram"},{"type":"text","body":"3. Durasi. Lama suatu kegiatan berlangsung. Contoh: Belajar dari pukul 8 sampai 9 selama satu jam"},{"type":"text","body":"4. Satuan. Acuan ukuran yang disepakati. Contoh: Sentimeter merupakan satuan panjang"},{"type":"text","body":"5. Konversi. Menyatakan ukuran sama dengan satuan berbeda. Contoh: 1 meter sama panjang dengan 100 sentimeter"},{"type":"text","body":"Contoh dan penalaran: Pengukuran panjang harus dimulai dari titik yang sama, dengan satuan sama besar tanpa celah atau tumpang tindih. Bila satu pita sepanjang 4 balok dan pita lain 6 balok, pita kedua lebih panjang dua balok. Urutan waktu dijelaskan dengan sebelum, sesudah, dan selama."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Bandingkan panjang dua pensil dari ujung yang sejajar. Ceritakan kegiatan sebelum dan sesudah sarapan."},{"type":"text","body":"Rangkuman: Panjang: Ukuran dari satu ujung ke ujung lain; Massa: Besaran yang diukur menggunakan neraca atau timbangan; Durasi: Lama suatu kegiatan berlangsung; Satuan: Acuan ukuran yang disepakati; Konversi: Menyatakan ukuran sama dengan satuan berbeda."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('44b56032-3283-598b-9f9d-324583163427','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Bilangan dan nilai tempat sampai 100','belajar-matematika-kelas-2-unit-1',2,'A','Bab 1','dasar','draft',8,'{"summary":"Bilangan dan nilai tempat sampai 100. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan bilangan dan nilai tempat sampai 100 dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas II","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-ii","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan bilangan dan nilai tempat sampai 100 dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar bilangan dan nilai tempat sampai 100. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Bilangan. Menyatakan banyak atau urutan. Contoh: Ada 12 biji di mangkuk"},{"type":"text","body":"2. Nilai tempat. Nilai angka bergantung posisinya. Contoh: Pada 24, angka 2 bernilai 20"},{"type":"text","body":"3. Membandingkan. Menentukan lebih banyak, lebih sedikit, atau sama. Contoh: 8 lebih banyak daripada 5"},{"type":"text","body":"4. Mengurutkan. Menyusun bilangan menurut nilainya. Contoh: 3, 5, 9 berurutan dari kecil"},{"type":"text","body":"5. Memeriksa hasil. Menghitung kembali dengan cara lain. Contoh: Cocokkan 10 biji dengan dua kelompok lima"},{"type":"text","body":"Contoh dan penalaran: Setiap sepuluh satuan dapat dikelompokkan menjadi satu puluhan. Bilangan 36 terdiri dari 3 puluhan dan 6 satuan: 30 + 6. Untuk membandingkan dua bilangan dua angka, bandingkan puluhannya dahulu, lalu satuannya jika puluhan sama."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Kelompokkan lidi aman menjadi puluhan dan satuan. Wakili tiga bilangan sampai 100."},{"type":"text","body":"Rangkuman: Bilangan: Menyatakan banyak atau urutan; Nilai tempat: Nilai angka bergantung posisinya; Membandingkan: Menentukan lebih banyak, lebih sedikit, atau sama; Mengurutkan: Menyusun bilangan menurut nilainya; Memeriksa hasil: Menghitung kembali dengan cara lain."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('fbdfc268-b9a5-5526-ae02-bebc83ffa947','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Penjumlahan dan pengurangan','belajar-matematika-kelas-2-unit-2',2,'A','Bab 2','dasar','draft',8,'{"summary":"Penjumlahan dan pengurangan. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan penjumlahan dan pengurangan dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas II","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-ii","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah. Periksa operasi yang melampaui 20; beri bantuan/label pengayaan sesuai ATP.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan penjumlahan dan pengurangan dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar penjumlahan dan pengurangan. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Penjumlahan. Menggabungkan dua banyak benda. Contoh: 3 apel dan 2 apel menjadi 5 apel"},{"type":"text","body":"2. Pengurangan. Mengambil atau mencari selisih. Contoh: 7 biji dikurangi 2 tersisa 5"},{"type":"text","body":"3. Perkalian. Menghitung kelompok sama banyak. Contoh: 3 kelompok berisi 4 benda berjumlah 12"},{"type":"text","body":"4. Pembagian. Membagi rata atau menentukan banyak kelompok. Contoh: 12 benda dibagi untuk 3 anak, masing-masing 4"},{"type":"text","body":"5. Kalimat matematika. Lambang yang menyatakan hubungan bilangan. Contoh: 3 + 2 = 5 menyatakan hasil penjumlahan"},{"type":"text","body":"Contoh dan penalaran: Gunakan nilai tempat ketika menjumlah atau mengurang. Pada 28 + 15, 8 satuan ditambah 5 satuan menjadi 13 satuan, yaitu 1 puluhan dan 3 satuan. Jumlah akhirnya 4 puluhan dan 3 satuan, yaitu 43. Pengurangan dapat diperiksa dengan penjumlahan kebalikannya."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Tuliskan satu penjumlahan dan satu pengurangan. Periksa dengan operasi kebalikannya."},{"type":"text","body":"Rangkuman: Penjumlahan: Menggabungkan dua banyak benda; Pengurangan: Mengambil atau mencari selisih; Perkalian: Menghitung kelompok sama banyak; Pembagian: Membagi rata atau menentukan banyak kelompok; Kalimat matematika: Lambang yang menyatakan hubungan bilangan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('81ab0261-1357-52e1-af5e-7e699ba74b2b','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Kelompok sama banyak','belajar-matematika-kelas-2-unit-3',2,'A','Bab 3','dasar','draft',8,'{"summary":"Kelompok sama banyak. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan kelompok sama banyak dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas II","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-ii","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah. Perkalian adalah pengayaan awal; target inti operasi perkalian terdapat pada Fase B.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan kelompok sama banyak dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar kelompok sama banyak. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Penjumlahan. Menggabungkan dua banyak benda. Contoh: 3 apel dan 2 apel menjadi 5 apel"},{"type":"text","body":"2. Pengurangan. Mengambil atau mencari selisih. Contoh: 7 biji dikurangi 2 tersisa 5"},{"type":"text","body":"3. Perkalian. Menghitung kelompok sama banyak. Contoh: 3 kelompok berisi 4 benda berjumlah 12"},{"type":"text","body":"4. Pembagian. Membagi rata atau menentukan banyak kelompok. Contoh: 12 benda dibagi untuk 3 anak, masing-masing 4"},{"type":"text","body":"5. Kalimat matematika. Lambang yang menyatakan hubungan bilangan. Contoh: 3 + 2 = 5 menyatakan hasil penjumlahan"},{"type":"text","body":"Contoh dan penalaran: Perkalian menyatakan kelompok sama banyak. Tiga piring masing-masing berisi dua buah dapat ditulis 2 + 2 + 2 = 6 atau 3 × 2 = 6. Jumlah kelompok dan isi setiap kelompok harus disebut agar cerita jelas."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat tiga kelompok tutup botol, masing-masing empat. Tulis penjumlahan berulangnya."},{"type":"text","body":"Rangkuman: Penjumlahan: Menggabungkan dua banyak benda; Pengurangan: Mengambil atau mencari selisih; Perkalian: Menghitung kelompok sama banyak; Pembagian: Membagi rata atau menentukan banyak kelompok; Kalimat matematika: Lambang yang menyatakan hubungan bilangan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('e83cfd6f-a68c-5cb4-82a9-6caf9e72a73e','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Berbagi sama banyak','belajar-matematika-kelas-2-unit-4',2,'A','Bab 4','sedang','draft',8,'{"summary":"Berbagi sama banyak. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan berbagi sama banyak dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas II","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-ii","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah. Pembagian adalah pengayaan awal; target inti operasi pembagian terdapat pada Fase B.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan berbagi sama banyak dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar berbagi sama banyak. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Penjumlahan. Menggabungkan dua banyak benda. Contoh: 3 apel dan 2 apel menjadi 5 apel"},{"type":"text","body":"2. Pengurangan. Mengambil atau mencari selisih. Contoh: 7 biji dikurangi 2 tersisa 5"},{"type":"text","body":"3. Perkalian. Menghitung kelompok sama banyak. Contoh: 3 kelompok berisi 4 benda berjumlah 12"},{"type":"text","body":"4. Pembagian. Membagi rata atau menentukan banyak kelompok. Contoh: 12 benda dibagi untuk 3 anak, masing-masing 4"},{"type":"text","body":"5. Kalimat matematika. Lambang yang menyatakan hubungan bilangan. Contoh: 3 + 2 = 5 menyatakan hasil penjumlahan"},{"type":"text","body":"Contoh dan penalaran: Pembagian rata memberi isi sama banyak kepada setiap penerima. Pada 9 benda untuk 3 penerima, bagikan satu-satu sampai habis. Setiap penerima mendapat 3; periksa dengan 3 × 3 = 9. Pembagian juga dapat digunakan mencari banyak kelompok."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Bagikan 12 benda sama banyak kepada tiga boneka. Periksa apakah masih ada sisa."},{"type":"text","body":"Rangkuman: Penjumlahan: Menggabungkan dua banyak benda; Pengurangan: Mengambil atau mencari selisih; Perkalian: Menghitung kelompok sama banyak; Pembagian: Membagi rata atau menentukan banyak kelompok; Kalimat matematika: Lambang yang menyatakan hubungan bilangan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('0c50674f-0077-50ab-b078-d7c5598097be','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Pengukuran panjang dan massa','belajar-matematika-kelas-2-unit-5',2,'A','Bab 5','sedang','draft',8,'{"summary":"Pengukuran panjang dan massa. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan pengukuran panjang dan massa dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas II","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-ii","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah. Satuan baku perlu diberi label pengayaan; inti pengukuran Fase A memakai satuan tidak baku.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan pengukuran panjang dan massa dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar pengukuran panjang dan massa. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Panjang. Ukuran dari satu ujung ke ujung lain. Contoh: Pita diukur dari tanda nol penggaris"},{"type":"text","body":"2. Massa. Besaran yang diukur menggunakan neraca atau timbangan. Contoh: Massa tepung dicatat dalam gram"},{"type":"text","body":"3. Durasi. Lama suatu kegiatan berlangsung. Contoh: Belajar dari pukul 8 sampai 9 selama satu jam"},{"type":"text","body":"4. Satuan. Acuan ukuran yang disepakati. Contoh: Sentimeter merupakan satuan panjang"},{"type":"text","body":"5. Konversi. Menyatakan ukuran sama dengan satuan berbeda. Contoh: 1 meter sama panjang dengan 100 sentimeter"},{"type":"text","body":"Contoh dan penalaran: Panjang diukur dengan penggaris mulai tanda nol, bukan ujung penggaris yang belum tentu nol. Satu meter sama dengan 100 sentimeter; satu jam sama dengan 60 menit. Massa dibandingkan dengan neraca atau diukur dengan timbangan yang sesuai, bukan ditentukan hanya dari ukuran benda."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Ukur panjang buku memakai penggaris dari nol. Amati tulisan satuan pada timbangan bersama pendamping."},{"type":"text","body":"Rangkuman: Panjang: Ukuran dari satu ujung ke ujung lain; Massa: Besaran yang diukur menggunakan neraca atau timbangan; Durasi: Lama suatu kegiatan berlangsung; Satuan: Acuan ukuran yang disepakati; Konversi: Menyatakan ukuran sama dengan satuan berbeda."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('7f3ccbc0-c95c-56af-ad9f-4f73dfbd82cc','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Bangun datar dan data gambar','belajar-matematika-kelas-2-unit-6',2,'A','Bab 6','sedang','draft',8,'{"summary":"Bangun datar dan data gambar. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan bangun datar dan data gambar dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas II","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-ii","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan bangun datar dan data gambar dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar bangun datar dan data gambar. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Sisi. Ruas pembatas pada bangun datar bersisi lurus. Contoh: Persegi memiliki empat sisi"},{"type":"text","body":"2. Sudut. Daerah pertemuan dua sinar atau sisi. Contoh: Pojok buku membentuk sudut"},{"type":"text","body":"3. Keliling. Jumlah panjang batas bangun datar. Contoh: Panjang empat sisi persegi dijumlahkan"},{"type":"text","body":"4. Luas. Ukuran daerah yang ditutupi suatu bangun. Contoh: Lantai ditutup dengan petak satuan"},{"type":"text","body":"5. Data. Informasi yang dikumpulkan untuk menjawab pertanyaan. Contoh: Jumlah pemilih buah dicatat dalam tabel"},{"type":"text","body":"Contoh dan penalaran: Kenali bangun dari cirinya, bukan posisinya pada kertas. Persegi yang diputar tetap persegi. Pada data gambar, periksa arti satu gambar dahulu: jika satu gambar mewakili satu orang, tiga gambar berarti tiga orang. Kesimpulan pilihan terbanyak harus mengikuti jumlahnya."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Tanyakan buah favorit lima anggota keluarga. Buat turus atau gambar satu orang per gambar."},{"type":"text","body":"Rangkuman: Sisi: Ruas pembatas pada bangun datar bersisi lurus; Sudut: Daerah pertemuan dua sinar atau sisi; Keliling: Jumlah panjang batas bangun datar; Luas: Ukuran daerah yang ditutupi suatu bangun; Data: Informasi yang dikumpulkan untuk menjawab pertanyaan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('9b5f2173-670e-5538-9e6a-3510a679c7b7','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Bilangan sampai 1.000','belajar-matematika-kelas-3-unit-1',3,'B','Bab 1','dasar','draft',12,'{"summary":"Bilangan sampai 1.000. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan bilangan sampai 1.000 dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas III","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-iii","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan bilangan sampai 1.000 dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar bilangan sampai 1.000. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Bilangan. Menyatakan banyak atau urutan. Contoh: Ada 12 biji di mangkuk"},{"type":"text","body":"2. Nilai tempat. Nilai angka bergantung posisinya. Contoh: Pada 24, angka 2 bernilai 20"},{"type":"text","body":"3. Membandingkan. Menentukan lebih banyak, lebih sedikit, atau sama. Contoh: 8 lebih banyak daripada 5"},{"type":"text","body":"4. Mengurutkan. Menyusun bilangan menurut nilainya. Contoh: 3, 5, 9 berurutan dari kecil"},{"type":"text","body":"5. Memeriksa hasil. Menghitung kembali dengan cara lain. Contoh: Cocokkan 10 biji dengan dua kelompok lima"},{"type":"text","body":"Contoh dan penalaran: Bilangan 426 terdiri dari empat ratusan, dua puluhan, dan enam satuan: 400 + 20 + 6. Angka sama dapat mempunyai nilai berbeda; angka 2 pada 426 bernilai 20. Bandingkan ratusan sebelum puluhan dan satuan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Wakili 348 dengan tiga ratusan, empat puluhan, dan delapan satuan."},{"type":"text","body":"Rangkuman: Bilangan: Menyatakan banyak atau urutan; Nilai tempat: Nilai angka bergantung posisinya; Membandingkan: Menentukan lebih banyak, lebih sedikit, atau sama; Mengurutkan: Menyusun bilangan menurut nilainya; Memeriksa hasil: Menghitung kembali dengan cara lain."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('34c9a94b-533c-59c6-b1dd-7962793e0c28','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Operasi hitung dan masalah sehari-hari','belajar-matematika-kelas-3-unit-2',3,'B','Bab 2','dasar','draft',12,'{"summary":"Operasi hitung dan masalah sehari-hari. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan operasi hitung dan masalah sehari-hari dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas III","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-iii","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan operasi hitung dan masalah sehari-hari dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar operasi hitung dan masalah sehari-hari. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Penjumlahan. Menggabungkan dua banyak benda. Contoh: 3 apel dan 2 apel menjadi 5 apel"},{"type":"text","body":"2. Pengurangan. Mengambil atau mencari selisih. Contoh: 7 biji dikurangi 2 tersisa 5"},{"type":"text","body":"3. Perkalian. Menghitung kelompok sama banyak. Contoh: 3 kelompok berisi 4 benda berjumlah 12"},{"type":"text","body":"4. Pembagian. Membagi rata atau menentukan banyak kelompok. Contoh: 12 benda dibagi untuk 3 anak, masing-masing 4"},{"type":"text","body":"5. Kalimat matematika. Lambang yang menyatakan hubungan bilangan. Contoh: 3 + 2 = 5 menyatakan hasil penjumlahan"},{"type":"text","body":"Contoh dan penalaran: Cerita menentukan operasi yang digunakan. Persediaan 140 buku bertambah 25 menjadi 165; jika 20 kemudian dipinjam, sisanya 145. Tulis setiap langkah beserta satuannya dan periksa apakah hasilnya masuk akal."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat cerita tentang menambah dan mengurangi persediaan buku. Tulis operasi yang sesuai."},{"type":"text","body":"Rangkuman: Penjumlahan: Menggabungkan dua banyak benda; Pengurangan: Mengambil atau mencari selisih; Perkalian: Menghitung kelompok sama banyak; Pembagian: Membagi rata atau menentukan banyak kelompok; Kalimat matematika: Lambang yang menyatakan hubungan bilangan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('7da641ff-40a2-5d11-a736-796131b04e77','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Perkalian dan pembagian','belajar-matematika-kelas-3-unit-3',3,'B','Bab 3','dasar','draft',12,'{"summary":"Perkalian dan pembagian. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan perkalian dan pembagian dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas III","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-iii","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan perkalian dan pembagian dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar perkalian dan pembagian. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Penjumlahan. Menggabungkan dua banyak benda. Contoh: 3 apel dan 2 apel menjadi 5 apel"},{"type":"text","body":"2. Pengurangan. Mengambil atau mencari selisih. Contoh: 7 biji dikurangi 2 tersisa 5"},{"type":"text","body":"3. Perkalian. Menghitung kelompok sama banyak. Contoh: 3 kelompok berisi 4 benda berjumlah 12"},{"type":"text","body":"4. Pembagian. Membagi rata atau menentukan banyak kelompok. Contoh: 12 benda dibagi untuk 3 anak, masing-masing 4"},{"type":"text","body":"5. Kalimat matematika. Lambang yang menyatakan hubungan bilangan. Contoh: 3 + 2 = 5 menyatakan hasil penjumlahan"},{"type":"text","body":"Contoh dan penalaran: Perkalian dan pembagian berhubungan sebagai operasi kebalikan. Dua kelompok masing-masing sembilan benda berjumlah 18. Karena 2 × 9 = 18, maka 18 ÷ 2 = 9 dan 18 ÷ 9 = 2. Jelaskan apakah pembagian mencari isi kelompok atau banyak kelompok."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Gambar baris dan kolom benda, lalu hubungkan perkalian dengan pembagian."},{"type":"text","body":"Rangkuman: Penjumlahan: Menggabungkan dua banyak benda; Pengurangan: Mengambil atau mencari selisih; Perkalian: Menghitung kelompok sama banyak; Pembagian: Membagi rata atau menentukan banyak kelompok; Kalimat matematika: Lambang yang menyatakan hubungan bilangan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('4d9fa96a-827d-5685-ac94-899308618e72','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Pecahan sederhana','belajar-matematika-kelas-3-unit-4',3,'B','Bab 4','sedang','draft',12,'{"summary":"Pecahan sederhana. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan pecahan sederhana dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas III","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-iii","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan pecahan sederhana dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar pecahan sederhana. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Pecahan. Bilangan yang menyatakan bagian sama besar dari keseluruhan. Contoh: Satu dari empat bagian sama besar ditulis 1/4"},{"type":"text","body":"2. Pembilang. Angka yang menyatakan banyak bagian yang dipilih. Contoh: Pada 3/5, pembilangnya 3"},{"type":"text","body":"3. Penyebut. Angka yang menyatakan pembagian sama besar pada keseluruhan. Contoh: Pada 3/5, keseluruhan dibagi lima bagian"},{"type":"text","body":"4. Pecahan senilai. Pecahan berbeda tulisan tetapi bernilai sama. Contoh: 1/2 senilai dengan 2/4"},{"type":"text","body":"5. Keseluruhan yang sama. Acuan yang harus disamakan ketika membandingkan bagian. Contoh: Bandingkan setengah dua pita yang sama panjang"},{"type":"text","body":"Contoh dan penalaran: Pecahan memakai keseluruhan yang dibagi sama besar. Pada 2/6, penyebut 6 menyatakan banyak bagian sama besar dan pembilang 2 menyatakan bagian yang dipilih. Dua dari enam bagian sama dengan satu dari tiga bagian. Saat membandingkan, pastikan keseluruhannya sama."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Lipat dua kertas sama ukuran menjadi dua dan empat bagian sama besar. Bandingkan bagiannya."},{"type":"text","body":"Rangkuman: Pecahan: Bilangan yang menyatakan bagian sama besar dari keseluruhan; Pembilang: Angka yang menyatakan banyak bagian yang dipilih; Penyebut: Angka yang menyatakan pembagian sama besar pada keseluruhan; Pecahan senilai: Pecahan berbeda tulisan tetapi bernilai sama; Keseluruhan yang sama: Acuan yang harus disamakan ketika membandingkan bagian."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('f916dc6b-d775-5f1a-b998-06b66bf619ca','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Satuan panjang, massa, dan waktu','belajar-matematika-kelas-3-unit-5',3,'B','Bab 5','sedang','draft',12,'{"summary":"Satuan panjang, massa, dan waktu. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan satuan panjang, massa, dan waktu dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas III","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-iii","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan satuan panjang, massa, dan waktu dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar satuan panjang, massa, dan waktu. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Panjang. Ukuran dari satu ujung ke ujung lain. Contoh: Pita diukur dari tanda nol penggaris"},{"type":"text","body":"2. Massa. Besaran yang diukur menggunakan neraca atau timbangan. Contoh: Massa tepung dicatat dalam gram"},{"type":"text","body":"3. Durasi. Lama suatu kegiatan berlangsung. Contoh: Belajar dari pukul 8 sampai 9 selama satu jam"},{"type":"text","body":"4. Satuan. Acuan ukuran yang disepakati. Contoh: Sentimeter merupakan satuan panjang"},{"type":"text","body":"5. Konversi. Menyatakan ukuran sama dengan satuan berbeda. Contoh: 1 meter sama panjang dengan 100 sentimeter"},{"type":"text","body":"Contoh dan penalaran: Samakan satuan sebelum menghitung ukuran. Contohnya 1 m 20 cm = 100 cm + 20 cm = 120 cm. Satu kilogram sama dengan 1.000 gram, dan satu jam sama dengan 60 menit. Tulis satuan pada hasil agar ukuran dapat dipahami."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Catat satu pengukuran panjang, massa, dan durasi. Sebut satuan yang digunakan."},{"type":"text","body":"Rangkuman: Panjang: Ukuran dari satu ujung ke ujung lain; Massa: Besaran yang diukur menggunakan neraca atau timbangan; Durasi: Lama suatu kegiatan berlangsung; Satuan: Acuan ukuran yang disepakati; Konversi: Menyatakan ukuran sama dengan satuan berbeda."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('15f1dff2-9022-5e78-bdcd-bade8a5d3b74','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Bentuk dan tabel data','belajar-matematika-kelas-3-unit-6',3,'B','Bab 6','sedang','draft',12,'{"summary":"Bentuk dan tabel data. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan bentuk dan tabel data dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas III","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-iii","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan bentuk dan tabel data dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar bentuk dan tabel data. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Sisi. Ruas pembatas pada bangun datar bersisi lurus. Contoh: Persegi memiliki empat sisi"},{"type":"text","body":"2. Sudut. Daerah pertemuan dua sinar atau sisi. Contoh: Pojok buku membentuk sudut"},{"type":"text","body":"3. Keliling. Jumlah panjang batas bangun datar. Contoh: Panjang empat sisi persegi dijumlahkan"},{"type":"text","body":"4. Tabel. Penyajian data dalam baris dan kolom. Contoh: Jumlah pemilih dicatat menurut buah"},{"type":"text","body":"5. Diagram batang. Penyajian data dengan panjang batang sesuai banyaknya. Contoh: Batang lebih tinggi berarti jumlah lebih besar"},{"type":"text","body":"Contoh dan penalaran: Keliling adalah panjang batas bangun, sehingga semua sisi pembatas dijumlahkan. Persegi dengan sisi 3 cm memiliki keliling 12 cm. Pada tabel, label menjelaskan apa yang dihitung; jumlah dua kelompok berisi 6 dan 2 benda adalah 8, dan selisihnya 4."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat tabel banyak pensil tiga warna. Tulis satu pertanyaan yang dapat dijawab dari tabelmu."},{"type":"text","body":"Rangkuman: Sisi: Ruas pembatas pada bangun datar bersisi lurus; Sudut: Daerah pertemuan dua sinar atau sisi; Keliling: Jumlah panjang batas bangun datar; Tabel: Penyajian data dalam baris dan kolom; Diagram batang: Penyajian data dengan panjang batang sesuai banyaknya."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('b2d250dc-505a-5930-91c3-723393e2d46c','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Bilangan sampai 10.000','belajar-matematika-kelas-4-unit-1',4,'B','Bab 1','dasar','draft',12,'{"summary":"Bilangan sampai 10.000. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan bilangan sampai 10.000 dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas IV","url":"https://buku.kemendikdasmen.go.id/katalog/Matematika-untuk-SDMI-Kelas-IV","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan bilangan sampai 10.000 dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar bilangan sampai 10.000. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Bilangan. Menyatakan banyak atau urutan. Contoh: Ada 12 biji di mangkuk"},{"type":"text","body":"2. Nilai tempat. Nilai angka bergantung posisinya. Contoh: Pada 24, angka 2 bernilai 20"},{"type":"text","body":"3. Membandingkan. Menentukan lebih banyak, lebih sedikit, atau sama. Contoh: 8 lebih banyak daripada 5"},{"type":"text","body":"4. Mengurutkan. Menyusun bilangan menurut nilainya. Contoh: 3, 5, 9 berurutan dari kecil"},{"type":"text","body":"5. Memeriksa hasil. Menghitung kembali dengan cara lain. Contoh: Cocokkan 10 biji dengan dua kelompok lima"},{"type":"text","body":"Contoh dan penalaran: Bilangan 7.318 terdiri dari 7.000 + 300 + 10 + 8. Nilai angka bergantung tempatnya. Jika ribuan dua bilangan sama, bandingkan ratusan, lalu puluhan dan satuan; jangan membandingkan dari angka terakhir saja."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Tulis tiga bilangan empat angka. Jelaskan nilai tiap angka dan urutkan."},{"type":"text","body":"Rangkuman: Bilangan: Menyatakan banyak atau urutan; Nilai tempat: Nilai angka bergantung posisinya; Membandingkan: Menentukan lebih banyak, lebih sedikit, atau sama; Mengurutkan: Menyusun bilangan menurut nilainya; Memeriksa hasil: Menghitung kembali dengan cara lain."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('d50aa56f-7a64-5a2d-9e71-5b574dcce432','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Faktor dan kelipatan sederhana','belajar-matematika-kelas-4-unit-2',4,'B','Bab 2','dasar','draft',12,'{"summary":"Faktor dan kelipatan sederhana. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan faktor dan kelipatan sederhana dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas IV","url":"https://buku.kemendikdasmen.go.id/katalog/Matematika-untuk-SDMI-Kelas-IV","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan faktor dan kelipatan sederhana dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar faktor dan kelipatan sederhana. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Faktor. Bilangan pembagi yang menghasilkan pembagian tanpa sisa. Contoh: 3 faktor dari 12 karena 12 ÷ 3 = 4"},{"type":"text","body":"2. Kelipatan. Hasil perkalian bilangan dengan bilangan bulat. Contoh: 6, 12, 18 adalah kelipatan 6"},{"type":"text","body":"3. Pasangan faktor. Dua faktor yang hasil kalinya bilangan tertentu. Contoh: 3 dan 4 membentuk pasangan faktor 12"},{"type":"text","body":"4. Sisa nol. Tanda bahwa pembagian habis. Contoh: 20 dibagi 5 bersisa nol"},{"type":"text","body":"5. Pola kelipatan. Susunan bilangan dengan pertambahan tetap. Contoh: Kelipatan 4 bertambah empat setiap langkah"},{"type":"text","body":"Contoh dan penalaran: Faktor membagi suatu bilangan tanpa sisa. Faktor 10 adalah 1, 2, 5, dan 10 karena dapat dipasangkan menjadi 1 × 10 dan 2 × 5. Kelipatan diperoleh dari perkalian berulang; kelipatan positif 5 dimulai 5, 10, 15, 20."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Gunakan benda untuk menyusun persegi panjang dengan 12 benda. Cari pasangan faktornya."},{"type":"text","body":"Rangkuman: Faktor: Bilangan pembagi yang menghasilkan pembagian tanpa sisa; Kelipatan: Hasil perkalian bilangan dengan bilangan bulat; Pasangan faktor: Dua faktor yang hasil kalinya bilangan tertentu; Sisa nol: Tanda bahwa pembagian habis; Pola kelipatan: Susunan bilangan dengan pertambahan tetap."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('e64704b6-3e8b-57f7-ad40-509b5216df8c','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Pecahan senilai dan perbandingan pecahan','belajar-matematika-kelas-4-unit-3',4,'B','Bab 3','dasar','draft',12,'{"summary":"Pecahan senilai dan perbandingan pecahan. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan pecahan senilai dan perbandingan pecahan dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas IV","url":"https://buku.kemendikdasmen.go.id/katalog/Matematika-untuk-SDMI-Kelas-IV","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan pecahan senilai dan perbandingan pecahan dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar pecahan senilai dan perbandingan pecahan. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Pecahan. Bilangan yang menyatakan bagian sama besar dari keseluruhan. Contoh: Satu dari empat bagian sama besar ditulis 1/4"},{"type":"text","body":"2. Pembilang. Angka yang menyatakan banyak bagian yang dipilih. Contoh: Pada 3/5, pembilangnya 3"},{"type":"text","body":"3. Penyebut. Angka yang menyatakan pembagian sama besar pada keseluruhan. Contoh: Pada 3/5, keseluruhan dibagi lima bagian"},{"type":"text","body":"4. Pecahan senilai. Pecahan berbeda tulisan tetapi bernilai sama. Contoh: 1/2 senilai dengan 2/4"},{"type":"text","body":"5. Keseluruhan yang sama. Acuan yang harus disamakan ketika membandingkan bagian. Contoh: Bandingkan setengah dua pita yang sama panjang"},{"type":"text","body":"Contoh dan penalaran: Pecahan senilai diperoleh dengan mengalikan atau membagi pembilang dan penyebut dengan bilangan sama yang bukan nol. Contohnya 3/6 = 1/2 karena keduanya dibagi 3. Untuk penyebut sama, bandingkan pembilang; 2/7 lebih kecil daripada 6/7."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat dua gambar keseluruhan sama besar untuk menunjukkan pecahan senilai."},{"type":"text","body":"Rangkuman: Pecahan: Bilangan yang menyatakan bagian sama besar dari keseluruhan; Pembilang: Angka yang menyatakan banyak bagian yang dipilih; Penyebut: Angka yang menyatakan pembagian sama besar pada keseluruhan; Pecahan senilai: Pecahan berbeda tulisan tetapi bernilai sama; Keseluruhan yang sama: Acuan yang harus disamakan ketika membandingkan bagian."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('2881fb07-a886-5aeb-b570-48cfd1a509e3','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Desimal dan persen sederhana','belajar-matematika-kelas-4-unit-4',4,'B','Bab 4','sedang','draft',12,'{"summary":"Desimal dan persen sederhana. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan desimal dan persen sederhana dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas IV","url":"https://buku.kemendikdasmen.go.id/katalog/Matematika-untuk-SDMI-Kelas-IV","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan desimal dan persen sederhana dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar desimal dan persen sederhana. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Pecahan. Bilangan yang menyatakan bagian sama besar dari keseluruhan. Contoh: Satu dari empat bagian sama besar ditulis 1/4"},{"type":"text","body":"2. Pembilang. Angka yang menyatakan banyak bagian yang dipilih. Contoh: Pada 3/5, pembilangnya 3"},{"type":"text","body":"3. Penyebut. Angka yang menyatakan pembagian sama besar pada keseluruhan. Contoh: Pada 3/5, keseluruhan dibagi lima bagian"},{"type":"text","body":"4. Pecahan senilai. Pecahan berbeda tulisan tetapi bernilai sama. Contoh: 1/2 senilai dengan 2/4"},{"type":"text","body":"5. Keseluruhan yang sama. Acuan yang harus disamakan ketika membandingkan bagian. Contoh: Bandingkan setengah dua pita yang sama panjang"},{"type":"text","body":"Contoh dan penalaran: Desimal menunjukkan bagian persepuluhan atau perseratusan: 0,4 = 4/10. Persen berarti per seratus, sehingga 20% = 20/100 = 1/5. Untuk mencari 20% dari 50, hitung 50 ÷ 5 = 10. Gunakan keseluruhan yang jelas ketika membicarakan persen."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Gunakan petak seratus untuk mewarnai 25 bagian. Hubungkan dengan pecahan dan persen."},{"type":"text","body":"Rangkuman: Pecahan: Bilangan yang menyatakan bagian sama besar dari keseluruhan; Pembilang: Angka yang menyatakan banyak bagian yang dipilih; Penyebut: Angka yang menyatakan pembagian sama besar pada keseluruhan; Pecahan senilai: Pecahan berbeda tulisan tetapi bernilai sama; Keseluruhan yang sama: Acuan yang harus disamakan ketika membandingkan bagian."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('cb42ebab-8312-564a-b244-198fa21e4932','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Luas, keliling, dan sudut','belajar-matematika-kelas-4-unit-5',4,'B','Bab 5','sedang','draft',12,'{"summary":"Luas, keliling, dan sudut. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan luas, keliling, dan sudut dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas IV","url":"https://buku.kemendikdasmen.go.id/katalog/Matematika-untuk-SDMI-Kelas-IV","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah. Bedakan estimasi luas/volume Fase B dari rumus keliling serta pengukuran sudut pada Fase C.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan luas, keliling, dan sudut dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar luas, keliling, dan sudut. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Sisi. Ruas pembatas pada bangun datar bersisi lurus. Contoh: Persegi memiliki empat sisi"},{"type":"text","body":"2. Sudut. Daerah pertemuan dua sinar atau sisi. Contoh: Pojok buku membentuk sudut"},{"type":"text","body":"3. Keliling. Jumlah panjang batas bangun datar. Contoh: Panjang empat sisi persegi dijumlahkan"},{"type":"text","body":"4. Luas. Ukuran daerah yang ditutupi suatu bangun. Contoh: Lantai ditutup dengan petak satuan"},{"type":"text","body":"5. Data. Informasi yang dikumpulkan untuk menjawab pertanyaan. Contoh: Jumlah pemilih buah dicatat dalam tabel"},{"type":"text","body":"Contoh dan penalaran: Luas persegi panjang adalah panjang × lebar karena dapat dihitung sebagai baris petak satuan. Bangun 6 cm × 2 cm memiliki luas 12 cm², tetapi kelilingnya 2 × (6 + 2) = 16 cm. Luas memakai satuan persegi; sudut siku-siku berukuran 90 derajat."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Gambar persegi panjang pada kertas berpetak. Hitung keliling dan luas tanpa tertukar."},{"type":"text","body":"Rangkuman: Sisi: Ruas pembatas pada bangun datar bersisi lurus; Sudut: Daerah pertemuan dua sinar atau sisi; Keliling: Jumlah panjang batas bangun datar; Luas: Ukuran daerah yang ditutupi suatu bangun; Data: Informasi yang dikumpulkan untuk menjawab pertanyaan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('d08a4d40-d03e-54f7-9bd6-d4dad37f35ed','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Tabel dan diagram batang','belajar-matematika-kelas-4-unit-6',4,'B','Bab 6','sedang','draft',12,'{"summary":"Tabel dan diagram batang. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan tabel dan diagram batang dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas IV","url":"https://buku.kemendikdasmen.go.id/katalog/Matematika-untuk-SDMI-Kelas-IV","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan tabel dan diagram batang dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar tabel dan diagram batang. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Tabel. Penyajian data dalam baris dan kolom. Contoh: Jumlah pemilih dicatat menurut buah"},{"type":"text","body":"2. Diagram batang. Penyajian data dengan panjang batang sesuai banyaknya. Contoh: Batang lebih tinggi berarti jumlah lebih besar"},{"type":"text","body":"3. Frekuensi. Banyak kemunculan suatu nilai atau kategori. Contoh: Lima anak memilih mangga, frekuensinya lima"},{"type":"text","body":"4. Kesimpulan data. Pernyataan yang didukung catatan pengamatan. Contoh: Pilihan terbanyak ditentukan dari jumlah terbesar"},{"type":"text","body":"5. Kemungkinan. Ukuran atau gambaran peluang suatu kejadian. Contoh: Mengambil bola merah lebih mungkin jika jumlahnya lebih banyak"},{"type":"text","body":"Contoh dan penalaran: Pada diagram batang, baca nama kategori dan skala sebelum membandingkan tinggi. Jika tiap petak berarti tiga orang, batang setinggi empat petak berarti 12 orang. Jangan menganggap satu petak selalu mewakili satu orang; kesimpulan hanya berlaku untuk data yang dicatat."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Kumpulkan pilihan permainan dari teman tanpa data pribadi. Buat diagram batang dengan skala jelas."},{"type":"text","body":"Rangkuman: Tabel: Penyajian data dalam baris dan kolom; Diagram batang: Penyajian data dengan panjang batang sesuai banyaknya; Frekuensi: Banyak kemunculan suatu nilai atau kategori; Kesimpulan data: Pernyataan yang didukung catatan pengamatan; Kemungkinan: Ukuran atau gambaran peluang suatu kejadian."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('bcb37bb6-3556-56d4-a9aa-fa2740deea49','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Bilangan dan operasi hitung','belajar-matematika-kelas-5-unit-1',5,'C','Bab 1','dasar','draft',12,'{"summary":"Bilangan dan operasi hitung. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan bilangan dan operasi hitung dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas V","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-v","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan bilangan dan operasi hitung dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar bilangan dan operasi hitung. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Penjumlahan. Menggabungkan dua banyak benda. Contoh: 3 apel dan 2 apel menjadi 5 apel"},{"type":"text","body":"2. Pengurangan. Mengambil atau mencari selisih. Contoh: 7 biji dikurangi 2 tersisa 5"},{"type":"text","body":"3. Perkalian. Menghitung kelompok sama banyak. Contoh: 3 kelompok berisi 4 benda berjumlah 12"},{"type":"text","body":"4. Pembagian. Membagi rata atau menentukan banyak kelompok. Contoh: 12 benda dibagi untuk 3 anak, masing-masing 4"},{"type":"text","body":"5. Kalimat matematika. Lambang yang menyatakan hubungan bilangan. Contoh: 3 + 2 = 5 menyatakan hasil penjumlahan"},{"type":"text","body":"Contoh dan penalaran: Utamakan makna cerita dan nilai tempat. Sebanyak 1.600 barang bertambah 250 menjadi 1.850. Jika dibagi dalam lima kelompok sama banyak, setiap kelompok berisi 370. Periksa hasil pembagian dengan perkalian dan gunakan perkiraan untuk mendeteksi kekeliruan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Pecahkan cerita persediaan barang dan jelaskan pilihan operasi. Periksa kewajaran hasil."},{"type":"text","body":"Rangkuman: Penjumlahan: Menggabungkan dua banyak benda; Pengurangan: Mengambil atau mencari selisih; Perkalian: Menghitung kelompok sama banyak; Pembagian: Membagi rata atau menentukan banyak kelompok; Kalimat matematika: Lambang yang menyatakan hubungan bilangan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('df2a4fd0-75b2-5e04-b01e-e3b41dbc23aa','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','KPK dan FPB dalam pemecahan masalah','belajar-matematika-kelas-5-unit-2',5,'C','Bab 2','dasar','draft',12,'{"summary":"KPK dan FPB dalam pemecahan masalah. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan kpk dan fpb dalam pemecahan masalah dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas V","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-v","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah. KPK/FPB termasuk capaian inti Fase C; kedalaman dan penerapan perlu ditinjau.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan kpk dan fpb dalam pemecahan masalah dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar kpk dan fpb dalam pemecahan masalah. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Faktor persekutuan. Faktor yang sama pada dua bilangan. Contoh: 1, 2, 3, 6 membagi 12 dan 18"},{"type":"text","body":"2. FPB. Faktor persekutuan terbesar. Contoh: FPB 12 dan 18 adalah 6"},{"type":"text","body":"3. Kelipatan persekutuan. Kelipatan yang dimiliki bersama. Contoh: 12 adalah kelipatan 4 sekaligus 6"},{"type":"text","body":"4. KPK. Kelipatan persekutuan positif terkecil. Contoh: KPK 4 dan 6 adalah 12"},{"type":"text","body":"5. Menguji pembagian. Memeriksa hasil dengan perkalian. Contoh: 12 ÷ 3 = 4 diperiksa dengan 3 × 4"},{"type":"text","body":"Contoh dan penalaran: FPB mencari faktor bersama paling besar; KPK mencari kelipatan positif bersama paling kecil. Faktor bersama 10 dan 15 adalah 1 serta 5, maka FPB-nya 5. Kelipatan positif bersama 2 dan 7 pertama kali bertemu pada 14, maka KPK-nya 14. Pilih sesuai masalah, bukan hanya menghafal singkatan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Daftar faktor 12 dan 18 serta kelipatan 4 dan 6. Bedakan faktor persekutuan dengan kelipatan persekutuan."},{"type":"text","body":"Rangkuman: Faktor persekutuan: Faktor yang sama pada dua bilangan; FPB: Faktor persekutuan terbesar; Kelipatan persekutuan: Kelipatan yang dimiliki bersama; KPK: Kelipatan persekutuan positif terkecil; Menguji pembagian: Memeriksa hasil dengan perkalian."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('dca98808-d032-5c0e-92ef-454d0602f915','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Operasi pecahan dan desimal','belajar-matematika-kelas-5-unit-3',5,'C','Bab 3','dasar','draft',12,'{"summary":"Operasi pecahan dan desimal. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan operasi pecahan dan desimal dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas V","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-v","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan operasi pecahan dan desimal dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar operasi pecahan dan desimal. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Pecahan. Bilangan yang menyatakan bagian sama besar dari keseluruhan. Contoh: Satu dari empat bagian sama besar ditulis 1/4"},{"type":"text","body":"2. Pembilang. Angka yang menyatakan banyak bagian yang dipilih. Contoh: Pada 3/5, pembilangnya 3"},{"type":"text","body":"3. Penyebut. Angka yang menyatakan pembagian sama besar pada keseluruhan. Contoh: Pada 3/5, keseluruhan dibagi lima bagian"},{"type":"text","body":"4. Pecahan senilai. Pecahan berbeda tulisan tetapi bernilai sama. Contoh: 1/2 senilai dengan 2/4"},{"type":"text","body":"5. Keseluruhan yang sama. Acuan yang harus disamakan ketika membandingkan bagian. Contoh: Bandingkan setengah dua pita yang sama panjang"},{"type":"text","body":"Contoh dan penalaran: Untuk menjumlah pecahan, samakan penyebut agar ukuran bagian sama. Contohnya 1/3 + 1/6 = 2/6 + 1/6 = 3/6 = 1/2. Pada desimal, sejajarkan nilai tempat, misalnya 0,3 + 0,4 = 0,7. Untuk mencari bagian dari kumpulan, bagi dengan penyebut lalu kalikan pembilang."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Gunakan garis bilangan atau gambar pecahan untuk menjelaskan satu operasi, bukan hanya rumus."},{"type":"text","body":"Rangkuman: Pecahan: Bilangan yang menyatakan bagian sama besar dari keseluruhan; Pembilang: Angka yang menyatakan banyak bagian yang dipilih; Penyebut: Angka yang menyatakan pembagian sama besar pada keseluruhan; Pecahan senilai: Pecahan berbeda tulisan tetapi bernilai sama; Keseluruhan yang sama: Acuan yang harus disamakan ketika membandingkan bagian."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('73f386a0-6e8e-5739-88c5-a9f160597c65','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Pengukuran dan luas bangun','belajar-matematika-kelas-5-unit-4',5,'C','Bab 4','sedang','draft',12,'{"summary":"Pengukuran dan luas bangun. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan pengukuran dan luas bangun dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas V","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-v","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan pengukuran dan luas bangun dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar pengukuran dan luas bangun. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Sisi. Ruas pembatas pada bangun datar bersisi lurus. Contoh: Persegi memiliki empat sisi"},{"type":"text","body":"2. Sudut. Daerah pertemuan dua sinar atau sisi. Contoh: Pojok buku membentuk sudut"},{"type":"text","body":"3. Keliling. Jumlah panjang batas bangun datar. Contoh: Panjang empat sisi persegi dijumlahkan"},{"type":"text","body":"4. Luas. Ukuran daerah yang ditutupi suatu bangun. Contoh: Lantai ditutup dengan petak satuan"},{"type":"text","body":"5. Data. Informasi yang dikumpulkan untuk menjawab pertanyaan. Contoh: Jumlah pemilih buah dicatat dalam tabel"},{"type":"text","body":"Contoh dan penalaran: Luas segitiga adalah setengah luas persegi panjang yang alas dan tingginya sama. Alas 8 cm dan tinggi tegak lurus 5 cm memberi luas 1/2 × 8 × 5 = 20 cm². Satuan luas juga dikuadratkan: karena 1 m = 100 cm, maka 1 m² = 100 × 100 cm²."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat sketsa persegi panjang dan segitiga beserta ukurannya. Jelaskan satuan luasnya."},{"type":"text","body":"Rangkuman: Sisi: Ruas pembatas pada bangun datar bersisi lurus; Sudut: Daerah pertemuan dua sinar atau sisi; Keliling: Jumlah panjang batas bangun datar; Luas: Ukuran daerah yang ditutupi suatu bangun; Data: Informasi yang dikumpulkan untuk menjawab pertanyaan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('992b74c2-724f-51c9-8014-86b86bd741d6','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Bangun ruang dan volume','belajar-matematika-kelas-5-unit-5',5,'C','Bab 5','sedang','draft',12,'{"summary":"Bangun ruang dan volume. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan bangun ruang dan volume dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas V","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-v","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan bangun ruang dan volume dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar bangun ruang dan volume. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Volume. Ukuran ruang yang ditempati bangun. Contoh: Balok berisi dua lapis kubus satuan"},{"type":"text","body":"2. Kubus satuan. Acuan volume berbentuk kubus dengan rusuk satu satuan. Contoh: Kubus rusuk 1 cm bervolume 1 cm³"},{"type":"text","body":"3. Kubus. Bangun ruang dengan enam sisi persegi sama besar. Contoh: Dadu yang ideal berbentuk kubus"},{"type":"text","body":"4. Balok. Bangun ruang bersisi enam persegi panjang dengan sudut siku-siku. Contoh: Kotak sepatu berbentuk balok"},{"type":"text","body":"5. Lapis. Susunan sejajar yang membantu menghitung volume. Contoh: Dua lapis masing-masing enam kubus berjumlah 12"},{"type":"text","body":"Contoh dan penalaran: Volume balok dapat dihitung dari banyak kubus per lapis dikali jumlah lapis. Balok 3 cm × 2 cm × 2 cm memuat 12 kubus berukuran 1 cm³. Rumusnya panjang × lebar × tinggi. Kubus mempunyai tiga ukuran rusuk sama, sehingga volumenya rusuk × rusuk × rusuk."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Susun kubus satuan menjadi balok. Hitung banyak kubus per lapis dan banyak lapis."},{"type":"text","body":"Rangkuman: Volume: Ukuran ruang yang ditempati bangun; Kubus satuan: Acuan volume berbentuk kubus dengan rusuk satu satuan; Kubus: Bangun ruang dengan enam sisi persegi sama besar; Balok: Bangun ruang bersisi enam persegi panjang dengan sudut siku-siku; Lapis: Susunan sejajar yang membantu menghitung volume."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('aa381688-6801-52c7-9570-ca96fdd007ae','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Membaca data dan peluang sederhana','belajar-matematika-kelas-5-unit-6',5,'C','Bab 6','sedang','draft',12,'{"summary":"Membaca data dan peluang sederhana. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan membaca data dan peluang sederhana dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas V","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-v","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan membaca data dan peluang sederhana dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar membaca data dan peluang sederhana. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Tabel. Penyajian data dalam baris dan kolom. Contoh: Jumlah pemilih dicatat menurut buah"},{"type":"text","body":"2. Diagram batang. Penyajian data dengan panjang batang sesuai banyaknya. Contoh: Batang lebih tinggi berarti jumlah lebih besar"},{"type":"text","body":"3. Frekuensi. Banyak kemunculan suatu nilai atau kategori. Contoh: Lima anak memilih mangga, frekuensinya lima"},{"type":"text","body":"4. Kesimpulan data. Pernyataan yang didukung catatan pengamatan. Contoh: Pilihan terbanyak ditentukan dari jumlah terbesar"},{"type":"text","body":"5. Kemungkinan. Ukuran atau gambaran peluang suatu kejadian. Contoh: Mengambil bola merah lebih mungkin jika jumlahnya lebih banyak"},{"type":"text","body":"Contoh dan penalaran: Rata-rata dihitung dengan menjumlah semua nilai lalu membaginya dengan banyak data; rata-rata 2, 4, 9 adalah 15 ÷ 3 = 5. Jangkauan adalah nilai terbesar dikurangi terkecil. Peluang sederhana membandingkan kemungkinan: warna lebih banyak lebih mungkin terambil secara acak, tetapi bukan berarti pasti."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Gunakan tabel atau kantong benda berwarna. Jelaskan kesimpulan dengan jumlah yang tercatat."},{"type":"text","body":"Rangkuman: Tabel: Penyajian data dalam baris dan kolom; Diagram batang: Penyajian data dengan panjang batang sesuai banyaknya; Frekuensi: Banyak kemunculan suatu nilai atau kategori; Kesimpulan data: Pernyataan yang didukung catatan pengamatan; Kemungkinan: Ukuran atau gambaran peluang suatu kejadian."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('dd4bca95-16e2-53e3-bccf-5a2628b7578c','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Operasi bilangan dan pemecahan masalah','belajar-matematika-kelas-6-unit-1',6,'C','Bab 1','dasar','draft',12,'{"summary":"Operasi bilangan dan pemecahan masalah. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan operasi bilangan dan pemecahan masalah dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas VI","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-vi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan operasi bilangan dan pemecahan masalah dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar operasi bilangan dan pemecahan masalah. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Penjumlahan. Menggabungkan dua banyak benda. Contoh: 3 apel dan 2 apel menjadi 5 apel"},{"type":"text","body":"2. Pengurangan. Mengambil atau mencari selisih. Contoh: 7 biji dikurangi 2 tersisa 5"},{"type":"text","body":"3. Perkalian. Menghitung kelompok sama banyak. Contoh: 3 kelompok berisi 4 benda berjumlah 12"},{"type":"text","body":"4. Pembagian. Membagi rata atau menentukan banyak kelompok. Contoh: 12 benda dibagi untuk 3 anak, masing-masing 4"},{"type":"text","body":"5. Kalimat matematika. Lambang yang menyatakan hubungan bilangan. Contoh: 3 + 2 = 5 menyatakan hasil penjumlahan"},{"type":"text","body":"Contoh dan penalaran: Pada hitung campuran, kerjakan kurung dahulu. Setelah itu perkalian dan pembagian setara dikerjakan dari kiri, lalu penjumlahan dan pengurangan dari kiri. Contohnya 20 − 2 × (3 + 1) = 20 − 8 = 12. Tuliskan tahap agar alasan tiap perubahan terlihat."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Tuliskan urutan pengerjaan hitung campuran. Periksa dengan cerita atau perkiraan hasil."},{"type":"text","body":"Rangkuman: Penjumlahan: Menggabungkan dua banyak benda; Pengurangan: Mengambil atau mencari selisih; Perkalian: Menghitung kelompok sama banyak; Pembagian: Membagi rata atau menentukan banyak kelompok; Kalimat matematika: Lambang yang menyatakan hubungan bilangan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('451a0bde-2bae-58cc-8c55-e604dd504a69','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Pecahan, desimal, dan persen','belajar-matematika-kelas-6-unit-2',6,'C','Bab 2','dasar','draft',12,'{"summary":"Pecahan, desimal, dan persen. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan pecahan, desimal, dan persen dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas VI","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-vi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan pecahan, desimal, dan persen dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar pecahan, desimal, dan persen. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Pecahan. Bilangan yang menyatakan bagian sama besar dari keseluruhan. Contoh: Satu dari empat bagian sama besar ditulis 1/4"},{"type":"text","body":"2. Pembilang. Angka yang menyatakan banyak bagian yang dipilih. Contoh: Pada 3/5, pembilangnya 3"},{"type":"text","body":"3. Penyebut. Angka yang menyatakan pembagian sama besar pada keseluruhan. Contoh: Pada 3/5, keseluruhan dibagi lima bagian"},{"type":"text","body":"4. Pecahan senilai. Pecahan berbeda tulisan tetapi bernilai sama. Contoh: 1/2 senilai dengan 2/4"},{"type":"text","body":"5. Keseluruhan yang sama. Acuan yang harus disamakan ketika membandingkan bagian. Contoh: Bandingkan setengah dua pita yang sama panjang"},{"type":"text","body":"Contoh dan penalaran: Pecahan, desimal, dan persen dapat menyatakan nilai sama: 3/5 = 0,6 = 60%. Persen dari suatu jumlah dihitung sebagai pecahan per seratus dikali jumlah. Contohnya 15% dari 200 = 15/100 × 200 = 30. Potongan harga dikurangkan dari harga awal, bukan menjadi harga akhirnya."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Gambarkan hubungan pecahan, desimal, dan persen memakai petak seratus."},{"type":"text","body":"Rangkuman: Pecahan: Bilangan yang menyatakan bagian sama besar dari keseluruhan; Pembilang: Angka yang menyatakan banyak bagian yang dipilih; Penyebut: Angka yang menyatakan pembagian sama besar pada keseluruhan; Pecahan senilai: Pecahan berbeda tulisan tetapi bernilai sama; Keseluruhan yang sama: Acuan yang harus disamakan ketika membandingkan bagian."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('09e287a8-34a3-5027-bed2-06de8cbbdb37','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Rasio dan proporsi sederhana','belajar-matematika-kelas-6-unit-3',6,'C','Bab 3','dasar','draft',12,'{"summary":"Rasio dan proporsi sederhana. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan rasio dan proporsi sederhana dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas VI","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-vi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan rasio dan proporsi sederhana dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar rasio dan proporsi sederhana. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Rasio. Perbandingan dua besaran dengan urutan yang jelas. Contoh: Merah:biru = 2:3"},{"type":"text","body":"2. Bagian rasio. Satuan perbandingan yang ukurannya sama. Contoh: Rasio 2:3 memuat lima bagian seluruhnya"},{"type":"text","body":"3. Rasio senilai. Rasio dengan perbandingan yang sama. Contoh: 2:3 senilai dengan 4:6"},{"type":"text","body":"4. Proporsi. Kesamaan dua rasio. Contoh: 2/3 = 4/6"},{"type":"text","body":"5. Urutan besaran. Penentu arti angka pada rasio. Contoh: Merah:biru berbeda penulisan dari biru:merah"},{"type":"text","body":"Contoh dan penalaran: Rasio menyatakan perbandingan dengan urutan jelas. Jika kuning:biru = 3:2 dan jumlah benda 25, ada lima bagian rasio. Satu bagian bernilai 25 ÷ 5 = 5; kuning 15 dan biru 10. Rasio senilai diperoleh dengan mengalikan kedua bagian dengan bilangan sama."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Campurkan dua warna benda dalam rasio tertentu. Jelaskan apa arti setiap bagian rasio."},{"type":"text","body":"Rangkuman: Rasio: Perbandingan dua besaran dengan urutan yang jelas; Bagian rasio: Satuan perbandingan yang ukurannya sama; Rasio senilai: Rasio dengan perbandingan yang sama; Proporsi: Kesamaan dua rasio; Urutan besaran: Penentu arti angka pada rasio."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('4b34b044-e28b-543b-8b3b-b68a7d879633','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Pengukuran luas dan volume','belajar-matematika-kelas-6-unit-4',6,'C','Bab 4','sedang','draft',12,'{"summary":"Pengukuran luas dan volume. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan pengukuran luas dan volume dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas VI","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-vi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan pengukuran luas dan volume dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar pengukuran luas dan volume. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Panjang. Ukuran dari satu ujung ke ujung lain. Contoh: Pita diukur dari tanda nol penggaris"},{"type":"text","body":"2. Massa. Besaran yang diukur menggunakan neraca atau timbangan. Contoh: Massa tepung dicatat dalam gram"},{"type":"text","body":"3. Durasi. Lama suatu kegiatan berlangsung. Contoh: Belajar dari pukul 8 sampai 9 selama satu jam"},{"type":"text","body":"4. Luas. Ukuran daerah yang ditutupi suatu bangun. Contoh: Lantai ditutup dengan petak satuan"},{"type":"text","body":"5. Volume. Ukuran ruang dalam satuan kubik. Contoh: 1 cm³ berupa kubus rusuk 1 cm"},{"type":"text","body":"Contoh dan penalaran: Samakan satuan ukuran sebelum menghitung. Luas memakai satuan persegi, volume memakai satuan kubik. Balok 2 m × 3 m × 4 m bervolume 24 m³. Untuk kapasitas, 1 liter = 1.000 mililiter. Angka sama dengan satuan berbeda tidak selalu menyatakan ukuran sama."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Bandingkan satuan panjang, luas, dan volume. Jelaskan mengapa faktor konversinya berbeda."},{"type":"text","body":"Rangkuman: Panjang: Ukuran dari satu ujung ke ujung lain; Massa: Besaran yang diukur menggunakan neraca atau timbangan; Durasi: Lama suatu kegiatan berlangsung; Luas: Ukuran daerah yang ditutupi suatu bangun; Volume: Ukuran ruang dalam satuan kubik."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('63c032be-32a9-52a1-a63e-a84a1d337f23','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Visualisasi bangun ruang','belajar-matematika-kelas-6-unit-5',6,'C','Bab 5','sedang','draft',12,'{"summary":"Visualisasi bangun ruang. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan visualisasi bangun ruang dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas VI","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-vi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan visualisasi bangun ruang dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar visualisasi bangun ruang. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Sisi bangun ruang. Permukaan pembatas bangun ruang. Contoh: Kubus memiliki enam sisi persegi"},{"type":"text","body":"2. Rusuk. Pertemuan dua sisi berupa ruas garis. Contoh: Dua sisi kotak bertemu pada sebuah tepi"},{"type":"text","body":"3. Titik sudut. Pertemuan beberapa rusuk. Contoh: Pojok kotak merupakan titik sudut"},{"type":"text","body":"4. Jaring-jaring. Susunan bangun datar yang dapat dilipat membentuk bangun ruang. Contoh: Enam persegi tersusun tepat dapat membentuk kubus"},{"type":"text","body":"5. Tampak bangun. Gambar bangun dari arah pandang tertentu. Contoh: Kotak dapat dilihat dari depan atau atas"},{"type":"text","body":"Contoh dan penalaran: Kubus dibatasi enam sisi persegi, memiliki 12 rusuk dan 8 titik sudut. Jaring-jaring perlu dapat dilipat menjadi bangun tanpa menumpuk sisi; enam persegi dengan susunan sembarang belum tentu membentuk kubus. Tampak depan, samping, dan atas dapat memperlihatkan informasi berbeda."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Gunakan kotak kemasan bersih untuk mengamati sisi, rusuk, dan titik sudut. Minta pendamping membuka sambungannya."},{"type":"text","body":"Rangkuman: Sisi bangun ruang: Permukaan pembatas bangun ruang; Rusuk: Pertemuan dua sisi berupa ruas garis; Titik sudut: Pertemuan beberapa rusuk; Jaring-jaring: Susunan bangun datar yang dapat dilipat membentuk bangun ruang; Tampak bangun: Gambar bangun dari arah pandang tertentu."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('21bb8cf6-40cc-54d7-9023-17089032364f','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Analisis data dan kemungkinan kejadian','belajar-matematika-kelas-6-unit-6',6,'C','Bab 6','sedang','draft',12,'{"summary":"Analisis data dan kemungkinan kejadian. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan analisis data dan kemungkinan kejadian dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Matematika untuk SD/MI Kelas VI","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-vi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan analisis data dan kemungkinan kejadian dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar analisis data dan kemungkinan kejadian. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Tabel. Penyajian data dalam baris dan kolom. Contoh: Jumlah pemilih dicatat menurut buah"},{"type":"text","body":"2. Diagram batang. Penyajian data dengan panjang batang sesuai banyaknya. Contoh: Batang lebih tinggi berarti jumlah lebih besar"},{"type":"text","body":"3. Frekuensi. Banyak kemunculan suatu nilai atau kategori. Contoh: Lima anak memilih mangga, frekuensinya lima"},{"type":"text","body":"4. Kesimpulan data. Pernyataan yang didukung catatan pengamatan. Contoh: Pilihan terbanyak ditentukan dari jumlah terbesar"},{"type":"text","body":"5. Kemungkinan. Ukuran atau gambaran peluang suatu kejadian. Contoh: Mengambil bola merah lebih mungkin jika jumlahnya lebih banyak"},{"type":"text","body":"Contoh dan penalaran: Modus adalah nilai yang muncul paling sering; pada 1, 2, 2, 6 modusnya 2. Rata-rata adalah jumlah dibagi banyak data dan jangkauan adalah terbesar dikurangi terkecil. Kejadian pasti selalu terjadi pada kondisi yang ditentukan, sedangkan kejadian mustahil tidak dapat terjadi pada kondisi itu. Kesimpulan tidak boleh melampaui data."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Baca data kecil, hitung ringkasannya, lalu bedakan kejadian mungkin dan pasti."},{"type":"text","body":"Rangkuman: Tabel: Penyajian data dalam baris dan kolom; Diagram batang: Penyajian data dengan panjang batang sesuai banyaknya; Frekuensi: Banyak kemunculan suatu nilai atau kategori; Kesimpulan data: Pernyataan yang didukung catatan pengamatan; Kemungkinan: Ukuran atau gambaran peluang suatu kejadian."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('7839e516-ff1e-551b-89c6-5ef4bf08f985','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Menyimak bunyi dan instruksi','belajar-bahasa-indonesia-kelas-1-unit-1',1,'A','Bab 1','dasar','draft',8,'{"summary":"Menyimak bunyi dan instruksi. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan menyimak bunyi dan instruksi dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Indonesia: Aku Bisa! (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-aku-bisa-untuk-sd-mi-kelas-i-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan menyimak bunyi dan instruksi dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar menyimak bunyi dan instruksi. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Menyimak. Mendengarkan dengan perhatian untuk memahami pesan. Contoh: Dina mendengar arahan sebelum bergerak"},{"type":"text","body":"2. Bunyi. Sesuatu yang dapat didengar. Contoh: Tepukan terdengar ketika dua telapak bertemu"},{"type":"text","body":"3. Sumber bunyi. Benda atau makhluk yang menghasilkan bunyi. Contoh: Bel berbunyi dari arah pintu"},{"type":"text","body":"4. Instruksi. Pesan tentang tindakan yang perlu dilakukan. Contoh: Guru berkata: ambil buku lalu duduk"},{"type":"text","body":"5. Urutan. Susunan langkah dari awal sampai akhir. Contoh: Buku diambil sebelum Dina duduk"},{"type":"text","body":"Contoh dan penalaran: Dina mendengar arahan sebelum bergerak Kita mengenal menyimak sebagai mendengarkan dengan perhatian untuk memahami pesan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Pendamping membunyikan tepukan dan menyampaikan dua instruksi pendek. Anak menirukan bunyi lalu melakukan instruksi sesuai urutan."},{"type":"text","body":"Rangkuman: Menyimak: Mendengarkan dengan perhatian untuk memahami pesan; Bunyi: Sesuatu yang dapat didengar; Sumber bunyi: Benda atau makhluk yang menghasilkan bunyi; Instruksi: Pesan tentang tindakan yang perlu dilakukan; Urutan: Susunan langkah dari awal sampai akhir."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('fece0e60-aa0a-550d-abc7-4982ef57662e','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Huruf dan suku kata','belajar-bahasa-indonesia-kelas-1-unit-2',1,'A','Bab 2','dasar','draft',8,'{"summary":"Huruf dan suku kata. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan huruf dan suku kata dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Indonesia: Aku Bisa! (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-aku-bisa-untuk-sd-mi-kelas-i-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan huruf dan suku kata dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar huruf dan suku kata. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Huruf. Lambang untuk menuliskan bunyi bahasa. Contoh: Kata buku ditulis dengan b, u, k, u"},{"type":"text","body":"2. Vokal. Huruf a, i, u, e, o. Contoh: Huruf u pada buku adalah vokal"},{"type":"text","body":"3. Konsonan. Huruf selain a, i, u, e, o. Contoh: Huruf b pada buku adalah konsonan"},{"type":"text","body":"4. Suku kata. Bagian kata yang diucapkan dalam satu ketukan. Contoh: Buku dapat ditepuk bu-ku"},{"type":"text","body":"5. Kata. Satuan bahasa yang mempunyai makna. Contoh: Kata buku menyebut benda untuk dibaca"},{"type":"text","body":"Contoh dan penalaran: Kata buku ditulis dengan b, u, k, u Kita mengenal huruf sebagai lambang untuk menuliskan bunyi bahasa. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat kartu huruf b, u, k, a. Rangkai bu-ku dan ba-ku sambil mengucapkan bunyinya bersama pendamping."},{"type":"text","body":"Rangkuman: Huruf: Lambang untuk menuliskan bunyi bahasa; Vokal: Huruf a, i, u, e, o; Konsonan: Huruf selain a, i, u, e, o; Suku kata: Bagian kata yang diucapkan dalam satu ketukan; Kata: Satuan bahasa yang mempunyai makna."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('dd317bcb-82f0-546d-92e1-ed5462834139','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Kosakata benda sekitar','belajar-bahasa-indonesia-kelas-1-unit-3',1,'A','Bab 3','dasar','draft',8,'{"summary":"Kosakata benda sekitar. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan kosakata benda sekitar dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Indonesia: Aku Bisa! (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-aku-bisa-untuk-sd-mi-kelas-i-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan kosakata benda sekitar dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar kosakata benda sekitar. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Nama benda. Kata untuk menyebut sesuatu. Contoh: Pensil adalah nama alat tulis"},{"type":"text","body":"2. Kegunaan. Manfaat atau fungsi suatu benda. Contoh: Pensil digunakan untuk menulis"},{"type":"text","body":"3. Ciri. Sifat yang membantu mengenali benda. Contoh: Penggaris itu panjang dan lurus"},{"type":"text","body":"4. Kosakata. Kumpulan kata yang diketahui atau digunakan. Contoh: Dina belajar kata mangkuk dan sendok"},{"type":"text","body":"5. Kalimat lisan. Rangkaian kata yang diucapkan untuk menyampaikan pesan. Contoh: Dina berkata: aku membawa buku"},{"type":"text","body":"Contoh dan penalaran: Pensil adalah nama alat tulis Kita mengenal nama benda sebagai kata untuk menyebut sesuatu. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Amati lima benda yang aman. Sebut namanya, kegunaannya, lalu gunakan satu nama dalam kalimat lisan."},{"type":"text","body":"Rangkuman: Nama benda: Kata untuk menyebut sesuatu; Kegunaan: Manfaat atau fungsi suatu benda; Ciri: Sifat yang membantu mengenali benda; Kosakata: Kumpulan kata yang diketahui atau digunakan; Kalimat lisan: Rangkaian kata yang diucapkan untuk menyampaikan pesan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('bb3288a5-b188-5c66-82f2-94ec63d3629f','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Membaca kata dan kalimat pendek','belajar-bahasa-indonesia-kelas-1-unit-4',1,'A','Bab 4','sedang','draft',8,'{"summary":"Membaca kata dan kalimat pendek. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan membaca kata dan kalimat pendek dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Indonesia: Aku Bisa! (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-aku-bisa-untuk-sd-mi-kelas-i-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan membaca kata dan kalimat pendek dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar membaca kata dan kalimat pendek. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Membaca kata. Mengenali tulisan dan memahami maknanya. Contoh: Lani membaca kata bola"},{"type":"text","body":"2. Spasi. Jarak yang memisahkan kata dalam tulisan. Contoh: Aku dan makan dipisahkan jarak"},{"type":"text","body":"3. Kalimat. Rangkaian kata yang menyampaikan gagasan. Contoh: Lani punya bola menyampaikan sebuah pesan"},{"type":"text","body":"4. Titik. Tanda akhir kalimat berita. Contoh: Kalimat Bola itu biru diakhiri titik"},{"type":"text","body":"5. Informasi bacaan. Keterangan yang dapat ditemukan pada teks. Contoh: Dari bacaan, warna bola Lani adalah biru"},{"type":"text","body":"Contoh dan penalaran: Lani membaca kata bola Kita mengenal membaca kata sebagai mengenali tulisan dan memahami maknanya. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Baca bersama: “Lani punya bola. Bola Lani biru.” Tunjuk setiap kata, lalu ceritakan kembali tanpa menebak dari gambar saja."},{"type":"text","body":"Rangkuman: Membaca kata: Mengenali tulisan dan memahami maknanya; Spasi: Jarak yang memisahkan kata dalam tulisan; Kalimat: Rangkaian kata yang menyampaikan gagasan; Titik: Tanda akhir kalimat berita; Informasi bacaan: Keterangan yang dapat ditemukan pada teks."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('445d088a-0515-51c1-8cfa-1dfc3138c2c7','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Bercerita tentang diri','belajar-bahasa-indonesia-kelas-1-unit-5',1,'A','Bab 5','sedang','draft',8,'{"summary":"Bercerita tentang diri. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan bercerita tentang diri dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Indonesia: Aku Bisa! (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-aku-bisa-untuk-sd-mi-kelas-i-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan bercerita tentang diri dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar bercerita tentang diri. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Perkenalan. Mengenalkan diri kepada orang lain. Contoh: Rani menyebut nama panggilannya"},{"type":"text","body":"2. Nama panggilan. Nama yang biasa digunakan untuk menyapa seseorang. Contoh: Teman-teman memanggilnya Rani"},{"type":"text","body":"3. Kesukaan. Hal yang disenangi seseorang. Contoh: Rani suka menggambar bunga"},{"type":"text","body":"4. Perasaan. Keadaan yang dirasakan dalam hati. Contoh: Rani merasa senang bermain bersama"},{"type":"text","body":"5. Bergiliran bicara. Memberi kesempatan orang lain berbicara. Contoh: Rani menunggu Bima selesai berbicara"},{"type":"text","body":"Contoh dan penalaran: Rani menyebut nama panggilannya Kita mengenal perkenalan sebagai mengenalkan diri kepada orang lain. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Perkenalkan diri memakai nama panggilan, hal yang disukai, dan perasaan. Tidak perlu menyebut alamat atau nomor telepon."},{"type":"text","body":"Rangkuman: Perkenalan: Mengenalkan diri kepada orang lain; Nama panggilan: Nama yang biasa digunakan untuk menyapa seseorang; Kesukaan: Hal yang disenangi seseorang; Perasaan: Keadaan yang dirasakan dalam hati; Bergiliran bicara: Memberi kesempatan orang lain berbicara."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('e3fae743-bb79-5608-9804-46e82b6ab937','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Menulis kalimat sederhana','belajar-bahasa-indonesia-kelas-1-unit-6',1,'A','Bab 6','sedang','draft',8,'{"summary":"Menulis kalimat sederhana. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan menulis kalimat sederhana dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Indonesia: Aku Bisa! (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-aku-bisa-untuk-sd-mi-kelas-i-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan menulis kalimat sederhana dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar menulis kalimat sederhana. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Huruf kapital. Huruf besar yang digunakan pada awal kalimat dan nama orang. Contoh: Nama Lani diawali huruf L besar"},{"type":"text","body":"2. Awal kalimat. Bagian pertama suatu kalimat. Contoh: Kata pertama pada Aku membaca diawali huruf besar"},{"type":"text","body":"3. Spasi antarkata. Jarak untuk membedakan kata satu dengan lainnya. Contoh: Dua kata buku baru tidak ditulis menyatu"},{"type":"text","body":"4. Tanda titik. Tanda yang mengakhiri kalimat berita. Contoh: Aku membawa tas diakhiri titik"},{"type":"text","body":"5. Membaca ulang. Memeriksa tulisan dengan membacanya kembali. Contoh: Lani menemukan kata yang belum lengkap setelah mengecek tulisannya"},{"type":"text","body":"Contoh dan penalaran: Nama Lani diawali huruf L besar Kita mengenal huruf kapital sebagai huruf besar yang digunakan pada awal kalimat dan nama orang. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Tuliskan satu kalimat tentang benda di meja. Periksa huruf pertama, jarak antarkata, dan tanda akhirnya."},{"type":"text","body":"Rangkuman: Huruf kapital: Huruf besar yang digunakan pada awal kalimat dan nama orang; Awal kalimat: Bagian pertama suatu kalimat; Spasi antarkata: Jarak untuk membedakan kata satu dengan lainnya; Tanda titik: Tanda yang mengakhiri kalimat berita; Membaca ulang: Memeriksa tulisan dengan membacanya kembali."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('b79f8ab4-7995-5c42-886d-736a76ab7c07','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Menyimak cerita pendek','belajar-bahasa-indonesia-kelas-2-unit-1',2,'A','Bab 1','dasar','draft',8,'{"summary":"Menyimak cerita pendek. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan menyimak cerita pendek dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Indonesia: Keluargaku Unik (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-keluargaku-unik-untuk-sd-mi-kelas-ii-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan menyimak cerita pendek dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar menyimak cerita pendek. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Tokoh. Pelaku yang ada dalam cerita. Contoh: Raka menolong Sita dalam cerita"},{"type":"text","body":"2. Tempat. Lokasi terjadinya cerita. Contoh: Raka dan Sita berada di halaman sekolah"},{"type":"text","body":"3. Kejadian. Peristiwa yang dialami tokoh. Contoh: Buku Sita jatuh saat berjalan"},{"type":"text","body":"4. Pesan cerita. Pelajaran yang dapat dipahami dari cerita. Contoh: Raka membantu tanpa mengejek temannya"},{"type":"text","body":"5. Menceritakan kembali. Mengungkapkan isi cerita dengan bahasa sendiri. Contoh: Anak menjelaskan kembali pertolongan Raka"},{"type":"text","body":"Contoh dan penalaran: Raka menolong Sita dalam cerita Kita mengenal tokoh sebagai pelaku yang ada dalam cerita. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Pendamping membacakan cerita tiga kalimat tentang anak yang menolong teman. Anak menyebut tokoh, kejadian awal, dan akhirnya."},{"type":"text","body":"Rangkuman: Tokoh: Pelaku yang ada dalam cerita; Tempat: Lokasi terjadinya cerita; Kejadian: Peristiwa yang dialami tokoh; Pesan cerita: Pelajaran yang dapat dipahami dari cerita; Menceritakan kembali: Mengungkapkan isi cerita dengan bahasa sendiri."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('d9e0e053-017a-5240-8e9e-4bbdc8e5fecc','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Membaca lancar bertahap','belajar-bahasa-indonesia-kelas-2-unit-2',2,'A','Bab 2','dasar','draft',8,'{"summary":"Membaca lancar bertahap. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan membaca lancar bertahap dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Indonesia: Keluargaku Unik (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-keluargaku-unik-untuk-sd-mi-kelas-ii-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan membaca lancar bertahap dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar membaca lancar bertahap. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Lafal. Cara mengucapkan bunyi kata. Contoh: Kata meja diucapkan dengan bunyi yang jelas"},{"type":"text","body":"2. Jeda. Berhenti sejenak saat membaca. Contoh: Pembaca berhenti sebentar pada akhir kalimat"},{"type":"text","body":"3. Kelancaran. Membaca dengan aliran yang wajar sambil memahami. Contoh: Anak menghubungkan kata menjadi kalimat bermakna"},{"type":"text","body":"4. Makna. Arti yang disampaikan kata atau kalimat. Contoh: Anak memahami isi tulisan, bukan hanya menyuarakannya"},{"type":"text","body":"5. Mengulang bacaan. Membaca kembali agar pemahaman bertambah. Contoh: Anak kembali ke kalimat yang belum jelas"},{"type":"text","body":"Contoh dan penalaran: Kata meja diucapkan dengan bunyi yang jelas Kita mengenal lafal sebagai cara mengucapkan bunyi kata. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Pilih bacaan pendek. Baca perlahan, berhenti pada tanda titik, lalu ceritakan maknanya. Kecepatan bukan satu-satunya tujuan."},{"type":"text","body":"Rangkuman: Lafal: Cara mengucapkan bunyi kata; Jeda: Berhenti sejenak saat membaca; Kelancaran: Membaca dengan aliran yang wajar sambil memahami; Makna: Arti yang disampaikan kata atau kalimat; Mengulang bacaan: Membaca kembali agar pemahaman bertambah."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('9029a979-0c9a-5f51-bf57-b11f6ef2a0ee','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Kalimat tanya dan tanda baca','belajar-bahasa-indonesia-kelas-2-unit-3',2,'A','Bab 3','dasar','draft',8,'{"summary":"Kalimat tanya dan tanda baca. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan kalimat tanya dan tanda baca dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Indonesia: Keluargaku Unik (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-keluargaku-unik-untuk-sd-mi-kelas-ii-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan kalimat tanya dan tanda baca dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar kalimat tanya dan tanda baca. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Apa. Kata tanya untuk benda atau suatu hal. Contoh: Apa yang kamu bawa menanyakan barang bawaan"},{"type":"text","body":"2. Siapa. Kata tanya untuk orang. Contoh: Siapa yang meminjam buku menanyakan pelakunya"},{"type":"text","body":"3. Di mana. Kata tanya untuk tempat. Contoh: Di mana kamu membaca menanyakan lokasi"},{"type":"text","body":"4. Tanda tanya. Tanda akhir untuk kalimat pertanyaan langsung. Contoh: Siapa namamu diakhiri tanda tanya"},{"type":"text","body":"5. Jawaban sesuai. Tanggapan yang menjawab hal yang ditanyakan. Contoh: Pertanyaan tempat dijawab dengan nama lokasi"},{"type":"text","body":"Contoh dan penalaran: Apa yang kamu bawa menanyakan barang bawaan Kita mengenal apa sebagai kata tanya untuk benda atau suatu hal. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat pertanyaan dengan apa, siapa, dan di mana. Pasanganmu menjawab berdasarkan benda atau cerita yang sama."},{"type":"text","body":"Rangkuman: Apa: Kata tanya untuk benda atau suatu hal; Siapa: Kata tanya untuk orang; Di mana: Kata tanya untuk tempat; Tanda tanya: Tanda akhir untuk kalimat pertanyaan langsung; Jawaban sesuai: Tanggapan yang menjawab hal yang ditanyakan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('7fff0678-9280-562e-9d93-5af7094ff6f3','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Mengurutkan kejadian','belajar-bahasa-indonesia-kelas-2-unit-4',2,'A','Bab 4','sedang','draft',8,'{"summary":"Mengurutkan kejadian. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan mengurutkan kejadian dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Indonesia: Keluargaku Unik (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-keluargaku-unik-untuk-sd-mi-kelas-ii-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan mengurutkan kejadian dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar mengurutkan kejadian. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Awal. Bagian pertama rangkaian kejadian. Contoh: Benih disiapkan sebelum ditanam"},{"type":"text","body":"2. Kemudian. Penghubung untuk kejadian berikutnya. Contoh: Setelah tanah disiapkan, kemudian benih ditanam"},{"type":"text","body":"3. Akhir. Bagian penutup rangkaian kejadian. Contoh: Tanaman dirawat setelah benih tumbuh"},{"type":"text","body":"4. Urutan waktu. Susunan kejadian berdasarkan kapan terjadinya. Contoh: Menyiram dilakukan setelah benih ditanam"},{"type":"text","body":"5. Sebab. Alasan suatu kejadian terjadi. Contoh: Tanaman layu karena tidak mendapat air yang cukup"},{"type":"text","body":"Contoh dan penalaran: Benih disiapkan sebelum ditanam Kita mengenal awal sebagai bagian pertama rangkaian kejadian. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Susun tiga gambar kegiatan menanam. Ceritakan memakai kata mula-mula, kemudian, dan akhirnya."},{"type":"text","body":"Rangkuman: Awal: Bagian pertama rangkaian kejadian; Kemudian: Penghubung untuk kejadian berikutnya; Akhir: Bagian penutup rangkaian kejadian; Urutan waktu: Susunan kejadian berdasarkan kapan terjadinya; Sebab: Alasan suatu kejadian terjadi."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('68682f40-cf54-5c8f-b563-33895606ee11','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Mendeskripsikan keluarga dan lingkungan','belajar-bahasa-indonesia-kelas-2-unit-5',2,'A','Bab 5','sedang','draft',8,'{"summary":"Mendeskripsikan keluarga dan lingkungan. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan mendeskripsikan keluarga dan lingkungan dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Indonesia: Keluargaku Unik (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-keluargaku-unik-untuk-sd-mi-kelas-ii-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan mendeskripsikan keluarga dan lingkungan dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar mendeskripsikan keluarga dan lingkungan. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Deskripsi. Penjelasan ciri sesuatu agar dapat dibayangkan. Contoh: Ruang baca itu terang dengan dua rak buku"},{"type":"text","body":"2. Ciri teramati. Sifat yang dapat dikenali dari pengamatan. Contoh: Warna pintu yang terlihat adalah hijau"},{"type":"text","body":"3. Kata sifat. Kata yang menjelaskan keadaan atau sifat. Contoh: Bersih menjelaskan keadaan meja"},{"type":"text","body":"4. Rincian. Keterangan tambahan yang membuat gambaran lebih jelas. Contoh: Di sudut ruang ada pot kecil"},{"type":"text","body":"5. Kalimat deskripsi. Kalimat yang menjelaskan sifat atau keadaan objek. Contoh: Meja itu bundar dan berwarna cokelat"},{"type":"text","body":"Contoh dan penalaran: Ruang baca itu terang dengan dua rak buku Kita mengenal deskripsi sebagai penjelasan ciri sesuatu agar dapat dibayangkan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Deskripsikan ruang yang kamu kenal dengan dua ciri yang dapat diamati. Jangan membagikan alamat rumah."},{"type":"text","body":"Rangkuman: Deskripsi: Penjelasan ciri sesuatu agar dapat dibayangkan; Ciri teramati: Sifat yang dapat dikenali dari pengamatan; Kata sifat: Kata yang menjelaskan keadaan atau sifat; Rincian: Keterangan tambahan yang membuat gambaran lebih jelas; Kalimat deskripsi: Kalimat yang menjelaskan sifat atau keadaan objek."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('e6d8290e-2177-5638-a1fb-6dc6f625bc31','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Menulis pengalaman singkat','belajar-bahasa-indonesia-kelas-2-unit-6',2,'A','Bab 6','sedang','draft',8,'{"summary":"Menulis pengalaman singkat. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan menulis pengalaman singkat dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Indonesia: Keluargaku Unik (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-keluargaku-unik-untuk-sd-mi-kelas-ii-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan menulis pengalaman singkat dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar menulis pengalaman singkat. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Pengalaman. Peristiwa yang pernah dialami seseorang. Contoh: Dina pernah membantu menanam di sekolah"},{"type":"text","body":"2. Pelaku. Orang yang melakukan suatu tindakan. Contoh: Dina menyiram bibit dalam pengalaman itu"},{"type":"text","body":"3. Kegiatan. Tindakan yang dilakukan dalam suatu peristiwa. Contoh: Menyiram merupakan kegiatan Dina"},{"type":"text","body":"4. Perasaan. Keadaan hati yang dapat diceritakan. Contoh: Dina senang melihat bibit tumbuh"},{"type":"text","body":"5. Penutup. Bagian akhir yang melengkapi cerita. Contoh: Dina menulis harapannya agar tanaman tetap sehat"},{"type":"text","body":"Contoh dan penalaran: Dina pernah membantu menanam di sekolah Kita mengenal pengalaman sebagai peristiwa yang pernah dialami seseorang. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Tulis tiga kalimat tentang pengalaman aman yang kamu pilih. Sebut awal, tindakanmu, dan perasaan setelahnya."},{"type":"text","body":"Rangkuman: Pengalaman: Peristiwa yang pernah dialami seseorang; Pelaku: Orang yang melakukan suatu tindakan; Kegiatan: Tindakan yang dilakukan dalam suatu peristiwa; Perasaan: Keadaan hati yang dapat diceritakan; Penutup: Bagian akhir yang melengkapi cerita."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('3f99a601-ca22-5831-b633-f4811cf9f5ff','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Informasi penting dalam bacaan','belajar-bahasa-indonesia-kelas-3-unit-1',3,'B','Bab 1','dasar','draft',12,'{"summary":"Informasi penting dalam bacaan. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan informasi penting dalam bacaan dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Indonesia: Kawan Seiring (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-kawan-seiring-untuk-sdmi-kelas-iii-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan informasi penting dalam bacaan dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar informasi penting dalam bacaan. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Informasi penting. Keterangan yang diperlukan untuk memahami isi teks. Contoh: Waktu dan tempat diperlukan untuk mengikuti kegiatan"},{"type":"text","body":"2. Kata kunci. Kata yang membantu menemukan gagasan atau informasi. Contoh: Kata perpustakaan membantu mencari lokasi kegiatan"},{"type":"text","body":"3. Pertanyaan penuntun. Pertanyaan untuk mengarahkan pencarian informasi. Contoh: Apa, siapa, kapan, di mana membantu membaca pengumuman"},{"type":"text","body":"4. Bukti teks. Bagian bacaan yang mendukung jawaban. Contoh: Anak menunjuk kalimat jadwal untuk menjelaskan jawabannya"},{"type":"text","body":"5. Mencatat ringkas. Menulis keterangan utama tanpa menyalin seluruh bacaan. Contoh: Anak membuat catatan tiga poin tentang pengumuman"},{"type":"text","body":"Contoh dan penalaran: Waktu dan tempat diperlukan untuk mengikuti kegiatan Kita mengenal informasi penting sebagai keterangan yang diperlukan untuk memahami isi teks. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Baca pengumuman kegiatan membaca. Garisbawahi kegiatan, waktu, tempat, dan siapa yang dapat ikut."},{"type":"text","body":"Rangkuman: Informasi penting: Keterangan yang diperlukan untuk memahami isi teks; Kata kunci: Kata yang membantu menemukan gagasan atau informasi; Pertanyaan penuntun: Pertanyaan untuk mengarahkan pencarian informasi; Bukti teks: Bagian bacaan yang mendukung jawaban; Mencatat ringkas: Menulis keterangan utama tanpa menyalin seluruh bacaan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('174e336d-919c-5ff0-8b7f-00436494c6ed','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Tokoh dan urutan cerita','belajar-bahasa-indonesia-kelas-3-unit-2',3,'B','Bab 2','dasar','draft',12,'{"summary":"Tokoh dan urutan cerita. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan tokoh dan urutan cerita dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Indonesia: Kawan Seiring (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-kawan-seiring-untuk-sdmi-kelas-iii-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan tokoh dan urutan cerita dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar tokoh dan urutan cerita. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Tokoh utama. Tokoh yang menjadi pusat cerita. Contoh: Perjalanan Sari paling banyak diceritakan"},{"type":"text","body":"2. Masalah cerita. Keadaan yang perlu diatasi tokoh. Contoh: Sari kehilangan petunjuk menuju taman"},{"type":"text","body":"3. Usaha tokoh. Tindakan untuk menghadapi masalah. Contoh: Sari bertanya dengan sopan kepada penjaga"},{"type":"text","body":"4. Urutan peristiwa. Hubungan kejadian dari awal hingga akhir. Contoh: Sari mencari jalan sebelum tiba di taman"},{"type":"text","body":"5. Akhir cerita. Keadaan tokoh setelah rangkaian peristiwa. Contoh: Sari akhirnya menemukan tempat yang dituju"},{"type":"text","body":"Contoh dan penalaran: Perjalanan Sari paling banyak diceritakan Kita mengenal tokoh utama sebagai tokoh yang menjadi pusat cerita. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Baca cerita pendek. Buat empat kotak berisi tokoh, masalah, usaha tokoh, dan akhir cerita."},{"type":"text","body":"Rangkuman: Tokoh utama: Tokoh yang menjadi pusat cerita; Masalah cerita: Keadaan yang perlu diatasi tokoh; Usaha tokoh: Tindakan untuk menghadapi masalah; Urutan peristiwa: Hubungan kejadian dari awal hingga akhir; Akhir cerita: Keadaan tokoh setelah rangkaian peristiwa."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('e2254e13-bd23-5d2c-b690-374e889fd416','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Kosakata dan kalimat efektif','belajar-bahasa-indonesia-kelas-3-unit-3',3,'B','Bab 3','dasar','draft',12,'{"summary":"Kosakata dan kalimat efektif. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan kosakata dan kalimat efektif dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Indonesia: Kawan Seiring (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-kawan-seiring-untuk-sdmi-kelas-iii-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan kosakata dan kalimat efektif dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar kosakata dan kalimat efektif. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Makna dalam konteks. Arti kata yang sesuai dengan kalimat tempatnya digunakan. Contoh: Bisa pada kalimat ular berbisa bermakna racun"},{"type":"text","body":"2. Sinonim. Kata yang memiliki makna mirip dalam konteks tertentu. Contoh: Senang dan gembira mempunyai makna mirip"},{"type":"text","body":"3. Antonim. Kata yang memiliki makna berlawanan. Contoh: Panjang berlawanan dengan pendek"},{"type":"text","body":"4. Kalimat efektif. Kalimat jelas dan hemat tanpa kata yang tidak perlu. Contoh: Para siswa membaca lebih hemat daripada para siswa-siswa membaca"},{"type":"text","body":"5. Kata rujukan. Kata yang merujuk bagian lain dalam teks. Contoh: Ia dapat merujuk nama tokoh yang disebut sebelumnya"},{"type":"text","body":"Contoh dan penalaran: Bisa pada kalimat ular berbisa bermakna racun Kita mengenal makna dalam konteks sebagai arti kata yang sesuai dengan kalimat tempatnya digunakan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Pilih tiga kata baru dari bacaan. Cari petunjuk maknanya, lalu susun satu kalimat yang jelas untuk tiap kata."},{"type":"text","body":"Rangkuman: Makna dalam konteks: Arti kata yang sesuai dengan kalimat tempatnya digunakan; Sinonim: Kata yang memiliki makna mirip dalam konteks tertentu; Antonim: Kata yang memiliki makna berlawanan; Kalimat efektif: Kalimat jelas dan hemat tanpa kata yang tidak perlu; Kata rujukan: Kata yang merujuk bagian lain dalam teks."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('a6b00ffe-d4f2-5a80-be76-0af3403520cd','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Petunjuk dan prosedur sederhana','belajar-bahasa-indonesia-kelas-3-unit-4',3,'B','Bab 4','sedang','draft',12,'{"summary":"Petunjuk dan prosedur sederhana. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan petunjuk dan prosedur sederhana dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Indonesia: Kawan Seiring (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-kawan-seiring-untuk-sdmi-kelas-iii-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan petunjuk dan prosedur sederhana dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar petunjuk dan prosedur sederhana. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Tujuan prosedur. Hasil yang ingin dicapai melalui langkah-langkah. Contoh: Petunjuk dibuat agar buku dipinjam dengan tertib"},{"type":"text","body":"2. Langkah kerja. Tindakan berurutan untuk mencapai tujuan. Contoh: Memilih buku dilakukan sebelum mencatat peminjaman"},{"type":"text","body":"3. Kalimat perintah. Kalimat yang mengarahkan suatu tindakan. Contoh: Tuliskan judul buku meminta pembaca melakukan tindakan"},{"type":"text","body":"4. Urutan logis. Susunan langkah yang dapat dilaksanakan dengan masuk akal. Contoh: Buku dikembalikan setelah digunakan"},{"type":"text","body":"5. Pemeriksaan petunjuk. Mencoba langkah untuk menemukan bagian yang perlu diperjelas. Contoh: Teman menguji apakah instruksi dapat diikuti"},{"type":"text","body":"Contoh dan penalaran: Petunjuk dibuat agar buku dipinjam dengan tertib Kita mengenal tujuan prosedur sebagai hasil yang ingin dicapai melalui langkah-langkah. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Tuliskan petunjuk meminjam buku dalam empat langkah. Minta teman mencobanya dan tandai bagian yang belum jelas."},{"type":"text","body":"Rangkuman: Tujuan prosedur: Hasil yang ingin dicapai melalui langkah-langkah; Langkah kerja: Tindakan berurutan untuk mencapai tujuan; Kalimat perintah: Kalimat yang mengarahkan suatu tindakan; Urutan logis: Susunan langkah yang dapat dilaksanakan dengan masuk akal; Pemeriksaan petunjuk: Mencoba langkah untuk menemukan bagian yang perlu diperjelas."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('b529bb53-b048-59fa-89e0-dcf6dbd8ad6f','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Percakapan dan tanggapan santun','belajar-bahasa-indonesia-kelas-3-unit-5',3,'B','Bab 5','sedang','draft',12,'{"summary":"Percakapan dan tanggapan santun. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan percakapan dan tanggapan santun dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Indonesia: Kawan Seiring (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-kawan-seiring-untuk-sdmi-kelas-iii-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan percakapan dan tanggapan santun dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar percakapan dan tanggapan santun. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Sapaan. Ungkapan untuk menyapa lawan bicara. Contoh: Selamat pagi digunakan saat mulai berbicara pada pagi hari"},{"type":"text","body":"2. Permintaan santun. Permintaan yang menghargai hak orang lain. Contoh: Bolehkah aku meminjam pensilmu memberi kesempatan menjawab"},{"type":"text","body":"3. Tanggapan sesuai. Jawaban yang berkaitan dengan ucapan sebelumnya. Contoh: Permintaan izin ditanggapi dengan izin atau alasan penolakan"},{"type":"text","body":"4. Mendengarkan giliran. Memperhatikan pembicara tanpa memotong. Contoh: Anak menunggu temannya selesai menjelaskan"},{"type":"text","body":"5. Penolakan santun. Menolak dengan bahasa hormat tanpa merendahkan. Contoh: Maaf, alat ini masih kupakai menyampaikan batas dengan sopan"},{"type":"text","body":"Contoh dan penalaran: Selamat pagi digunakan saat mulai berbicara pada pagi hari Kita mengenal sapaan sebagai ungkapan untuk menyapa lawan bicara. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Latih percakapan meminjam alat. Satu anak meminta, satu menjawab, lalu keduanya bertukar peran."},{"type":"text","body":"Rangkuman: Sapaan: Ungkapan untuk menyapa lawan bicara; Permintaan santun: Permintaan yang menghargai hak orang lain; Tanggapan sesuai: Jawaban yang berkaitan dengan ucapan sebelumnya; Mendengarkan giliran: Memperhatikan pembicara tanpa memotong; Penolakan santun: Menolak dengan bahasa hormat tanpa merendahkan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('a6196ba2-e204-5040-9759-5ec2a0a31d82','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Paragraf pengalaman','belajar-bahasa-indonesia-kelas-3-unit-6',3,'B','Bab 6','sedang','draft',12,'{"summary":"Paragraf pengalaman. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan paragraf pengalaman dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Indonesia: Kawan Seiring (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-kawan-seiring-untuk-sdmi-kelas-iii-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan paragraf pengalaman dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar paragraf pengalaman. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Paragraf. Kelompok kalimat yang membahas satu gagasan. Contoh: Beberapa kalimat menceritakan kegiatan menanam"},{"type":"text","body":"2. Gagasan utama. Pokok yang dibahas dalam paragraf. Contoh: Paragraf membahas cara kelas merawat tanaman"},{"type":"text","body":"3. Rincian pendukung. Keterangan yang menjelaskan pokok paragraf. Contoh: Jadwal menyiram mendukung cerita perawatan"},{"type":"text","body":"4. Keterkaitan kalimat. Hubungan antarkalimat yang membuat paragraf padu. Contoh: Setiap kalimat tetap membahas kegiatan yang sama"},{"type":"text","body":"5. Revisi. Perubahan untuk memperjelas isi tulisan. Contoh: Penulis menambah keterangan yang sebelumnya belum ada"},{"type":"text","body":"Contoh dan penalaran: Beberapa kalimat menceritakan kegiatan menanam Kita mengenal paragraf sebagai kelompok kalimat yang membahas satu gagasan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Tuliskan satu paragraf pengalaman dengan satu gagasan utama dan tiga rincian. Minta pendamping menunjukkan bagian yang belum jelas."},{"type":"text","body":"Rangkuman: Paragraf: Kelompok kalimat yang membahas satu gagasan; Gagasan utama: Pokok yang dibahas dalam paragraf; Rincian pendukung: Keterangan yang menjelaskan pokok paragraf; Keterkaitan kalimat: Hubungan antarkalimat yang membuat paragraf padu; Revisi: Perubahan untuk memperjelas isi tulisan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('2e5b7f36-134d-51e6-b1b9-d97816dcfd53','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Gagasan pokok dan pendukung','belajar-bahasa-indonesia-kelas-4-unit-1',4,'B','Bab 1','dasar','draft',12,'{"summary":"Gagasan pokok dan pendukung. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan gagasan pokok dan pendukung dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Bahasa Indonesia: Lihat Sekitar (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-bahasa-indonesia-lihat-sekitar-untuk-sd-mi-kelas-iv-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan gagasan pokok dan pendukung dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar gagasan pokok dan pendukung. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Gagasan pokok. Inti pembahasan suatu paragraf. Contoh: Paragraf menjelaskan manfaat perpustakaan"},{"type":"text","body":"2. Gagasan pendukung. Keterangan yang menjelaskan gagasan pokok. Contoh: Contoh peminjaman buku memperjelas manfaatnya"},{"type":"text","body":"3. Kalimat utama. Kalimat yang menyatakan pokok paragraf jika ditulis secara jelas. Contoh: Penulis menyatakan inti sebelum memberi contoh"},{"type":"text","body":"4. Kaitan rincian. Hubungan informasi tambahan dengan pokok bahasan. Contoh: Rincian tentang buku tetap berkaitan dengan perpustakaan"},{"type":"text","body":"5. Merumuskan inti. Menyatakan pokok isi memakai kata sendiri. Contoh: Pembaca merangkum topik paragraf dalam satu kalimat"},{"type":"text","body":"Contoh dan penalaran: Paragraf menjelaskan manfaat perpustakaan Kita mengenal gagasan pokok sebagai inti pembahasan suatu paragraf. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Baca paragraf tentang perpustakaan. Tulis gagasan pokok dan dua rincian yang benar-benar mendukungnya."},{"type":"text","body":"Rangkuman: Gagasan pokok: Inti pembahasan suatu paragraf; Gagasan pendukung: Keterangan yang menjelaskan gagasan pokok; Kalimat utama: Kalimat yang menyatakan pokok paragraf jika ditulis secara jelas; Kaitan rincian: Hubungan informasi tambahan dengan pokok bahasan; Merumuskan inti: Menyatakan pokok isi memakai kata sendiri."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('f2edfd13-4955-5043-aeec-eb1f712a47da','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Narasi dan deskripsi','belajar-bahasa-indonesia-kelas-4-unit-2',4,'B','Bab 2','dasar','draft',12,'{"summary":"Narasi dan deskripsi. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan narasi dan deskripsi dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Bahasa Indonesia: Lihat Sekitar (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-bahasa-indonesia-lihat-sekitar-untuk-sd-mi-kelas-iv-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan narasi dan deskripsi dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar narasi dan deskripsi. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Narasi. Teks yang menceritakan rangkaian kejadian. Contoh: Cerita perjalanan memuat awal, kejadian, dan akhir"},{"type":"text","body":"2. Deskripsi. Teks yang menggambarkan ciri suatu objek. Contoh: Gambaran taman menjelaskan warna dan letak tanaman"},{"type":"text","body":"3. Latar. Keterangan tempat, waktu, atau suasana dalam cerita. Contoh: Cerita berlangsung pada pagi hari di pasar"},{"type":"text","body":"4. Alur. Rangkaian peristiwa yang membentuk cerita. Contoh: Masalah muncul lalu tokoh berusaha menyelesaikannya"},{"type":"text","body":"5. Detail indrawi. Rincian berdasarkan penglihatan, pendengaran, atau indra lain. Contoh: Deskripsi menyebut bunyi gemericik air"},{"type":"text","body":"Contoh dan penalaran: Cerita perjalanan memuat awal, kejadian, dan akhir Kita mengenal narasi sebagai teks yang menceritakan rangkaian kejadian. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Tuliskan satu paragraf yang menceritakan kejadian dan satu yang menggambarkan tempat. Bandingkan tujuan keduanya."},{"type":"text","body":"Rangkuman: Narasi: Teks yang menceritakan rangkaian kejadian; Deskripsi: Teks yang menggambarkan ciri suatu objek; Latar: Keterangan tempat, waktu, atau suasana dalam cerita; Alur: Rangkaian peristiwa yang membentuk cerita; Detail indrawi: Rincian berdasarkan penglihatan, pendengaran, atau indra lain."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('07ce2322-7eb8-5be8-a947-f2fe6c1a63cb','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Teks petunjuk dan laporan pengamatan','belajar-bahasa-indonesia-kelas-4-unit-3',4,'B','Bab 3','dasar','draft',12,'{"summary":"Teks petunjuk dan laporan pengamatan. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan teks petunjuk dan laporan pengamatan dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Bahasa Indonesia: Lihat Sekitar (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-bahasa-indonesia-lihat-sekitar-untuk-sd-mi-kelas-iv-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan teks petunjuk dan laporan pengamatan dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar teks petunjuk dan laporan pengamatan. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Teks petunjuk. Teks yang membantu pembaca melakukan langkah tertentu. Contoh: Cara menyiram ditulis berurutan"},{"type":"text","body":"2. Laporan pengamatan. Teks yang menyampaikan hasil mengamati objek. Contoh: Laporan menyebut jumlah daun yang terlihat"},{"type":"text","body":"3. Fakta pengamatan. Informasi yang didukung hal yang benar-benar diamati. Contoh: Pengamat mencatat empat daun terbuka"},{"type":"text","body":"4. Urutan prosedur. Susunan tindakan agar tujuan tercapai. Contoh: Wadah disiapkan sebelum tanah dimasukkan"},{"type":"text","body":"5. Catatan objektif. Catatan yang memisahkan pengamatan dari dugaan pribadi. Contoh: Pengamat mencatat warna daun tanpa menebak penyebabnya"},{"type":"text","body":"Contoh dan penalaran: Cara menyiram ditulis berurutan Kita mengenal teks petunjuk sebagai teks yang membantu pembaca melakukan langkah tertentu. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Amati tanaman tanpa merusaknya. Pisahkan catatan hasil pengamatan dari petunjuk cara merawatnya."},{"type":"text","body":"Rangkuman: Teks petunjuk: Teks yang membantu pembaca melakukan langkah tertentu; Laporan pengamatan: Teks yang menyampaikan hasil mengamati objek; Fakta pengamatan: Informasi yang didukung hal yang benar-benar diamati; Urutan prosedur: Susunan tindakan agar tujuan tercapai; Catatan objektif: Catatan yang memisahkan pengamatan dari dugaan pribadi."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('2f86bef3-744d-5e0b-a246-552ea333f5a4','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Wawancara sederhana','belajar-bahasa-indonesia-kelas-4-unit-4',4,'B','Bab 4','sedang','draft',12,'{"summary":"Wawancara sederhana. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan wawancara sederhana dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Bahasa Indonesia: Lihat Sekitar (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-bahasa-indonesia-lihat-sekitar-untuk-sd-mi-kelas-iv-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan wawancara sederhana dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar wawancara sederhana. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Narasumber. Orang yang memberikan informasi dalam wawancara. Contoh: Penjaga perpustakaan menjawab pertanyaan siswa"},{"type":"text","body":"2. Pewawancara. Orang yang mengajukan pertanyaan wawancara. Contoh: Siswa menanyakan cara merawat buku"},{"type":"text","body":"3. Pertanyaan terbuka. Pertanyaan yang memberi ruang jawaban lebih dari ya atau tidak. Contoh: Bagaimana cara merawat buku mengundang penjelasan"},{"type":"text","body":"4. Catatan jawaban. Rekaman tertulis isi jawaban narasumber. Contoh: Siswa menuliskan inti penjelasan penjaga"},{"type":"text","body":"5. Mengonfirmasi. Memastikan kembali bahwa informasi dipahami dengan benar. Contoh: Siswa mengulang inti jawaban dan meminta kepastian"},{"type":"text","body":"Contoh dan penalaran: Penjaga perpustakaan menjawab pertanyaan siswa Kita mengenal narasumber sebagai orang yang memberikan informasi dalam wawancara. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Susun tiga pertanyaan tentang kebiasaan membaca. Wawancarai pendamping dengan izin, lalu catat jawabannya tanpa data pribadi."},{"type":"text","body":"Rangkuman: Narasumber: Orang yang memberikan informasi dalam wawancara; Pewawancara: Orang yang mengajukan pertanyaan wawancara; Pertanyaan terbuka: Pertanyaan yang memberi ruang jawaban lebih dari ya atau tidak; Catatan jawaban: Rekaman tertulis isi jawaban narasumber; Mengonfirmasi: Memastikan kembali bahwa informasi dipahami dengan benar."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('452b3933-bfe3-5a6c-bdc0-d89a281bac24','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Kosakata kiasan dalam konteks','belajar-bahasa-indonesia-kelas-4-unit-5',4,'B','Bab 5','sedang','draft',12,'{"summary":"Kosakata kiasan dalam konteks. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan kosakata kiasan dalam konteks dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Bahasa Indonesia: Lihat Sekitar (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-bahasa-indonesia-lihat-sekitar-untuk-sd-mi-kelas-iv-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan kosakata kiasan dalam konteks dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar kosakata kiasan dalam konteks. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Makna lugas. Makna yang langsung sesuai arti biasanya. Contoh: Tangan kanan sakit berarti anggota tubuh terasa sakit"},{"type":"text","body":"2. Makna kiasan. Makna yang berbeda dari arti harfiahnya. Contoh: Buah tangan dalam konteks oleh-oleh bukan buah dari tangan"},{"type":"text","body":"3. Konteks. Bagian teks atau situasi yang membantu menentukan makna. Contoh: Kalimat sekitar menjelaskan arti ungkapan"},{"type":"text","body":"4. Perbandingan. Cara menjelaskan kesamaan sifat dua hal. Contoh: Wajah cerah seperti matahari memakai perbandingan"},{"type":"text","body":"5. Petunjuk makna. Keterangan yang membantu menafsirkan kata. Contoh: Tindakan tokoh memperjelas maksud ungkapannya"},{"type":"text","body":"Contoh dan penalaran: Tangan kanan sakit berarti anggota tubuh terasa sakit Kita mengenal makna lugas sebagai makna yang langsung sesuai arti biasanya. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Temukan satu ungkapan kiasan pada bacaan. Jelaskan maknanya berdasarkan kalimat, bukan arti setiap kata saja."},{"type":"text","body":"Rangkuman: Makna lugas: Makna yang langsung sesuai arti biasanya; Makna kiasan: Makna yang berbeda dari arti harfiahnya; Konteks: Bagian teks atau situasi yang membantu menentukan makna; Perbandingan: Cara menjelaskan kesamaan sifat dua hal; Petunjuk makna: Keterangan yang membantu menafsirkan kata."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('8a498e3b-aea9-5fb1-a2d7-ebd156091b19','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Menyunting paragraf','belajar-bahasa-indonesia-kelas-4-unit-6',4,'B','Bab 6','sedang','draft',12,'{"summary":"Menyunting paragraf. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan menyunting paragraf dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Bahasa Indonesia: Lihat Sekitar (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-bahasa-indonesia-lihat-sekitar-untuk-sd-mi-kelas-iv-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan menyunting paragraf dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar menyunting paragraf. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Menyunting. Memperbaiki ketepatan bahasa dan penyajian tulisan. Contoh: Penulis membetulkan tanda baca pada draf"},{"type":"text","body":"2. Revisi isi. Mengubah gagasan atau rincian agar pesan lebih jelas. Contoh: Penulis menambah alasan yang belum dijelaskan"},{"type":"text","body":"3. Ejaan. Aturan penulisan huruf dan kata. Contoh: Nama orang ditulis dengan huruf kapital"},{"type":"text","body":"4. Tanda baca. Tanda yang membantu memahami susunan tulisan. Contoh: Koma membantu memisahkan unsur perincian"},{"type":"text","body":"5. Kepaduan. Keterhubungan bagian tulisan dalam satu gagasan. Contoh: Kalimat yang keluar topik diperbaiki agar sesuai"},{"type":"text","body":"Contoh dan penalaran: Penulis membetulkan tanda baca pada draf Kita mengenal menyunting sebagai memperbaiki ketepatan bahasa dan penyajian tulisan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Sunting paragraf pendek. Periksa isi dahulu, lalu ejaan dan tanda baca. Jelaskan alasan tiap perbaikan."},{"type":"text","body":"Rangkuman: Menyunting: Memperbaiki ketepatan bahasa dan penyajian tulisan; Revisi isi: Mengubah gagasan atau rincian agar pesan lebih jelas; Ejaan: Aturan penulisan huruf dan kata; Tanda baca: Tanda yang membantu memahami susunan tulisan; Kepaduan: Keterhubungan bagian tulisan dalam satu gagasan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('6696f99f-38aa-5c45-a88a-5b4ce3e8f36e','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Menyimpulkan informasi','belajar-bahasa-indonesia-kelas-5-unit-1',5,'C','Bab 1','dasar','draft',12,'{"summary":"Menyimpulkan informasi. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan menyimpulkan informasi dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Indonesia: Bergerak Bersama (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-bergerak-bersama-untuk-sd-mi-kelas-v-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan menyimpulkan informasi dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar menyimpulkan informasi. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Simpulan. Inti pemahaman yang disusun dari informasi teks. Contoh: Pembaca merumuskan hasil setelah menimbang seluruh keterangan"},{"type":"text","body":"2. Ringkasan. Penyajian singkat isi utama bacaan. Contoh: Pembaca memadatkan pokok tiap bagian tanpa mengubah maksud"},{"type":"text","body":"3. Informasi tersurat. Informasi yang dinyatakan langsung dalam teks. Contoh: Waktu kegiatan tertulis jelas dalam pengumuman"},{"type":"text","body":"4. Informasi tersirat. Informasi yang disimpulkan dari petunjuk teks. Contoh: Pembaca menafsirkan perasaan tokoh dari tindakan dan ucapannya"},{"type":"text","body":"5. Bukti pendukung. Keterangan yang menjadi dasar simpulan. Contoh: Pembaca menunjuk dua fakta yang sesuai dengan simpulannya"},{"type":"text","body":"Contoh dan penalaran: Pembaca merumuskan hasil setelah menimbang seluruh keterangan Kita mengenal simpulan sebagai inti pemahaman yang disusun dari informasi teks. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Baca teks informatif dua paragraf. Tulis simpulan dua kalimat dan tunjuk informasi yang mendukungnya."},{"type":"text","body":"Rangkuman: Simpulan: Inti pemahaman yang disusun dari informasi teks; Ringkasan: Penyajian singkat isi utama bacaan; Informasi tersurat: Informasi yang dinyatakan langsung dalam teks; Informasi tersirat: Informasi yang disimpulkan dari petunjuk teks; Bukti pendukung: Keterangan yang menjadi dasar simpulan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('d27ff7bc-b511-54a1-afa4-1174513f1fa4','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Unsur cerita dan sudut pandang','belajar-bahasa-indonesia-kelas-5-unit-2',5,'C','Bab 2','dasar','draft',12,'{"summary":"Unsur cerita dan sudut pandang. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan unsur cerita dan sudut pandang dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Indonesia: Bergerak Bersama (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-bergerak-bersama-untuk-sd-mi-kelas-v-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan unsur cerita dan sudut pandang dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar unsur cerita dan sudut pandang. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Penokohan. Cara sifat tokoh ditampilkan dalam cerita. Contoh: Tokoh tampak tekun karena terus berlatih"},{"type":"text","body":"2. Sudut pandang orang pertama. Penceritaan menggunakan aku atau saya sebagai pelaku. Contoh: Aku membuka pintu menempatkan pencerita di dalam cerita"},{"type":"text","body":"3. Sudut pandang orang ketiga. Penceritaan menggunakan nama atau ia sebagai tokoh. Contoh: Rani membuka pintu menceritakan tokoh dari luar"},{"type":"text","body":"4. Konflik. Pertentangan atau masalah yang menggerakkan cerita. Contoh: Tokoh harus memilih dua kegiatan pada waktu sama"},{"type":"text","body":"5. Bukti sifat tokoh. Ucapan atau tindakan yang mendukung penilaian sifat. Contoh: Tokoh mengembalikan barang yang ditemukan sehingga dinilai jujur"},{"type":"text","body":"Contoh dan penalaran: Tokoh tampak tekun karena terus berlatih Kita mengenal penokohan sebagai cara sifat tokoh ditampilkan dalam cerita. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Baca cerita lalu jelaskan sifat tokoh dengan bukti tindakan. Bandingkan cerita memakai aku dan ia."},{"type":"text","body":"Rangkuman: Penokohan: Cara sifat tokoh ditampilkan dalam cerita; Sudut pandang orang pertama: Penceritaan menggunakan aku atau saya sebagai pelaku; Sudut pandang orang ketiga: Penceritaan menggunakan nama atau ia sebagai tokoh; Konflik: Pertentangan atau masalah yang menggerakkan cerita; Bukti sifat tokoh: Ucapan atau tindakan yang mendukung penilaian sifat."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('24b92d6e-ee11-55a3-8762-c6e556d38107','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Fakta dan pendapat','belajar-bahasa-indonesia-kelas-5-unit-3',5,'C','Bab 3','dasar','draft',12,'{"summary":"Fakta dan pendapat. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan fakta dan pendapat dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Indonesia: Bergerak Bersama (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-bergerak-bersama-untuk-sd-mi-kelas-v-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan fakta dan pendapat dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar fakta dan pendapat. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Fakta. Pernyataan yang kebenarannya dapat diperiksa dengan bukti. Contoh: Jumlah kursi dapat dihitung langsung"},{"type":"text","body":"2. Pendapat. Penilaian atau pandangan seseorang. Contoh: Pernyataan bahwa suatu taman paling indah adalah penilaian"},{"type":"text","body":"3. Alasan. Dasar yang menjelaskan suatu pendapat. Contoh: Penulis menerangkan mengapa ia memilih kegiatan tertentu"},{"type":"text","body":"4. Sumber informasi. Asal keterangan yang dibaca atau didengar. Contoh: Jadwal resmi menjadi asal informasi waktu kegiatan"},{"type":"text","body":"5. Verifikasi. Pemeriksaan kebenaran memakai bukti yang relevan. Contoh: Pembaca memeriksa pengumuman asli sebelum menyebarkan kabar"},{"type":"text","body":"Contoh dan penalaran: Jumlah kursi dapat dihitung langsung Kita mengenal fakta sebagai pernyataan yang kebenarannya dapat diperiksa dengan bukti. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Kumpulkan tiga kalimat tentang sekolah. Bedakan fakta yang bisa diperiksa, pendapat, dan dugaan yang belum terbukti."},{"type":"text","body":"Rangkuman: Fakta: Pernyataan yang kebenarannya dapat diperiksa dengan bukti; Pendapat: Penilaian atau pandangan seseorang; Alasan: Dasar yang menjelaskan suatu pendapat; Sumber informasi: Asal keterangan yang dibaca atau didengar; Verifikasi: Pemeriksaan kebenaran memakai bukti yang relevan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('88764535-34f9-5209-a706-e771c4c7faf1','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Laporan dan teks penjelasan','belajar-bahasa-indonesia-kelas-5-unit-4',5,'C','Bab 4','sedang','draft',12,'{"summary":"Laporan dan teks penjelasan. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan laporan dan teks penjelasan dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Indonesia: Bergerak Bersama (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-bergerak-bersama-untuk-sd-mi-kelas-v-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan laporan dan teks penjelasan dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar laporan dan teks penjelasan. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Laporan. Penyajian kegiatan atau hasil pengamatan secara teratur. Contoh: Penulis mencatat apa yang dilakukan dan ditemukan"},{"type":"text","body":"2. Teks penjelasan. Teks yang menerangkan bagaimana atau mengapa sesuatu terjadi. Contoh: Penulis menjelaskan proses perubahan wujud"},{"type":"text","body":"3. Hubungan sebab-akibat. Hubungan alasan dengan peristiwa yang ditimbulkannya. Contoh: Pemanasan berkaitan dengan mencairnya es"},{"type":"text","body":"4. Data pengamatan. Catatan yang diperoleh saat mengamati. Contoh: Pengamat mencatat perubahan yang benar-benar terlihat"},{"type":"text","body":"5. Urutan proses. Tahapan perubahan yang disusun sesuai kejadian. Contoh: Es mengecil sebelum seluruhnya menjadi air"},{"type":"text","body":"Contoh dan penalaran: Penulis mencatat apa yang dilakukan dan ditemukan Kita mengenal laporan sebagai penyajian kegiatan atau hasil pengamatan secara teratur. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Amati perubahan es yang mencair bersama pendamping. Tulis hasil pengamatan dan penjelasan, tanpa menebak data yang tidak diamati."},{"type":"text","body":"Rangkuman: Laporan: Penyajian kegiatan atau hasil pengamatan secara teratur; Teks penjelasan: Teks yang menerangkan bagaimana atau mengapa sesuatu terjadi; Hubungan sebab-akibat: Hubungan alasan dengan peristiwa yang ditimbulkannya; Data pengamatan: Catatan yang diperoleh saat mengamati; Urutan proses: Tahapan perubahan yang disusun sesuai kejadian."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('5da8dc55-3efb-5c8d-80f0-8d12722e12f1','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Presentasi dan diskusi','belajar-bahasa-indonesia-kelas-5-unit-5',5,'C','Bab 5','sedang','draft',12,'{"summary":"Presentasi dan diskusi. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan presentasi dan diskusi dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Indonesia: Bergerak Bersama (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-bergerak-bersama-untuk-sd-mi-kelas-v-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan presentasi dan diskusi dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar presentasi dan diskusi. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Presentasi. Penyampaian informasi atau gagasan kepada pendengar. Contoh: Siswa menjelaskan usulan sudut baca di depan kelompok"},{"type":"text","body":"2. Pokok pembicaraan. Gagasan utama yang menjadi arah penyampaian. Contoh: Pembicara tetap membahas perbaikan tempat membaca"},{"type":"text","body":"3. Argumen sederhana. Pendapat disertai alasan yang berkaitan. Contoh: Pembicara mengusulkan rak rendah agar mudah dijangkau"},{"type":"text","body":"4. Pertanyaan relevan. Pertanyaan yang berkaitan dengan pokok diskusi. Contoh: Pendengar menanyakan bahan rak dalam diskusi rak buku"},{"type":"text","body":"5. Tanggapan santun. Respons yang menghargai orang sambil menilai gagasannya. Contoh: Peserta mengkritik usulan tanpa mengejek pembicaranya"},{"type":"text","body":"Contoh dan penalaran: Siswa menjelaskan usulan sudut baca di depan kelompok Kita mengenal presentasi sebagai penyampaian informasi atau gagasan kepada pendengar. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Presentasikan ide memperbaiki sudut baca selama satu menit. Teman mengajukan pertanyaan yang berkaitan dengan usulan."},{"type":"text","body":"Rangkuman: Presentasi: Penyampaian informasi atau gagasan kepada pendengar; Pokok pembicaraan: Gagasan utama yang menjadi arah penyampaian; Argumen sederhana: Pendapat disertai alasan yang berkaitan; Pertanyaan relevan: Pertanyaan yang berkaitan dengan pokok diskusi; Tanggapan santun: Respons yang menghargai orang sambil menilai gagasannya."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('da2729d7-427d-5cd4-91af-de26320e723c','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Menulis dan menyunting teks','belajar-bahasa-indonesia-kelas-5-unit-6',5,'C','Bab 6','sedang','draft',12,'{"summary":"Menulis dan menyunting teks. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan menulis dan menyunting teks dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Indonesia: Bergerak Bersama (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-bergerak-bersama-untuk-sd-mi-kelas-v-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan menulis dan menyunting teks dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar menulis dan menyunting teks. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Tujuan menulis. Hasil komunikasi yang ingin dicapai penulis. Contoh: Penulis ingin mengajak teman menjaga kebersihan"},{"type":"text","body":"2. Pembaca sasaran. Orang yang dituju oleh tulisan. Contoh: Pilihan kata disesuaikan untuk anak kelas rendah"},{"type":"text","body":"3. Draf. Tulisan awal yang masih dapat diubah. Contoh: Penulis menuangkan ide sebelum memperbaikinya"},{"type":"text","body":"4. Umpan balik. Tanggapan yang membantu memperbaiki karya. Contoh: Teman menunjukkan bagian alasan yang belum jelas"},{"type":"text","body":"5. Penyuntingan akhir. Pemeriksaan bahasa setelah isi diperbaiki. Contoh: Penulis memeriksa ejaan sebelum membagikan tulisan"},{"type":"text","body":"Contoh dan penalaran: Penulis ingin mengajak teman menjaga kebersihan Kita mengenal tujuan menulis sebagai hasil komunikasi yang ingin dicapai penulis. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Tulis teks dua paragraf untuk pembaca tertentu. Minta umpan balik isi, lakukan revisi, lalu sunting bahasanya."},{"type":"text","body":"Rangkuman: Tujuan menulis: Hasil komunikasi yang ingin dicapai penulis; Pembaca sasaran: Orang yang dituju oleh tulisan; Draf: Tulisan awal yang masih dapat diubah; Umpan balik: Tanggapan yang membantu memperbaiki karya; Penyuntingan akhir: Pemeriksaan bahasa setelah isi diperbaiki."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('ad254fc7-6f68-5de5-a28e-bc57a5ad53c2','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Membandingkan dua sumber','belajar-bahasa-indonesia-kelas-6-unit-1',6,'C','Bab 1','dasar','draft',12,'{"summary":"Membandingkan dua sumber. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan membandingkan dua sumber dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Bahasa Indonesia: Anak-Anak yang Mengubah Dunia","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-bahasa-indonesia-anak-anak-yang-mengubah-dunia-untuk-sdmi-kelas-vi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan membandingkan dua sumber dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar membandingkan dua sumber. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Membandingkan sumber. Mencari kesamaan dan perbedaan informasi dari beberapa sumber. Contoh: Dua bacaan tentang air dibandingkan pokok isinya"},{"type":"text","body":"2. Kredibilitas. Kelayakan suatu sumber dipercaya berdasarkan bukti dan keahliannya. Contoh: Sumber resmi yang menjelaskan data diperiksa penulis dan tanggalnya"},{"type":"text","body":"3. Persamaan informasi. Keterangan yang sesuai pada dua sumber. Contoh: Kedua teks menyebut tanaman membutuhkan air"},{"type":"text","body":"4. Perbedaan informasi. Keterangan yang tidak sama dan perlu dipahami konteksnya. Contoh: Dua teks membahas jenis tanaman yang berbeda"},{"type":"text","body":"5. Sintesis. Menggabungkan informasi yang sesuai menjadi pemahaman baru. Contoh: Pembaca merangkum dua sumber sambil menyebut perbedaannya"},{"type":"text","body":"Contoh dan penalaran: Dua bacaan tentang air dibandingkan pokok isinya Kita mengenal membandingkan sumber sebagai mencari kesamaan dan perbedaan informasi dari beberapa sumber. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Bandingkan dua teks tentang topik sama. Catat kesamaan, perbedaan, sumber, dan informasi yang masih perlu diperiksa."},{"type":"text","body":"Rangkuman: Membandingkan sumber: Mencari kesamaan dan perbedaan informasi dari beberapa sumber; Kredibilitas: Kelayakan suatu sumber dipercaya berdasarkan bukti dan keahliannya; Persamaan informasi: Keterangan yang sesuai pada dua sumber; Perbedaan informasi: Keterangan yang tidak sama dan perlu dipahami konteksnya; Sintesis: Menggabungkan informasi yang sesuai menjadi pemahaman baru."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('a0fc25b4-c40a-586a-b470-88b5721c3e2a','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Menilai informasi dan alasan','belajar-bahasa-indonesia-kelas-6-unit-2',6,'C','Bab 2','dasar','draft',12,'{"summary":"Menilai informasi dan alasan. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan menilai informasi dan alasan dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Bahasa Indonesia: Anak-Anak yang Mengubah Dunia","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-bahasa-indonesia-anak-anak-yang-mengubah-dunia-untuk-sdmi-kelas-vi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan menilai informasi dan alasan dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar menilai informasi dan alasan. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Klaim. Pernyataan yang diajukan untuk diterima atau dipertimbangkan. Contoh: Penulis mengusulkan jam membaca ditambah"},{"type":"text","body":"2. Bukti. Informasi yang mendukung atau melemahkan klaim. Contoh: Catatan peminjaman dipakai untuk menjelaskan kebutuhan buku"},{"type":"text","body":"3. Relevansi. Kesesuaian informasi dengan hal yang dibahas. Contoh: Alasan tentang buku berkaitan dengan usulan perpustakaan"},{"type":"text","body":"4. Asumsi. Anggapan yang dipakai meskipun belum dibuktikan. Contoh: Penulis mengira semua anak mempunyai akses internet"},{"type":"text","body":"5. Simpulan beralasan. Kesimpulan yang sesuai dengan bukti dan batas informasi. Contoh: Pembaca menyatakan hasil sekaligus hal yang belum diketahui"},{"type":"text","body":"Contoh dan penalaran: Penulis mengusulkan jam membaca ditambah Kita mengenal klaim sebagai pernyataan yang diajukan untuk diterima atau dipertimbangkan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Nilai satu usulan sederhana. Tanyakan apakah alasannya relevan dan bukti cukup; jangan hanya melihat siapa yang berbicara."},{"type":"text","body":"Rangkuman: Klaim: Pernyataan yang diajukan untuk diterima atau dipertimbangkan; Bukti: Informasi yang mendukung atau melemahkan klaim; Relevansi: Kesesuaian informasi dengan hal yang dibahas; Asumsi: Anggapan yang dipakai meskipun belum dibuktikan; Simpulan beralasan: Kesimpulan yang sesuai dengan bukti dan batas informasi."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('93ccc10e-6e9a-53ed-9ec3-16f1a3a80d6c','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Teks narasi dan informatif','belajar-bahasa-indonesia-kelas-6-unit-3',6,'C','Bab 3','dasar','draft',12,'{"summary":"Teks narasi dan informatif. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan teks narasi dan informatif dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Bahasa Indonesia: Anak-Anak yang Mengubah Dunia","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-bahasa-indonesia-anak-anak-yang-mengubah-dunia-untuk-sdmi-kelas-vi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan teks narasi dan informatif dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar teks narasi dan informatif. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Teks narasi. Teks yang berpusat pada rangkaian peristiwa. Contoh: Cerita mengikuti pengalaman seorang tokoh"},{"type":"text","body":"2. Teks informatif. Teks yang menyampaikan pengetahuan atau keterangan. Contoh: Bacaan menjelaskan jenis dan kegunaan sumber air"},{"type":"text","body":"3. Struktur teks. Susunan bagian yang membantu mencapai tujuan tulisan. Contoh: Informasi dikelompokkan dengan urutan yang jelas"},{"type":"text","body":"4. Detail relevan. Rincian yang membantu pembaca memahami pokok bahasan. Contoh: Penulis memilih contoh yang sesuai dengan topik air"},{"type":"text","body":"5. Koherensi. Hubungan makna yang logis antarbagian teks. Contoh: Sebab yang dijelaskan sesuai dengan akibat yang dibahas"},{"type":"text","body":"Contoh dan penalaran: Cerita mengikuti pengalaman seorang tokoh Kita mengenal teks narasi sebagai teks yang berpusat pada rangkaian peristiwa. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Tulis pembuka cerita dan pembuka teks informatif tentang objek yang sama. Jelaskan perbedaan tujuan dan susunannya."},{"type":"text","body":"Rangkuman: Teks narasi: Teks yang berpusat pada rangkaian peristiwa; Teks informatif: Teks yang menyampaikan pengetahuan atau keterangan; Struktur teks: Susunan bagian yang membantu mencapai tujuan tulisan; Detail relevan: Rincian yang membantu pembaca memahami pokok bahasan; Koherensi: Hubungan makna yang logis antarbagian teks."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('af35604a-0781-5184-9135-92bc9ee8d118','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Pidato dan presentasi','belajar-bahasa-indonesia-kelas-6-unit-4',6,'C','Bab 4','sedang','draft',12,'{"summary":"Pidato dan presentasi. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan pidato dan presentasi dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Bahasa Indonesia: Anak-Anak yang Mengubah Dunia","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-bahasa-indonesia-anak-anak-yang-mengubah-dunia-untuk-sdmi-kelas-vi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan pidato dan presentasi dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar pidato dan presentasi. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Pembukaan. Bagian awal yang menyapa dan mengenalkan topik. Contoh: Pembicara menjelaskan tujuan sebelum uraian"},{"type":"text","body":"2. Isi pidato. Bagian yang mengembangkan gagasan dan alasannya. Contoh: Pembicara memberi contoh kebiasaan merawat buku"},{"type":"text","body":"3. Penutup. Bagian akhir yang menegaskan pesan atau ajakan. Contoh: Pembicara merangkum ajakan yang telah dijelaskan"},{"type":"text","body":"4. Intonasi. Naik-turun nada suara yang membantu menyampaikan maksud. Contoh: Kalimat tanya dibacakan dengan nada yang sesuai"},{"type":"text","body":"5. Kontak dengan pendengar. Perhatian pada respons dan kebutuhan orang yang menyimak. Contoh: Pembicara memberi jeda ketika pendengar belum memahami"},{"type":"text","body":"Contoh dan penalaran: Pembicara menjelaskan tujuan sebelum uraian Kita mengenal pembukaan sebagai bagian awal yang menyapa dan mengenalkan topik. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Siapkan pidato singkat tentang kebiasaan baik. Berlatih dengan volume wajar dan terima satu pertanyaan pendengar."},{"type":"text","body":"Rangkuman: Pembukaan: Bagian awal yang menyapa dan mengenalkan topik; Isi pidato: Bagian yang mengembangkan gagasan dan alasannya; Penutup: Bagian akhir yang menegaskan pesan atau ajakan; Intonasi: Naik-turun nada suara yang membantu menyampaikan maksud; Kontak dengan pendengar: Perhatian pada respons dan kebutuhan orang yang menyimak."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('068906ab-9239-55de-a6fc-13d1d8110c89','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Laporan pengamatan terstruktur','belajar-bahasa-indonesia-kelas-6-unit-5',6,'C','Bab 5','sedang','draft',12,'{"summary":"Laporan pengamatan terstruktur. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan laporan pengamatan terstruktur dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Bahasa Indonesia: Anak-Anak yang Mengubah Dunia","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-bahasa-indonesia-anak-anak-yang-mengubah-dunia-untuk-sdmi-kelas-vi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan laporan pengamatan terstruktur dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar laporan pengamatan terstruktur. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Tujuan pengamatan. Hal yang ingin diketahui melalui pengamatan. Contoh: Siswa ingin mengetahui jenis sampah di sudut kelas"},{"type":"text","body":"2. Cara pengamatan. Langkah yang dilakukan untuk memperoleh informasi. Contoh: Siswa menghitung jenis sampah pada waktu yang disepakati"},{"type":"text","body":"3. Temuan. Hasil yang benar-benar diperoleh saat mengamati. Contoh: Siswa mencatat jumlah kertas dan plastik yang ditemukan"},{"type":"text","body":"4. Simpulan laporan. Pemahaman akhir yang sesuai hasil pengamatan. Contoh: Siswa menyimpulkan jenis terbanyak dari catatannya"},{"type":"text","body":"5. Batas pengamatan. Hal yang tidak dapat dipastikan dari kegiatan tersebut. Contoh: Catatan satu hari belum mewakili semua hari dalam setahun"},{"type":"text","body":"Contoh dan penalaran: Siswa ingin mengetahui jenis sampah di sudut kelas Kita mengenal tujuan pengamatan sebagai hal yang ingin diketahui melalui pengamatan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat laporan pengamatan terstruktur tanpa data pribadi. Pisahkan tujuan, cara, temuan, dan simpulan yang didukung temuan."},{"type":"text","body":"Rangkuman: Tujuan pengamatan: Hal yang ingin diketahui melalui pengamatan; Cara pengamatan: Langkah yang dilakukan untuk memperoleh informasi; Temuan: Hasil yang benar-benar diperoleh saat mengamati; Simpulan laporan: Pemahaman akhir yang sesuai hasil pengamatan; Batas pengamatan: Hal yang tidak dapat dipastikan dari kegiatan tersebut."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('e9b6a3b0-9770-53b3-ae37-04663d67f018','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Refleksi dan revisi tulisan','belajar-bahasa-indonesia-kelas-6-unit-6',6,'C','Bab 6','sedang','draft',12,'{"summary":"Refleksi dan revisi tulisan. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan refleksi dan revisi tulisan dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Bahasa Indonesia: Anak-Anak yang Mengubah Dunia","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-bahasa-indonesia-anak-anak-yang-mengubah-dunia-untuk-sdmi-kelas-vi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan refleksi dan revisi tulisan dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar refleksi dan revisi tulisan. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Refleksi menulis. Menilai proses dan hasil tulisan untuk belajar. Contoh: Penulis mengenali bagian yang sudah jelas dan yang perlu diperbaiki"},{"type":"text","body":"2. Revisi substansi. Perubahan isi atau susunan gagasan. Contoh: Penulis menambah bukti untuk memperkuat alasan"},{"type":"text","body":"3. Revisi bahasa. Perbaikan pilihan kata dan susunan kalimat. Contoh: Penulis mengganti kalimat berbelit agar lebih mudah dipahami"},{"type":"text","body":"4. Konsistensi. Keselarasan penggunaan istilah dan cara penyajian. Contoh: Nama tokoh ditulis sama sepanjang cerita"},{"type":"text","body":"5. Portofolio. Kumpulan karya yang memperlihatkan proses perkembangan. Contoh: Draf awal dan hasil revisi disimpan untuk melihat kemajuan"},{"type":"text","body":"Contoh dan penalaran: Penulis mengenali bagian yang sudah jelas dan yang perlu diperbaiki Kita mengenal refleksi menulis sebagai menilai proses dan hasil tulisan untuk belajar. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Pilih tulisanmu sendiri. Tandai perubahan isi dan bahasa secara berbeda, lalu tulis alasan dua revisi terpenting."},{"type":"text","body":"Rangkuman: Refleksi menulis: Menilai proses dan hasil tulisan untuk belajar; Revisi substansi: Perubahan isi atau susunan gagasan; Revisi bahasa: Perbaikan pilihan kata dan susunan kalimat; Konsistensi: Keselarasan penggunaan istilah dan cara penyajian; Portofolio: Kumpulan karya yang memperlihatkan proses perkembangan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('8a1dc116-a498-5bbf-9808-73dc6221c722','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Mengamati dengan pancaindra','belajar-ipas-kelas-1-unit-1',1,'A','Bab 1','dasar','draft',8,'{"summary":"Mengamati dengan pancaindra. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan mengamati dengan pancaindra dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan mata pelajaran untuk pendamping","url":"https://kurikulum.kemendikdasmen.go.id/panduan-mapel","usage":"Acuan pendamping; pengayaan Fase A bukan klaim CP mapel wajib."}],"curriculum_note":"Pengayaan awal; bukan klaim mata pelajaran wajib atau CP IPAS/Inggris Fase A.","enrichment":true,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan mengamati dengan pancaindra dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar mengamati dengan pancaindra. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Mata. Indra untuk melihat cahaya, warna, dan bentuk. Contoh: Anak mengenali warna daun dari penglihatannya"},{"type":"text","body":"2. Telinga. Indra untuk mendengar bunyi. Contoh: Anak mendengar ketukan pintu"},{"type":"text","body":"3. Hidung. Indra untuk mengenali bau. Contoh: Anak mengenali aroma makanan yang sudah dikenal"},{"type":"text","body":"4. Lidah. Indra untuk mengenali rasa dengan aman. Contoh: Anak merasakan rasa pada makanan yang biasa dimakannya"},{"type":"text","body":"5. Kulit. Indra yang membantu merasakan sentuhan dan suhu. Contoh: Anak merasakan permukaan kain yang lembut"},{"type":"text","body":"Contoh dan penalaran: Anak mengenali warna daun dari penglihatannya Kita mengenal mata sebagai indra untuk melihat cahaya, warna, dan bentuk. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Amati benda aman dengan mata, telinga, dan sentuhan seperlunya. Jangan mencicipi atau mencium bahan yang tidak dikenal."},{"type":"text","body":"Rangkuman: Mata: Indra untuk melihat cahaya, warna, dan bentuk; Telinga: Indra untuk mendengar bunyi; Hidung: Indra untuk mengenali bau; Lidah: Indra untuk mengenali rasa dengan aman; Kulit: Indra yang membantu merasakan sentuhan dan suhu."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('625f01a3-7699-5b93-82f4-b50b3ea0eed8','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Bagian tubuh dan kebiasaan sehat','belajar-ipas-kelas-1-unit-2',1,'A','Bab 2','dasar','draft',8,'{"summary":"Bagian tubuh dan kebiasaan sehat. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan bagian tubuh dan kebiasaan sehat dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan mata pelajaran untuk pendamping","url":"https://kurikulum.kemendikdasmen.go.id/panduan-mapel","usage":"Acuan pendamping; pengayaan Fase A bukan klaim CP mapel wajib."}],"curriculum_note":"Pengayaan awal; bukan klaim mata pelajaran wajib atau CP IPAS/Inggris Fase A.","enrichment":true,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan bagian tubuh dan kebiasaan sehat dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar bagian tubuh dan kebiasaan sehat. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Tangan. Bagian tubuh untuk memegang dan melakukan banyak kegiatan. Contoh: Anak memegang pensil dengan tangannya"},{"type":"text","body":"2. Kaki. Bagian tubuh yang membantu berdiri dan bergerak. Contoh: Anak berjalan menuju rak buku"},{"type":"text","body":"3. Kebersihan. Keadaan dan kebiasaan menjaga diri dari kotoran. Contoh: Anak mencuci tangan sebelum makan"},{"type":"text","body":"4. Istirahat. Waktu memberi kesempatan tubuh untuk pulih. Contoh: Anak tidur sesuai kebiasaan sehat bersama keluarganya"},{"type":"text","body":"5. Kebiasaan aman. Tindakan yang melindungi diri dan orang lain. Contoh: Anak tidak menyentuh benda panas dan meminta bantuan"},{"type":"text","body":"Contoh dan penalaran: Anak memegang pensil dengan tangannya Kita mengenal tangan sebagai bagian tubuh untuk memegang dan melakukan banyak kegiatan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Ceritakan kebiasaan merawat tubuh dan menjaga kebersihan tangan. Praktikkan bersama pendamping dengan alat yang biasa digunakan."},{"type":"text","body":"Rangkuman: Tangan: Bagian tubuh untuk memegang dan melakukan banyak kegiatan; Kaki: Bagian tubuh yang membantu berdiri dan bergerak; Kebersihan: Keadaan dan kebiasaan menjaga diri dari kotoran; Istirahat: Waktu memberi kesempatan tubuh untuk pulih; Kebiasaan aman: Tindakan yang melindungi diri dan orang lain."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('685a99e4-3c94-59c0-a3a5-0de79933584f','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Benda hidup di sekitar','belajar-ipas-kelas-1-unit-3',1,'A','Bab 3','dasar','draft',8,'{"summary":"Benda hidup di sekitar. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan benda hidup di sekitar dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan mata pelajaran untuk pendamping","url":"https://kurikulum.kemendikdasmen.go.id/panduan-mapel","usage":"Acuan pendamping; pengayaan Fase A bukan klaim CP mapel wajib."}],"curriculum_note":"Pengayaan awal; bukan klaim mata pelajaran wajib atau CP IPAS/Inggris Fase A.","enrichment":true,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan benda hidup di sekitar dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar benda hidup di sekitar. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Makhluk hidup. Sesuatu yang tumbuh dan menjalankan proses kehidupan. Contoh: Bibit berubah menjadi tanaman yang lebih besar"},{"type":"text","body":"2. Tumbuhan. Makhluk hidup yang antara lain dapat membuat makanan dengan bantuan cahaya. Contoh: Tanaman hijau tumbuh ketika kebutuhannya terpenuhi"},{"type":"text","body":"3. Hewan. Makhluk hidup yang memperoleh makanan dari makhluk hidup lain. Contoh: Kucing mencari makanan untuk kebutuhan tubuhnya"},{"type":"text","body":"4. Benda tak hidup. Benda yang tidak menjalankan proses kehidupan. Contoh: Batu tidak tumbuh seperti tanaman"},{"type":"text","body":"5. Kebutuhan hidup. Hal yang diperlukan makhluk hidup agar dapat bertahan. Contoh: Tanaman memerlukan air dan kondisi lingkungan yang sesuai"},{"type":"text","body":"Contoh dan penalaran: Bibit berubah menjadi tanaman yang lebih besar Kita mengenal makhluk hidup sebagai sesuatu yang tumbuh dan menjalankan proses kehidupan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Amati satu tanaman dan satu benda buatan. Catat ciri yang terlihat; jangan merusak tanaman atau mengganggu hewan."},{"type":"text","body":"Rangkuman: Makhluk hidup: Sesuatu yang tumbuh dan menjalankan proses kehidupan; Tumbuhan: Makhluk hidup yang antara lain dapat membuat makanan dengan bantuan cahaya; Hewan: Makhluk hidup yang memperoleh makanan dari makhluk hidup lain; Benda tak hidup: Benda yang tidak menjalankan proses kehidupan; Kebutuhan hidup: Hal yang diperlukan makhluk hidup agar dapat bertahan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('89724639-ce78-5ca2-aeb9-0343a909adb5','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Bahan dan sifat benda sederhana','belajar-ipas-kelas-1-unit-4',1,'A','Bab 4','sedang','draft',8,'{"summary":"Bahan dan sifat benda sederhana. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan bahan dan sifat benda sederhana dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan mata pelajaran untuk pendamping","url":"https://kurikulum.kemendikdasmen.go.id/panduan-mapel","usage":"Acuan pendamping; pengayaan Fase A bukan klaim CP mapel wajib."}],"curriculum_note":"Pengayaan awal; bukan klaim mata pelajaran wajib atau CP IPAS/Inggris Fase A.","enrichment":true,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan bahan dan sifat benda sederhana dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar bahan dan sifat benda sederhana. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Bahan. Zat atau materi yang digunakan untuk membuat benda. Contoh: Meja dapat dibuat dari kayu"},{"type":"text","body":"2. Keras. Sifat benda yang tidak mudah berubah bentuk saat ditekan ringan. Contoh: Batu terasa keras ketika ditekan perlahan"},{"type":"text","body":"3. Lentur. Sifat benda yang dapat dibengkokkan tanpa mudah patah. Contoh: Karet gelang dapat dilenturkan sesuai batasnya"},{"type":"text","body":"4. Kasar. Sifat permukaan yang terasa tidak rata. Contoh: Permukaan batu tertentu terasa kasar"},{"type":"text","body":"5. Halus. Sifat permukaan yang terasa rata saat diraba dengan aman. Contoh: Permukaan kertas tulis terasa halus"},{"type":"text","body":"Contoh dan penalaran: Meja dapat dibuat dari kayu Kita mengenal bahan sebagai zat atau materi yang digunakan untuk membuat benda. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Kelompokkan benda aman berdasarkan bahan dan sifatnya. Jelaskan bahwa satu benda dapat mempunyai lebih dari satu sifat."},{"type":"text","body":"Rangkuman: Bahan: Zat atau materi yang digunakan untuk membuat benda; Keras: Sifat benda yang tidak mudah berubah bentuk saat ditekan ringan; Lentur: Sifat benda yang dapat dibengkokkan tanpa mudah patah; Kasar: Sifat permukaan yang terasa tidak rata; Halus: Sifat permukaan yang terasa rata saat diraba dengan aman."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('141af28d-93e2-5bd5-939a-08d9a5993031','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Cuaca yang diamati','belajar-ipas-kelas-1-unit-5',1,'A','Bab 5','sedang','draft',8,'{"summary":"Cuaca yang diamati. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan cuaca yang diamati dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan mata pelajaran untuk pendamping","url":"https://kurikulum.kemendikdasmen.go.id/panduan-mapel","usage":"Acuan pendamping; pengayaan Fase A bukan klaim CP mapel wajib."}],"curriculum_note":"Pengayaan awal; bukan klaim mata pelajaran wajib atau CP IPAS/Inggris Fase A.","enrichment":true,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan cuaca yang diamati dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar cuaca yang diamati. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Cuaca. Keadaan udara di tempat dan waktu tertentu. Contoh: Pagi ini langit di sekolah berawan"},{"type":"text","body":"2. Cerah. Keadaan langit dengan sedikit awan sehingga tampak terang. Contoh: Langit terang dan sedikit awan tampak di atas rumah"},{"type":"text","body":"3. Berawan. Keadaan langit yang tertutup banyak awan. Contoh: Sebagian besar langit tertutup awan"},{"type":"text","body":"4. Hujan. Air yang jatuh dari awan ke permukaan bumi. Contoh: Tetes air turun dari langit ke halaman"},{"type":"text","body":"5. Pengamatan cuaca. Pencatatan keadaan cuaca yang benar-benar diamati. Contoh: Anak mencatat langit berawan pada waktu tertentu"},{"type":"text","body":"Contoh dan penalaran: Pagi ini langit di sekolah berawan Kita mengenal cuaca sebagai keadaan udara di tempat dan waktu tertentu. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Lihat cuaca dari tempat terlindung pada pagi dan siang. Gambar keadaan langit; jangan melihat matahari langsung."},{"type":"text","body":"Rangkuman: Cuaca: Keadaan udara di tempat dan waktu tertentu; Cerah: Keadaan langit dengan sedikit awan sehingga tampak terang; Berawan: Keadaan langit yang tertutup banyak awan; Hujan: Air yang jatuh dari awan ke permukaan bumi; Pengamatan cuaca: Pencatatan keadaan cuaca yang benar-benar diamati."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('920ef341-78fa-585a-afcd-769093322816','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Merawat lingkungan rumah','belajar-ipas-kelas-1-unit-6',1,'A','Bab 6','sedang','draft',8,'{"summary":"Merawat lingkungan rumah. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan merawat lingkungan rumah dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan mata pelajaran untuk pendamping","url":"https://kurikulum.kemendikdasmen.go.id/panduan-mapel","usage":"Acuan pendamping; pengayaan Fase A bukan klaim CP mapel wajib."}],"curriculum_note":"Pengayaan awal; bukan klaim mata pelajaran wajib atau CP IPAS/Inggris Fase A.","enrichment":true,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan merawat lingkungan rumah dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar merawat lingkungan rumah. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Lingkungan. Segala sesuatu di sekitar tempat hidup. Contoh: Tanaman, halaman, dan bangunan berada di sekitar anak"},{"type":"text","body":"2. Sampah. Sisa kegiatan yang perlu dikelola dengan benar. Contoh: Bungkus bekas ditempatkan pada tempat sampah"},{"type":"text","body":"3. Hemat air. Menggunakan air sesuai kebutuhan tanpa membuangnya sia-sia. Contoh: Keran ditutup setelah digunakan"},{"type":"text","body":"4. Merawat tanaman. Memenuhi kebutuhan tanaman tanpa berlebihan. Contoh: Anak menyiram sesuai kebutuhan dengan pendamping"},{"type":"text","body":"5. Tanggung jawab bersama. Peran setiap orang menjaga tempat yang dipakai bersama. Contoh: Anggota kelas bergantian merapikan sudut baca"},{"type":"text","body":"Contoh dan penalaran: Tanaman, halaman, dan bangunan berada di sekitar anak Kita mengenal lingkungan sebagai segala sesuatu di sekitar tempat hidup. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Pilih satu tindakan kecil menjaga lingkungan rumah atau sekolah. Lakukan dengan pendamping dan alat yang aman."},{"type":"text","body":"Rangkuman: Lingkungan: Segala sesuatu di sekitar tempat hidup; Sampah: Sisa kegiatan yang perlu dikelola dengan benar; Hemat air: Menggunakan air sesuai kebutuhan tanpa membuangnya sia-sia; Merawat tanaman: Memenuhi kebutuhan tanaman tanpa berlebihan; Tanggung jawab bersama: Peran setiap orang menjaga tempat yang dipakai bersama."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('a0b847d5-1b0f-520c-9b52-97fcc027cfa4','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Kebutuhan tumbuhan dan hewan','belajar-ipas-kelas-2-unit-1',2,'A','Bab 1','dasar','draft',8,'{"summary":"Kebutuhan tumbuhan dan hewan. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan kebutuhan tumbuhan dan hewan dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan mata pelajaran untuk pendamping","url":"https://kurikulum.kemendikdasmen.go.id/panduan-mapel","usage":"Acuan pendamping; pengayaan Fase A bukan klaim CP mapel wajib."}],"curriculum_note":"Pengayaan awal; bukan klaim mata pelajaran wajib atau CP IPAS/Inggris Fase A.","enrichment":true,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan kebutuhan tumbuhan dan hewan dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar kebutuhan tumbuhan dan hewan. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Air. Kebutuhan penting makhluk hidup dalam jumlah yang sesuai. Contoh: Tanaman disiram secukupnya"},{"type":"text","body":"2. Cahaya. Energi yang membantu tumbuhan hijau membuat makanan. Contoh: Tanaman memperoleh cahaya di tempat yang sesuai"},{"type":"text","body":"3. Udara. Campuran gas di sekitar yang diperlukan proses kehidupan. Contoh: Hewan menggunakan oksigen dari udara untuk bernapas"},{"type":"text","body":"4. Makanan. Sumber zat dan energi bagi hewan dan manusia. Contoh: Hewan memperoleh makanan yang sesuai jenisnya"},{"type":"text","body":"5. Tempat hidup. Lingkungan yang menyediakan kebutuhan makhluk hidup. Contoh: Ikan hidup pada lingkungan air yang sesuai"},{"type":"text","body":"Contoh dan penalaran: Tanaman disiram secukupnya Kita mengenal air sebagai kebutuhan penting makhluk hidup dalam jumlah yang sesuai. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Amati pertumbuhan tanaman pada dua waktu berbeda. Gambar perubahan tanpa mencabut atau merusaknya."},{"type":"text","body":"Rangkuman: Air: Kebutuhan penting makhluk hidup dalam jumlah yang sesuai; Cahaya: Energi yang membantu tumbuhan hijau membuat makanan; Udara: Campuran gas di sekitar yang diperlukan proses kehidupan; Makanan: Sumber zat dan energi bagi hewan dan manusia; Tempat hidup: Lingkungan yang menyediakan kebutuhan makhluk hidup."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('2673975e-967c-5cb9-bc47-9aea9fd57376','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Perubahan yang dapat diamati','belajar-ipas-kelas-2-unit-2',2,'A','Bab 2','dasar','draft',8,'{"summary":"Perubahan yang dapat diamati. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan perubahan yang dapat diamati dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan mata pelajaran untuk pendamping","url":"https://kurikulum.kemendikdasmen.go.id/panduan-mapel","usage":"Acuan pendamping; pengayaan Fase A bukan klaim CP mapel wajib."}],"curriculum_note":"Pengayaan awal; bukan klaim mata pelajaran wajib atau CP IPAS/Inggris Fase A.","enrichment":true,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan perubahan yang dapat diamati dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar perubahan yang dapat diamati. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Perubahan bentuk. Perubahan rupa tanpa selalu menjadi bahan baru. Contoh: Kertas dilipat menjadi bentuk perahu"},{"type":"text","body":"2. Mencair. Perubahan benda padat menjadi cair. Contoh: Es berubah menjadi air di tempat yang lebih hangat"},{"type":"text","body":"3. Membeku. Perubahan benda cair menjadi padat. Contoh: Air menjadi es di dalam pembeku"},{"type":"text","body":"4. Perubahan ukuran. Perubahan besar atau kecil suatu benda. Contoh: Potongan kertas menjadi lebih kecil setelah digunting pendamping"},{"type":"text","body":"5. Catatan pengamatan. Keterangan tentang keadaan yang benar-benar dilihat. Contoh: Anak mencatat es mengecil dan air bertambah"},{"type":"text","body":"Contoh dan penalaran: Kertas dilipat menjadi bentuk perahu Kita mengenal perubahan bentuk sebagai perubahan rupa tanpa selalu menjadi bahan baru. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Amati es yang mencair dalam wadah bersama pendamping. Catat apa yang berubah tanpa menggunakan api atau air panas."},{"type":"text","body":"Rangkuman: Perubahan bentuk: Perubahan rupa tanpa selalu menjadi bahan baru; Mencair: Perubahan benda padat menjadi cair; Membeku: Perubahan benda cair menjadi padat; Perubahan ukuran: Perubahan besar atau kecil suatu benda; Catatan pengamatan: Keterangan tentang keadaan yang benar-benar dilihat."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('c3301951-e374-57ce-973b-db6dc3b1363c','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Air dan penggunaannya','belajar-ipas-kelas-2-unit-3',2,'A','Bab 3','dasar','draft',8,'{"summary":"Air dan penggunaannya. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan air dan penggunaannya dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan mata pelajaran untuk pendamping","url":"https://kurikulum.kemendikdasmen.go.id/panduan-mapel","usage":"Acuan pendamping; pengayaan Fase A bukan klaim CP mapel wajib."}],"curriculum_note":"Pengayaan awal; bukan klaim mata pelajaran wajib atau CP IPAS/Inggris Fase A.","enrichment":true,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan air dan penggunaannya dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar air dan penggunaannya. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Sumber air. Asal air yang digunakan makhluk hidup. Contoh: Air dapat berasal dari mata air atau hujan"},{"type":"text","body":"2. Air bersih. Air yang memenuhi kebutuhan kebersihan sesuai penggunaannya. Contoh: Air untuk mencuci tangan disediakan dengan baik"},{"type":"text","body":"3. Penggunaan air. Pemanfaatan air dalam suatu kegiatan. Contoh: Air dipakai untuk menyiram tanaman"},{"type":"text","body":"4. Pencemaran air. Masuknya bahan yang menurunkan kualitas air. Contoh: Sampah dan limbah dapat mengotori sungai"},{"type":"text","body":"5. Penghematan. Menggunakan sumber daya sesuai kebutuhan. Contoh: Air siraman tidak dibiarkan mengalir tanpa tujuan"},{"type":"text","body":"Contoh dan penalaran: Air dapat berasal dari mata air atau hujan Kita mengenal sumber air sebagai asal air yang digunakan makhluk hidup. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Catat penggunaan air selama satu kegiatan. Cari cara menghemat tanpa mengurangi kebersihan yang diperlukan."},{"type":"text","body":"Rangkuman: Sumber air: Asal air yang digunakan makhluk hidup; Air bersih: Air yang memenuhi kebutuhan kebersihan sesuai penggunaannya; Penggunaan air: Pemanfaatan air dalam suatu kegiatan; Pencemaran air: Masuknya bahan yang menurunkan kualitas air; Penghematan: Menggunakan sumber daya sesuai kebutuhan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('7e69bc06-6ff6-58f6-9f31-91d352dd56ce','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Lingkungan rumah dan sekolah','belajar-ipas-kelas-2-unit-4',2,'A','Bab 4','sedang','draft',8,'{"summary":"Lingkungan rumah dan sekolah. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan lingkungan rumah dan sekolah dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan mata pelajaran untuk pendamping","url":"https://kurikulum.kemendikdasmen.go.id/panduan-mapel","usage":"Acuan pendamping; pengayaan Fase A bukan klaim CP mapel wajib."}],"curriculum_note":"Pengayaan awal; bukan klaim mata pelajaran wajib atau CP IPAS/Inggris Fase A.","enrichment":true,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan lingkungan rumah dan sekolah dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar lingkungan rumah dan sekolah. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Rumah. Tempat tinggal yang perlu dijaga bersama. Contoh: Anggota keluarga merawat tempat tinggalnya"},{"type":"text","body":"2. Sekolah. Lingkungan untuk kegiatan belajar bersama. Contoh: Siswa menggunakan ruang kelas sesuai aturan"},{"type":"text","body":"3. Denah. Gambar letak tempat dilihat secara sederhana dari atas. Contoh: Letak pintu dan meja ditandai pada gambar"},{"type":"text","body":"4. Simbol. Tanda yang mewakili objek atau tempat. Contoh: Kotak kecil mewakili meja pada denah"},{"type":"text","body":"5. Aturan lingkungan. Kesepakatan menjaga keamanan dan kenyamanan bersama. Contoh: Anak berjalan tertib di lorong sekolah"},{"type":"text","body":"Contoh dan penalaran: Anggota keluarga merawat tempat tinggalnya Kita mengenal rumah sebagai tempat tinggal yang perlu dijaga bersama. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Gambar denah sederhana ruang yang dikenal. Gunakan simbol tanpa mencantumkan alamat pribadi."},{"type":"text","body":"Rangkuman: Rumah: Tempat tinggal yang perlu dijaga bersama; Sekolah: Lingkungan untuk kegiatan belajar bersama; Denah: Gambar letak tempat dilihat secara sederhana dari atas; Simbol: Tanda yang mewakili objek atau tempat; Aturan lingkungan: Kesepakatan menjaga keamanan dan kenyamanan bersama."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('5f5212bd-c6ba-5abe-8bde-ae91000eb328','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Pekerjaan di sekitar','belajar-ipas-kelas-2-unit-5',2,'A','Bab 5','sedang','draft',8,'{"summary":"Pekerjaan di sekitar. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan pekerjaan di sekitar dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan mata pelajaran untuk pendamping","url":"https://kurikulum.kemendikdasmen.go.id/panduan-mapel","usage":"Acuan pendamping; pengayaan Fase A bukan klaim CP mapel wajib."}],"curriculum_note":"Pengayaan awal; bukan klaim mata pelajaran wajib atau CP IPAS/Inggris Fase A.","enrichment":true,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan pekerjaan di sekitar dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar pekerjaan di sekitar. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Pekerjaan. Kegiatan yang dilakukan untuk menghasilkan barang atau jasa. Contoh: Petani merawat tanaman untuk menghasilkan pangan"},{"type":"text","body":"2. Barang. Hasil atau benda yang dapat digunakan. Contoh: Roti adalah barang yang dibuat pembuat roti"},{"type":"text","body":"3. Jasa. Layanan yang membantu kebutuhan orang lain. Contoh: Pengemudi mengantar penumpang sebagai layanan"},{"type":"text","body":"4. Kerja sama. Usaha bersama untuk mencapai tujuan. Contoh: Penjual dan pengantar bekerja agar barang sampai"},{"type":"text","body":"5. Menghargai pekerjaan. Menghormati usaha dan peran orang lain. Contoh: Anak berbicara sopan kepada petugas kebersihan"},{"type":"text","body":"Contoh dan penalaran: Petani merawat tanaman untuk menghasilkan pangan Kita mengenal pekerjaan sebagai kegiatan yang dilakukan untuk menghasilkan barang atau jasa. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Tanyakan kepada pendamping tentang dua pekerjaan di sekitar. Fokus pada tugasnya, bukan pendapatan atau data pribadi."},{"type":"text","body":"Rangkuman: Pekerjaan: Kegiatan yang dilakukan untuk menghasilkan barang atau jasa; Barang: Hasil atau benda yang dapat digunakan; Jasa: Layanan yang membantu kebutuhan orang lain; Kerja sama: Usaha bersama untuk mencapai tujuan; Menghargai pekerjaan: Menghormati usaha dan peran orang lain."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('5ab3b231-bb97-5a55-8537-fc6cc7036bee','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Kegiatan mengurangi sampah','belajar-ipas-kelas-2-unit-6',2,'A','Bab 6','sedang','draft',8,'{"summary":"Kegiatan mengurangi sampah. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan kegiatan mengurangi sampah dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan mata pelajaran untuk pendamping","url":"https://kurikulum.kemendikdasmen.go.id/panduan-mapel","usage":"Acuan pendamping; pengayaan Fase A bukan klaim CP mapel wajib."}],"curriculum_note":"Pengayaan awal; bukan klaim mata pelajaran wajib atau CP IPAS/Inggris Fase A.","enrichment":true,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan kegiatan mengurangi sampah dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar kegiatan mengurangi sampah. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Mengurangi. Mencegah timbulnya sisa yang tidak diperlukan. Contoh: Anak membawa botol minum yang dapat dipakai ulang"},{"type":"text","body":"2. Menggunakan kembali. Memakai benda yang masih layak untuk keperluan berikutnya. Contoh: Kotak bersih dipakai menyimpan alat"},{"type":"text","body":"3. Memilah. Memisahkan benda menurut kelompok atau pengelolaannya. Contoh: Kertas bersih dipisahkan dari sisa makanan"},{"type":"text","body":"4. Daur ulang. Mengolah bahan bekas menjadi bahan atau produk lain. Contoh: Kertas bekas diolah kembali melalui proses yang sesuai"},{"type":"text","body":"5. Sampah berbahaya. Sisa yang perlu ditangani orang dewasa dengan cara khusus. Contoh: Baterai bekas tidak dimainkan atau dibuka anak"},{"type":"text","body":"Contoh dan penalaran: Anak membawa botol minum yang dapat dipakai ulang Kita mengenal mengurangi sebagai mencegah timbulnya sisa yang tidak diperlukan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Periksa satu benda yang dapat digunakan kembali. Hindari sampah tajam, kotor, atau berbahaya."},{"type":"text","body":"Rangkuman: Mengurangi: Mencegah timbulnya sisa yang tidak diperlukan; Menggunakan kembali: Memakai benda yang masih layak untuk keperluan berikutnya; Memilah: Memisahkan benda menurut kelompok atau pengelolaannya; Daur ulang: Mengolah bahan bekas menjadi bahan atau produk lain; Sampah berbahaya: Sisa yang perlu ditangani orang dewasa dengan cara khusus."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('6b1099a0-3cd4-537c-989d-b6a510f5df6e','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Makhluk hidup dan lingkungannya','belajar-ipas-kelas-3-unit-1',3,'B','Bab 1','dasar','draft',12,'{"summary":"Makhluk hidup dan lingkungannya. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan makhluk hidup dan lingkungannya dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru IPAS Kelas III (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-ilmu-pengetahuan-alam-dan-sosial-untuk-sdmi-kelas-iii-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan makhluk hidup dan lingkungannya dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar makhluk hidup dan lingkungannya. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Habitat. Tempat hidup alami yang menyediakan kebutuhan makhluk hidup. Contoh: Katak hidup di lingkungan yang sesuai kebutuhan airnya"},{"type":"text","body":"2. Kebutuhan makhluk hidup. Hal yang diperlukan untuk menjalankan kehidupan. Contoh: Hewan memerlukan makanan, air, dan tempat yang sesuai"},{"type":"text","body":"3. Ciri makhluk hidup. Tanda proses kehidupan seperti tumbuh dan berkembang. Contoh: Bibit menjadi tanaman lebih besar"},{"type":"text","body":"4. Interaksi. Hubungan makhluk hidup dengan makhluk lain atau lingkungannya. Contoh: Kupu-kupu mengunjungi bunga untuk memperoleh makanan"},{"type":"text","body":"5. Pelestarian. Usaha menjaga keberadaan makhluk hidup dan lingkungannya. Contoh: Tanaman lokal dirawat tanpa mengambil hewan dari habitatnya"},{"type":"text","body":"Contoh dan penalaran: Katak hidup di lingkungan yang sesuai kebutuhan airnya Kita mengenal habitat sebagai tempat hidup alami yang menyediakan kebutuhan makhluk hidup. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat catatan tentang makhluk hidup dan tempat hidupnya. Jelaskan satu hubungan tanpa mengganggu hewan."},{"type":"text","body":"Rangkuman: Habitat: Tempat hidup alami yang menyediakan kebutuhan makhluk hidup; Kebutuhan makhluk hidup: Hal yang diperlukan untuk menjalankan kehidupan; Ciri makhluk hidup: Tanda proses kehidupan seperti tumbuh dan berkembang; Interaksi: Hubungan makhluk hidup dengan makhluk lain atau lingkungannya; Pelestarian: Usaha menjaga keberadaan makhluk hidup dan lingkungannya."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('5503c793-bd93-5e9c-b817-00d48ccba41d','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Siklus hidup','belajar-ipas-kelas-3-unit-2',3,'B','Bab 2','dasar','draft',12,'{"summary":"Siklus hidup. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan siklus hidup dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru IPAS Kelas III (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-ilmu-pengetahuan-alam-dan-sosial-untuk-sdmi-kelas-iii-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan siklus hidup dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar siklus hidup. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Siklus hidup. Tahapan kehidupan makhluk hidup dari satu generasi ke berikutnya. Contoh: Kupu-kupu melewati telur hingga dewasa lalu bertelur"},{"type":"text","body":"2. Telur. Tahap awal perkembangan banyak jenis hewan. Contoh: Ulat menetas dari telur kupu-kupu"},{"type":"text","body":"3. Larva. Tahap muda pada hewan tertentu yang bentuknya berbeda dari dewasa. Contoh: Ulat merupakan larva kupu-kupu"},{"type":"text","body":"4. Pupa. Tahap perubahan sebelum dewasa pada serangga tertentu. Contoh: Kepompong adalah tahap pupa kupu-kupu"},{"type":"text","body":"5. Perkecambahan. Awal pertumbuhan biji menjadi tumbuhan muda. Contoh: Akar kecil mulai keluar dari biji yang mendapat kondisi sesuai"},{"type":"text","body":"Contoh dan penalaran: Kupu-kupu melewati telur hingga dewasa lalu bertelur Kita mengenal siklus hidup sebagai tahapan kehidupan makhluk hidup dari satu generasi ke berikutnya. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Gambar urutan pertumbuhan kupu-kupu atau tanaman dari sumber yang dibaca bersama pendamping."},{"type":"text","body":"Rangkuman: Siklus hidup: Tahapan kehidupan makhluk hidup dari satu generasi ke berikutnya; Telur: Tahap awal perkembangan banyak jenis hewan; Larva: Tahap muda pada hewan tertentu yang bentuknya berbeda dari dewasa; Pupa: Tahap perubahan sebelum dewasa pada serangga tertentu; Perkecambahan: Awal pertumbuhan biji menjadi tumbuhan muda."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('a9f5a2fb-3044-50d2-8973-e552676e00ae','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Sifat dan perubahan wujud benda','belajar-ipas-kelas-3-unit-3',3,'B','Bab 3','dasar','draft',12,'{"summary":"Sifat dan perubahan wujud benda. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan sifat dan perubahan wujud benda dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru IPAS Kelas III (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-ilmu-pengetahuan-alam-dan-sosial-untuk-sdmi-kelas-iii-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan sifat dan perubahan wujud benda dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar sifat dan perubahan wujud benda. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Padat. Wujud yang bentuk dan volumenya relatif tetap. Contoh: Batu tetap berbentuk ketika dipindahkan ke wadah lain"},{"type":"text","body":"2. Cair. Wujud yang mengikuti bentuk wadah dengan volume relatif tetap. Contoh: Air berpindah bentuk saat dituangkan ke gelas"},{"type":"text","body":"3. Gas. Wujud yang menyebar mengisi ruang yang tersedia. Contoh: Udara mengisi bagian dalam balon"},{"type":"text","body":"4. Menguap. Perubahan cair menjadi gas. Contoh: Air pada pakaian basah berangsur masuk ke udara"},{"type":"text","body":"5. Mengembun. Perubahan gas menjadi cair. Contoh: Uap air membentuk tetes pada permukaan gelas dingin"},{"type":"text","body":"Contoh dan penalaran: Batu tetap berbentuk ketika dipindahkan ke wadah lain Kita mengenal padat sebagai wujud yang bentuk dan volumenya relatif tetap. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Amati air dan es dalam wadah aman. Jelaskan perubahan wujud dengan contoh yang dikenal tanpa pemanasan langsung."},{"type":"text","body":"Rangkuman: Padat: Wujud yang bentuk dan volumenya relatif tetap; Cair: Wujud yang mengikuti bentuk wadah dengan volume relatif tetap; Gas: Wujud yang menyebar mengisi ruang yang tersedia; Menguap: Perubahan cair menjadi gas; Mengembun: Perubahan gas menjadi cair."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('1b9042be-7761-5d61-99df-62eafc05854f','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Energi dalam kehidupan','belajar-ipas-kelas-3-unit-4',3,'B','Bab 4','sedang','draft',12,'{"summary":"Energi dalam kehidupan. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan energi dalam kehidupan dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru IPAS Kelas III (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-ilmu-pengetahuan-alam-dan-sosial-untuk-sdmi-kelas-iii-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan energi dalam kehidupan dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar energi dalam kehidupan. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Energi. Kemampuan yang berkaitan dengan melakukan kerja atau menyebabkan perubahan. Contoh: Energi membantu alat bergerak atau memberi cahaya"},{"type":"text","body":"2. Cahaya. Energi yang memungkinkan mata melihat benda. Contoh: Lampu menerangi halaman buku"},{"type":"text","body":"3. Bunyi. Getaran yang merambat melalui medium dan dapat didengar. Contoh: Senar yang bergetar menghasilkan suara"},{"type":"text","body":"4. Gerak. Perubahan posisi benda terhadap acuan. Contoh: Bola berpindah tempat setelah didorong"},{"type":"text","body":"5. Hemat energi. Menggunakan energi sesuai kebutuhan. Contoh: Lampu dimatikan saat ruangan tidak dipakai"},{"type":"text","body":"Contoh dan penalaran: Energi membantu alat bergerak atau memberi cahaya Kita mengenal energi sebagai kemampuan yang berkaitan dengan melakukan kerja atau menyebabkan perubahan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Cari contoh penggunaan cahaya, bunyi, dan gerak di sekitar. Jangan membuka alat listrik atau menatap sumber cahaya kuat."},{"type":"text","body":"Rangkuman: Energi: Kemampuan yang berkaitan dengan melakukan kerja atau menyebabkan perubahan; Cahaya: Energi yang memungkinkan mata melihat benda; Bunyi: Getaran yang merambat melalui medium dan dapat didengar; Gerak: Perubahan posisi benda terhadap acuan; Hemat energi: Menggunakan energi sesuai kebutuhan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('aeb0b84e-6b24-5f51-bbfd-731d0d15ead1','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Keluarga dan lingkungan sosial','belajar-ipas-kelas-3-unit-5',3,'B','Bab 5','sedang','draft',12,'{"summary":"Keluarga dan lingkungan sosial. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan keluarga dan lingkungan sosial dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru IPAS Kelas III (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-ilmu-pengetahuan-alam-dan-sosial-untuk-sdmi-kelas-iii-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan keluarga dan lingkungan sosial dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar keluarga dan lingkungan sosial. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Keluarga. Kelompok orang yang saling terhubung dan saling merawat dalam kehidupan. Contoh: Anggota keluarga berbagi tugas sesuai kemampuan"},{"type":"text","body":"2. Lingkungan sosial. Orang dan hubungan yang ada di sekitar kehidupan. Contoh: Teman, tetangga, dan guru berinteraksi sehari-hari"},{"type":"text","body":"3. Peran. Tugas atau kedudukan seseorang dalam kegiatan. Contoh: Penjaga perpustakaan membantu peminjaman buku"},{"type":"text","body":"4. Keragaman. Perbedaan ciri dan kebiasaan yang ada dalam kelompok. Contoh: Teman dapat menggunakan bahasa keluarga berbeda"},{"type":"text","body":"5. Kerja sama. Pembagian usaha untuk mencapai tujuan bersama. Contoh: Kelompok merapikan kelas dengan tugas yang disepakati"},{"type":"text","body":"Contoh dan penalaran: Anggota keluarga berbagi tugas sesuai kemampuan Kita mengenal keluarga sebagai kelompok orang yang saling terhubung dan saling merawat dalam kehidupan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat bagan peran dalam kegiatan bersama di sekolah. Gunakan nama peran, bukan data pribadi orang."},{"type":"text","body":"Rangkuman: Keluarga: Kelompok orang yang saling terhubung dan saling merawat dalam kehidupan; Lingkungan sosial: Orang dan hubungan yang ada di sekitar kehidupan; Peran: Tugas atau kedudukan seseorang dalam kegiatan; Keragaman: Perbedaan ciri dan kebiasaan yang ada dalam kelompok; Kerja sama: Pembagian usaha untuk mencapai tujuan bersama."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('8cdd8a47-7203-56cf-9227-1992718aa052','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Peta lingkungan dan bentang alam','belajar-ipas-kelas-3-unit-6',3,'B','Bab 6','sedang','draft',12,'{"summary":"Peta lingkungan dan bentang alam. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan peta lingkungan dan bentang alam dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru IPAS Kelas III (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-ilmu-pengetahuan-alam-dan-sosial-untuk-sdmi-kelas-iii-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan peta lingkungan dan bentang alam dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar peta lingkungan dan bentang alam. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Peta. Gambaran permukaan atau wilayah dengan tanda dan ukuran tertentu. Contoh: Peta menunjukkan hubungan letak antartempat"},{"type":"text","body":"2. Legenda. Penjelasan arti simbol pada peta. Contoh: Tanda garis biru dijelaskan sebagai sungai"},{"type":"text","body":"3. Arah mata angin. Pedoman arah seperti utara, timur, selatan, dan barat. Contoh: Panah utara membantu membaca arah peta"},{"type":"text","body":"4. Bentang alam. Bentuk permukaan bumi yang terbentuk secara alami. Contoh: Gunung, dataran, dan pantai adalah contoh bentang alam"},{"type":"text","body":"5. Adaptasi kegiatan. Penyesuaian tindakan manusia dengan keadaan lingkungan. Contoh: Penduduk menyesuaikan kegiatan dengan kondisi wilayah"},{"type":"text","body":"Contoh dan penalaran: Peta menunjukkan hubungan letak antartempat Kita mengenal peta sebagai gambaran permukaan atau wilayah dengan tanda dan ukuran tertentu. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Gambar peta lingkungan sederhana dengan simbol. Sebut bentang alam yang benar-benar kamu kenal dari sumber terpercaya."},{"type":"text","body":"Rangkuman: Peta: Gambaran permukaan atau wilayah dengan tanda dan ukuran tertentu; Legenda: Penjelasan arti simbol pada peta; Arah mata angin: Pedoman arah seperti utara, timur, selatan, dan barat; Bentang alam: Bentuk permukaan bumi yang terbentuk secara alami; Adaptasi kegiatan: Penyesuaian tindakan manusia dengan keadaan lingkungan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('5a75c5bc-fb2c-5ad9-ac23-d96cec57ab39','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Bentuk dan fungsi bagian tubuh tumbuhan','belajar-ipas-kelas-4-unit-1',4,'B','Bab 1','dasar','draft',12,'{"summary":"Bentuk dan fungsi bagian tubuh tumbuhan. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan bentuk dan fungsi bagian tubuh tumbuhan dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Buku Interaktif IPAS Kelas IV (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/buku-interaktif-ilmu-pengetahuan-alam-dan-sosial-untuk-sd-mi-kelas-iv-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan bentuk dan fungsi bagian tubuh tumbuhan dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar bentuk dan fungsi bagian tubuh tumbuhan. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Akar. Bagian tumbuhan yang menyerap air dan membantu menambatkan tumbuhan. Contoh: Akar menghubungkan tanaman dengan tanah"},{"type":"text","body":"2. Batang. Bagian penopang serta jalur pengangkutan pada tumbuhan. Contoh: Batang menopang daun ke arah cahaya"},{"type":"text","body":"3. Daun. Bagian utama tempat fotosintesis pada banyak tumbuhan hijau. Contoh: Daun memanfaatkan cahaya untuk proses pembuatan makanan"},{"type":"text","body":"4. Bunga. Bagian perkembangbiakan pada tumbuhan berbunga. Contoh: Bunga dapat berkembang menjadi buah setelah proses yang sesuai"},{"type":"text","body":"5. Biji. Bagian yang mengandung calon tumbuhan baru. Contoh: Biji kacang dapat berkecambah dalam kondisi sesuai"},{"type":"text","body":"Contoh dan penalaran: Akar menghubungkan tanaman dengan tanah Kita mengenal akar sebagai bagian tumbuhan yang menyerap air dan membantu menambatkan tumbuhan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Amati tanaman tanpa memetiknya. Gambarkan bagian dan jelaskan fungsi yang sesuai."},{"type":"text","body":"Rangkuman: Akar: Bagian tumbuhan yang menyerap air dan membantu menambatkan tumbuhan; Batang: Bagian penopang serta jalur pengangkutan pada tumbuhan; Daun: Bagian utama tempat fotosintesis pada banyak tumbuhan hijau; Bunga: Bagian perkembangbiakan pada tumbuhan berbunga; Biji: Bagian yang mengandung calon tumbuhan baru."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('37c99dda-4f18-543e-afab-7fc7c86136e0','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Gaya dan gerak','belajar-ipas-kelas-4-unit-2',4,'B','Bab 2','dasar','draft',12,'{"summary":"Gaya dan gerak. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan gaya dan gerak dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Buku Interaktif IPAS Kelas IV (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/buku-interaktif-ilmu-pengetahuan-alam-dan-sosial-untuk-sd-mi-kelas-iv-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan gaya dan gerak dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar gaya dan gerak. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Gaya. Tarikan atau dorongan yang dapat mengubah gerak atau bentuk. Contoh: Tangan mendorong mobil mainan"},{"type":"text","body":"2. Gerak. Perubahan posisi benda terhadap acuan. Contoh: Mobil berpindah dari satu tanda ke tanda lain"},{"type":"text","body":"3. Gesekan. Gaya yang menghambat gerak relatif antara permukaan bersentuhan. Contoh: Mobil melambat di permukaan kasar"},{"type":"text","body":"4. Gravitasi. Tarikan antarbenda bermassa yang antara lain membuat benda menuju bumi. Contoh: Benda yang dilepas dekat tanah jatuh ke bawah"},{"type":"text","body":"5. Magnet. Benda yang dapat menarik bahan tertentu seperti besi. Contoh: Penjepit besi dapat tertarik magnet yang sesuai"},{"type":"text","body":"Contoh dan penalaran: Tangan mendorong mobil mainan Kita mengenal gaya sebagai tarikan atau dorongan yang dapat mengubah gerak atau bentuk. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Dorong mobil mainan pelan pada permukaan aman. Catat perubahan gerak, bukan hanya kuat dorongannya."},{"type":"text","body":"Rangkuman: Gaya: Tarikan atau dorongan yang dapat mengubah gerak atau bentuk; Gerak: Perubahan posisi benda terhadap acuan; Gesekan: Gaya yang menghambat gerak relatif antara permukaan bersentuhan; Gravitasi: Tarikan antarbenda bermassa yang antara lain membuat benda menuju bumi; Magnet: Benda yang dapat menarik bahan tertentu seperti besi."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('0682fe24-eebd-58a1-90ea-3b696d65ccf9','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Energi dan perubahannya','belajar-ipas-kelas-4-unit-3',4,'B','Bab 3','dasar','draft',12,'{"summary":"Energi dan perubahannya. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan energi dan perubahannya dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Buku Interaktif IPAS Kelas IV (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/buku-interaktif-ilmu-pengetahuan-alam-dan-sosial-untuk-sd-mi-kelas-iv-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan energi dan perubahannya dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar energi dan perubahannya. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Energi listrik. Energi yang dipindahkan melalui rangkaian listrik. Contoh: Lampu memperoleh energi melalui rangkaian listrik"},{"type":"text","body":"2. Energi panas. Energi yang berpindah karena perbedaan suhu. Contoh: Benda hangat melepaskan panas ke sekitarnya"},{"type":"text","body":"3. Energi gerak. Energi yang dimiliki benda karena geraknya. Contoh: Baling-baling berputar saat kipas bekerja"},{"type":"text","body":"4. Perubahan energi. Peralihan energi dari satu bentuk ke bentuk lainnya. Contoh: Lampu mengubah sebagian energi listrik menjadi cahaya"},{"type":"text","body":"5. Sumber energi. Asal energi yang dimanfaatkan suatu sistem. Contoh: Matahari memberi energi cahaya pada panel surya"},{"type":"text","body":"Contoh dan penalaran: Lampu memperoleh energi melalui rangkaian listrik Kita mengenal energi listrik sebagai energi yang dipindahkan melalui rangkaian listrik. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Identifikasi perubahan energi pada alat dari gambar. Amati dari luar tanpa membuka alat listrik."},{"type":"text","body":"Rangkuman: Energi listrik: Energi yang dipindahkan melalui rangkaian listrik; Energi panas: Energi yang berpindah karena perbedaan suhu; Energi gerak: Energi yang dimiliki benda karena geraknya; Perubahan energi: Peralihan energi dari satu bentuk ke bentuk lainnya; Sumber energi: Asal energi yang dimanfaatkan suatu sistem."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('5b902a4e-3e76-5235-9a2b-b6da085dc840','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Sumber daya dan pelestarian','belajar-ipas-kelas-4-unit-4',4,'B','Bab 4','sedang','draft',12,'{"summary":"Sumber daya dan pelestarian. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan sumber daya dan pelestarian dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Buku Interaktif IPAS Kelas IV (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/buku-interaktif-ilmu-pengetahuan-alam-dan-sosial-untuk-sd-mi-kelas-iv-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan sumber daya dan pelestarian dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar sumber daya dan pelestarian. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Sumber daya alam. Bagian alam yang dimanfaatkan untuk memenuhi kebutuhan. Contoh: Air dan kayu dimanfaatkan manusia"},{"type":"text","body":"2. Terbarukan. Sumber daya yang dapat pulih melalui proses alam bila dikelola dengan baik. Contoh: Tumbuhan dapat ditanam kembali dengan waktu dan kondisi sesuai"},{"type":"text","body":"3. Tidak terbarukan. Sumber daya yang terbentuk sangat lama sehingga persediaannya terbatas. Contoh: Minyak bumi tidak cepat tergantikan setelah digunakan"},{"type":"text","body":"4. Pelestarian. Tindakan menjaga fungsi dan keberlanjutan lingkungan. Contoh: Hutan dikelola agar habitat dan sumber air tetap terjaga"},{"type":"text","body":"5. Penggunaan bijak. Pemanfaatan sesuai kebutuhan dengan mempertimbangkan dampaknya. Contoh: Air digunakan secukupnya dan kebocoran dilaporkan"},{"type":"text","body":"Contoh dan penalaran: Air dan kayu dimanfaatkan manusia Kita mengenal sumber daya alam sebagai bagian alam yang dimanfaatkan untuk memenuhi kebutuhan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Pilih sumber daya di sekitar dan buat usulan penggunaan hemat. Jelaskan alasan serta batas pengamatanmu."},{"type":"text","body":"Rangkuman: Sumber daya alam: Bagian alam yang dimanfaatkan untuk memenuhi kebutuhan; Terbarukan: Sumber daya yang dapat pulih melalui proses alam bila dikelola dengan baik; Tidak terbarukan: Sumber daya yang terbentuk sangat lama sehingga persediaannya terbatas; Pelestarian: Tindakan menjaga fungsi dan keberlanjutan lingkungan; Penggunaan bijak: Pemanfaatan sesuai kebutuhan dengan mempertimbangkan dampaknya."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('f5d74b49-5aa2-58f8-bb23-68c5eaeb65d0','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Keberagaman budaya dan sejarah daerah','belajar-ipas-kelas-4-unit-5',4,'B','Bab 5','sedang','draft',12,'{"summary":"Keberagaman budaya dan sejarah daerah. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan keberagaman budaya dan sejarah daerah dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Buku Interaktif IPAS Kelas IV (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/buku-interaktif-ilmu-pengetahuan-alam-dan-sosial-untuk-sd-mi-kelas-iv-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan keberagaman budaya dan sejarah daerah dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar keberagaman budaya dan sejarah daerah. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Budaya. Cara hidup dan hasil cipta yang dipelajari dalam masyarakat. Contoh: Bahasa dan kesenian diwariskan melalui pembelajaran"},{"type":"text","body":"2. Sejarah. Kajian tentang peristiwa masa lalu berdasarkan sumber. Contoh: Cerita masa lalu dibandingkan dengan bukti yang tersedia"},{"type":"text","body":"3. Sumber sejarah. Bukti atau keterangan yang membantu memahami masa lalu. Contoh: Foto lama dan dokumen dapat menjadi sumber sejarah"},{"type":"text","body":"4. Keragaman budaya. Keberadaan berbagai cara hidup dan karya masyarakat. Contoh: Wilayah Indonesia memiliki beragam bahasa dan kesenian"},{"type":"text","body":"5. Menghargai budaya. Sikap menghormati praktik dan karya masyarakat tanpa merendahkan. Contoh: Siswa mempelajari tradisi lain dengan bertanya sopan"},{"type":"text","body":"Contoh dan penalaran: Bahasa dan kesenian diwariskan melalui pembelajaran Kita mengenal budaya sebagai cara hidup dan hasil cipta yang dipelajari dalam masyarakat. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Cari satu informasi sejarah atau budaya daerah dari sumber terpercaya. Bedakan bukti, penafsiran, dan hal yang belum diketahui."},{"type":"text","body":"Rangkuman: Budaya: Cara hidup dan hasil cipta yang dipelajari dalam masyarakat; Sejarah: Kajian tentang peristiwa masa lalu berdasarkan sumber; Sumber sejarah: Bukti atau keterangan yang membantu memahami masa lalu; Keragaman budaya: Keberadaan berbagai cara hidup dan karya masyarakat; Menghargai budaya: Sikap menghormati praktik dan karya masyarakat tanpa merendahkan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('7799a6a9-18be-5b14-97fc-435dddb01c80','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Kebutuhan, uang, dan kegiatan ekonomi','belajar-ipas-kelas-4-unit-6',4,'B','Bab 6','sedang','draft',12,'{"summary":"Kebutuhan, uang, dan kegiatan ekonomi. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan kebutuhan, uang, dan kegiatan ekonomi dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Buku Interaktif IPAS Kelas IV (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/buku-interaktif-ilmu-pengetahuan-alam-dan-sosial-untuk-sd-mi-kelas-iv-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan kebutuhan, uang, dan kegiatan ekonomi dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar kebutuhan, uang, dan kegiatan ekonomi. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Kebutuhan. Hal yang diperlukan untuk hidup atau menjalankan kegiatan. Contoh: Air minum diperlukan tubuh"},{"type":"text","body":"2. Keinginan. Hal yang diharapkan tetapi tidak selalu harus dipenuhi. Contoh: Memilih warna tas tertentu dapat menjadi keinginan"},{"type":"text","body":"3. Uang. Alat tukar dan satuan untuk menilai harga dalam kegiatan ekonomi. Contoh: Pembeli membayar barang dengan uang yang berlaku"},{"type":"text","body":"4. Anggaran. Rencana penggunaan uang berdasarkan prioritas. Contoh: Anak mengalokasikan uang rekaan untuk alat yang diperlukan"},{"type":"text","body":"5. Kegiatan ekonomi. Kegiatan menghasilkan, menyalurkan, atau menggunakan barang dan jasa. Contoh: Pembuat roti, pengantar, dan pembeli mempunyai peran berbeda"},{"type":"text","body":"Contoh dan penalaran: Air minum diperlukan tubuh Kita mengenal kebutuhan sebagai hal yang diperlukan untuk hidup atau menjalankan kegiatan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat daftar kebutuhan suatu kegiatan belajar dan anggaran rekaan. Tidak perlu memakai data uang keluarga."},{"type":"text","body":"Rangkuman: Kebutuhan: Hal yang diperlukan untuk hidup atau menjalankan kegiatan; Keinginan: Hal yang diharapkan tetapi tidak selalu harus dipenuhi; Uang: Alat tukar dan satuan untuk menilai harga dalam kegiatan ekonomi; Anggaran: Rencana penggunaan uang berdasarkan prioritas; Kegiatan ekonomi: Kegiatan menghasilkan, menyalurkan, atau menggunakan barang dan jasa."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('b4b1ddd2-996e-5afb-9800-ab276f19400a','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Sistem tubuh dan pemeliharaan kesehatan','belajar-ipas-kelas-5-unit-1',5,'C','Bab 1','dasar','draft',12,'{"summary":"Sistem tubuh dan pemeliharaan kesehatan. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan sistem tubuh dan pemeliharaan kesehatan dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"IPAS Kelas V (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/ilmu-pengetahuan-alam-dan-sosial-untuk-sd-mi-kelas-v-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan sistem tubuh dan pemeliharaan kesehatan dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar sistem tubuh dan pemeliharaan kesehatan. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Pernapasan. Proses mengambil oksigen dan mengeluarkan karbon dioksida. Contoh: Udara masuk melalui saluran napas menuju paru-paru"},{"type":"text","body":"2. Pencernaan. Proses mengolah makanan agar zatnya dapat diserap. Contoh: Makanan dikunyah sebelum melalui saluran pencernaan"},{"type":"text","body":"3. Peredaran darah. Pergerakan darah yang mengangkut zat di dalam tubuh. Contoh: Jantung memompa darah melalui pembuluh"},{"type":"text","body":"4. Sistem gerak. Kerja tulang, sendi, dan otot yang mendukung gerakan. Contoh: Otot dan sendi membantu tangan ditekuk"},{"type":"text","body":"5. Kebiasaan sehat. Tindakan sehari-hari yang mendukung kesehatan tubuh. Contoh: Kebersihan, gerak, istirahat, dan makanan beragam diperhatikan"},{"type":"text","body":"Contoh dan penalaran: Udara masuk melalui saluran napas menuju paru-paru Kita mengenal pernapasan sebagai proses mengambil oksigen dan mengeluarkan karbon dioksida. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Gunakan gambar tubuh dari sumber belajar. Jelaskan fungsi umum dan kebiasaan merawat kesehatan tanpa mendiagnosis diri atau teman."},{"type":"text","body":"Rangkuman: Pernapasan: Proses mengambil oksigen dan mengeluarkan karbon dioksida; Pencernaan: Proses mengolah makanan agar zatnya dapat diserap; Peredaran darah: Pergerakan darah yang mengangkut zat di dalam tubuh; Sistem gerak: Kerja tulang, sendi, dan otot yang mendukung gerakan; Kebiasaan sehat: Tindakan sehari-hari yang mendukung kesehatan tubuh."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('401ec9a4-650b-5934-9bf1-02e6e13ae251','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Ekosistem dan hubungan makhluk hidup','belajar-ipas-kelas-5-unit-2',5,'C','Bab 2','dasar','draft',12,'{"summary":"Ekosistem dan hubungan makhluk hidup. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan ekosistem dan hubungan makhluk hidup dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"IPAS Kelas V (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/ilmu-pengetahuan-alam-dan-sosial-untuk-sd-mi-kelas-v-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan ekosistem dan hubungan makhluk hidup dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar ekosistem dan hubungan makhluk hidup. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Produsen. Makhluk hidup yang membuat makanannya sendiri. Contoh: Tumbuhan hijau menggunakan cahaya dalam fotosintesis"},{"type":"text","body":"2. Konsumen. Makhluk hidup yang memperoleh makanan dari makhluk lain. Contoh: Belalang memperoleh makanan dari tumbuhan"},{"type":"text","body":"3. Pengurai. Makhluk hidup yang menguraikan sisa organisme menjadi zat lebih sederhana. Contoh: Jamur dan bakteri menguraikan sisa makhluk hidup"},{"type":"text","body":"4. Rantai makanan. Urutan sederhana perpindahan energi melalui kegiatan makan. Contoh: Rumput dimakan belalang lalu belalang dimakan katak"},{"type":"text","body":"5. Ekosistem. Kesatuan makhluk hidup, lingkungan fisik, dan interaksinya. Contoh: Kolam memuat air, tumbuhan, hewan, serta hubungan di antaranya"},{"type":"text","body":"Contoh dan penalaran: Tumbuhan hijau menggunakan cahaya dalam fotosintesis Kita mengenal produsen sebagai makhluk hidup yang membuat makanannya sendiri. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Gambar hubungan sederhana tumbuhan, pemakan tumbuhan, dan pemangsa. Ingat bahwa jejaring nyata dapat lebih rumit."},{"type":"text","body":"Rangkuman: Produsen: Makhluk hidup yang membuat makanannya sendiri; Konsumen: Makhluk hidup yang memperoleh makanan dari makhluk lain; Pengurai: Makhluk hidup yang menguraikan sisa organisme menjadi zat lebih sederhana; Rantai makanan: Urutan sederhana perpindahan energi melalui kegiatan makan; Ekosistem: Kesatuan makhluk hidup, lingkungan fisik, dan interaksinya."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('04ddd5a7-5010-5e5b-95e6-b13a15d2f2b2','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Cahaya, bunyi, dan energi','belajar-ipas-kelas-5-unit-3',5,'C','Bab 3','dasar','draft',12,'{"summary":"Cahaya, bunyi, dan energi. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan cahaya, bunyi, dan energi dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"IPAS Kelas V (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/ilmu-pengetahuan-alam-dan-sosial-untuk-sd-mi-kelas-v-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan cahaya, bunyi, dan energi dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar cahaya, bunyi, dan energi. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Pemantulan cahaya. Perubahan arah cahaya setelah mengenai permukaan. Contoh: Cahaya dari cermin dapat berubah arah"},{"type":"text","body":"2. Pembiasan cahaya. Perubahan arah cahaya ketika melewati medium berbeda. Contoh: Sedotan dalam air tampak berubah arah di batas air"},{"type":"text","body":"3. Bayangan gelap. Daerah yang kurang mendapat cahaya karena terhalang benda. Contoh: Benda tidak tembus cahaya menghalangi cahaya ke layar"},{"type":"text","body":"4. Getaran. Gerak bolak-balik di sekitar posisi keseimbangan. Contoh: Penggaris yang digetarkan menimbulkan bunyi"},{"type":"text","body":"5. Perambatan bunyi. Penyebaran getaran melalui medium. Contoh: Bunyi merambat melalui udara menuju pendengar"},{"type":"text","body":"Contoh dan penalaran: Cahaya dari cermin dapat berubah arah Kita mengenal pemantulan cahaya sebagai perubahan arah cahaya setelah mengenai permukaan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Amati bayangan dengan lampu kecil dan benda aman bersama pendamping. Jangan menyorot mata atau memakai sumber bunyi keras."},{"type":"text","body":"Rangkuman: Pemantulan cahaya: Perubahan arah cahaya setelah mengenai permukaan; Pembiasan cahaya: Perubahan arah cahaya ketika melewati medium berbeda; Bayangan gelap: Daerah yang kurang mendapat cahaya karena terhalang benda; Getaran: Gerak bolak-balik di sekitar posisi keseimbangan; Perambatan bunyi: Penyebaran getaran melalui medium."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('9c78c6bc-937c-5d58-9fed-d2bcbd51492e','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Bumi dan perubahan lingkungan','belajar-ipas-kelas-5-unit-4',5,'C','Bab 4','sedang','draft',12,'{"summary":"Bumi dan perubahan lingkungan. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan bumi dan perubahan lingkungan dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"IPAS Kelas V (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/ilmu-pengetahuan-alam-dan-sosial-untuk-sd-mi-kelas-v-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan bumi dan perubahan lingkungan dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar bumi dan perubahan lingkungan. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Penguapan. Perubahan air cair menjadi uap air. Contoh: Sebagian air permukaan masuk ke udara"},{"type":"text","body":"2. Kondensasi. Perubahan uap air menjadi tetesan air. Contoh: Uap air yang mendingin dapat membentuk tetes kecil"},{"type":"text","body":"3. Presipitasi. Jatuhnya air dari atmosfer ke permukaan bumi. Contoh: Hujan membawa air kembali ke permukaan"},{"type":"text","body":"4. Infiltrasi. Masuknya air dari permukaan ke dalam tanah. Contoh: Sebagian air hujan meresap pada tanah yang sesuai"},{"type":"text","body":"5. Iklim. Pola keadaan cuaca dalam jangka panjang pada suatu wilayah. Contoh: Iklim tidak disimpulkan hanya dari hujan satu sore"},{"type":"text","body":"Contoh dan penalaran: Sebagian air permukaan masuk ke udara Kita mengenal penguapan sebagai perubahan air cair menjadi uap air. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat diagram sederhana siklus air. Bedakan pengamatan cuaca harian dari pembahasan iklim jangka panjang."},{"type":"text","body":"Rangkuman: Penguapan: Perubahan air cair menjadi uap air; Kondensasi: Perubahan uap air menjadi tetesan air; Presipitasi: Jatuhnya air dari atmosfer ke permukaan bumi; Infiltrasi: Masuknya air dari permukaan ke dalam tanah; Iklim: Pola keadaan cuaca dalam jangka panjang pada suatu wilayah."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('a44e92e4-9a54-5109-816e-3e3f77734f68','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Kondisi geografis Indonesia','belajar-ipas-kelas-5-unit-5',5,'C','Bab 5','sedang','draft',12,'{"summary":"Kondisi geografis Indonesia. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan kondisi geografis indonesia dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"IPAS Kelas V (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/ilmu-pengetahuan-alam-dan-sosial-untuk-sd-mi-kelas-v-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan kondisi geografis indonesia dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar kondisi geografis indonesia. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Kepulauan. Wilayah yang terdiri dari banyak pulau. Contoh: Indonesia memiliki banyak pulau yang dihubungkan perairan"},{"type":"text","body":"2. Letak geografis. Posisi wilayah terhadap wilayah atau unsur bumi di sekitarnya. Contoh: Letak suatu pulau dijelaskan terhadap laut dan pulau lain"},{"type":"text","body":"3. Dataran tinggi. Wilayah daratan yang berada relatif tinggi dibanding sekitarnya. Contoh: Kondisi dataran tinggi dapat memengaruhi pilihan kegiatan"},{"type":"text","body":"4. Pesisir. Wilayah peralihan daratan dan laut di dekat pantai. Contoh: Kegiatan masyarakat pesisir berkaitan dengan kondisi setempat"},{"type":"text","body":"5. Keterhubungan wilayah. Hubungan antartempat melalui perpindahan orang, barang, atau informasi. Contoh: Hasil suatu daerah dikirim untuk kebutuhan daerah lain"},{"type":"text","body":"Contoh dan penalaran: Indonesia memiliki banyak pulau yang dihubungkan perairan Kita mengenal kepulauan sebagai wilayah yang terdiri dari banyak pulau. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Baca peta Indonesia dengan legenda dan arah. Jelaskan satu hubungan letak wilayah dengan aktivitas tanpa menganggap semua penduduk sama."},{"type":"text","body":"Rangkuman: Kepulauan: Wilayah yang terdiri dari banyak pulau; Letak geografis: Posisi wilayah terhadap wilayah atau unsur bumi di sekitarnya; Dataran tinggi: Wilayah daratan yang berada relatif tinggi dibanding sekitarnya; Pesisir: Wilayah peralihan daratan dan laut di dekat pantai; Keterhubungan wilayah: Hubungan antartempat melalui perpindahan orang, barang, atau informasi."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('7beb046f-24cd-5880-8278-e62f0b293085','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Kegiatan ekonomi dan budaya','belajar-ipas-kelas-5-unit-6',5,'C','Bab 6','sedang','draft',12,'{"summary":"Kegiatan ekonomi dan budaya. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan kegiatan ekonomi dan budaya dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"IPAS Kelas V (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/ilmu-pengetahuan-alam-dan-sosial-untuk-sd-mi-kelas-v-edisi-revisi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan kegiatan ekonomi dan budaya dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar kegiatan ekonomi dan budaya. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Produksi. Kegiatan menghasilkan barang atau jasa. Contoh: Pengrajin membuat keranjang"},{"type":"text","body":"2. Distribusi. Kegiatan menyalurkan barang atau jasa menuju pengguna. Contoh: Keranjang diangkut ke tempat penjualan"},{"type":"text","body":"3. Konsumsi. Kegiatan menggunakan barang atau jasa untuk memenuhi kebutuhan. Contoh: Keluarga memakai keranjang untuk menyimpan barang"},{"type":"text","body":"4. Interdependensi. Keadaan saling bergantung antarorang atau wilayah. Contoh: Pembuat barang memerlukan bahan dan jasa pihak lain"},{"type":"text","body":"5. Konsumsi bertanggung jawab. Penggunaan barang dengan mempertimbangkan kebutuhan dan dampaknya. Contoh: Pembeli memilih barang yang diperlukan dan merawatnya"},{"type":"text","body":"Contoh dan penalaran: Pengrajin membuat keranjang Kita mengenal produksi sebagai kegiatan menghasilkan barang atau jasa. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Ikuti perjalanan barang sederhana dari pembuat hingga pemakai. Jelaskan peran setiap pihak dan dampak pilihan konsumsi."},{"type":"text","body":"Rangkuman: Produksi: Kegiatan menghasilkan barang atau jasa; Distribusi: Kegiatan menyalurkan barang atau jasa menuju pengguna; Konsumsi: Kegiatan menggunakan barang atau jasa untuk memenuhi kebutuhan; Interdependensi: Keadaan saling bergantung antarorang atau wilayah; Konsumsi bertanggung jawab: Penggunaan barang dengan mempertimbangkan kebutuhan dan dampaknya."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('63a9ead7-a041-50d7-8ca2-fa0ed23815dc','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Sistem tubuh dan kesehatan','belajar-ipas-kelas-6-unit-1',6,'C','Bab 1','dasar','draft',12,'{"summary":"Sistem tubuh dan kesehatan. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan sistem tubuh dan kesehatan dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan mata pelajaran untuk pendamping","url":"https://kurikulum.kemendikdasmen.go.id/panduan-mapel","usage":"Acuan pendamping; pengayaan Fase A bukan klaim CP mapel wajib."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan sistem tubuh dan kesehatan dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar sistem tubuh dan kesehatan. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Koordinasi sistem tubuh. Kerja beberapa sistem tubuh yang saling mendukung. Contoh: Gerak tubuh memerlukan kerja otot, tulang, saraf, dan suplai zat"},{"type":"text","body":"2. Oksigen. Gas yang diperlukan sel tubuh untuk proses memperoleh energi. Contoh: Pernapasan menyediakan oksigen yang diangkut darah"},{"type":"text","body":"3. Zat gizi. Zat dalam makanan yang mendukung fungsi dan pertumbuhan tubuh. Contoh: Makanan beragam membantu memenuhi kebutuhan zat gizi"},{"type":"text","body":"4. Kebersihan diri. Kebiasaan merawat tubuh dan lingkungan pribadi. Contoh: Anak membersihkan tangan serta menggunakan alat pribadi dengan benar"},{"type":"text","body":"5. Mencari bantuan. Menyampaikan keluhan atau keadaan tidak aman kepada orang dewasa tepercaya. Contoh: Anak memberi tahu pendamping ketika merasa tidak sehat"},{"type":"text","body":"Contoh dan penalaran: Gerak tubuh memerlukan kerja otot, tulang, saraf, dan suplai zat Kita mengenal koordinasi sistem tubuh sebagai kerja beberapa sistem tubuh yang saling mendukung. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Gunakan bagan sederhana hubungan beberapa sistem tubuh. Jelaskan kebiasaan merawat kesehatan dan kapan meminta bantuan orang dewasa."},{"type":"text","body":"Rangkuman: Koordinasi sistem tubuh: Kerja beberapa sistem tubuh yang saling mendukung; Oksigen: Gas yang diperlukan sel tubuh untuk proses memperoleh energi; Zat gizi: Zat dalam makanan yang mendukung fungsi dan pertumbuhan tubuh; Kebersihan diri: Kebiasaan merawat tubuh dan lingkungan pribadi; Mencari bantuan: Menyampaikan keluhan atau keadaan tidak aman kepada orang dewasa tepercaya."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('d3303805-f948-5eb7-8c4d-bb2c6194721d','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Energi dan pemanfaatannya','belajar-ipas-kelas-6-unit-2',6,'C','Bab 2','dasar','draft',12,'{"summary":"Energi dan pemanfaatannya. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan energi dan pemanfaatannya dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan mata pelajaran untuk pendamping","url":"https://kurikulum.kemendikdasmen.go.id/panduan-mapel","usage":"Acuan pendamping; pengayaan Fase A bukan klaim CP mapel wajib."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan energi dan pemanfaatannya dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar energi dan pemanfaatannya. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Energi surya. Energi yang berasal dari matahari. Contoh: Panel surya memanfaatkan cahaya matahari"},{"type":"text","body":"2. Energi kimia. Energi yang tersimpan dalam zat dan dapat dilepas melalui proses kimia. Contoh: Baterai menyimpan energi kimia"},{"type":"text","body":"3. Konversi energi. Perubahan energi menjadi bentuk lain yang dapat dimanfaatkan. Contoh: Motor mengubah energi listrik menjadi gerak dan panas"},{"type":"text","body":"4. Efisiensi. Perbandingan manfaat yang diperoleh terhadap sumber daya yang digunakan. Contoh: Alat yang memberi manfaat sama dengan energi lebih sedikit lebih efisien"},{"type":"text","body":"5. Dampak energi. Pengaruh penyediaan dan penggunaan energi pada lingkungan dan masyarakat. Contoh: Pilihan sumber energi mempunyai manfaat serta konsekuensi"},{"type":"text","body":"Contoh dan penalaran: Panel surya memanfaatkan cahaya matahari Kita mengenal energi surya sebagai energi yang berasal dari matahari. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Bandingkan dua cara menggunakan energi pada gambar. Jelaskan manfaat dan dampaknya tanpa melakukan percobaan listrik sendiri."},{"type":"text","body":"Rangkuman: Energi surya: Energi yang berasal dari matahari; Energi kimia: Energi yang tersimpan dalam zat dan dapat dilepas melalui proses kimia; Konversi energi: Perubahan energi menjadi bentuk lain yang dapat dimanfaatkan; Efisiensi: Perbandingan manfaat yang diperoleh terhadap sumber daya yang digunakan; Dampak energi: Pengaruh penyediaan dan penggunaan energi pada lingkungan dan masyarakat."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('7a18b5b0-c5bf-562f-8a60-b26518d6cb51','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Bumi dan tata surya','belajar-ipas-kelas-6-unit-3',6,'C','Bab 3','dasar','draft',12,'{"summary":"Bumi dan tata surya. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan bumi dan tata surya dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan mata pelajaran untuk pendamping","url":"https://kurikulum.kemendikdasmen.go.id/panduan-mapel","usage":"Acuan pendamping; pengayaan Fase A bukan klaim CP mapel wajib."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan bumi dan tata surya dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar bumi dan tata surya. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Rotasi bumi. Perputaran bumi pada sumbunya. Contoh: Bagian bumi bergantian menghadap sumber cahaya dalam model"},{"type":"text","body":"2. Revolusi bumi. Gerakan bumi mengelilingi matahari. Contoh: Bumi bergerak mengitari matahari sepanjang tahun"},{"type":"text","body":"3. Bulan. Satelit alami bumi. Contoh: Bulan mengelilingi bumi"},{"type":"text","body":"4. Tata surya. Matahari dan benda-benda yang terikat gravitasinya. Contoh: Planet-planet mengelilingi matahari"},{"type":"text","body":"5. Model ilmiah. Representasi untuk membantu menjelaskan gejala dengan keterbatasan. Contoh: Bola dan lampu membantu memahami siang-malam tetapi tidak berskala nyata"},{"type":"text","body":"Contoh dan penalaran: Bagian bumi bergantian menghadap sumber cahaya dalam model Kita mengenal rotasi bumi sebagai perputaran bumi pada sumbunya. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Gunakan bola dan lampu dengan pendamping untuk memodelkan siang-malam. Jangan menganggap ukuran model sama dengan keadaan sebenarnya."},{"type":"text","body":"Rangkuman: Rotasi bumi: Perputaran bumi pada sumbunya; Revolusi bumi: Gerakan bumi mengelilingi matahari; Bulan: Satelit alami bumi; Tata surya: Matahari dan benda-benda yang terikat gravitasinya; Model ilmiah: Representasi untuk membantu menjelaskan gejala dengan keterbatasan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('69f70881-f416-5ebe-a05e-ac56cc99bd59','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Perubahan lingkungan dan tindakan bersama','belajar-ipas-kelas-6-unit-4',6,'C','Bab 4','sedang','draft',12,'{"summary":"Perubahan lingkungan dan tindakan bersama. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan perubahan lingkungan dan tindakan bersama dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan mata pelajaran untuk pendamping","url":"https://kurikulum.kemendikdasmen.go.id/panduan-mapel","usage":"Acuan pendamping; pengayaan Fase A bukan klaim CP mapel wajib."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan perubahan lingkungan dan tindakan bersama dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar perubahan lingkungan dan tindakan bersama. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Perubahan lingkungan. Perubahan kondisi fisik atau kehidupan pada suatu tempat. Contoh: Jumlah sampah di sudut sekolah meningkat"},{"type":"text","body":"2. Dampak. Pengaruh yang ditimbulkan suatu perubahan atau tindakan. Contoh: Saluran tersumbat dapat mengganggu aliran air"},{"type":"text","body":"3. Mitigasi. Upaya mengurangi risiko atau dampak merugikan. Contoh: Ruang resapan dijaga dan sampah dikelola dengan benar"},{"type":"text","body":"4. Adaptasi. Penyesuaian tindakan terhadap perubahan kondisi. Contoh: Warga menyesuaikan kegiatan dengan informasi cuaca yang sah"},{"type":"text","body":"5. Evaluasi tindakan. Pemeriksaan hasil untuk menentukan perbaikan berikutnya. Contoh: Kelompok membandingkan catatan sebelum dan setelah kegiatan"},{"type":"text","body":"Contoh dan penalaran: Jumlah sampah di sudut sekolah meningkat Kita mengenal perubahan lingkungan sebagai perubahan kondisi fisik atau kehidupan pada suatu tempat. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Pilih masalah lingkungan kecil yang dapat ditangani bersama. Tulis bukti, usulan tindakan aman, dan cara menilai hasilnya."},{"type":"text","body":"Rangkuman: Perubahan lingkungan: Perubahan kondisi fisik atau kehidupan pada suatu tempat; Dampak: Pengaruh yang ditimbulkan suatu perubahan atau tindakan; Mitigasi: Upaya mengurangi risiko atau dampak merugikan; Adaptasi: Penyesuaian tindakan terhadap perubahan kondisi; Evaluasi tindakan: Pemeriksaan hasil untuk menentukan perbaikan berikutnya."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('c3e1dcfc-a8fd-54e4-9f5f-ae339dc771cf','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Peristiwa sejarah dan kehidupan masyarakat','belajar-ipas-kelas-6-unit-5',6,'C','Bab 5','sedang','draft',12,'{"summary":"Peristiwa sejarah dan kehidupan masyarakat. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan peristiwa sejarah dan kehidupan masyarakat dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan mata pelajaran untuk pendamping","url":"https://kurikulum.kemendikdasmen.go.id/panduan-mapel","usage":"Acuan pendamping; pengayaan Fase A bukan klaim CP mapel wajib."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan peristiwa sejarah dan kehidupan masyarakat dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar peristiwa sejarah dan kehidupan masyarakat. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Kronologi. Urutan peristiwa berdasarkan waktu terjadinya. Contoh: Peristiwa ditata dari lebih dahulu ke kemudian"},{"type":"text","body":"2. Sumber primer. Sumber yang berasal langsung dari masa atau pelaku peristiwa. Contoh: Dokumen asli dapat memberi bukti tentang suatu kejadian"},{"type":"text","body":"3. Sumber sekunder. Uraian yang disusun dari penelaahan sumber lain. Contoh: Buku sejarah menjelaskan peristiwa memakai berbagai bukti"},{"type":"text","body":"4. Perubahan sosial. Perubahan dalam cara hidup atau hubungan masyarakat. Contoh: Cara masyarakat bertukar informasi berubah seiring teknologi"},{"type":"text","body":"5. Keberlanjutan. Hal yang tetap bertahan meskipun keadaan lain berubah. Contoh: Nilai kerja sama tetap dijalankan dengan bentuk kegiatan baru"},{"type":"text","body":"Contoh dan penalaran: Peristiwa ditata dari lebih dahulu ke kemudian Kita mengenal kronologi sebagai urutan peristiwa berdasarkan waktu terjadinya. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Susun lini masa peristiwa sejarah dari sumber terpercaya. Sebut asal informasi dan bedakan fakta dengan pendapat tentang peristiwa itu."},{"type":"text","body":"Rangkuman: Kronologi: Urutan peristiwa berdasarkan waktu terjadinya; Sumber primer: Sumber yang berasal langsung dari masa atau pelaku peristiwa; Sumber sekunder: Uraian yang disusun dari penelaahan sumber lain; Perubahan sosial: Perubahan dalam cara hidup atau hubungan masyarakat; Keberlanjutan: Hal yang tetap bertahan meskipun keadaan lain berubah."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('2c6ec67b-853e-51fb-95c4-98332e61dd94','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Indonesia dalam hubungan antarwilayah','belajar-ipas-kelas-6-unit-6',6,'C','Bab 6','sedang','draft',12,'{"summary":"Indonesia dalam hubungan antarwilayah. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan indonesia dalam hubungan antarwilayah dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan mata pelajaran untuk pendamping","url":"https://kurikulum.kemendikdasmen.go.id/panduan-mapel","usage":"Acuan pendamping; pengayaan Fase A bukan klaim CP mapel wajib."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan indonesia dalam hubungan antarwilayah dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar indonesia dalam hubungan antarwilayah. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Perdagangan antarwilayah. Pertukaran barang atau jasa antara tempat berbeda. Contoh: Hasil pertanian suatu daerah dijual ke daerah lain"},{"type":"text","body":"2. Transportasi. Sarana dan kegiatan memindahkan orang atau barang. Contoh: Kapal mengangkut barang antarpulau"},{"type":"text","body":"3. Komunikasi. Penyampaian informasi antara pihak yang berbeda. Contoh: Penjual memberi kabar pengiriman kepada pembeli"},{"type":"text","body":"4. Kerja sama. Usaha bersama untuk memenuhi tujuan atau kebutuhan. Contoh: Beberapa wilayah saling mendukung penyediaan barang"},{"type":"text","body":"5. Dampak keterhubungan. Pengaruh hubungan antarwilayah pada kehidupan. Contoh: Perubahan pengiriman di satu tempat dapat memengaruhi persediaan di tempat lain"},{"type":"text","body":"Contoh dan penalaran: Hasil pertanian suatu daerah dijual ke daerah lain Kita mengenal perdagangan antarwilayah sebagai pertukaran barang atau jasa antara tempat berbeda. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Pilih satu barang sehari-hari dan petakan hubungan antarwilayah yang diperlukan untuk menyediakannya. Hindari menganggap asal barang tanpa bukti."},{"type":"text","body":"Rangkuman: Perdagangan antarwilayah: Pertukaran barang atau jasa antara tempat berbeda; Transportasi: Sarana dan kegiatan memindahkan orang atau barang; Komunikasi: Penyampaian informasi antara pihak yang berbeda; Kerja sama: Usaha bersama untuk memenuhi tujuan atau kebutuhan; Dampak keterhubungan: Pengaruh hubungan antarwilayah pada kehidupan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('f23532da-0b39-5223-8ab5-2469841431c1','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Mengenal diri dan teman','belajar-pancasila-kelas-1-unit-1',1,'A','Bab 1','dasar','draft',8,'{"summary":"Mengenal diri dan teman. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan mengenal diri dan teman dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Pendidikan Pancasila Kelas I","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-pendidikan-pancasila-untuk-sdmi-kelas-i","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan mengenal diri dan teman dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar mengenal diri dan teman. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Identitas. Ciri atau keterangan yang membantu mengenali seseorang. Contoh: Anak memperkenalkan nama panggilan dan kesukaan"},{"type":"text","body":"2. Persamaan. Ciri yang dimiliki bersama oleh beberapa orang. Contoh: Dua teman sama-sama senang membaca"},{"type":"text","body":"3. Perbedaan. Ciri yang tidak sama antara satu orang dan lainnya. Contoh: Teman mempunyai kesukaan berbeda"},{"type":"text","body":"4. Menghargai. Memperlakukan orang lain dengan hormat. Contoh: Anak tidak mengejek cara bicara temannya"},{"type":"text","body":"5. Privasi. Hal pribadi yang perlu dijaga dan tidak dibagikan sembarangan. Contoh: Anak tidak menyebarkan alamat atau nomor telepon teman"},{"type":"text","body":"Contoh dan penalaran: Anak memperkenalkan nama panggilan dan kesukaan Kita mengenal identitas sebagai ciri atau keterangan yang membantu mengenali seseorang. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Perkenalkan diri dengan nama panggilan dan kesukaan. Temukan satu persamaan dan satu perbedaan dengan teman tanpa mengejek."},{"type":"text","body":"Rangkuman: Identitas: Ciri atau keterangan yang membantu mengenali seseorang; Persamaan: Ciri yang dimiliki bersama oleh beberapa orang; Perbedaan: Ciri yang tidak sama antara satu orang dan lainnya; Menghargai: Memperlakukan orang lain dengan hormat; Privasi: Hal pribadi yang perlu dijaga dan tidak dibagikan sembarangan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('e2aee0fe-6fc2-5250-938f-8034906948ca','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Aturan sederhana di rumah','belajar-pancasila-kelas-1-unit-2',1,'A','Bab 2','dasar','draft',8,'{"summary":"Aturan sederhana di rumah. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan aturan sederhana di rumah dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Pendidikan Pancasila Kelas I","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-pendidikan-pancasila-untuk-sdmi-kelas-i","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan aturan sederhana di rumah dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar aturan sederhana di rumah. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Aturan. Ketentuan untuk menjaga keteraturan dan kenyamanan. Contoh: Anggota keluarga merapikan alat setelah digunakan"},{"type":"text","body":"2. Kesepakatan. Hal yang disetujui bersama. Contoh: Kelompok menyetujui giliran memakai mainan"},{"type":"text","body":"3. Giliran. Kesempatan yang diberikan secara bergantian. Contoh: Anak menunggu teman selesai memakai alat"},{"type":"text","body":"4. Tanggung jawab. Kesediaan menjalankan tugas dan menjaga akibat tindakan. Contoh: Anak mengembalikan buku yang dipinjam"},{"type":"text","body":"5. Konsekuensi. Akibat yang berkaitan dengan tindakan dan perlu dipahami. Contoh: Mainan yang tidak dirapikan dapat menghalangi jalan"},{"type":"text","body":"Contoh dan penalaran: Anggota keluarga merapikan alat setelah digunakan Kita mengenal aturan sebagai ketentuan untuk menjaga keteraturan dan kenyamanan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat dua aturan kegiatan rumah bersama pendamping. Jelaskan tujuan dan akibat bila tidak dijalankan."},{"type":"text","body":"Rangkuman: Aturan: Ketentuan untuk menjaga keteraturan dan kenyamanan; Kesepakatan: Hal yang disetujui bersama; Giliran: Kesempatan yang diberikan secara bergantian; Tanggung jawab: Kesediaan menjalankan tugas dan menjaga akibat tindakan; Konsekuensi: Akibat yang berkaitan dengan tindakan dan perlu dipahami."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('666c4058-f1c2-50ee-8dd7-400699df17d7','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Simbol dan nilai Pancasila','belajar-pancasila-kelas-1-unit-3',1,'A','Bab 3','dasar','draft',8,'{"summary":"Simbol dan nilai Pancasila. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan simbol dan nilai pancasila dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Pendidikan Pancasila Kelas I","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-pendidikan-pancasila-untuk-sdmi-kelas-i","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan simbol dan nilai pancasila dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar simbol dan nilai pancasila. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Ketuhanan. Nilai menghormati keyakinan dan menjalankan ajaran agama masing-masing. Contoh: Anak tidak mengganggu teman yang beribadah"},{"type":"text","body":"2. Kemanusiaan. Nilai memperlakukan orang dengan hormat dan peduli. Contoh: Anak membantu teman yang mengalami kesulitan"},{"type":"text","body":"3. Persatuan. Nilai menjaga kebersamaan dalam perbedaan. Contoh: Teman yang berbeda kesukaan tetap bekerja bersama"},{"type":"text","body":"4. Musyawarah. Membahas pilihan dengan mendengarkan pendapat bersama. Contoh: Kelompok mendiskusikan permainan yang akan dipilih"},{"type":"text","body":"5. Keadilan. Nilai memperlakukan orang secara layak sesuai hak dan kebutuhannya. Contoh: Anak membagi kesempatan memakai alat dengan wajar"},{"type":"text","body":"Contoh dan penalaran: Anak tidak mengganggu teman yang beribadah Kita mengenal ketuhanan sebagai nilai menghormati keyakinan dan menjalankan ajaran agama masing-masing. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Ceritakan satu tindakan sesuai nilai Pancasila. Hubungkan dengan alasan menghormati orang lain."},{"type":"text","body":"Rangkuman: Ketuhanan: Nilai menghormati keyakinan dan menjalankan ajaran agama masing-masing; Kemanusiaan: Nilai memperlakukan orang dengan hormat dan peduli; Persatuan: Nilai menjaga kebersamaan dalam perbedaan; Musyawarah: Membahas pilihan dengan mendengarkan pendapat bersama; Keadilan: Nilai memperlakukan orang secara layak sesuai hak dan kebutuhannya."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('84b73c98-dbf5-5362-a5d8-91ce85b974c3','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Berbagi dan bergiliran','belajar-pancasila-kelas-1-unit-4',1,'A','Bab 4','sedang','draft',8,'{"summary":"Berbagi dan bergiliran. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan berbagi dan bergiliran dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Pendidikan Pancasila Kelas I","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-pendidikan-pancasila-untuk-sdmi-kelas-i","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan berbagi dan bergiliran dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar berbagi dan bergiliran. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Berbagi. Memberi kesempatan menggunakan sesuatu bersama secara wajar. Contoh: Anak menawarkan alat yang tidak sedang digunakan"},{"type":"text","body":"2. Bergiliran. Menggunakan kesempatan satu demi satu menurut kesepakatan. Contoh: Setelah Rani mencoba, Bima mendapat kesempatan"},{"type":"text","body":"3. Meminta izin. Meminta persetujuan sebelum memakai milik orang lain. Contoh: Anak bertanya sebelum meminjam pensil"},{"type":"text","body":"4. Menjaga barang. Menggunakan benda dengan hati-hati sesuai fungsinya. Contoh: Pensil pinjaman dikembalikan dalam keadaan baik"},{"type":"text","body":"5. Batas pribadi. Hal yang boleh atau tidak boleh dilakukan terhadap diri atau milik seseorang. Contoh: Teman boleh menolak meminjamkan barang yang masih dipakai"},{"type":"text","body":"Contoh dan penalaran: Anak menawarkan alat yang tidak sedang digunakan Kita mengenal berbagi sebagai memberi kesempatan menggunakan sesuatu bersama secara wajar. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Praktikkan meminta izin dan bergiliran memakai alat. Teman boleh menolak ketika masih memakainya."},{"type":"text","body":"Rangkuman: Berbagi: Memberi kesempatan menggunakan sesuatu bersama secara wajar; Bergiliran: Menggunakan kesempatan satu demi satu menurut kesepakatan; Meminta izin: Meminta persetujuan sebelum memakai milik orang lain; Menjaga barang: Menggunakan benda dengan hati-hati sesuai fungsinya; Batas pribadi: Hal yang boleh atau tidak boleh dilakukan terhadap diri atau milik seseorang."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('29fd7f89-17f3-50c1-8625-0a9e1173b208','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Menghargai perbedaan','belajar-pancasila-kelas-1-unit-5',1,'A','Bab 5','sedang','draft',8,'{"summary":"Menghargai perbedaan. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan menghargai perbedaan dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Pendidikan Pancasila Kelas I","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-pendidikan-pancasila-untuk-sdmi-kelas-i","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan menghargai perbedaan dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar menghargai perbedaan. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Identitas. Ciri atau keterangan yang membantu mengenali seseorang. Contoh: Anak memperkenalkan nama panggilan dan kesukaan"},{"type":"text","body":"2. Persamaan. Ciri yang dimiliki bersama oleh beberapa orang. Contoh: Dua teman sama-sama senang membaca"},{"type":"text","body":"3. Perbedaan. Ciri yang tidak sama antara satu orang dan lainnya. Contoh: Teman mempunyai kesukaan berbeda"},{"type":"text","body":"4. Menghargai. Memperlakukan orang lain dengan hormat. Contoh: Anak tidak mengejek cara bicara temannya"},{"type":"text","body":"5. Privasi. Hal pribadi yang perlu dijaga dan tidak dibagikan sembarangan. Contoh: Anak tidak menyebarkan alamat atau nomor telepon teman"},{"type":"text","body":"Contoh dan penalaran: Anak memperkenalkan nama panggilan dan kesukaan Kita mengenal identitas sebagai ciri atau keterangan yang membantu mengenali seseorang. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Gambar kesukaan teman yang berbeda darimu. Tanyakan dengan sopan tanpa membagikan data pribadinya."},{"type":"text","body":"Rangkuman: Identitas: Ciri atau keterangan yang membantu mengenali seseorang; Persamaan: Ciri yang dimiliki bersama oleh beberapa orang; Perbedaan: Ciri yang tidak sama antara satu orang dan lainnya; Menghargai: Memperlakukan orang lain dengan hormat; Privasi: Hal pribadi yang perlu dijaga dan tidak dibagikan sembarangan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('65100e6a-545f-51fa-b8a4-b190d6288809','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Merawat lingkungan bersama','belajar-pancasila-kelas-1-unit-6',1,'A','Bab 6','sedang','draft',8,'{"summary":"Merawat lingkungan bersama. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan merawat lingkungan bersama dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Pendidikan Pancasila Kelas I","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-pendidikan-pancasila-untuk-sdmi-kelas-i","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan merawat lingkungan bersama dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar merawat lingkungan bersama. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Kerja sama. Melakukan usaha bersama untuk mencapai tujuan. Contoh: Kelompok menata sudut baca bersama"},{"type":"text","body":"2. Pembagian tugas. Membagi pekerjaan sesuai kemampuan dan kesepakatan. Contoh: Seorang anak menyusun buku, yang lain menyiapkan label"},{"type":"text","body":"3. Tolong-menolong. Membantu orang lain sesuai kemampuan tanpa merendahkan. Contoh: Teman membantu membawa benda yang aman"},{"type":"text","body":"4. Peduli. Memperhatikan keadaan dan kebutuhan orang lain. Contoh: Anak menyadari temannya belum mendapat giliran"},{"type":"text","body":"5. Gotong royong. Bekerja bersama demi kepentingan bersama. Contoh: Warga sekolah merawat taman secara bersama"},{"type":"text","body":"Contoh dan penalaran: Kelompok menata sudut baca bersama Kita mengenal kerja sama sebagai melakukan usaha bersama untuk mencapai tujuan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Pilih satu fasilitas yang dipakai bersama dan lakukan tindakan aman untuk merawatnya."},{"type":"text","body":"Rangkuman: Kerja sama: Melakukan usaha bersama untuk mencapai tujuan; Pembagian tugas: Membagi pekerjaan sesuai kemampuan dan kesepakatan; Tolong-menolong: Membantu orang lain sesuai kemampuan tanpa merendahkan; Peduli: Memperhatikan keadaan dan kebutuhan orang lain; Gotong royong: Bekerja bersama demi kepentingan bersama."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('59202a7e-e23a-5c44-83a9-1af4423fdd08','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Kebiasaan sesuai nilai Pancasila','belajar-pancasila-kelas-2-unit-1',2,'A','Bab 1','dasar','draft',8,'{"summary":"Kebiasaan sesuai nilai Pancasila. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan kebiasaan sesuai nilai pancasila dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Pendidikan Pancasila Kelas II","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-pendidikan-pancasila-untuk-sdmi-kelas-ii","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan kebiasaan sesuai nilai pancasila dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar kebiasaan sesuai nilai pancasila. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Ketuhanan. Nilai menghormati keyakinan dan menjalankan ajaran agama masing-masing. Contoh: Anak tidak mengganggu teman yang beribadah"},{"type":"text","body":"2. Kemanusiaan. Nilai memperlakukan orang dengan hormat dan peduli. Contoh: Anak membantu teman yang mengalami kesulitan"},{"type":"text","body":"3. Persatuan. Nilai menjaga kebersamaan dalam perbedaan. Contoh: Teman yang berbeda kesukaan tetap bekerja bersama"},{"type":"text","body":"4. Musyawarah. Membahas pilihan dengan mendengarkan pendapat bersama. Contoh: Kelompok mendiskusikan permainan yang akan dipilih"},{"type":"text","body":"5. Keadilan. Nilai memperlakukan orang secara layak sesuai hak dan kebutuhannya. Contoh: Anak membagi kesempatan memakai alat dengan wajar"},{"type":"text","body":"Contoh dan penalaran: Anak tidak mengganggu teman yang beribadah Kita mengenal ketuhanan sebagai nilai menghormati keyakinan dan menjalankan ajaran agama masing-masing. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Amati satu kegiatan sehari-hari. Jelaskan nilai Pancasila yang tampak tanpa menganggap tindakan hanya berkaitan dengan satu nilai."},{"type":"text","body":"Rangkuman: Ketuhanan: Nilai menghormati keyakinan dan menjalankan ajaran agama masing-masing; Kemanusiaan: Nilai memperlakukan orang dengan hormat dan peduli; Persatuan: Nilai menjaga kebersamaan dalam perbedaan; Musyawarah: Membahas pilihan dengan mendengarkan pendapat bersama; Keadilan: Nilai memperlakukan orang secara layak sesuai hak dan kebutuhannya."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('90970efe-fa20-58c4-b3e1-6045eb9828f6','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Aturan dan kesepakatan','belajar-pancasila-kelas-2-unit-2',2,'A','Bab 2','dasar','draft',8,'{"summary":"Aturan dan kesepakatan. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan aturan dan kesepakatan dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Pendidikan Pancasila Kelas II","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-pendidikan-pancasila-untuk-sdmi-kelas-ii","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan aturan dan kesepakatan dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar aturan dan kesepakatan. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Aturan. Ketentuan untuk menjaga keteraturan dan kenyamanan. Contoh: Anggota keluarga merapikan alat setelah digunakan"},{"type":"text","body":"2. Kesepakatan. Hal yang disetujui bersama. Contoh: Kelompok menyetujui giliran memakai mainan"},{"type":"text","body":"3. Giliran. Kesempatan yang diberikan secara bergantian. Contoh: Anak menunggu teman selesai memakai alat"},{"type":"text","body":"4. Tanggung jawab. Kesediaan menjalankan tugas dan menjaga akibat tindakan. Contoh: Anak mengembalikan buku yang dipinjam"},{"type":"text","body":"5. Konsekuensi. Akibat yang berkaitan dengan tindakan dan perlu dipahami. Contoh: Mainan yang tidak dirapikan dapat menghalangi jalan"},{"type":"text","body":"Contoh dan penalaran: Anggota keluarga merapikan alat setelah digunakan Kita mengenal aturan sebagai ketentuan untuk menjaga keteraturan dan kenyamanan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Susun aturan permainan yang memberi kesempatan semua peserta. Coba dan perbaiki setelah bermain."},{"type":"text","body":"Rangkuman: Aturan: Ketentuan untuk menjaga keteraturan dan kenyamanan; Kesepakatan: Hal yang disetujui bersama; Giliran: Kesempatan yang diberikan secara bergantian; Tanggung jawab: Kesediaan menjalankan tugas dan menjaga akibat tindakan; Konsekuensi: Akibat yang berkaitan dengan tindakan dan perlu dipahami."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('bbc913f3-3394-5a05-9000-32bf9f3bda21','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Hak dan tanggung jawab sederhana','belajar-pancasila-kelas-2-unit-3',2,'A','Bab 3','dasar','draft',8,'{"summary":"Hak dan tanggung jawab sederhana. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan hak dan tanggung jawab sederhana dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Pendidikan Pancasila Kelas II","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-pendidikan-pancasila-untuk-sdmi-kelas-ii","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan hak dan tanggung jawab sederhana dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar hak dan tanggung jawab sederhana. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Hak. Hal yang layak diterima atau dimiliki seseorang. Contoh: Anak berhak diperlakukan aman dan dihargai"},{"type":"text","body":"2. Kewajiban. Hal yang perlu dilaksanakan sesuai peran dan aturan. Contoh: Anggota kelas perlu menjaga kebersihan ruang bersama"},{"type":"text","body":"3. Tanggung jawab. Kesediaan melaksanakan tugas dan memperbaiki akibat tindakan. Contoh: Anak merapikan alat yang ia gunakan"},{"type":"text","body":"4. Menghormati hak. Menjaga agar tindakan tidak merugikan kesempatan orang lain. Contoh: Anak tidak mengganggu teman yang sedang membaca"},{"type":"text","body":"5. Mencari pertolongan. Meminta bantuan ketika hak atau keselamatan terganggu. Contoh: Anak bercerita kepada orang dewasa tepercaya ketika dirundung"},{"type":"text","body":"Contoh dan penalaran: Anak berhak diperlakukan aman dan dihargai Kita mengenal hak sebagai hal yang layak diterima atau dimiliki seseorang. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Pasangkan contoh hak dengan tindakan menghormati hak teman. Hak aman tidak hilang ketika seseorang melakukan kesalahan."},{"type":"text","body":"Rangkuman: Hak: Hal yang layak diterima atau dimiliki seseorang; Kewajiban: Hal yang perlu dilaksanakan sesuai peran dan aturan; Tanggung jawab: Kesediaan melaksanakan tugas dan memperbaiki akibat tindakan; Menghormati hak: Menjaga agar tindakan tidak merugikan kesempatan orang lain; Mencari pertolongan: Meminta bantuan ketika hak atau keselamatan terganggu."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('deeca749-ed5d-5e68-9b1f-dc08d410503a','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Identitas dan keragaman','belajar-pancasila-kelas-2-unit-4',2,'A','Bab 4','sedang','draft',8,'{"summary":"Identitas dan keragaman. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan identitas dan keragaman dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Pendidikan Pancasila Kelas II","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-pendidikan-pancasila-untuk-sdmi-kelas-ii","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan identitas dan keragaman dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar identitas dan keragaman. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Identitas. Ciri atau keterangan yang membantu mengenali seseorang. Contoh: Anak memperkenalkan nama panggilan dan kesukaan"},{"type":"text","body":"2. Persamaan. Ciri yang dimiliki bersama oleh beberapa orang. Contoh: Dua teman sama-sama senang membaca"},{"type":"text","body":"3. Perbedaan. Ciri yang tidak sama antara satu orang dan lainnya. Contoh: Teman mempunyai kesukaan berbeda"},{"type":"text","body":"4. Menghargai. Memperlakukan orang lain dengan hormat. Contoh: Anak tidak mengejek cara bicara temannya"},{"type":"text","body":"5. Privasi. Hal pribadi yang perlu dijaga dan tidak dibagikan sembarangan. Contoh: Anak tidak menyebarkan alamat atau nomor telepon teman"},{"type":"text","body":"Contoh dan penalaran: Anak memperkenalkan nama panggilan dan kesukaan Kita mengenal identitas sebagai ciri atau keterangan yang membantu mengenali seseorang. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat gambar tentang kebiasaan keluarga yang boleh dibagikan. Hormati teman yang memilih tidak menceritakan hal pribadi."},{"type":"text","body":"Rangkuman: Identitas: Ciri atau keterangan yang membantu mengenali seseorang; Persamaan: Ciri yang dimiliki bersama oleh beberapa orang; Perbedaan: Ciri yang tidak sama antara satu orang dan lainnya; Menghargai: Memperlakukan orang lain dengan hormat; Privasi: Hal pribadi yang perlu dijaga dan tidak dibagikan sembarangan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('93be9477-1431-5911-8a11-e9c317c55ef1','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Kerja sama dan tolong-menolong','belajar-pancasila-kelas-2-unit-5',2,'A','Bab 5','sedang','draft',8,'{"summary":"Kerja sama dan tolong-menolong. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan kerja sama dan tolong-menolong dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Pendidikan Pancasila Kelas II","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-pendidikan-pancasila-untuk-sdmi-kelas-ii","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan kerja sama dan tolong-menolong dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar kerja sama dan tolong-menolong. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Kerja sama. Melakukan usaha bersama untuk mencapai tujuan. Contoh: Kelompok menata sudut baca bersama"},{"type":"text","body":"2. Pembagian tugas. Membagi pekerjaan sesuai kemampuan dan kesepakatan. Contoh: Seorang anak menyusun buku, yang lain menyiapkan label"},{"type":"text","body":"3. Tolong-menolong. Membantu orang lain sesuai kemampuan tanpa merendahkan. Contoh: Teman membantu membawa benda yang aman"},{"type":"text","body":"4. Peduli. Memperhatikan keadaan dan kebutuhan orang lain. Contoh: Anak menyadari temannya belum mendapat giliran"},{"type":"text","body":"5. Gotong royong. Bekerja bersama demi kepentingan bersama. Contoh: Warga sekolah merawat taman secara bersama"},{"type":"text","body":"Contoh dan penalaran: Kelompok menata sudut baca bersama Kita mengenal kerja sama sebagai melakukan usaha bersama untuk mencapai tujuan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Bagilah tugas sederhana merapikan ruang sesuai kemampuan. Ucapkan terima kasih atas setiap kontribusi."},{"type":"text","body":"Rangkuman: Kerja sama: Melakukan usaha bersama untuk mencapai tujuan; Pembagian tugas: Membagi pekerjaan sesuai kemampuan dan kesepakatan; Tolong-menolong: Membantu orang lain sesuai kemampuan tanpa merendahkan; Peduli: Memperhatikan keadaan dan kebutuhan orang lain; Gotong royong: Bekerja bersama demi kepentingan bersama."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('dc534d22-8a80-53cb-90df-95fc1d250220','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Lingkungan sebagai bagian Indonesia','belajar-pancasila-kelas-2-unit-6',2,'A','Bab 6','sedang','draft',8,'{"summary":"Lingkungan sebagai bagian Indonesia. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan lingkungan sebagai bagian indonesia dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Pendidikan Pancasila Kelas II","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-pendidikan-pancasila-untuk-sdmi-kelas-ii","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan lingkungan sebagai bagian indonesia dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar lingkungan sebagai bagian indonesia. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Lingkungan tempat tinggal. Tempat dan kehidupan di sekitar rumah. Contoh: Anak mengenali jalan dan ruang bersama dengan pendamping"},{"type":"text","body":"2. Wilayah. Bagian tempat yang mempunyai batas tertentu. Contoh: Desa atau kelurahan merupakan contoh wilayah"},{"type":"text","body":"3. Simbol negara. Lambang yang mewakili identitas negara. Contoh: Bendera Merah Putih adalah bendera Indonesia"},{"type":"text","body":"4. Indonesia. Negara tempat beragam masyarakat hidup bersama. Contoh: Berbagai daerah menjadi bagian dari Indonesia"},{"type":"text","body":"5. Merawat tempat bersama. Menjaga kebersihan dan fungsi fasilitas yang digunakan banyak orang. Contoh: Anak tidak mencoret bangku taman"},{"type":"text","body":"Contoh dan penalaran: Anak mengenali jalan dan ruang bersama dengan pendamping Kita mengenal lingkungan tempat tinggal sebagai tempat dan kehidupan di sekitar rumah. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Gunakan peta atau gambar untuk mengenal daerah sebagai bagian Indonesia tanpa menuliskan alamat pribadi."},{"type":"text","body":"Rangkuman: Lingkungan tempat tinggal: Tempat dan kehidupan di sekitar rumah; Wilayah: Bagian tempat yang mempunyai batas tertentu; Simbol negara: Lambang yang mewakili identitas negara; Indonesia: Negara tempat beragam masyarakat hidup bersama; Merawat tempat bersama: Menjaga kebersihan dan fungsi fasilitas yang digunakan banyak orang."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('fb59edc0-99f3-5153-88d5-49dcef719656','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Nilai Pancasila dalam kehidupan','belajar-pancasila-kelas-3-unit-1',3,'B','Bab 1','dasar','draft',12,'{"summary":"Nilai Pancasila dalam kehidupan. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan nilai pancasila dalam kehidupan dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Pendidikan Pancasila Kelas III","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-pendidikan-pancasila-untuk-sdmi-kelas-iii","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan nilai pancasila dalam kehidupan dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar nilai pancasila dalam kehidupan. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Nilai Pancasila. Pedoman nilai untuk hidup bersama secara berketuhanan, manusiawi, bersatu, bermusyawarah, dan adil. Contoh: Kelompok menilai apakah keputusannya menghormati semua anggota"},{"type":"text","body":"2. Keteladanan. Perilaku baik yang dapat dicontoh dengan memahami alasannya. Contoh: Anak mengembalikan barang yang ditemukan"},{"type":"text","body":"3. Penerapan nilai. Tindakan nyata yang menunjukkan nilai yang diyakini. Contoh: Keputusan kelompok memberi kesempatan anggota yang belum berbicara"},{"type":"text","body":"4. Pertimbangan akibat. Memikirkan pengaruh tindakan terhadap diri dan orang lain. Contoh: Anak memikirkan apakah lelucon dapat melukai perasaan teman"},{"type":"text","body":"5. Refleksi tindakan. Menilai kembali perbuatan untuk memperbaiki perilaku. Contoh: Anak mengakui kesalahan dan merencanakan perbaikan"},{"type":"text","body":"Contoh dan penalaran: Kelompok menilai apakah keputusannya menghormati semua anggota Kita mengenal nilai pancasila sebagai pedoman nilai untuk hidup bersama secara berketuhanan, manusiawi, bersatu, bermusyawarah, dan adil. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Bahas contoh anak yang menemukan barang. Jelaskan tindakan serta alasan yang sesuai nilai Pancasila."},{"type":"text","body":"Rangkuman: Nilai Pancasila: Pedoman nilai untuk hidup bersama secara berketuhanan, manusiawi, bersatu, bermusyawarah, dan adil; Keteladanan: Perilaku baik yang dapat dicontoh dengan memahami alasannya; Penerapan nilai: Tindakan nyata yang menunjukkan nilai yang diyakini; Pertimbangan akibat: Memikirkan pengaruh tindakan terhadap diri dan orang lain; Refleksi tindakan: Menilai kembali perbuatan untuk memperbaiki perilaku."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('53342e87-a7fe-5838-bdb3-480dec094faf','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Aturan, hak, dan kewajiban','belajar-pancasila-kelas-3-unit-2',3,'B','Bab 2','dasar','draft',12,'{"summary":"Aturan, hak, dan kewajiban. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan aturan, hak, dan kewajiban dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Pendidikan Pancasila Kelas III","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-pendidikan-pancasila-untuk-sdmi-kelas-iii","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan aturan, hak, dan kewajiban dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar aturan, hak, dan kewajiban. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Hak bersama. Hak yang perlu dijaga untuk semua anggota kelompok. Contoh: Seluruh siswa berhak mendapat lingkungan belajar yang aman"},{"type":"text","body":"2. Kewajiban sesuai peran. Tugas yang berkaitan dengan kedudukan dalam kegiatan. Contoh: Petugas kelompok melaksanakan tugas yang disepakati"},{"type":"text","body":"3. Tanggung jawab atas akibat. Kesediaan memperbaiki dampak perbuatan sendiri. Contoh: Anak membantu memperbaiki keadaan setelah menumpahkan air"},{"type":"text","body":"4. Norma. Pedoman perilaku yang berlaku dalam kehidupan bersama. Contoh: Masyarakat mengharapkan orang berbicara sopan"},{"type":"text","body":"5. Keseimbangan hak dan kewajiban. Menjalankan tugas sambil menghormati hak setiap orang. Contoh: Anak menjaga ketertiban tanpa menghalangi hak teman belajar"},{"type":"text","body":"Contoh dan penalaran: Seluruh siswa berhak mendapat lingkungan belajar yang aman Kita mengenal hak bersama sebagai hak yang perlu dijaga untuk semua anggota kelompok. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Pilih satu kegiatan sekolah. Jelaskan hak peserta, kewajiban sesuai peran, dan tanggung jawab atas akibat tindakan."},{"type":"text","body":"Rangkuman: Hak bersama: Hak yang perlu dijaga untuk semua anggota kelompok; Kewajiban sesuai peran: Tugas yang berkaitan dengan kedudukan dalam kegiatan; Tanggung jawab atas akibat: Kesediaan memperbaiki dampak perbuatan sendiri; Norma: Pedoman perilaku yang berlaku dalam kehidupan bersama; Keseimbangan hak dan kewajiban: Menjalankan tugas sambil menghormati hak setiap orang."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('ebbd2d84-cfd3-5e9d-a67b-79e7d7dabcc6','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Kesepakatan bersama','belajar-pancasila-kelas-3-unit-3',3,'B','Bab 3','dasar','draft',12,'{"summary":"Kesepakatan bersama. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan kesepakatan bersama dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Pendidikan Pancasila Kelas III","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-pendidikan-pancasila-untuk-sdmi-kelas-iii","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan kesepakatan bersama dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar kesepakatan bersama. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Musyawarah. Membahas masalah bersama dengan mendengarkan alasan peserta. Contoh: Kelompok mencari jadwal kegiatan yang dapat diikuti anggota"},{"type":"text","body":"2. Pendapat. Pandangan seseorang tentang suatu hal. Contoh: Seorang anggota mengusulkan kegiatan membaca"},{"type":"text","body":"3. Alasan relevan. Penjelasan yang berhubungan dengan masalah yang dibahas. Contoh: Usulan tempat didukung alasan akses yang mudah"},{"type":"text","body":"4. Mufakat. Kesepakatan bersama setelah pembahasan. Contoh: Anggota menyepakati pilihan yang dapat diterima bersama"},{"type":"text","body":"5. Pelaksanaan keputusan. Menjalankan hasil kesepakatan dengan tanggung jawab. Contoh: Kelompok melakukan tugas sesuai keputusan yang dibuat"},{"type":"text","body":"Contoh dan penalaran: Kelompok mencari jadwal kegiatan yang dapat diikuti anggota Kita mengenal musyawarah sebagai membahas masalah bersama dengan mendengarkan alasan peserta. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Lakukan musyawarah memilih kegiatan kelompok. Setiap anggota menyampaikan alasan dan didengar."},{"type":"text","body":"Rangkuman: Musyawarah: Membahas masalah bersama dengan mendengarkan alasan peserta; Pendapat: Pandangan seseorang tentang suatu hal; Alasan relevan: Penjelasan yang berhubungan dengan masalah yang dibahas; Mufakat: Kesepakatan bersama setelah pembahasan; Pelaksanaan keputusan: Menjalankan hasil kesepakatan dengan tanggung jawab."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('0d43fa8a-009b-5369-9b0c-664a2b6e826b','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Keberagaman identitas','belajar-pancasila-kelas-3-unit-4',3,'B','Bab 4','sedang','draft',12,'{"summary":"Keberagaman identitas. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan keberagaman identitas dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Pendidikan Pancasila Kelas III","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-pendidikan-pancasila-untuk-sdmi-kelas-iii","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan keberagaman identitas dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar keberagaman identitas. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Identitas budaya. Ciri budaya yang berkaitan dengan kehidupan seseorang atau kelompok. Contoh: Bahasa keluarga dapat menjadi bagian identitas budaya"},{"type":"text","body":"2. Toleransi. Menghormati perbedaan tanpa memaksakan pilihan pribadi. Contoh: Anak memberi ruang teman menjalankan kebiasaannya yang tidak merugikan"},{"type":"text","body":"3. Stereotip. Anggapan menyamaratakan orang berdasarkan kelompoknya. Contoh: Menyebut semua orang suatu daerah pasti bersifat sama adalah penyamarataan"},{"type":"text","body":"4. Inklusif. Memberi ruang partisipasi kepada anggota dengan kebutuhan beragam. Contoh: Kelompok menyesuaikan cara agar teman dapat ikut"},{"type":"text","body":"5. Kesetaraan martabat. Pandangan bahwa setiap orang layak dihormati sebagai manusia. Contoh: Anak tidak mengukur harga diri teman dari latar keluarganya"},{"type":"text","body":"Contoh dan penalaran: Bahasa keluarga dapat menjadi bagian identitas budaya Kita mengenal identitas budaya sebagai ciri budaya yang berkaitan dengan kehidupan seseorang atau kelompok. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Bandingkan dua kebiasaan budaya dari sumber yang baik. Hindari menyimpulkan sifat semua anggota kelompok."},{"type":"text","body":"Rangkuman: Identitas budaya: Ciri budaya yang berkaitan dengan kehidupan seseorang atau kelompok; Toleransi: Menghormati perbedaan tanpa memaksakan pilihan pribadi; Stereotip: Anggapan menyamaratakan orang berdasarkan kelompoknya; Inklusif: Memberi ruang partisipasi kepada anggota dengan kebutuhan beragam; Kesetaraan martabat: Pandangan bahwa setiap orang layak dihormati sebagai manusia."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('0458085e-271c-528c-9ba4-79d884f12a52','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Gotong royong di lingkungan','belajar-pancasila-kelas-3-unit-5',3,'B','Bab 5','sedang','draft',12,'{"summary":"Gotong royong di lingkungan. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan gotong royong di lingkungan dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Pendidikan Pancasila Kelas III","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-pendidikan-pancasila-untuk-sdmi-kelas-iii","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan gotong royong di lingkungan dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar gotong royong di lingkungan. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Kerja sama. Melakukan usaha bersama untuk mencapai tujuan. Contoh: Kelompok menata sudut baca bersama"},{"type":"text","body":"2. Pembagian tugas. Membagi pekerjaan sesuai kemampuan dan kesepakatan. Contoh: Seorang anak menyusun buku, yang lain menyiapkan label"},{"type":"text","body":"3. Tolong-menolong. Membantu orang lain sesuai kemampuan tanpa merendahkan. Contoh: Teman membantu membawa benda yang aman"},{"type":"text","body":"4. Peduli. Memperhatikan keadaan dan kebutuhan orang lain. Contoh: Anak menyadari temannya belum mendapat giliran"},{"type":"text","body":"5. Gotong royong. Bekerja bersama demi kepentingan bersama. Contoh: Warga sekolah merawat taman secara bersama"},{"type":"text","body":"Contoh dan penalaran: Kelompok menata sudut baca bersama Kita mengenal kerja sama sebagai melakukan usaha bersama untuk mencapai tujuan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Rencanakan kerja sama merawat sudut baca. Bagilah peran dan catat bagaimana anggota saling membantu."},{"type":"text","body":"Rangkuman: Kerja sama: Melakukan usaha bersama untuk mencapai tujuan; Pembagian tugas: Membagi pekerjaan sesuai kemampuan dan kesepakatan; Tolong-menolong: Membantu orang lain sesuai kemampuan tanpa merendahkan; Peduli: Memperhatikan keadaan dan kebutuhan orang lain; Gotong royong: Bekerja bersama demi kepentingan bersama."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('1cda37e3-5737-5c57-b637-0b4024b214e3','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Mengenal wilayah tempat tinggal','belajar-pancasila-kelas-3-unit-6',3,'B','Bab 6','sedang','draft',12,'{"summary":"Mengenal wilayah tempat tinggal. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan mengenal wilayah tempat tinggal dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Pendidikan Pancasila Kelas III","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-pendidikan-pancasila-untuk-sdmi-kelas-iii","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan mengenal wilayah tempat tinggal dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar mengenal wilayah tempat tinggal. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Wilayah tempat tinggal. Bagian daerah yang menjadi lingkungan kehidupan sehari-hari. Contoh: Desa atau kelurahan memiliki lingkungan dan pengelolaan tertentu"},{"type":"text","body":"2. Bagian dari Indonesia. Hubungan daerah dengan keseluruhan negara. Contoh: Daerah berbeda berada dalam satu Indonesia"},{"type":"text","body":"3. Kekayaan daerah. Potensi alam dan budaya yang perlu dipelajari serta dijaga. Contoh: Kesenian lokal dipelajari dengan menghormati masyarakatnya"},{"type":"text","body":"4. Bhinneka Tunggal Ika. Semboyan yang menegaskan persatuan dalam keberagaman. Contoh: Perbedaan budaya dipahami sebagai bagian kebersamaan Indonesia"},{"type":"text","body":"5. Kepedulian wilayah. Tindakan menjaga kehidupan dan lingkungan daerah. Contoh: Anak ikut kegiatan aman untuk merawat fasilitas bersama"},{"type":"text","body":"Contoh dan penalaran: Desa atau kelurahan memiliki lingkungan dan pengelolaan tertentu Kita mengenal wilayah tempat tinggal sebagai bagian daerah yang menjadi lingkungan kehidupan sehari-hari. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Cari satu informasi tentang daerah dari sumber terpercaya. Jelaskan hubungannya dengan Indonesia."},{"type":"text","body":"Rangkuman: Wilayah tempat tinggal: Bagian daerah yang menjadi lingkungan kehidupan sehari-hari; Bagian dari Indonesia: Hubungan daerah dengan keseluruhan negara; Kekayaan daerah: Potensi alam dan budaya yang perlu dipelajari serta dijaga; Bhinneka Tunggal Ika: Semboyan yang menegaskan persatuan dalam keberagaman; Kepedulian wilayah: Tindakan menjaga kehidupan dan lingkungan daerah."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('8d65c850-6486-53d2-956a-1ae63764ad6f','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Penerapan sila-sila Pancasila','belajar-pancasila-kelas-4-unit-1',4,'B','Bab 1','dasar','draft',12,'{"summary":"Penerapan sila-sila Pancasila. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan penerapan sila-sila pancasila dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Pendidikan Pancasila Kelas IV","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-pendidikan-pancasila-untuk-sdmi-kelas-iv","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan penerapan sila-sila pancasila dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar penerapan sila-sila pancasila. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Nilai Pancasila. Pedoman nilai untuk hidup bersama secara berketuhanan, manusiawi, bersatu, bermusyawarah, dan adil. Contoh: Kelompok menilai apakah keputusannya menghormati semua anggota"},{"type":"text","body":"2. Keteladanan. Perilaku baik yang dapat dicontoh dengan memahami alasannya. Contoh: Anak mengembalikan barang yang ditemukan"},{"type":"text","body":"3. Penerapan nilai. Tindakan nyata yang menunjukkan nilai yang diyakini. Contoh: Keputusan kelompok memberi kesempatan anggota yang belum berbicara"},{"type":"text","body":"4. Pertimbangan akibat. Memikirkan pengaruh tindakan terhadap diri dan orang lain. Contoh: Anak memikirkan apakah lelucon dapat melukai perasaan teman"},{"type":"text","body":"5. Refleksi tindakan. Menilai kembali perbuatan untuk memperbaiki perilaku. Contoh: Anak mengakui kesalahan dan merencanakan perbaikan"},{"type":"text","body":"Contoh dan penalaran: Kelompok menilai apakah keputusannya menghormati semua anggota Kita mengenal nilai pancasila sebagai pedoman nilai untuk hidup bersama secara berketuhanan, manusiawi, bersatu, bermusyawarah, dan adil. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Nilai dua pilihan tindakan saat teman kesulitan. Jelaskan pilihan berdasarkan nilai dan akibatnya."},{"type":"text","body":"Rangkuman: Nilai Pancasila: Pedoman nilai untuk hidup bersama secara berketuhanan, manusiawi, bersatu, bermusyawarah, dan adil; Keteladanan: Perilaku baik yang dapat dicontoh dengan memahami alasannya; Penerapan nilai: Tindakan nyata yang menunjukkan nilai yang diyakini; Pertimbangan akibat: Memikirkan pengaruh tindakan terhadap diri dan orang lain; Refleksi tindakan: Menilai kembali perbuatan untuk memperbaiki perilaku."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('6f1c7e21-30b2-5946-b3f9-3d68763778be','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Norma dan kesepakatan','belajar-pancasila-kelas-4-unit-2',4,'B','Bab 2','dasar','draft',12,'{"summary":"Norma dan kesepakatan. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan norma dan kesepakatan dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Pendidikan Pancasila Kelas IV","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-pendidikan-pancasila-untuk-sdmi-kelas-iv","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan norma dan kesepakatan dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar norma dan kesepakatan. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Hak bersama. Hak yang perlu dijaga untuk semua anggota kelompok. Contoh: Seluruh siswa berhak mendapat lingkungan belajar yang aman"},{"type":"text","body":"2. Kewajiban sesuai peran. Tugas yang berkaitan dengan kedudukan dalam kegiatan. Contoh: Petugas kelompok melaksanakan tugas yang disepakati"},{"type":"text","body":"3. Tanggung jawab atas akibat. Kesediaan memperbaiki dampak perbuatan sendiri. Contoh: Anak membantu memperbaiki keadaan setelah menumpahkan air"},{"type":"text","body":"4. Norma. Pedoman perilaku yang berlaku dalam kehidupan bersama. Contoh: Masyarakat mengharapkan orang berbicara sopan"},{"type":"text","body":"5. Keseimbangan hak dan kewajiban. Menjalankan tugas sambil menghormati hak setiap orang. Contoh: Anak menjaga ketertiban tanpa menghalangi hak teman belajar"},{"type":"text","body":"Contoh dan penalaran: Seluruh siswa berhak mendapat lingkungan belajar yang aman Kita mengenal hak bersama sebagai hak yang perlu dijaga untuk semua anggota kelompok. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Bedakan norma, aturan kegiatan, dan kesepakatan. Bahas cara memperbaiki pelanggaran tanpa mempermalukan."},{"type":"text","body":"Rangkuman: Hak bersama: Hak yang perlu dijaga untuk semua anggota kelompok; Kewajiban sesuai peran: Tugas yang berkaitan dengan kedudukan dalam kegiatan; Tanggung jawab atas akibat: Kesediaan memperbaiki dampak perbuatan sendiri; Norma: Pedoman perilaku yang berlaku dalam kehidupan bersama; Keseimbangan hak dan kewajiban: Menjalankan tugas sambil menghormati hak setiap orang."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('b357a60d-e241-551c-b937-b1daa819f43b','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Musyawarah sederhana','belajar-pancasila-kelas-4-unit-3',4,'B','Bab 3','dasar','draft',12,'{"summary":"Musyawarah sederhana. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan musyawarah sederhana dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Pendidikan Pancasila Kelas IV","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-pendidikan-pancasila-untuk-sdmi-kelas-iv","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan musyawarah sederhana dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar musyawarah sederhana. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Musyawarah. Membahas masalah bersama dengan mendengarkan alasan peserta. Contoh: Kelompok mencari jadwal kegiatan yang dapat diikuti anggota"},{"type":"text","body":"2. Pendapat. Pandangan seseorang tentang suatu hal. Contoh: Seorang anggota mengusulkan kegiatan membaca"},{"type":"text","body":"3. Alasan relevan. Penjelasan yang berhubungan dengan masalah yang dibahas. Contoh: Usulan tempat didukung alasan akses yang mudah"},{"type":"text","body":"4. Mufakat. Kesepakatan bersama setelah pembahasan. Contoh: Anggota menyepakati pilihan yang dapat diterima bersama"},{"type":"text","body":"5. Pelaksanaan keputusan. Menjalankan hasil kesepakatan dengan tanggung jawab. Contoh: Kelompok melakukan tugas sesuai keputusan yang dibuat"},{"type":"text","body":"Contoh dan penalaran: Kelompok mencari jadwal kegiatan yang dapat diikuti anggota Kita mengenal musyawarah sebagai membahas masalah bersama dengan mendengarkan alasan peserta. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Musyawarahkan penggunaan alat yang terbatas. Pastikan kebutuhan anggota yang belum berbicara ikut dipertimbangkan."},{"type":"text","body":"Rangkuman: Musyawarah: Membahas masalah bersama dengan mendengarkan alasan peserta; Pendapat: Pandangan seseorang tentang suatu hal; Alasan relevan: Penjelasan yang berhubungan dengan masalah yang dibahas; Mufakat: Kesepakatan bersama setelah pembahasan; Pelaksanaan keputusan: Menjalankan hasil kesepakatan dengan tanggung jawab."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('e76e0189-47d6-5d2a-b6a6-8548d209aeb8','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Menghormati keberagaman','belajar-pancasila-kelas-4-unit-4',4,'B','Bab 4','sedang','draft',12,'{"summary":"Menghormati keberagaman. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan menghormati keberagaman dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Pendidikan Pancasila Kelas IV","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-pendidikan-pancasila-untuk-sdmi-kelas-iv","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan menghormati keberagaman dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar menghormati keberagaman. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Identitas budaya. Ciri budaya yang berkaitan dengan kehidupan seseorang atau kelompok. Contoh: Bahasa keluarga dapat menjadi bagian identitas budaya"},{"type":"text","body":"2. Toleransi. Menghormati perbedaan tanpa memaksakan pilihan pribadi. Contoh: Anak memberi ruang teman menjalankan kebiasaannya yang tidak merugikan"},{"type":"text","body":"3. Stereotip. Anggapan menyamaratakan orang berdasarkan kelompoknya. Contoh: Menyebut semua orang suatu daerah pasti bersifat sama adalah penyamarataan"},{"type":"text","body":"4. Inklusif. Memberi ruang partisipasi kepada anggota dengan kebutuhan beragam. Contoh: Kelompok menyesuaikan cara agar teman dapat ikut"},{"type":"text","body":"5. Kesetaraan martabat. Pandangan bahwa setiap orang layak dihormati sebagai manusia. Contoh: Anak tidak mengukur harga diri teman dari latar keluarganya"},{"type":"text","body":"Contoh dan penalaran: Bahasa keluarga dapat menjadi bagian identitas budaya Kita mengenal identitas budaya sebagai ciri budaya yang berkaitan dengan kehidupan seseorang atau kelompok. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Perbaiki satu pernyataan yang menyamaratakan suatu kelompok. Ganti dengan informasi yang terukur dan hormat."},{"type":"text","body":"Rangkuman: Identitas budaya: Ciri budaya yang berkaitan dengan kehidupan seseorang atau kelompok; Toleransi: Menghormati perbedaan tanpa memaksakan pilihan pribadi; Stereotip: Anggapan menyamaratakan orang berdasarkan kelompoknya; Inklusif: Memberi ruang partisipasi kepada anggota dengan kebutuhan beragam; Kesetaraan martabat: Pandangan bahwa setiap orang layak dihormati sebagai manusia."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('b9a605eb-3109-5b61-826a-1241f668dd3f','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Persatuan dalam kegiatan bersama','belajar-pancasila-kelas-4-unit-5',4,'B','Bab 5','sedang','draft',12,'{"summary":"Persatuan dalam kegiatan bersama. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan persatuan dalam kegiatan bersama dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Pendidikan Pancasila Kelas IV","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-pendidikan-pancasila-untuk-sdmi-kelas-iv","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan persatuan dalam kegiatan bersama dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar persatuan dalam kegiatan bersama. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Persatuan. Kebersamaan sebagai satu kelompok dengan tetap menghargai perbedaan. Contoh: Anak berbeda pendapat tetap menjaga hubungan baik"},{"type":"text","body":"2. Kepentingan bersama. Kebutuhan yang bermanfaat bagi banyak anggota. Contoh: Tempat belajar yang aman menjadi kebutuhan semua siswa"},{"type":"text","body":"3. Solidaritas. Kesediaan mendukung orang lain dalam kehidupan bersama. Contoh: Kelompok membantu anggota yang mengalami kesulitan"},{"type":"text","body":"4. Pembagian peran adil. Pembagian usaha sesuai kemampuan dan kebutuhan tanpa merendahkan. Contoh: Tugas disesuaikan agar setiap anak dapat berkontribusi"},{"type":"text","body":"5. Menghargai kontribusi. Mengakui usaha yang diberikan orang lain. Contoh: Kelompok berterima kasih kepada semua pelaksana tugas"},{"type":"text","body":"Contoh dan penalaran: Anak berbeda pendapat tetap menjaga hubungan baik Kita mengenal persatuan sebagai kebersamaan sebagai satu kelompok dengan tetap menghargai perbedaan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat kegiatan yang memungkinkan setiap anak berkontribusi sesuai kemampuan. Evaluasi pembagian perannya."},{"type":"text","body":"Rangkuman: Persatuan: Kebersamaan sebagai satu kelompok dengan tetap menghargai perbedaan; Kepentingan bersama: Kebutuhan yang bermanfaat bagi banyak anggota; Solidaritas: Kesediaan mendukung orang lain dalam kehidupan bersama; Pembagian peran adil: Pembagian usaha sesuai kemampuan dan kebutuhan tanpa merendahkan; Menghargai kontribusi: Mengakui usaha yang diberikan orang lain."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('5aebee0e-bd84-549f-a3ed-c4a019db9d5a','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Wilayah Indonesia dan lingkungan','belajar-pancasila-kelas-4-unit-6',4,'B','Bab 6','sedang','draft',12,'{"summary":"Wilayah Indonesia dan lingkungan. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan wilayah indonesia dan lingkungan dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Pendidikan Pancasila Kelas IV","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-pendidikan-pancasila-untuk-sdmi-kelas-iv","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan wilayah indonesia dan lingkungan dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar wilayah indonesia dan lingkungan. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Wilayah tempat tinggal. Bagian daerah yang menjadi lingkungan kehidupan sehari-hari. Contoh: Desa atau kelurahan memiliki lingkungan dan pengelolaan tertentu"},{"type":"text","body":"2. Bagian dari Indonesia. Hubungan daerah dengan keseluruhan negara. Contoh: Daerah berbeda berada dalam satu Indonesia"},{"type":"text","body":"3. Kekayaan daerah. Potensi alam dan budaya yang perlu dipelajari serta dijaga. Contoh: Kesenian lokal dipelajari dengan menghormati masyarakatnya"},{"type":"text","body":"4. Bhinneka Tunggal Ika. Semboyan yang menegaskan persatuan dalam keberagaman. Contoh: Perbedaan budaya dipahami sebagai bagian kebersamaan Indonesia"},{"type":"text","body":"5. Kepedulian wilayah. Tindakan menjaga kehidupan dan lingkungan daerah. Contoh: Anak ikut kegiatan aman untuk merawat fasilitas bersama"},{"type":"text","body":"Contoh dan penalaran: Desa atau kelurahan memiliki lingkungan dan pengelolaan tertentu Kita mengenal wilayah tempat tinggal sebagai bagian daerah yang menjadi lingkungan kehidupan sehari-hari. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Amati peta Indonesia dan satu kekayaan daerah. Jelaskan mengapa perbedaan daerah tidak menghilangkan persatuan."},{"type":"text","body":"Rangkuman: Wilayah tempat tinggal: Bagian daerah yang menjadi lingkungan kehidupan sehari-hari; Bagian dari Indonesia: Hubungan daerah dengan keseluruhan negara; Kekayaan daerah: Potensi alam dan budaya yang perlu dipelajari serta dijaga; Bhinneka Tunggal Ika: Semboyan yang menegaskan persatuan dalam keberagaman; Kepedulian wilayah: Tindakan menjaga kehidupan dan lingkungan daerah."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('8c451d0d-6160-51e4-84d9-cd047ea45ef4','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Sejarah dan keteladanan perumusan Pancasila','belajar-pancasila-kelas-5-unit-1',5,'C','Bab 1','dasar','draft',12,'{"summary":"Sejarah dan keteladanan perumusan Pancasila. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan sejarah dan keteladanan perumusan pancasila dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Pendidikan Pancasila Kelas V","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-pendidikan-pancasila-untuk-sdmi-kelas-v","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan sejarah dan keteladanan perumusan pancasila dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar sejarah dan keteladanan perumusan pancasila. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Perumusan. Proses menyusun gagasan melalui pemikiran dan pembahasan. Contoh: Gagasan dasar negara dibahas dalam proses sejarah"},{"type":"text","body":"2. Tokoh sejarah. Orang yang berperan dalam peristiwa masa lalu. Contoh: Peran tokoh dipelajari berdasarkan sumber sejarah"},{"type":"text","body":"3. Kronologi. Urutan kejadian berdasarkan waktu. Contoh: Tahapan pembahasan disusun menurut urutannya"},{"type":"text","body":"4. Keteladanan kebangsaan. Sikap baik yang dapat dipelajari dari perjuangan bersama. Contoh: Kemauan mendengar dan mengutamakan bangsa dipelajari dari sejarah"},{"type":"text","body":"5. Bukti sejarah. Sumber yang menjadi dasar penjelasan peristiwa. Contoh: Dokumen diperiksa sebelum menyimpulkan suatu kejadian"},{"type":"text","body":"Contoh dan penalaran: Gagasan dasar negara dibahas dalam proses sejarah Kita mengenal perumusan sebagai proses menyusun gagasan melalui pemikiran dan pembahasan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Gunakan sumber sejarah yang dipilih pendamping. Susun urutan proses perumusan dasar negara dan sikap yang dapat diteladani."},{"type":"text","body":"Rangkuman: Perumusan: Proses menyusun gagasan melalui pemikiran dan pembahasan; Tokoh sejarah: Orang yang berperan dalam peristiwa masa lalu; Kronologi: Urutan kejadian berdasarkan waktu; Keteladanan kebangsaan: Sikap baik yang dapat dipelajari dari perjuangan bersama; Bukti sejarah: Sumber yang menjadi dasar penjelasan peristiwa."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('1a07b7a7-963d-5a10-9722-de7d48867e5e','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Nilai Pancasila dan keputusan sehari-hari','belajar-pancasila-kelas-5-unit-2',5,'C','Bab 2','dasar','draft',12,'{"summary":"Nilai Pancasila dan keputusan sehari-hari. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan nilai pancasila dan keputusan sehari-hari dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Pendidikan Pancasila Kelas V","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-pendidikan-pancasila-untuk-sdmi-kelas-v","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan nilai pancasila dan keputusan sehari-hari dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar nilai pancasila dan keputusan sehari-hari. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Pancasila sebagai pedoman. Nilai dasar yang menjadi arah pertimbangan tindakan dalam kehidupan bersama. Contoh: Siswa menilai keputusan berdasarkan kemanusiaan, persatuan, dan keadilan"},{"type":"text","body":"2. Konsistensi nilai. Kesesuaian antara nilai yang diucapkan dengan tindakan. Contoh: Anak menyatakan menghargai perbedaan dan tidak mengejek teman"},{"type":"text","body":"3. Penalaran moral. Pertimbangan alasan, hak, dan dampak sebelum bertindak. Contoh: Kelompok memikirkan pilihan yang paling menghormati semua anggota"},{"type":"text","body":"4. Tanggung jawab warga. Peran aktif menjaga kehidupan bersama sesuai kemampuan. Contoh: Anak menggunakan fasilitas umum dengan tertib"},{"type":"text","body":"5. Perbaikan diri. Usaha mengubah tindakan setelah memahami kesalahannya. Contoh: Anak meminta maaf dan melakukan langkah memperbaiki akibat"},{"type":"text","body":"Contoh dan penalaran: Siswa menilai keputusan berdasarkan kemanusiaan, persatuan, dan keadilan Kita mengenal pancasila sebagai pedoman sebagai nilai dasar yang menjadi arah pertimbangan tindakan dalam kehidupan bersama. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Bandingkan ucapan dan tindakan pada cerita. Jelaskan apakah keduanya konsisten dengan nilai Pancasila."},{"type":"text","body":"Rangkuman: Pancasila sebagai pedoman: Nilai dasar yang menjadi arah pertimbangan tindakan dalam kehidupan bersama; Konsistensi nilai: Kesesuaian antara nilai yang diucapkan dengan tindakan; Penalaran moral: Pertimbangan alasan, hak, dan dampak sebelum bertindak; Tanggung jawab warga: Peran aktif menjaga kehidupan bersama sesuai kemampuan; Perbaikan diri: Usaha mengubah tindakan setelah memahami kesalahannya."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('7f9f0a1c-1aaa-56bc-8374-9255ad50b302','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Hak, kewajiban, dan tanggung jawab','belajar-pancasila-kelas-5-unit-3',5,'C','Bab 3','dasar','draft',12,'{"summary":"Hak, kewajiban, dan tanggung jawab. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan hak, kewajiban, dan tanggung jawab dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Pendidikan Pancasila Kelas V","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-pendidikan-pancasila-untuk-sdmi-kelas-v","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan hak, kewajiban, dan tanggung jawab dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar hak, kewajiban, dan tanggung jawab. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Hak asasi. Hak dasar yang melekat pada setiap manusia. Contoh: Setiap anak layak diperlakukan bermartabat dan aman"},{"type":"text","body":"2. Kewajiban warga. Tugas hidup bersama sesuai aturan dan peran. Contoh: Warga menjaga ketertiban serta menghormati hak orang lain"},{"type":"text","body":"3. Akuntabilitas sederhana. Kesediaan menjelaskan tindakan dan bertanggung jawab atasnya. Contoh: Pengurus kelompok menerangkan penggunaan bahan bersama"},{"type":"text","body":"4. Kepentingan umum. Kebutuhan yang berkaitan dengan kesejahteraan banyak orang. Contoh: Akses fasilitas aman bermanfaat bagi seluruh warga"},{"type":"text","body":"5. Perlindungan pihak rentan. Upaya menjaga orang yang memerlukan dukungan lebih. Contoh: Kelompok menyesuaikan kegiatan agar teman tidak tersisih"},{"type":"text","body":"Contoh dan penalaran: Setiap anak layak diperlakukan bermartabat dan aman Kita mengenal hak asasi sebagai hak dasar yang melekat pada setiap manusia. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Bahas penggunaan fasilitas umum. Jelaskan cara memenuhi kewajiban sambil tetap melindungi hak semua orang."},{"type":"text","body":"Rangkuman: Hak asasi: Hak dasar yang melekat pada setiap manusia; Kewajiban warga: Tugas hidup bersama sesuai aturan dan peran; Akuntabilitas sederhana: Kesediaan menjelaskan tindakan dan bertanggung jawab atasnya; Kepentingan umum: Kebutuhan yang berkaitan dengan kesejahteraan banyak orang; Perlindungan pihak rentan: Upaya menjaga orang yang memerlukan dukungan lebih."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('bb956ced-bb37-5a54-9baf-6543265c5155','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Musyawarah dan alasan yang adil','belajar-pancasila-kelas-5-unit-4',5,'C','Bab 4','sedang','draft',12,'{"summary":"Musyawarah dan alasan yang adil. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan musyawarah dan alasan yang adil dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Pendidikan Pancasila Kelas V","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-pendidikan-pancasila-untuk-sdmi-kelas-v","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan musyawarah dan alasan yang adil dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar musyawarah dan alasan yang adil. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Perbedaan pendapat. Ketidaksamaan pandangan yang dapat dibahas dengan hormat. Contoh: Dua anak mengusulkan kegiatan berbeda"},{"type":"text","body":"2. Mendengar aktif. Memperhatikan dan memastikan pemahaman sebelum menanggapi. Contoh: Anak mengulang inti alasan teman dengan benar"},{"type":"text","body":"3. Kompromi. Penyesuaian sebagian keinginan untuk memperoleh pilihan yang dapat diterima. Contoh: Anggota mengubah sebagian rencana setelah memahami kebutuhan lain"},{"type":"text","body":"4. Mediasi sederhana. Bantuan pihak netral untuk memudahkan pembicaraan. Contoh: Pendamping membantu dua pihak menyampaikan kebutuhan tanpa saling menyerang"},{"type":"text","body":"5. Kesepakatan adil. Keputusan yang mempertimbangkan hak, kebutuhan, dan alasan semua pihak. Contoh: Kelompok memilih cara yang tidak mengorbankan keselamatan anggotanya"},{"type":"text","body":"Contoh dan penalaran: Dua anak mengusulkan kegiatan berbeda Kita mengenal perbedaan pendapat sebagai ketidaksamaan pandangan yang dapat dibahas dengan hormat. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Bahas pilihan kegiatan dengan kebutuhan peserta yang berbeda. Cari alasan dan kesepakatan yang adil."},{"type":"text","body":"Rangkuman: Perbedaan pendapat: Ketidaksamaan pandangan yang dapat dibahas dengan hormat; Mendengar aktif: Memperhatikan dan memastikan pemahaman sebelum menanggapi; Kompromi: Penyesuaian sebagian keinginan untuk memperoleh pilihan yang dapat diterima; Mediasi sederhana: Bantuan pihak netral untuk memudahkan pembicaraan; Kesepakatan adil: Keputusan yang mempertimbangkan hak, kebutuhan, dan alasan semua pihak."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('fbac2e5e-9998-55d6-ac1c-4f4dd27de8e0','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Keberagaman budaya','belajar-pancasila-kelas-5-unit-5',5,'C','Bab 5','sedang','draft',12,'{"summary":"Keberagaman budaya. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan keberagaman budaya dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Pendidikan Pancasila Kelas V","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-pendidikan-pancasila-untuk-sdmi-kelas-v","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan keberagaman budaya dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar keberagaman budaya. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Identitas budaya. Ciri budaya yang berkaitan dengan kehidupan seseorang atau kelompok. Contoh: Bahasa keluarga dapat menjadi bagian identitas budaya"},{"type":"text","body":"2. Toleransi. Menghormati perbedaan tanpa memaksakan pilihan pribadi. Contoh: Anak memberi ruang teman menjalankan kebiasaannya yang tidak merugikan"},{"type":"text","body":"3. Stereotip. Anggapan menyamaratakan orang berdasarkan kelompoknya. Contoh: Menyebut semua orang suatu daerah pasti bersifat sama adalah penyamarataan"},{"type":"text","body":"4. Inklusif. Memberi ruang partisipasi kepada anggota dengan kebutuhan beragam. Contoh: Kelompok menyesuaikan cara agar teman dapat ikut"},{"type":"text","body":"5. Kesetaraan martabat. Pandangan bahwa setiap orang layak dihormati sebagai manusia. Contoh: Anak tidak mengukur harga diri teman dari latar keluarganya"},{"type":"text","body":"Contoh dan penalaran: Bahasa keluarga dapat menjadi bagian identitas budaya Kita mengenal identitas budaya sebagai ciri budaya yang berkaitan dengan kehidupan seseorang atau kelompok. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Pelajari satu karya budaya dari sumber resmi. Catat asal informasi dan cara menghargainya tanpa menyamaratakan masyarakatnya."},{"type":"text","body":"Rangkuman: Identitas budaya: Ciri budaya yang berkaitan dengan kehidupan seseorang atau kelompok; Toleransi: Menghormati perbedaan tanpa memaksakan pilihan pribadi; Stereotip: Anggapan menyamaratakan orang berdasarkan kelompoknya; Inklusif: Memberi ruang partisipasi kepada anggota dengan kebutuhan beragam; Kesetaraan martabat: Pandangan bahwa setiap orang layak dihormati sebagai manusia."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('d60ca7fe-a504-54c4-a7b7-b56cfced26f7','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Menjaga persatuan Indonesia','belajar-pancasila-kelas-5-unit-6',5,'C','Bab 6','sedang','draft',12,'{"summary":"Menjaga persatuan Indonesia. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan menjaga persatuan indonesia dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Pendidikan Pancasila Kelas V","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-pendidikan-pancasila-untuk-sdmi-kelas-v","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan menjaga persatuan indonesia dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar menjaga persatuan indonesia. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Keutuhan wilayah. Keberlangsungan wilayah negara sebagai satu kesatuan. Contoh: Berbagai pulau dan daerah dipahami sebagai bagian Indonesia"},{"type":"text","body":"2. Persatuan nasional. Kebersamaan sebagai bangsa di tengah perbedaan daerah dan identitas. Contoh: Warga menghormati daerah lain sebagai bagian bangsa yang sama"},{"type":"text","body":"3. Tanggung jawab lingkungan. Peran merawat alam dan ruang hidup yang dipakai bersama. Contoh: Tindakan lokal menjaga sumber air dapat bermanfaat bagi wilayah lain"},{"type":"text","body":"4. Informasi bertanggung jawab. Penyampaian kabar yang diperiksa agar tidak memecah hubungan. Contoh: Anak mengecek sumber sebelum menyebarkan kabar tentang kelompok lain"},{"type":"text","body":"5. Kerja sama antarwilayah. Usaha daerah yang berbeda untuk kepentingan bersama. Contoh: Wilayah saling membantu saat menghadapi kebutuhan bersama"},{"type":"text","body":"Contoh dan penalaran: Berbagai pulau dan daerah dipahami sebagai bagian Indonesia Kita mengenal keutuhan wilayah sebagai keberlangsungan wilayah negara sebagai satu kesatuan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat pesan tentang persatuan yang menghormati perbedaan. Hindari stereotip dan periksa informasi yang digunakan."},{"type":"text","body":"Rangkuman: Keutuhan wilayah: Keberlangsungan wilayah negara sebagai satu kesatuan; Persatuan nasional: Kebersamaan sebagai bangsa di tengah perbedaan daerah dan identitas; Tanggung jawab lingkungan: Peran merawat alam dan ruang hidup yang dipakai bersama; Informasi bertanggung jawab: Penyampaian kabar yang diperiksa agar tidak memecah hubungan; Kerja sama antarwilayah: Usaha daerah yang berbeda untuk kepentingan bersama."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('54c720e2-b180-551a-9865-e93fd711a694','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Pancasila sebagai pedoman tindakan','belajar-pancasila-kelas-6-unit-1',6,'C','Bab 1','dasar','draft',12,'{"summary":"Pancasila sebagai pedoman tindakan. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan pancasila sebagai pedoman tindakan dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Pendidikan Pancasila untuk SD/MI Kelas VI","url":"https://buku.kemendikdasmen.go.id/katalog/pendidikan-pancasila-untuk-sdmi-kelas-vi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan pancasila sebagai pedoman tindakan dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar pancasila sebagai pedoman tindakan. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Pancasila sebagai pedoman. Nilai dasar yang menjadi arah pertimbangan tindakan dalam kehidupan bersama. Contoh: Siswa menilai keputusan berdasarkan kemanusiaan, persatuan, dan keadilan"},{"type":"text","body":"2. Konsistensi nilai. Kesesuaian antara nilai yang diucapkan dengan tindakan. Contoh: Anak menyatakan menghargai perbedaan dan tidak mengejek teman"},{"type":"text","body":"3. Penalaran moral. Pertimbangan alasan, hak, dan dampak sebelum bertindak. Contoh: Kelompok memikirkan pilihan yang paling menghormati semua anggota"},{"type":"text","body":"4. Tanggung jawab warga. Peran aktif menjaga kehidupan bersama sesuai kemampuan. Contoh: Anak menggunakan fasilitas umum dengan tertib"},{"type":"text","body":"5. Perbaikan diri. Usaha mengubah tindakan setelah memahami kesalahannya. Contoh: Anak meminta maaf dan melakukan langkah memperbaiki akibat"},{"type":"text","body":"Contoh dan penalaran: Siswa menilai keputusan berdasarkan kemanusiaan, persatuan, dan keadilan Kita mengenal pancasila sebagai pedoman sebagai nilai dasar yang menjadi arah pertimbangan tindakan dalam kehidupan bersama. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Gunakan nilai Pancasila untuk menilai pilihan pada masalah sehari-hari. Berikan alasan, bukan sekadar menyebut nama sila."},{"type":"text","body":"Rangkuman: Pancasila sebagai pedoman: Nilai dasar yang menjadi arah pertimbangan tindakan dalam kehidupan bersama; Konsistensi nilai: Kesesuaian antara nilai yang diucapkan dengan tindakan; Penalaran moral: Pertimbangan alasan, hak, dan dampak sebelum bertindak; Tanggung jawab warga: Peran aktif menjaga kehidupan bersama sesuai kemampuan; Perbaikan diri: Usaha mengubah tindakan setelah memahami kesalahannya."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('f548949e-23db-5ac5-a51d-957ab350ca0c','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Norma dan tanggung jawab warga','belajar-pancasila-kelas-6-unit-2',6,'C','Bab 2','dasar','draft',12,'{"summary":"Norma dan tanggung jawab warga. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan norma dan tanggung jawab warga dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Pendidikan Pancasila untuk SD/MI Kelas VI","url":"https://buku.kemendikdasmen.go.id/katalog/pendidikan-pancasila-untuk-sdmi-kelas-vi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan norma dan tanggung jawab warga dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar norma dan tanggung jawab warga. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Norma hukum. Pedoman perilaku yang ditetapkan lembaga berwenang dengan akibat hukum. Contoh: Peraturan lalu lintas merupakan contoh aturan resmi"},{"type":"text","body":"2. Norma kesopanan. Pedoman tata perilaku yang dianggap pantas dalam masyarakat. Contoh: Berbicara santun kepada orang lain menjaga hubungan"},{"type":"text","body":"3. Norma kesusilaan. Pedoman baik-buruk yang berkaitan dengan hati nurani. Contoh: Anak memilih jujur meskipun tidak diawasi"},{"type":"text","body":"4. Kesepakatan kelompok. Aturan bersama yang dibentuk untuk mengelola kegiatan. Contoh: Anggota menyepakati batas waktu memakai alat"},{"type":"text","body":"5. Penyelesaian bertanggung jawab. Menghadapi pelanggaran dengan bukti, keadilan, dan bantuan yang tepat. Contoh: Kelompok mencari perbaikan tanpa mempermalukan pelaku"},{"type":"text","body":"Contoh dan penalaran: Peraturan lalu lintas merupakan contoh aturan resmi Kita mengenal norma hukum sebagai pedoman perilaku yang ditetapkan lembaga berwenang dengan akibat hukum. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Bandingkan contoh norma dalam kehidupan. Untuk masalah hukum nyata, minta pendamping menggunakan sumber resmi yang berlaku."},{"type":"text","body":"Rangkuman: Norma hukum: Pedoman perilaku yang ditetapkan lembaga berwenang dengan akibat hukum; Norma kesopanan: Pedoman tata perilaku yang dianggap pantas dalam masyarakat; Norma kesusilaan: Pedoman baik-buruk yang berkaitan dengan hati nurani; Kesepakatan kelompok: Aturan bersama yang dibentuk untuk mengelola kegiatan; Penyelesaian bertanggung jawab: Menghadapi pelanggaran dengan bukti, keadilan, dan bantuan yang tepat."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('ec3d8b30-fe49-572e-ab5f-9771cb63f1c1','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Musyawarah dan penyelesaian perbedaan','belajar-pancasila-kelas-6-unit-3',6,'C','Bab 3','dasar','draft',12,'{"summary":"Musyawarah dan penyelesaian perbedaan. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan musyawarah dan penyelesaian perbedaan dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Pendidikan Pancasila untuk SD/MI Kelas VI","url":"https://buku.kemendikdasmen.go.id/katalog/pendidikan-pancasila-untuk-sdmi-kelas-vi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan musyawarah dan penyelesaian perbedaan dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar musyawarah dan penyelesaian perbedaan. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Perbedaan pendapat. Ketidaksamaan pandangan yang dapat dibahas dengan hormat. Contoh: Dua anak mengusulkan kegiatan berbeda"},{"type":"text","body":"2. Mendengar aktif. Memperhatikan dan memastikan pemahaman sebelum menanggapi. Contoh: Anak mengulang inti alasan teman dengan benar"},{"type":"text","body":"3. Kompromi. Penyesuaian sebagian keinginan untuk memperoleh pilihan yang dapat diterima. Contoh: Anggota mengubah sebagian rencana setelah memahami kebutuhan lain"},{"type":"text","body":"4. Mediasi sederhana. Bantuan pihak netral untuk memudahkan pembicaraan. Contoh: Pendamping membantu dua pihak menyampaikan kebutuhan tanpa saling menyerang"},{"type":"text","body":"5. Kesepakatan adil. Keputusan yang mempertimbangkan hak, kebutuhan, dan alasan semua pihak. Contoh: Kelompok memilih cara yang tidak mengorbankan keselamatan anggotanya"},{"type":"text","body":"Contoh dan penalaran: Dua anak mengusulkan kegiatan berbeda Kita mengenal perbedaan pendapat sebagai ketidaksamaan pandangan yang dapat dibahas dengan hormat. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Latih penyelesaian perbedaan dengan mendengar, menjelaskan kebutuhan, dan meminta bantuan netral bila perlu."},{"type":"text","body":"Rangkuman: Perbedaan pendapat: Ketidaksamaan pandangan yang dapat dibahas dengan hormat; Mendengar aktif: Memperhatikan dan memastikan pemahaman sebelum menanggapi; Kompromi: Penyesuaian sebagian keinginan untuk memperoleh pilihan yang dapat diterima; Mediasi sederhana: Bantuan pihak netral untuk memudahkan pembicaraan; Kesepakatan adil: Keputusan yang mempertimbangkan hak, kebutuhan, dan alasan semua pihak."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('58296a77-c9c0-5017-a3c3-1c80409d66da','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Menghormati identitas dan keyakinan','belajar-pancasila-kelas-6-unit-4',6,'C','Bab 4','sedang','draft',12,'{"summary":"Menghormati identitas dan keyakinan. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan menghormati identitas dan keyakinan dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Pendidikan Pancasila untuk SD/MI Kelas VI","url":"https://buku.kemendikdasmen.go.id/katalog/pendidikan-pancasila-untuk-sdmi-kelas-vi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan menghormati identitas dan keyakinan dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar menghormati identitas dan keyakinan. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Identitas budaya. Ciri budaya yang berkaitan dengan kehidupan seseorang atau kelompok. Contoh: Bahasa keluarga dapat menjadi bagian identitas budaya"},{"type":"text","body":"2. Toleransi. Menghormati perbedaan tanpa memaksakan pilihan pribadi. Contoh: Anak memberi ruang teman menjalankan kebiasaannya yang tidak merugikan"},{"type":"text","body":"3. Stereotip. Anggapan menyamaratakan orang berdasarkan kelompoknya. Contoh: Menyebut semua orang suatu daerah pasti bersifat sama adalah penyamarataan"},{"type":"text","body":"4. Inklusif. Memberi ruang partisipasi kepada anggota dengan kebutuhan beragam. Contoh: Kelompok menyesuaikan cara agar teman dapat ikut"},{"type":"text","body":"5. Kesetaraan martabat. Pandangan bahwa setiap orang layak dihormati sebagai manusia. Contoh: Anak tidak mengukur harga diri teman dari latar keluarganya"},{"type":"text","body":"Contoh dan penalaran: Bahasa keluarga dapat menjadi bagian identitas budaya Kita mengenal identitas budaya sebagai ciri budaya yang berkaitan dengan kehidupan seseorang atau kelompok. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Rancang kegiatan yang menghormati identitas dan keyakinan peserta. Tidak memaksa teman mengikuti praktik yang berbeda."},{"type":"text","body":"Rangkuman: Identitas budaya: Ciri budaya yang berkaitan dengan kehidupan seseorang atau kelompok; Toleransi: Menghormati perbedaan tanpa memaksakan pilihan pribadi; Stereotip: Anggapan menyamaratakan orang berdasarkan kelompoknya; Inklusif: Memberi ruang partisipasi kepada anggota dengan kebutuhan beragam; Kesetaraan martabat: Pandangan bahwa setiap orang layak dihormati sebagai manusia."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('88980b08-0932-5d3b-840a-0cf0739bcfcc','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Gotong royong untuk masalah bersama','belajar-pancasila-kelas-6-unit-5',6,'C','Bab 5','sedang','draft',12,'{"summary":"Gotong royong untuk masalah bersama. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan gotong royong untuk masalah bersama dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Pendidikan Pancasila untuk SD/MI Kelas VI","url":"https://buku.kemendikdasmen.go.id/katalog/pendidikan-pancasila-untuk-sdmi-kelas-vi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan gotong royong untuk masalah bersama dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar gotong royong untuk masalah bersama. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Masalah bersama. Keadaan yang memengaruhi banyak anggota dan perlu ditangani bersama. Contoh: Ruang belajar sulit digunakan karena buku tidak tertata"},{"type":"text","body":"2. Identifikasi kebutuhan. Usaha memahami hal yang benar-benar perlu diperbaiki. Contoh: Kelompok bertanya bagian mana yang paling menghambat penggunaan ruang"},{"type":"text","body":"3. Rencana aksi. Langkah, peran, waktu, dan alat untuk menjalankan perbaikan. Contoh: Kelompok membagi tugas merapikan serta memberi label"},{"type":"text","body":"4. Partisipasi. Keterlibatan sesuai kemampuan dalam kegiatan bersama. Contoh: Setiap anggota dapat mengambil peran yang sesuai"},{"type":"text","body":"5. Evaluasi bersama. Pembahasan hasil tindakan untuk menentukan perbaikan berikutnya. Contoh: Kelompok memeriksa apakah susunan baru memudahkan semua anggota"},{"type":"text","body":"Contoh dan penalaran: Ruang belajar sulit digunakan karena buku tidak tertata Kita mengenal masalah bersama sebagai keadaan yang memengaruhi banyak anggota dan perlu ditangani bersama. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Pilih masalah kecil yang dapat ditangani bersama. Buat rencana, laksanakan secara aman, lalu nilai hasilnya."},{"type":"text","body":"Rangkuman: Masalah bersama: Keadaan yang memengaruhi banyak anggota dan perlu ditangani bersama; Identifikasi kebutuhan: Usaha memahami hal yang benar-benar perlu diperbaiki; Rencana aksi: Langkah, peran, waktu, dan alat untuk menjalankan perbaikan; Partisipasi: Keterlibatan sesuai kemampuan dalam kegiatan bersama; Evaluasi bersama: Pembahasan hasil tindakan untuk menentukan perbaikan berikutnya."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('8cf73b8c-5b23-5f64-a380-3c0ca6af7478','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Persatuan dan keutuhan wilayah','belajar-pancasila-kelas-6-unit-6',6,'C','Bab 6','sedang','draft',12,'{"summary":"Persatuan dan keutuhan wilayah. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan persatuan dan keutuhan wilayah dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Pendidikan Pancasila untuk SD/MI Kelas VI","url":"https://buku.kemendikdasmen.go.id/katalog/pendidikan-pancasila-untuk-sdmi-kelas-vi","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan persatuan dan keutuhan wilayah dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar persatuan dan keutuhan wilayah. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Keutuhan wilayah. Keberlangsungan wilayah negara sebagai satu kesatuan. Contoh: Berbagai pulau dan daerah dipahami sebagai bagian Indonesia"},{"type":"text","body":"2. Persatuan nasional. Kebersamaan sebagai bangsa di tengah perbedaan daerah dan identitas. Contoh: Warga menghormati daerah lain sebagai bagian bangsa yang sama"},{"type":"text","body":"3. Tanggung jawab lingkungan. Peran merawat alam dan ruang hidup yang dipakai bersama. Contoh: Tindakan lokal menjaga sumber air dapat bermanfaat bagi wilayah lain"},{"type":"text","body":"4. Informasi bertanggung jawab. Penyampaian kabar yang diperiksa agar tidak memecah hubungan. Contoh: Anak mengecek sumber sebelum menyebarkan kabar tentang kelompok lain"},{"type":"text","body":"5. Kerja sama antarwilayah. Usaha daerah yang berbeda untuk kepentingan bersama. Contoh: Wilayah saling membantu saat menghadapi kebutuhan bersama"},{"type":"text","body":"Contoh dan penalaran: Berbagai pulau dan daerah dipahami sebagai bagian Indonesia Kita mengenal keutuhan wilayah sebagai keberlangsungan wilayah negara sebagai satu kesatuan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Jelaskan hubungan tindakan lokal dengan persatuan dan keutuhan Indonesia. Gunakan informasi yang dapat diperiksa."},{"type":"text","body":"Rangkuman: Keutuhan wilayah: Keberlangsungan wilayah negara sebagai satu kesatuan; Persatuan nasional: Kebersamaan sebagai bangsa di tengah perbedaan daerah dan identitas; Tanggung jawab lingkungan: Peran merawat alam dan ruang hidup yang dipakai bersama; Informasi bertanggung jawab: Penyampaian kabar yang diperiksa agar tidak memecah hubungan; Kerja sama antarwilayah: Usaha daerah yang berbeda untuk kepentingan bersama."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('644b84f4-167e-5597-8a59-a51fe56cb928','620ca8d1-025d-5ecc-80e1-727f5c59216d','Greetings','belajar-bahasa-inggris-kelas-1-unit-1',1,'A','Bab 1','dasar','draft',8,'{"summary":"Greetings. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan greetings dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan mata pelajaran untuk pendamping","url":"https://kurikulum.kemendikdasmen.go.id/panduan-mapel","usage":"Acuan pendamping; pengayaan Fase A bukan klaim CP mapel wajib."}],"curriculum_note":"Pengayaan awal; bukan klaim mata pelajaran wajib atau CP IPAS/Inggris Fase A.","enrichment":true,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan greetings dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar greetings. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Hello. Sapaan halo ketika bertemu. Contoh: Hello, Nara menyapa Nara"},{"type":"text","body":"2. Good morning. Sapaan selamat pagi. Contoh: Good morning, friends digunakan pada pagi hari"},{"type":"text","body":"3. Goodbye. Ungkapan selamat tinggal atau sampai berjumpa. Contoh: Goodbye diucapkan saat berpisah"},{"type":"text","body":"4. Please. Kata untuk membuat permintaan lebih santun. Contoh: Sit down, please adalah permintaan sopan"},{"type":"text","body":"5. Thank you. Ungkapan terima kasih. Contoh: Thank you diucapkan setelah menerima bantuan"},{"type":"text","body":"Contoh dan penalaran: Hello, Nara menyapa Nara Kita mengenal hello sebagai sapaan halo ketika bertemu. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Dengan pendamping, ucapkan sapaan untuk pagi, saat bertemu, dan saat berpisah. Tidak perlu meniru aksen tertentu; utamakan pesan yang dipahami."},{"type":"text","body":"Rangkuman: Hello: Sapaan halo ketika bertemu; Good morning: Sapaan selamat pagi; Goodbye: Ungkapan selamat tinggal atau sampai berjumpa; Please: Kata untuk membuat permintaan lebih santun; Thank you: Ungkapan terima kasih."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('b22fe63d-2093-53a7-ba21-e6ac0f0f75ef','620ca8d1-025d-5ecc-80e1-727f5c59216d','My name and feelings','belajar-bahasa-inggris-kelas-1-unit-2',1,'A','Bab 2','dasar','draft',8,'{"summary":"My name and feelings. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan my name and feelings dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan mata pelajaran untuk pendamping","url":"https://kurikulum.kemendikdasmen.go.id/panduan-mapel","usage":"Acuan pendamping; pengayaan Fase A bukan klaim CP mapel wajib."}],"curriculum_note":"Pengayaan awal; bukan klaim mata pelajaran wajib atau CP IPAS/Inggris Fase A.","enrichment":true,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan my name and feelings dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar my name and feelings. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. My name is …. Ungkapan untuk memperkenalkan nama sendiri. Contoh: My name is Nara berarti namaku Nara"},{"type":"text","body":"2. Happy. Merasa senang. Contoh: I am happy menyatakan perasaan senang"},{"type":"text","body":"3. Sad. Merasa sedih. Contoh: I am sad menyatakan perasaan sedih"},{"type":"text","body":"4. Tired. Merasa lelah. Contoh: I am tired menyatakan keadaan lelah"},{"type":"text","body":"5. How are you?. Pertanyaan tentang keadaan atau kabar. Contoh: How are you dipakai menanyakan kabar teman"},{"type":"text","body":"Contoh dan penalaran: My name is Nara berarti namaku Nara Kita mengenal my name is … sebagai ungkapan untuk memperkenalkan nama sendiri. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Gunakan tokoh rekaan untuk mengenalkan nama dan perasaannya. Anak boleh tidak menceritakan perasaan pribadinya."},{"type":"text","body":"Rangkuman: My name is …: Ungkapan untuk memperkenalkan nama sendiri; Happy: Merasa senang; Sad: Merasa sedih; Tired: Merasa lelah; How are you?: Pertanyaan tentang keadaan atau kabar."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('b7557d6c-3065-54ce-b5f4-0456585a62a5','620ca8d1-025d-5ecc-80e1-727f5c59216d','Colours and numbers','belajar-bahasa-inggris-kelas-1-unit-3',1,'A','Bab 3','dasar','draft',8,'{"summary":"Colours and numbers. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan colours and numbers dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan mata pelajaran untuk pendamping","url":"https://kurikulum.kemendikdasmen.go.id/panduan-mapel","usage":"Acuan pendamping; pengayaan Fase A bukan klaim CP mapel wajib."}],"curriculum_note":"Pengayaan awal; bukan klaim mata pelajaran wajib atau CP IPAS/Inggris Fase A.","enrichment":true,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan colours and numbers dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar colours and numbers. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. One. Bilangan satu. Contoh: One pencil berarti satu pensil"},{"type":"text","body":"2. Two. Bilangan dua. Contoh: Two books berarti dua buku"},{"type":"text","body":"3. Red. Warna merah. Contoh: A red bag adalah tas merah"},{"type":"text","body":"4. Blue. Warna biru. Contoh: A blue book adalah buku biru"},{"type":"text","body":"5. Green. Warna hijau. Contoh: A green leaf adalah daun hijau"},{"type":"text","body":"Contoh dan penalaran: One pencil berarti satu pensil Kita mengenal one sebagai bilangan satu. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Hitung sampai tiga benda aman. Pilih dua warna lalu sebut jumlah serta warnanya bersama pendamping."},{"type":"text","body":"Rangkuman: One: Bilangan satu; Two: Bilangan dua; Red: Warna merah; Blue: Warna biru; Green: Warna hijau."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('ab53d123-3cda-5a98-bf83-e54b58e4b420','620ca8d1-025d-5ecc-80e1-727f5c59216d','Classroom objects','belajar-bahasa-inggris-kelas-1-unit-4',1,'A','Bab 4','sedang','draft',8,'{"summary":"Classroom objects. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan classroom objects dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan mata pelajaran untuk pendamping","url":"https://kurikulum.kemendikdasmen.go.id/panduan-mapel","usage":"Acuan pendamping; pengayaan Fase A bukan klaim CP mapel wajib."}],"curriculum_note":"Pengayaan awal; bukan klaim mata pelajaran wajib atau CP IPAS/Inggris Fase A.","enrichment":true,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan classroom objects dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar classroom objects. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Book. Buku. Contoh: A book dapat dibaca"},{"type":"text","body":"2. Pencil. Pensil. Contoh: A pencil digunakan untuk menulis"},{"type":"text","body":"3. Bag. Tas. Contoh: A bag dapat membawa alat belajar"},{"type":"text","body":"4. Ruler. Penggaris. Contoh: A ruler membantu mengukur panjang"},{"type":"text","body":"5. Chair. Kursi. Contoh: A chair digunakan untuk duduk"},{"type":"text","body":"Contoh dan penalaran: A book dapat dibaca Kita mengenal book sebagai buku. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Tunjuk benda kelas yang aman dan sebut namanya. Gunakan frasa pendek, misalnya a book."},{"type":"text","body":"Rangkuman: Book: Buku; Pencil: Pensil; Bag: Tas; Ruler: Penggaris; Chair: Kursi."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('250af53b-988c-5ea4-b2de-3358498d7dbd','620ca8d1-025d-5ecc-80e1-727f5c59216d','Family words','belajar-bahasa-inggris-kelas-1-unit-5',1,'A','Bab 5','sedang','draft',8,'{"summary":"Family words. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan family words dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan mata pelajaran untuk pendamping","url":"https://kurikulum.kemendikdasmen.go.id/panduan-mapel","usage":"Acuan pendamping; pengayaan Fase A bukan klaim CP mapel wajib."}],"curriculum_note":"Pengayaan awal; bukan klaim mata pelajaran wajib atau CP IPAS/Inggris Fase A.","enrichment":true,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan family words dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar family words. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Mother. Ibu. Contoh: Her mother berarti ibunya"},{"type":"text","body":"2. Father. Ayah. Contoh: His father berarti ayahnya"},{"type":"text","body":"3. Brother. Saudara laki-laki. Contoh: My brother berarti saudara laki-lakiku"},{"type":"text","body":"4. Sister. Saudara perempuan. Contoh: My sister berarti saudara perempuanku"},{"type":"text","body":"5. Family. Keluarga. Contoh: My family berarti keluargaku"},{"type":"text","body":"Contoh dan penalaran: Her mother berarti ibunya Kita mengenal mother sebagai ibu. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat keluarga tokoh rekaan dan sebut hubungan antaranggota. Keluarga dapat mempunyai susunan yang berbeda dan tetap saling merawat."},{"type":"text","body":"Rangkuman: Mother: Ibu; Father: Ayah; Brother: Saudara laki-laki; Sister: Saudara perempuan; Family: Keluarga."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('b73d8a95-24e3-591d-8949-9ff8384a30f2','620ca8d1-025d-5ecc-80e1-727f5c59216d','Simple instructions','belajar-bahasa-inggris-kelas-1-unit-6',1,'A','Bab 6','sedang','draft',8,'{"summary":"Simple instructions. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan simple instructions dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan mata pelajaran untuk pendamping","url":"https://kurikulum.kemendikdasmen.go.id/panduan-mapel","usage":"Acuan pendamping; pengayaan Fase A bukan klaim CP mapel wajib."}],"curriculum_note":"Pengayaan awal; bukan klaim mata pelajaran wajib atau CP IPAS/Inggris Fase A.","enrichment":true,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan simple instructions dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar simple instructions. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Sit down. Duduk. Contoh: Sit down, please meminta seseorang duduk"},{"type":"text","body":"2. Stand up. Berdiri. Contoh: Stand up meminta seseorang berdiri"},{"type":"text","body":"3. Open your book. Buka bukumu. Contoh: Open your book mengarahkan untuk membuka buku"},{"type":"text","body":"4. Close your book. Tutup bukumu. Contoh: Close your book mengarahkan untuk menutup buku"},{"type":"text","body":"5. Listen. Dengarkan. Contoh: Listen, please meminta orang memperhatikan bunyi atau ucapan"},{"type":"text","body":"Contoh dan penalaran: Sit down, please meminta seseorang duduk Kita mengenal sit down sebagai duduk. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Pendamping memberi instruksi satu per satu dengan gerak yang aman. Anak mengikuti setelah memahami, bukan karena ditekan untuk cepat."},{"type":"text","body":"Rangkuman: Sit down: Duduk; Stand up: Berdiri; Open your book: Buka bukumu; Close your book: Tutup bukumu; Listen: Dengarkan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('d943483e-9df0-5a82-8c44-81c0a4784005','620ca8d1-025d-5ecc-80e1-727f5c59216d','Introducing myself','belajar-bahasa-inggris-kelas-2-unit-1',2,'A','Bab 1','dasar','draft',8,'{"summary":"Introducing myself. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan introducing myself dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan mata pelajaran untuk pendamping","url":"https://kurikulum.kemendikdasmen.go.id/panduan-mapel","usage":"Acuan pendamping; pengayaan Fase A bukan klaim CP mapel wajib."}],"curriculum_note":"Pengayaan awal; bukan klaim mata pelajaran wajib atau CP IPAS/Inggris Fase A.","enrichment":true,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan introducing myself dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar introducing myself. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. I am … years old. Ungkapan menyatakan usia. Contoh: I am eight years old berarti aku berusia delapan tahun"},{"type":"text","body":"2. What is your name?. Pertanyaan untuk menanyakan nama. Contoh: What is your name meminta nama lawan bicara"},{"type":"text","body":"3. Nice to meet you. Ungkapan senang berkenalan. Contoh: Nice to meet you diucapkan dalam perkenalan"},{"type":"text","body":"4. This is …. Ungkapan mengenalkan orang atau benda yang ditunjuk. Contoh: This is Nara mengenalkan tokoh Nara"},{"type":"text","body":"5. I am from …. Ungkapan menyebut asal secara umum. Contoh: I am from Indonesia menyebut negara asal"},{"type":"text","body":"Contoh dan penalaran: I am eight years old berarti aku berusia delapan tahun Kita mengenal i am … years old sebagai ungkapan menyatakan usia. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Perkenalkan tokoh rekaan memakai nama dan usia. Jangan menuliskan alamat lengkap atau data pribadi anak."},{"type":"text","body":"Rangkuman: I am … years old: Ungkapan menyatakan usia; What is your name?: Pertanyaan untuk menanyakan nama; Nice to meet you: Ungkapan senang berkenalan; This is …: Ungkapan mengenalkan orang atau benda yang ditunjuk; I am from …: Ungkapan menyebut asal secara umum."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('58841e3b-7d97-535c-a549-8f28efd6b431','620ca8d1-025d-5ecc-80e1-727f5c59216d','Numbers and colours','belajar-bahasa-inggris-kelas-2-unit-2',2,'A','Bab 2','dasar','draft',8,'{"summary":"Numbers and colours. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan numbers and colours dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan mata pelajaran untuk pendamping","url":"https://kurikulum.kemendikdasmen.go.id/panduan-mapel","usage":"Acuan pendamping; pengayaan Fase A bukan klaim CP mapel wajib."}],"curriculum_note":"Pengayaan awal; bukan klaim mata pelajaran wajib atau CP IPAS/Inggris Fase A.","enrichment":true,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan numbers and colours dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar numbers and colours. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Ten. Bilangan sepuluh. Contoh: Ten pencils berarti sepuluh pensil"},{"type":"text","body":"2. Thirteen. Bilangan tiga belas. Contoh: Thirteen books berarti tiga belas buku"},{"type":"text","body":"3. Twenty. Bilangan dua puluh. Contoh: Twenty dots berarti dua puluh titik"},{"type":"text","body":"4. Yellow. Warna kuning. Contoh: A yellow flower adalah bunga kuning"},{"type":"text","body":"5. Black. Warna hitam. Contoh: A black pencil adalah pensil hitam"},{"type":"text","body":"Contoh dan penalaran: Ten pencils berarti sepuluh pensil Kita mengenal ten sebagai bilangan sepuluh. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat kartu bilangan dan warna. Baca bersama dan cocokkan dengan jumlah atau warna, tanpa menjadikan warna sebagai satu-satunya petunjuk."},{"type":"text","body":"Rangkuman: Ten: Bilangan sepuluh; Thirteen: Bilangan tiga belas; Twenty: Bilangan dua puluh; Yellow: Warna kuning; Black: Warna hitam."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('1b5be4df-e876-536f-8d24-d0d35e1e98d4','620ca8d1-025d-5ecc-80e1-727f5c59216d','Things around us','belajar-bahasa-inggris-kelas-2-unit-3',2,'A','Bab 3','dasar','draft',8,'{"summary":"Things around us. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan things around us dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan mata pelajaran untuk pendamping","url":"https://kurikulum.kemendikdasmen.go.id/panduan-mapel","usage":"Acuan pendamping; pengayaan Fase A bukan klaim CP mapel wajib."}],"curriculum_note":"Pengayaan awal; bukan klaim mata pelajaran wajib atau CP IPAS/Inggris Fase A.","enrichment":true,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan things around us dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar things around us. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Table. Meja. Contoh: A table dapat menjadi tempat meletakkan buku"},{"type":"text","body":"2. Door. Pintu. Contoh: Open the door berarti buka pintunya"},{"type":"text","body":"3. Window. Jendela. Contoh: A window dapat menjadi jalan masuk cahaya"},{"type":"text","body":"4. Clock. Jam penunjuk waktu. Contoh: A clock menunjukkan waktu"},{"type":"text","body":"5. Board. Papan. Contoh: The board dapat digunakan guru untuk menulis"},{"type":"text","body":"Contoh dan penalaran: A table dapat menjadi tempat meletakkan buku Kita mengenal table sebagai meja. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Amati ruangan atau gambar. Pilih lima benda lalu buat frasa yang dapat dipahami pasanganmu."},{"type":"text","body":"Rangkuman: Table: Meja; Door: Pintu; Window: Jendela; Clock: Jam penunjuk waktu; Board: Papan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('a2affe6d-82b7-5ac9-9d86-7ab62466d0a8','620ca8d1-025d-5ecc-80e1-727f5c59216d','Family and friends','belajar-bahasa-inggris-kelas-2-unit-4',2,'A','Bab 4','sedang','draft',8,'{"summary":"Family and friends. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan family and friends dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan mata pelajaran untuk pendamping","url":"https://kurikulum.kemendikdasmen.go.id/panduan-mapel","usage":"Acuan pendamping; pengayaan Fase A bukan klaim CP mapel wajib."}],"curriculum_note":"Pengayaan awal; bukan klaim mata pelajaran wajib atau CP IPAS/Inggris Fase A.","enrichment":true,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan family and friends dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar family and friends. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Friend. Teman. Contoh: My friend likes reading berarti temanku suka membaca"},{"type":"text","body":"2. We. Kami atau kita. Contoh: We read berarti kami atau kita membaca"},{"type":"text","body":"3. They. Mereka; juga dapat merujuk seseorang tanpa menyebut gender. Contoh: They are here menyatakan mereka ada di sini"},{"type":"text","body":"4. She. Kata ganti untuk perempuan dalam konteks yang diketahui. Contoh: She is my sister merujuk saudara perempuan"},{"type":"text","body":"5. He. Kata ganti untuk laki-laki dalam konteks yang diketahui. Contoh: He is my brother merujuk saudara laki-laki"},{"type":"text","body":"Contoh dan penalaran: My friend likes reading berarti temanku suka membaca Kita mengenal friend sebagai teman. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat gambar teman rekaan. Latih kata ganti dengan konteks yang jelas; they juga dapat dipakai ketika tidak menyebut gender seseorang."},{"type":"text","body":"Rangkuman: Friend: Teman; We: Kami atau kita; They: Mereka; juga dapat merujuk seseorang tanpa menyebut gender; She: Kata ganti untuk perempuan dalam konteks yang diketahui; He: Kata ganti untuk laki-laki dalam konteks yang diketahui."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('b15b344b-1f93-51db-93d8-65f40649dc22','620ca8d1-025d-5ecc-80e1-727f5c59216d','Animals and actions','belajar-bahasa-inggris-kelas-2-unit-5',2,'A','Bab 5','sedang','draft',8,'{"summary":"Animals and actions. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan animals and actions dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan mata pelajaran untuk pendamping","url":"https://kurikulum.kemendikdasmen.go.id/panduan-mapel","usage":"Acuan pendamping; pengayaan Fase A bukan klaim CP mapel wajib."}],"curriculum_note":"Pengayaan awal; bukan klaim mata pelajaran wajib atau CP IPAS/Inggris Fase A.","enrichment":true,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan animals and actions dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar animals and actions. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Bird. Burung. Contoh: A bird adalah seekor burung"},{"type":"text","body":"2. Fish. Ikan. Contoh: A fish adalah seekor ikan"},{"type":"text","body":"3. Run. Berlari. Contoh: I can run berarti aku dapat berlari"},{"type":"text","body":"4. Swim. Berenang. Contoh: Some fish swim menyatakan sebagian ikan berenang"},{"type":"text","body":"5. Eat. Makan. Contoh: Animals eat food menyatakan hewan makan"},{"type":"text","body":"Contoh dan penalaran: A bird adalah seekor burung Kita mengenal bird sebagai burung. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Pilih gambar hewan lalu cocokkan dengan kata tindakan. Jangan menyimpulkan semua hewan bergerak dengan satu cara saja."},{"type":"text","body":"Rangkuman: Bird: Burung; Fish: Ikan; Run: Berlari; Swim: Berenang; Eat: Makan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('36ed1bd0-e91f-5483-89af-386d9b8b0014','620ca8d1-025d-5ecc-80e1-727f5c59216d','Polite expressions','belajar-bahasa-inggris-kelas-2-unit-6',2,'A','Bab 6','sedang','draft',8,'{"summary":"Polite expressions. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan polite expressions dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan mata pelajaran untuk pendamping","url":"https://kurikulum.kemendikdasmen.go.id/panduan-mapel","usage":"Acuan pendamping; pengayaan Fase A bukan klaim CP mapel wajib."}],"curriculum_note":"Pengayaan awal; bukan klaim mata pelajaran wajib atau CP IPAS/Inggris Fase A.","enrichment":true,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan polite expressions dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar polite expressions. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. May I …?. Ungkapan meminta izin. Contoh: May I borrow a pencil meminta izin meminjam pensil"},{"type":"text","body":"2. Sorry. Ungkapan meminta maaf atau menyatakan penyesalan. Contoh: Sorry diucapkan setelah melakukan kesalahan"},{"type":"text","body":"3. You are welcome. Tanggapan terhadap ucapan terima kasih. Contoh: You are welcome menjawab Thank you"},{"type":"text","body":"4. Excuse me. Ungkapan meminta perhatian atau izin lewat dengan santun. Contoh: Excuse me digunakan sebelum menyela secara sopan"},{"type":"text","body":"5. Can you help me?. Pertanyaan meminta bantuan. Contoh: Can you help me meminta orang membantu"},{"type":"text","body":"Contoh dan penalaran: May I borrow a pencil meminta izin meminjam pensil Kita mengenal may i …? sebagai ungkapan meminta izin. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Mainkan percakapan singkat meminta bantuan, berterima kasih, dan meminta maaf. Lawan bicara tetap boleh menolak dengan sopan."},{"type":"text","body":"Rangkuman: May I …?: Ungkapan meminta izin; Sorry: Ungkapan meminta maaf atau menyatakan penyesalan; You are welcome: Tanggapan terhadap ucapan terima kasih; Excuse me: Ungkapan meminta perhatian atau izin lewat dengan santun; Can you help me?: Pertanyaan meminta bantuan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('05c80c5e-945e-5683-9082-7a025e173f05','620ca8d1-025d-5ecc-80e1-727f5c59216d','Greetings and introductions','belajar-bahasa-inggris-kelas-3-unit-1',3,'B','Bab 1','dasar','draft',12,'{"summary":"Greetings and introductions. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan greetings and introductions dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Inggris: English for Nusantara Kids Kelas III","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-inggris-english-for-nusantara-kids-untuk-sd-mi-kelas-iii","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan greetings and introductions dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar greetings and introductions. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Good afternoon. Sapaan selamat siang atau sore sesuai kebiasaan pemakaian. Contoh: Good afternoon digunakan sesudah tengah hari"},{"type":"text","body":"2. Good evening. Sapaan ketika bertemu pada petang atau malam. Contoh: Good evening digunakan saat mulai bertemu pada malam hari"},{"type":"text","body":"3. Good night. Ungkapan ketika berpisah untuk tidur pada malam hari. Contoh: Good night diucapkan menjelang tidur"},{"type":"text","body":"4. How are you?. Pertanyaan tentang kabar atau keadaan. Contoh: How are you menanyakan keadaan lawan bicara"},{"type":"text","body":"5. See you later. Ungkapan sampai bertemu lagi. Contoh: See you later menutup pertemuan dengan harapan berjumpa kembali"},{"type":"text","body":"Contoh dan penalaran: Good afternoon digunakan sesudah tengah hari Kita mengenal good afternoon sebagai sapaan selamat siang atau sore sesuai kebiasaan pemakaian. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Lakukan percakapan perkenalan dua tokoh rekaan. Tanyakan kabar, tanggapi, lalu tutup percakapan secara wajar."},{"type":"text","body":"Rangkuman: Good afternoon: Sapaan selamat siang atau sore sesuai kebiasaan pemakaian; Good evening: Sapaan ketika bertemu pada petang atau malam; Good night: Ungkapan ketika berpisah untuk tidur pada malam hari; How are you?: Pertanyaan tentang kabar atau keadaan; See you later: Ungkapan sampai bertemu lagi."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('528ce333-d4da-5764-8c88-26c9c7eda906','620ca8d1-025d-5ecc-80e1-727f5c59216d','Numbers and classroom language','belajar-bahasa-inggris-kelas-3-unit-2',3,'B','Bab 2','dasar','draft',12,'{"summary":"Numbers and classroom language. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan numbers and classroom language dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Inggris: English for Nusantara Kids Kelas III","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-inggris-english-for-nusantara-kids-untuk-sd-mi-kelas-iii","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan numbers and classroom language dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar numbers and classroom language. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Twenty-one. Bilangan dua puluh satu. Contoh: Twenty-one books menyatakan 21 buku"},{"type":"text","body":"2. Thirty. Bilangan tiga puluh. Contoh: Thirty days menyatakan 30 hari"},{"type":"text","body":"3. Forty. Bilangan empat puluh. Contoh: Forty pencils menyatakan 40 pensil"},{"type":"text","body":"4. Raise your hand. Angkat tanganmu. Contoh: Raise your hand meminta peserta mengangkat tangan"},{"type":"text","body":"5. Work in pairs. Bekerjalah berpasangan. Contoh: Work in pairs meminta dua orang bekerja bersama"},{"type":"text","body":"Contoh dan penalaran: Twenty-one books menyatakan 21 buku Kita mengenal twenty-one sebagai bilangan dua puluh satu. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Susun lima kartu jumlah dan instruksi kelas. Dengarkan pendamping lalu cocokkan dengan gambar yang sesuai."},{"type":"text","body":"Rangkuman: Twenty-one: Bilangan dua puluh satu; Thirty: Bilangan tiga puluh; Forty: Bilangan empat puluh; Raise your hand: Angkat tanganmu; Work in pairs: Bekerjalah berpasangan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('707862bf-1794-527b-9dab-5207498712da','620ca8d1-025d-5ecc-80e1-727f5c59216d','People and objects','belajar-bahasa-inggris-kelas-3-unit-3',3,'B','Bab 3','dasar','draft',12,'{"summary":"People and objects. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan people and objects dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Inggris: English for Nusantara Kids Kelas III","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-inggris-english-for-nusantara-kids-untuk-sd-mi-kelas-iii","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan people and objects dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar people and objects. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Tall. Tinggi dalam perbandingan yang sesuai. Contoh: A tall tree adalah pohon tinggi"},{"type":"text","body":"2. Short. Pendek dalam perbandingan yang sesuai. Contoh: A short pencil adalah pensil pendek"},{"type":"text","body":"3. Kind. Baik hati dalam perilaku terhadap orang lain. Contoh: A kind friend membantu tanpa mengejek"},{"type":"text","body":"4. Young. Muda atau berusia relatif lebih awal. Contoh: A young plant adalah tanaman muda"},{"type":"text","body":"5. Old. Tua atau sudah lama dalam konteks yang sesuai. Contoh: An old book adalah buku yang sudah lama"},{"type":"text","body":"Contoh dan penalaran: A tall tree adalah pohon tinggi Kita mengenal tall sebagai tinggi dalam perbandingan yang sesuai. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Deskripsikan orang atau benda rekaan dengan kata yang hormat. Jangan menilai harga diri seseorang berdasarkan ciri tubuh."},{"type":"text","body":"Rangkuman: Tall: Tinggi dalam perbandingan yang sesuai; Short: Pendek dalam perbandingan yang sesuai; Kind: Baik hati dalam perilaku terhadap orang lain; Young: Muda atau berusia relatif lebih awal; Old: Tua atau sudah lama dalam konteks yang sesuai."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('a06e4ae7-6b55-5c58-8e70-cf8b19ab234e','620ca8d1-025d-5ecc-80e1-727f5c59216d','Likes and simple choices','belajar-bahasa-inggris-kelas-3-unit-4',3,'B','Bab 4','sedang','draft',12,'{"summary":"Likes and simple choices. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan likes and simple choices dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Inggris: English for Nusantara Kids Kelas III","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-inggris-english-for-nusantara-kids-untuk-sd-mi-kelas-iii","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan likes and simple choices dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar likes and simple choices. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. I like …. Ungkapan menyatakan kesukaan. Contoh: I like drawing berarti aku suka menggambar"},{"type":"text","body":"2. I do not like …. Ungkapan menyatakan hal yang tidak disukai. Contoh: I do not like loud sounds berarti aku tidak menyukai bunyi keras"},{"type":"text","body":"3. Do you like …?. Pertanyaan tentang kesukaan lawan bicara. Contoh: Do you like reading menanyakan kesukaan membaca"},{"type":"text","body":"4. Yes, I do. Jawaban positif untuk pertanyaan dengan Do you. Contoh: Yes, I do menjawab Do you like music secara positif"},{"type":"text","body":"5. No, I do not. Jawaban negatif untuk pertanyaan dengan Do you. Contoh: No, I do not menjawab Do you like dancing secara negatif"},{"type":"text","body":"Contoh dan penalaran: I like drawing berarti aku suka menggambar Kita mengenal i like … sebagai ungkapan menyatakan kesukaan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Beri pilihan kegiatan kepada pasangan. Latih menyukai dan tidak menyukai tanpa merendahkan pilihan teman."},{"type":"text","body":"Rangkuman: I like …: Ungkapan menyatakan kesukaan; I do not like …: Ungkapan menyatakan hal yang tidak disukai; Do you like …?: Pertanyaan tentang kesukaan lawan bicara; Yes, I do: Jawaban positif untuk pertanyaan dengan Do you; No, I do not: Jawaban negatif untuk pertanyaan dengan Do you."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('388f2122-4feb-5de6-8abc-c480405481db','620ca8d1-025d-5ecc-80e1-727f5c59216d','Daily actions','belajar-bahasa-inggris-kelas-3-unit-5',3,'B','Bab 5','sedang','draft',12,'{"summary":"Daily actions. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan daily actions dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Inggris: English for Nusantara Kids Kelas III","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-inggris-english-for-nusantara-kids-untuk-sd-mi-kelas-iii","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan daily actions dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar daily actions. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Wake up. Bangun dari tidur. Contoh: I wake up berarti aku bangun"},{"type":"text","body":"2. Wash. Mencuci atau membasuh. Contoh: I wash my hands berarti aku mencuci tanganku"},{"type":"text","body":"3. Read. Membaca. Contoh: I read a book berarti aku membaca buku"},{"type":"text","body":"4. Play. Bermain. Contoh: I play with friends berarti aku bermain dengan teman"},{"type":"text","body":"5. Help. Membantu. Contoh: I help my family berarti aku membantu keluargaku"},{"type":"text","body":"Contoh dan penalaran: I wake up berarti aku bangun Kita mengenal wake up sebagai bangun dari tidur. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat urutan empat kegiatan harian tokoh. Bacakan kalimat pendek sambil menunjuk gambar."},{"type":"text","body":"Rangkuman: Wake up: Bangun dari tidur; Wash: Mencuci atau membasuh; Read: Membaca; Play: Bermain; Help: Membantu."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('01314abe-c2e0-558b-8403-514f4b7cb03e','620ca8d1-025d-5ecc-80e1-727f5c59216d','Short spoken messages','belajar-bahasa-inggris-kelas-3-unit-6',3,'B','Bab 6','sedang','draft',12,'{"summary":"Short spoken messages. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan short spoken messages dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Inggris: English for Nusantara Kids Kelas III","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-inggris-english-for-nusantara-kids-untuk-sd-mi-kelas-iii","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan short spoken messages dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar short spoken messages. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Today. Hari ini. Contoh: We read today menyebut kegiatan hari ini"},{"type":"text","body":"2. Tomorrow. Besok. Contoh: Bring a book tomorrow meminta membawa buku besok"},{"type":"text","body":"3. Bring. Membawa ke tempat yang dituju. Contoh: Please bring a pencil meminta membawa pensil"},{"type":"text","body":"4. Meet. Bertemu. Contoh: We meet at school menyebut pertemuan di sekolah"},{"type":"text","body":"5. Message. Pesan yang menyampaikan informasi atau permintaan. Contoh: Catatan pendek mengingatkan barang yang perlu dibawa"},{"type":"text","body":"Contoh dan penalaran: We read today menyebut kegiatan hari ini Kita mengenal today sebagai hari ini. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Baca pesan rekaan: “Please bring a book tomorrow.” Sebut barang dan waktu yang diminta tanpa menambahkan informasi yang tidak ada."},{"type":"text","body":"Rangkuman: Today: Hari ini; Tomorrow: Besok; Bring: Membawa ke tempat yang dituju; Meet: Bertemu; Message: Pesan yang menyampaikan informasi atau permintaan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('759fca3a-c79f-500d-ac47-66701019572a','620ca8d1-025d-5ecc-80e1-727f5c59216d','Descriptions of people and places','belajar-bahasa-inggris-kelas-4-unit-1',4,'B','Bab 1','dasar','draft',12,'{"summary":"Descriptions of people and places. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan descriptions of people and places dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Inggris: English for Nusantara Kids Kelas IV","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-inggris-english-for-nusantara-kids-untuk-sd-mi-kelas-iv","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan descriptions of people and places dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar descriptions of people and places. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. There is …. Ungkapan menyatakan adanya satu benda. Contoh: There is a tree berarti ada sebuah pohon"},{"type":"text","body":"2. There are …. Ungkapan menyatakan adanya lebih dari satu benda. Contoh: There are two chairs berarti ada dua kursi"},{"type":"text","body":"3. Clean. Bersih. Contoh: A clean room adalah ruang bersih"},{"type":"text","body":"4. Quiet. Tenang atau tidak bising. Contoh: A quiet library menggambarkan perpustakaan yang tidak bising"},{"type":"text","body":"5. Near. Dekat dengan. Contoh: The bag is near the chair menyatakan posisi tas"},{"type":"text","body":"Contoh dan penalaran: There is a tree berarti ada sebuah pohon Kita mengenal there is … sebagai ungkapan menyatakan adanya satu benda. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Deskripsikan tempat rekaan dengan tiga kalimat. Pilih kata berdasarkan pengamatan atau gambar, bukan tebakan."},{"type":"text","body":"Rangkuman: There is …: Ungkapan menyatakan adanya satu benda; There are …: Ungkapan menyatakan adanya lebih dari satu benda; Clean: Bersih; Quiet: Tenang atau tidak bising; Near: Dekat dengan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('890f80fa-8d4e-59ad-bc2c-cdbad240d6c0','620ca8d1-025d-5ecc-80e1-727f5c59216d','Daily routines','belajar-bahasa-inggris-kelas-4-unit-2',4,'B','Bab 2','dasar','draft',12,'{"summary":"Daily routines. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan daily routines dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Inggris: English for Nusantara Kids Kelas IV","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-inggris-english-for-nusantara-kids-untuk-sd-mi-kelas-iv","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan daily routines dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar daily routines. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Every day. Setiap hari. Contoh: I read every day menyebut kebiasaan harian"},{"type":"text","body":"2. In the morning. Pada pagi hari. Contoh: I walk in the morning menyebut waktu berjalan"},{"type":"text","body":"3. She reads. Ia perempuan membaca dalam pola simple present. Contoh: She reads books menyatakan kebiasaan membaca"},{"type":"text","body":"4. He plays. Ia laki-laki bermain dalam pola simple present. Contoh: He plays after school menyebut kebiasaan tokoh"},{"type":"text","body":"5. I usually …. Ungkapan menyatakan sesuatu yang biasanya dilakukan. Contoh: I usually read at home berarti aku biasanya membaca di rumah"},{"type":"text","body":"Contoh dan penalaran: I read every day menyebut kebiasaan harian Kita mengenal every day sebagai setiap hari. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Gunakan tokoh rekaan untuk menulis dua kebiasaan. Bandingkan I read dengan She reads sebagai pola, bukan aturan tanpa konteks."},{"type":"text","body":"Rangkuman: Every day: Setiap hari; In the morning: Pada pagi hari; She reads: Ia perempuan membaca dalam pola simple present; He plays: Ia laki-laki bermain dalam pola simple present; I usually …: Ungkapan menyatakan sesuatu yang biasanya dilakukan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('0c9b6334-eb57-5934-9e84-141205339305','620ca8d1-025d-5ecc-80e1-727f5c59216d','Time expressions','belajar-bahasa-inggris-kelas-4-unit-3',4,'B','Bab 3','dasar','draft',12,'{"summary":"Time expressions. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan time expressions dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Inggris: English for Nusantara Kids Kelas IV","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-inggris-english-for-nusantara-kids-untuk-sd-mi-kelas-iv","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan time expressions dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar time expressions. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. At seven o’clock. Pada pukul tujuh tepat. Contoh: We meet at seven o’clock menyebut jam pertemuan"},{"type":"text","body":"2. On Monday. Pada hari Senin. Contoh: We read on Monday menyebut hari kegiatan"},{"type":"text","body":"3. In the morning. Pada pagi hari. Contoh: We play in the morning menyebut bagian hari"},{"type":"text","body":"4. After school. Setelah sekolah. Contoh: I read after school menyebut urutan waktu"},{"type":"text","body":"5. Before lunch. Sebelum makan siang. Contoh: We wash our hands before lunch menyebut kegiatan lebih dahulu"},{"type":"text","body":"Contoh dan penalaran: We meet at seven o’clock menyebut jam pertemuan Kita mengenal at seven o’clock sebagai pada pukul tujuh tepat. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Cocokkan jadwal rekaan dengan ungkapan waktu. Tidak perlu mengungkap jadwal pribadi anak."},{"type":"text","body":"Rangkuman: At seven o’clock: Pada pukul tujuh tepat; On Monday: Pada hari Senin; In the morning: Pada pagi hari; After school: Setelah sekolah; Before lunch: Sebelum makan siang."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('e1270193-4221-5aee-8984-006114f7830c','620ca8d1-025d-5ecc-80e1-727f5c59216d','Food and preferences','belajar-bahasa-inggris-kelas-4-unit-4',4,'B','Bab 4','sedang','draft',12,'{"summary":"Food and preferences. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan food and preferences dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Inggris: English for Nusantara Kids Kelas IV","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-inggris-english-for-nusantara-kids-untuk-sd-mi-kelas-iv","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan food and preferences dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar food and preferences. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Hungry. Lapar. Contoh: I am hungry menyatakan rasa lapar"},{"type":"text","body":"2. Thirsty. Haus. Contoh: I am thirsty menyatakan rasa haus"},{"type":"text","body":"3. Rice. Nasi atau beras sesuai konteks. Contoh: I eat rice berarti aku makan nasi"},{"type":"text","body":"4. Water. Air. Contoh: I drink water berarti aku minum air"},{"type":"text","body":"5. I would like …. Ungkapan menyampaikan keinginan dengan sopan. Contoh: I would like some water meminta air dengan sopan"},{"type":"text","body":"Contoh dan penalaran: I am hungry menyatakan rasa lapar Kita mengenal hungry sebagai lapar. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat percakapan memilih makanan dari gambar. Hargai kebutuhan, kebiasaan, dan pantangan tiap orang tanpa meminta penjelasan pribadi."},{"type":"text","body":"Rangkuman: Hungry: Lapar; Thirsty: Haus; Rice: Nasi atau beras sesuai konteks; Water: Air; I would like …: Ungkapan menyampaikan keinginan dengan sopan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('6fbca8de-4bbe-566e-a81f-9cec8fa75ac3','620ca8d1-025d-5ecc-80e1-727f5c59216d','Simple questions and answers','belajar-bahasa-inggris-kelas-4-unit-5',4,'B','Bab 5','sedang','draft',12,'{"summary":"Simple questions and answers. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan simple questions and answers dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Inggris: English for Nusantara Kids Kelas IV","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-inggris-english-for-nusantara-kids-untuk-sd-mi-kelas-iv","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan simple questions and answers dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar simple questions and answers. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. What …?. Pertanyaan tentang benda, kegiatan, atau suatu hal. Contoh: What is this menanyakan benda yang ditunjuk"},{"type":"text","body":"2. Who …?. Pertanyaan tentang orang. Contoh: Who is reading menanyakan siapa yang membaca"},{"type":"text","body":"3. Where …?. Pertanyaan tentang tempat. Contoh: Where is the book menanyakan letak buku"},{"type":"text","body":"4. When …?. Pertanyaan tentang waktu. Contoh: When do we meet menanyakan waktu pertemuan"},{"type":"text","body":"5. How many …?. Pertanyaan tentang banyak benda yang dapat dihitung. Contoh: How many books menanyakan jumlah buku"},{"type":"text","body":"Contoh dan penalaran: What is this menanyakan benda yang ditunjuk Kita mengenal what …? sebagai pertanyaan tentang benda, kegiatan, atau suatu hal. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Susun pertanyaan tentang gambar kelas lalu jawab sesuai informasi yang terlihat."},{"type":"text","body":"Rangkuman: What …?: Pertanyaan tentang benda, kegiatan, atau suatu hal; Who …?: Pertanyaan tentang orang; Where …?: Pertanyaan tentang tempat; When …?: Pertanyaan tentang waktu; How many …?: Pertanyaan tentang banyak benda yang dapat dihitung."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('4aee9849-5be3-5651-a0db-78bb51f17287','620ca8d1-025d-5ecc-80e1-727f5c59216d','Short texts with pictures','belajar-bahasa-inggris-kelas-4-unit-6',4,'B','Bab 6','sedang','draft',12,'{"summary":"Short texts with pictures. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan short texts with pictures dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Inggris: English for Nusantara Kids Kelas IV","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-inggris-english-for-nusantara-kids-untuk-sd-mi-kelas-iv","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan short texts with pictures dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar short texts with pictures. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Title. Judul bacaan. Contoh: A title membantu mengenali topik"},{"type":"text","body":"2. Picture. Gambar. Contoh: A picture dapat membantu memahami benda dalam bacaan"},{"type":"text","body":"3. Main idea. Gagasan utama. Contoh: The main idea adalah pokok yang dibahas"},{"type":"text","body":"4. Detail. Rincian informasi. Contoh: Jumlah benda merupakan detail dalam teks"},{"type":"text","body":"5. Evidence. Bukti yang mendukung jawaban. Contoh: A sentence in the text dapat menjadi evidence untuk jawaban"},{"type":"text","body":"Contoh dan penalaran: A title membantu mengenali topik Kita mengenal title sebagai judul bacaan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Baca teks dan gambar yang sama. Tulis informasi yang didukung teks, gambar, atau keduanya; jangan menganggap gambar selalu memuat semua informasi."},{"type":"text","body":"Rangkuman: Title: Judul bacaan; Picture: Gambar; Main idea: Gagasan utama; Detail: Rincian informasi; Evidence: Bukti yang mendukung jawaban."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('884fe324-d7c5-5407-9dc1-9ccc3c1b3341','620ca8d1-025d-5ecc-80e1-727f5c59216d','Describing experiences','belajar-bahasa-inggris-kelas-5-unit-1',5,'C','Bab 1','dasar','draft',12,'{"summary":"Describing experiences. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan describing experiences dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Inggris: English for Nusantara Kids Kelas V","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-inggris-english-for-nusantara-kids-untuk-sd-mi-kelas-v","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan describing experiences dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar describing experiences. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Yesterday. Kemarin. Contoh: Yesterday, I played menyatakan kegiatan sehari sebelumnya"},{"type":"text","body":"2. Last week. Minggu lalu. Contoh: Last week, we visited a park menyebut waktu lampau"},{"type":"text","body":"3. Visited. Bentuk lampau dari visit yang berarti mengunjungi. Contoh: We visited a library berarti kami mengunjungi perpustakaan"},{"type":"text","body":"4. Played. Bentuk lampau dari play yang berarti bermain. Contoh: They played a game berarti mereka bermain permainan"},{"type":"text","body":"5. Was. Bentuk lampau be untuk I, he, she, atau it. Contoh: It was fun menyatakan kegiatan itu menyenangkan pada masa lampau"},{"type":"text","body":"Contoh dan penalaran: Yesterday, I played menyatakan kegiatan sehari sebelumnya Kita mengenal yesterday sebagai kemarin. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Ceritakan pengalaman tokoh rekaan dengan penanda waktu. Bedakan waktu kejadian dari waktu kamu menceritakannya."},{"type":"text","body":"Rangkuman: Yesterday: Kemarin; Last week: Minggu lalu; Visited: Bentuk lampau dari visit yang berarti mengunjungi; Played: Bentuk lampau dari play yang berarti bermain; Was: Bentuk lampau be untuk I, he, she, atau it."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('dd342445-f404-537f-ab15-c7456f80f908','620ca8d1-025d-5ecc-80e1-727f5c59216d','Routines and activities','belajar-bahasa-inggris-kelas-5-unit-2',5,'C','Bab 2','dasar','draft',12,'{"summary":"Routines and activities. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan routines and activities dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Inggris: English for Nusantara Kids Kelas V","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-inggris-english-for-nusantara-kids-untuk-sd-mi-kelas-v","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan routines and activities dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar routines and activities. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Always. Selalu. Contoh: I always check my work berarti aku selalu memeriksa pekerjaanku"},{"type":"text","body":"2. Usually. Biasanya. Contoh: I usually read at home menyatakan kebiasaan yang umum"},{"type":"text","body":"3. Sometimes. Kadang-kadang. Contoh: I sometimes draw menyatakan kegiatan yang sesekali terjadi"},{"type":"text","body":"4. Never. Tidak pernah. Contoh: I never open unknown links menyatakan kegiatan yang tidak dilakukan"},{"type":"text","body":"5. Routine. Kegiatan yang dilakukan secara teratur. Contoh: A morning routine berisi kebiasaan pagi"},{"type":"text","body":"Contoh dan penalaran: I always check my work berarti aku selalu memeriksa pekerjaanku Kita mengenal always sebagai selalu. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat jadwal tokoh dan jelaskan kebiasaan memakai always, usually, atau sometimes secara sesuai."},{"type":"text","body":"Rangkuman: Always: Selalu; Usually: Biasanya; Sometimes: Kadang-kadang; Never: Tidak pernah; Routine: Kegiatan yang dilakukan secara teratur."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('b0596baf-f8c4-5d0a-a470-68d22f043765','620ca8d1-025d-5ecc-80e1-727f5c59216d','Places and directions','belajar-bahasa-inggris-kelas-5-unit-3',5,'C','Bab 3','dasar','draft',12,'{"summary":"Places and directions. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan places and directions dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Inggris: English for Nusantara Kids Kelas V","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-inggris-english-for-nusantara-kids-untuk-sd-mi-kelas-v","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan places and directions dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar places and directions. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Turn left. Belok kiri. Contoh: Turn left at the door meminta berbelok ke kiri"},{"type":"text","body":"2. Turn right. Belok kanan. Contoh: Turn right at the corner meminta berbelok ke kanan"},{"type":"text","body":"3. Go straight. Jalan lurus. Contoh: Go straight meminta terus maju tanpa berbelok"},{"type":"text","body":"4. Next to. Di sebelah. Contoh: The library is next to the classroom menjelaskan letak bersebelahan"},{"type":"text","body":"5. Opposite. Di seberang atau berhadapan dengan. Contoh: The gate is opposite the park menyatakan posisi berhadapan"},{"type":"text","body":"Contoh dan penalaran: Turn left at the door meminta berbelok ke kiri Kita mengenal turn left sebagai belok kiri. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Gunakan denah rekaan. Berikan petunjuk singkat yang dapat diuji teman tanpa membagikan lokasi pribadi."},{"type":"text","body":"Rangkuman: Turn left: Belok kiri; Turn right: Belok kanan; Go straight: Jalan lurus; Next to: Di sebelah; Opposite: Di seberang atau berhadapan dengan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('f548571f-60d7-5a81-9b4e-cfd7f69fa9cc','620ca8d1-025d-5ecc-80e1-727f5c59216d','Comparisons in familiar contexts','belajar-bahasa-inggris-kelas-5-unit-4',5,'C','Bab 4','sedang','draft',12,'{"summary":"Comparisons in familiar contexts. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan comparisons in familiar contexts dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Inggris: English for Nusantara Kids Kelas V","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-inggris-english-for-nusantara-kids-untuk-sd-mi-kelas-v","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan comparisons in familiar contexts dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar comparisons in familiar contexts. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Bigger than. Lebih besar daripada. Contoh: This box is bigger than that box membandingkan ukuran kotak"},{"type":"text","body":"2. Smaller than. Lebih kecil daripada. Contoh: This cup is smaller than that cup membandingkan ukuran cangkir"},{"type":"text","body":"3. Longer than. Lebih panjang daripada. Contoh: This ribbon is longer than that ribbon membandingkan panjang"},{"type":"text","body":"4. Shorter than. Lebih pendek daripada. Contoh: This pencil is shorter than that pencil membandingkan panjang pensil"},{"type":"text","body":"5. The same as. Sama dengan dalam ciri yang dibandingkan. Contoh: This colour is the same as that colour menyatakan kesamaan warna"},{"type":"text","body":"Contoh dan penalaran: This box is bigger than that box membandingkan ukuran kotak Kita mengenal bigger than sebagai lebih besar daripada. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Bandingkan dua benda dengan acuan yang jelas. Jangan menggunakan perbandingan untuk merendahkan orang."},{"type":"text","body":"Rangkuman: Bigger than: Lebih besar daripada; Smaller than: Lebih kecil daripada; Longer than: Lebih panjang daripada; Shorter than: Lebih pendek daripada; The same as: Sama dengan dalam ciri yang dibandingkan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('6d623832-3199-5ac2-b48b-86ead8d28c00','620ca8d1-025d-5ecc-80e1-727f5c59216d','Reading short informative texts','belajar-bahasa-inggris-kelas-5-unit-5',5,'C','Bab 5','sedang','draft',12,'{"summary":"Reading short informative texts. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan reading short informative texts dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Inggris: English for Nusantara Kids Kelas V","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-inggris-english-for-nusantara-kids-untuk-sd-mi-kelas-v","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan reading short informative texts dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar reading short informative texts. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Topic. Hal yang dibahas dalam teks. Contoh: A text about birds mempunyai topic burung"},{"type":"text","body":"2. Main idea. Pesan atau gagasan utama yang dikembangkan. Contoh: The main idea merangkum pokok bacaan"},{"type":"text","body":"3. Supporting detail. Rincian yang menjelaskan gagasan utama. Contoh: Contoh makanan burung dapat mendukung pembahasan kebutuhannya"},{"type":"text","body":"4. Fact. Pernyataan yang dapat diperiksa kebenarannya. Contoh: Jumlah kaki hewan dapat diperiksa sebagai fact"},{"type":"text","body":"5. Summary. Penyajian singkat isi utama bacaan. Contoh: A summary memadatkan informasi tanpa menambah cerita baru"},{"type":"text","body":"Contoh dan penalaran: A text about birds mempunyai topic burung Kita mengenal topic sebagai hal yang dibahas dalam teks. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Baca teks informatif pendek tentang hewan dari sumber pendamping. Cari judul, gagasan utama, dan bukti jawaban."},{"type":"text","body":"Rangkuman: Topic: Hal yang dibahas dalam teks; Main idea: Pesan atau gagasan utama yang dikembangkan; Supporting detail: Rincian yang menjelaskan gagasan utama; Fact: Pernyataan yang dapat diperiksa kebenarannya; Summary: Penyajian singkat isi utama bacaan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('8d3ca137-daaa-58b5-9986-6a5ba36ac4db','620ca8d1-025d-5ecc-80e1-727f5c59216d','Writing simple connected sentences','belajar-bahasa-inggris-kelas-5-unit-6',5,'C','Bab 6','sedang','draft',12,'{"summary":"Writing simple connected sentences. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan writing simple connected sentences dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Bahasa Inggris: English for Nusantara Kids Kelas V","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-inggris-english-for-nusantara-kids-untuk-sd-mi-kelas-v","audience":"student","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan writing simple connected sentences dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar writing simple connected sentences. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. And. Penghubung untuk menambahkan informasi. Contoh: I read and draw menggabungkan dua kegiatan"},{"type":"text","body":"2. But. Penghubung untuk menyatakan pertentangan. Contoh: I like the game, but I am tired menunjukkan dua keadaan berbeda"},{"type":"text","body":"3. Because. Penghubung untuk menyatakan alasan. Contoh: I rest because I am tired menjelaskan alasan beristirahat"},{"type":"text","body":"4. Then. Penanda langkah atau kejadian berikutnya. Contoh: I open the book, then I read menyatakan urutan"},{"type":"text","body":"5. Paragraph. Kelompok kalimat yang membahas satu gagasan. Contoh: A paragraph about a garden menghubungkan kalimat tentang taman"},{"type":"text","body":"Contoh dan penalaran: I read and draw menggabungkan dua kegiatan Kita mengenal and sebagai penghubung untuk menambahkan informasi. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Tulis tiga kalimat yang saling berkaitan tentang tokoh rekaan. Gunakan penghubung sesuai hubungan maknanya."},{"type":"text","body":"Rangkuman: And: Penghubung untuk menambahkan informasi; But: Penghubung untuk menyatakan pertentangan; Because: Penghubung untuk menyatakan alasan; Then: Penanda langkah atau kejadian berikutnya; Paragraph: Kelompok kalimat yang membahas satu gagasan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('146ccb46-f7eb-5863-bee1-01378042fc61','620ca8d1-025d-5ecc-80e1-727f5c59216d','Talking about past activities','belajar-bahasa-inggris-kelas-6-unit-1',6,'C','Bab 1','dasar','draft',12,'{"summary":"Talking about past activities. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan talking about past activities dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Bahasa Inggris: English for Nusantara Kids Kelas VI","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-bahasa-inggris-english-for-nusantara-kids-untuk-sd-mi-kelas-vi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan talking about past activities dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar talking about past activities. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Went. Bentuk lampau dari go yang berarti pergi. Contoh: She went to the library berarti ia pergi ke perpustakaan"},{"type":"text","body":"2. Saw. Bentuk lampau dari see yang berarti melihat. Contoh: They saw a bird berarti mereka melihat seekor burung"},{"type":"text","body":"3. Made. Bentuk lampau dari make yang berarti membuat. Contoh: We made a poster berarti kami membuat poster"},{"type":"text","body":"4. Did not …. Pola menyangkal kegiatan lampau diikuti kata kerja dasar. Contoh: I did not play berarti aku tidak bermain"},{"type":"text","body":"5. Did you …?. Pola pertanyaan kegiatan lampau diikuti kata kerja dasar. Contoh: Did you read menanyakan apakah kamu membaca pada waktu lampau"},{"type":"text","body":"Contoh dan penalaran: She went to the library berarti ia pergi ke perpustakaan Kita mengenal went sebagai bentuk lampau dari go yang berarti pergi. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Ceritakan tiga kegiatan lampau tokoh rekaan. Periksa penanda waktu dan bentuk kata kerjanya bersama pendamping."},{"type":"text","body":"Rangkuman: Went: Bentuk lampau dari go yang berarti pergi; Saw: Bentuk lampau dari see yang berarti melihat; Made: Bentuk lampau dari make yang berarti membuat; Did not …: Pola menyangkal kegiatan lampau diikuti kata kerja dasar; Did you …?: Pola pertanyaan kegiatan lampau diikuti kata kerja dasar."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('021af1e5-e8f3-5085-aa82-a069e6167de6','620ca8d1-025d-5ecc-80e1-727f5c59216d','Plans in familiar contexts','belajar-bahasa-inggris-kelas-6-unit-2',6,'C','Bab 2','dasar','draft',12,'{"summary":"Plans in familiar contexts. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan plans in familiar contexts dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Bahasa Inggris: English for Nusantara Kids Kelas VI","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-bahasa-inggris-english-for-nusantara-kids-untuk-sd-mi-kelas-vi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan plans in familiar contexts dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar plans in familiar contexts. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Be going to. Pola untuk menyampaikan rencana atau maksud dalam konteks tertentu. Contoh: I am going to read menyatakan rencana membaca"},{"type":"text","body":"2. Will. Kata bantu untuk antara lain menyampaikan keputusan atau perkiraan mendatang. Contoh: I will help menyampaikan kesediaan membantu"},{"type":"text","body":"3. Next week. Minggu depan. Contoh: Next week, we will meet menyebut waktu mendatang"},{"type":"text","body":"4. Plan. Rencana tentang hal yang ingin dilakukan. Contoh: A plan memuat kegiatan dan langkah yang dipikirkan"},{"type":"text","body":"5. Maybe. Mungkin. Contoh: Maybe we will draw menunjukkan hal yang belum pasti"},{"type":"text","body":"Contoh dan penalaran: I am going to read menyatakan rencana membaca Kita mengenal be going to sebagai pola untuk menyampaikan rencana atau maksud dalam konteks tertentu. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Tuliskan rencana rekaan akhir pekan. Jelaskan bahwa rencana dapat berubah dan bukan kepastian."},{"type":"text","body":"Rangkuman: Be going to: Pola untuk menyampaikan rencana atau maksud dalam konteks tertentu; Will: Kata bantu untuk antara lain menyampaikan keputusan atau perkiraan mendatang; Next week: Minggu depan; Plan: Rencana tentang hal yang ingin dilakukan; Maybe: Mungkin."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('4dce38c0-7bc2-5468-a7a3-095efee1d093','620ca8d1-025d-5ecc-80e1-727f5c59216d','Descriptions and comparisons','belajar-bahasa-inggris-kelas-6-unit-3',6,'C','Bab 3','dasar','draft',12,'{"summary":"Descriptions and comparisons. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan descriptions and comparisons dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Bahasa Inggris: English for Nusantara Kids Kelas VI","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-bahasa-inggris-english-for-nusantara-kids-untuk-sd-mi-kelas-vi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan descriptions and comparisons dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar descriptions and comparisons. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. More crowded than. Lebih ramai daripada. Contoh: The market is more crowded than the garden membandingkan keramaian"},{"type":"text","body":"2. Quieter than. Lebih tenang daripada. Contoh: This room is quieter than that room membandingkan kebisingan"},{"type":"text","body":"3. As tall as. Sama tinggi dengan. Contoh: This tree is as tall as that tree menyatakan tinggi yang sama"},{"type":"text","body":"4. Description. Uraian tentang ciri seseorang, benda, atau tempat. Contoh: A description menjelaskan sifat yang relevan"},{"type":"text","body":"5. Comparison. Penjelasan persamaan atau perbedaan menurut acuan tertentu. Contoh: A comparison of two boxes dapat membahas ukurannya"},{"type":"text","body":"Contoh dan penalaran: The market is more crowded than the garden membandingkan keramaian Kita mengenal more crowded than sebagai lebih ramai daripada. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Deskripsikan dan bandingkan dua tempat rekaan memakai informasi yang diberikan, bukan tebakan."},{"type":"text","body":"Rangkuman: More crowded than: Lebih ramai daripada; Quieter than: Lebih tenang daripada; As tall as: Sama tinggi dengan; Description: Uraian tentang ciri seseorang, benda, atau tempat; Comparison: Penjelasan persamaan atau perbedaan menurut acuan tertentu."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('73554ad1-8444-58f3-b44d-97f3e0e67188','620ca8d1-025d-5ecc-80e1-727f5c59216d','Giving simple instructions','belajar-bahasa-inggris-kelas-6-unit-4',6,'C','Bab 4','sedang','draft',12,'{"summary":"Giving simple instructions. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan giving simple instructions dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Bahasa Inggris: English for Nusantara Kids Kelas VI","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-bahasa-inggris-english-for-nusantara-kids-untuk-sd-mi-kelas-vi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan giving simple instructions dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar giving simple instructions. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. First. Pertama. Contoh: First, prepare the paper menyatakan langkah awal"},{"type":"text","body":"2. Next. Berikutnya. Contoh: Next, fold the paper menyatakan langkah sesudahnya"},{"type":"text","body":"3. Finally. Terakhir. Contoh: Finally, check your work menyatakan langkah penutup"},{"type":"text","body":"4. Instruction. Arahan tentang tindakan yang perlu dilakukan. Contoh: An instruction membantu pembaca menjalankan langkah"},{"type":"text","body":"5. Check. Periksa. Contoh: Check the result meminta memastikan hasil sesuai tujuan"},{"type":"text","body":"Contoh dan penalaran: First, prepare the paper menyatakan langkah awal Kita mengenal first sebagai pertama. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Tulis petunjuk membuat penanda buku dari kertas. Uji urutannya dengan alat aman dan pendamping."},{"type":"text","body":"Rangkuman: First: Pertama; Next: Berikutnya; Finally: Terakhir; Instruction: Arahan tentang tindakan yang perlu dilakukan; Check: Periksa."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('7399f0df-69b4-51a0-a755-26e76a42c030','620ca8d1-025d-5ecc-80e1-727f5c59216d','Understanding short narratives','belajar-bahasa-inggris-kelas-6-unit-5',6,'C','Bab 5','sedang','draft',12,'{"summary":"Understanding short narratives. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan understanding short narratives dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Bahasa Inggris: English for Nusantara Kids Kelas VI","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-bahasa-inggris-english-for-nusantara-kids-untuk-sd-mi-kelas-vi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan understanding short narratives dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar understanding short narratives. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Character. Tokoh dalam cerita. Contoh: The character dapat berupa anak dalam kisah"},{"type":"text","body":"2. Setting. Latar tempat, waktu, atau suasana. Contoh: The setting dapat berupa taman pada pagi hari"},{"type":"text","body":"3. Problem. Masalah yang dihadapi tokoh. Contoh: A missing book menjadi problem dalam cerita"},{"type":"text","body":"4. Action. Tindakan yang dilakukan tokoh. Contoh: The action dapat berupa mencari dan meminta bantuan"},{"type":"text","body":"5. Resolution. Penyelesaian atau keadaan akhir masalah. Contoh: The resolution menjelaskan bagaimana masalah berakhir"},{"type":"text","body":"Contoh dan penalaran: The character dapat berupa anak dalam kisah Kita mengenal character sebagai tokoh dalam cerita. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Baca narasi pendek bersama pendamping. Ceritakan tokoh, masalah, tindakan, dan penyelesaiannya dengan bukti teks."},{"type":"text","body":"Rangkuman: Character: Tokoh dalam cerita; Setting: Latar tempat, waktu, atau suasana; Problem: Masalah yang dihadapi tokoh; Action: Tindakan yang dilakukan tokoh; Resolution: Penyelesaian atau keadaan akhir masalah."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('444b6b93-669c-5525-be15-f4a5d201c690','620ca8d1-025d-5ecc-80e1-727f5c59216d','Writing and presenting short texts','belajar-bahasa-inggris-kelas-6-unit-6',6,'C','Bab 6','sedang','draft',12,'{"summary":"Writing and presenting short texts. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan writing and presenting short texts dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Bahasa Inggris: English for Nusantara Kids Kelas VI","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-bahasa-inggris-english-for-nusantara-kids-untuk-sd-mi-kelas-vi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pembagian per kelas merupakan usulan aplikasi; sesuaikan ATP sekolah.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan writing and presenting short texts dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar writing and presenting short texts. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Audience. Pendengar atau pembaca yang dituju. Contoh: The audience membantu menentukan pilihan kata"},{"type":"text","body":"2. Purpose. Tujuan komunikasi. Contoh: The purpose dapat berupa menjelaskan suatu cara"},{"type":"text","body":"3. Draft. Tulisan awal yang masih dapat diperbaiki. Contoh: A draft disusun sebelum hasil akhir"},{"type":"text","body":"4. Feedback. Tanggapan yang membantu perbaikan. Contoh: Feedback menunjukkan bagian yang belum jelas"},{"type":"text","body":"5. Revise. Mengubah isi atau susunan agar lebih jelas. Contoh: Revise the paragraph meminta memperbaiki paragraf"},{"type":"text","body":"Contoh dan penalaran: The audience membantu menentukan pilihan kata Kita mengenal audience sebagai pendengar atau pembaca yang dituju. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Tulis satu paragraf untuk menjelaskan proyek rekaan. Presentasikan singkat, lalu gunakan umpan balik untuk memperjelas pesan."},{"type":"text","body":"Rangkuman: Audience: Pendengar atau pembaca yang dituju; Purpose: Tujuan komunikasi; Draft: Tulisan awal yang masih dapat diperbaiki; Feedback: Tanggapan yang membantu perbaikan; Revise: Mengubah isi atau susunan agar lebih jelas."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('a702ba2d-d40d-5455-811c-f65192907614','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Garis dan bentuk','belajar-seni-budaya-kelas-1-unit-1',1,'A','Bab 1','dasar','draft',8,'{"summary":"Garis dan bentuk. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan garis dan bentuk dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas I (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sd-mi-kelas-i-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."},{"title":"Panduan Guru Seni Tari Kelas I (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-tari-untuk-sd-mi-kelas-i-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan garis dan bentuk dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar garis dan bentuk. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Garis. Jejak yang memanjang dan dapat berbeda arah atau sifat. Contoh: Goresan pensil dapat lurus, melengkung, atau berkelok"},{"type":"text","body":"2. Bentuk. Rupa bidang atau benda yang dapat dikenali. Contoh: Potongan kertas dapat berbentuk lingkaran"},{"type":"text","body":"3. Titik. Unsur rupa kecil yang dapat disusun menjadi pola. Contoh: Beberapa titik disusun membentuk jejak"},{"type":"text","body":"4. Arah. Orientasi gerak atau letak unsur rupa. Contoh: Garis dapat menuju atas, samping, atau diagonal"},{"type":"text","body":"5. Pengamatan visual. Memperhatikan ciri yang terlihat sebelum menggambar. Contoh: Anak mengamati bentuk daun tanpa memetiknya"},{"type":"text","body":"Contoh dan penalaran: Goresan pensil dapat lurus, melengkung, atau berkelok Kita mengenal garis sebagai jejak yang memanjang dan dapat berbeda arah atau sifat. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Cari tiga garis dan bentuk dari benda sekitar. Gambarkan tanpa harus sama persis dengan karya teman."},{"type":"text","body":"Rangkuman: Garis: Jejak yang memanjang dan dapat berbeda arah atau sifat; Bentuk: Rupa bidang atau benda yang dapat dikenali; Titik: Unsur rupa kecil yang dapat disusun menjadi pola; Arah: Orientasi gerak atau letak unsur rupa; Pengamatan visual: Memperhatikan ciri yang terlihat sebelum menggambar."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('e447663f-9db0-5171-a9a7-15d8c2a47e4b','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Warna dan bahan aman','belajar-seni-budaya-kelas-1-unit-2',1,'A','Bab 2','dasar','draft',8,'{"summary":"Warna dan bahan aman. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan warna dan bahan aman dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas I (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sd-mi-kelas-i-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."},{"title":"Panduan Guru Seni Tari Kelas I (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-tari-untuk-sd-mi-kelas-i-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan warna dan bahan aman dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar warna dan bahan aman. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Warna. Unsur rupa yang berkaitan dengan pengalaman melihat cahaya. Contoh: Daun tampak memiliki berbagai warna hijau"},{"type":"text","body":"2. Campuran warna. Hasil menggabungkan bahan warna yang dapat berbeda menurut mediumnya. Contoh: Cat merah dan kuning dapat menghasilkan jingga"},{"type":"text","body":"3. Bahan aman. Bahan yang sesuai usia dan digunakan menurut petunjuk pendamping. Contoh: Krayon yang diperuntukkan anak dipakai pada kertas"},{"type":"text","body":"4. Alat berkarya. Perlengkapan yang digunakan untuk membuat karya. Contoh: Kuas digunakan untuk mengoleskan cat"},{"type":"text","body":"5. Perawatan alat. Tindakan menjaga alat tetap layak dan ruang tetap aman. Contoh: Kuas dibersihkan dan alat disimpan setelah digunakan"},{"type":"text","body":"Contoh dan penalaran: Daun tampak memiliki berbagai warna hijau Kita mengenal warna sebagai unsur rupa yang berkaitan dengan pengalaman melihat cahaya. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Coba dua warna pada kertas sisa dengan bahan aman. Jangan mencampur bahan yang tidak diketahui."},{"type":"text","body":"Rangkuman: Warna: Unsur rupa yang berkaitan dengan pengalaman melihat cahaya; Campuran warna: Hasil menggabungkan bahan warna yang dapat berbeda menurut mediumnya; Bahan aman: Bahan yang sesuai usia dan digunakan menurut petunjuk pendamping; Alat berkarya: Perlengkapan yang digunakan untuk membuat karya; Perawatan alat: Tindakan menjaga alat tetap layak dan ruang tetap aman."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('7b1d1b97-3759-5d63-ad99-830f0c2af5b0','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Menggambar pengalaman','belajar-seni-budaya-kelas-1-unit-3',1,'A','Bab 3','dasar','draft',8,'{"summary":"Menggambar pengalaman. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan menggambar pengalaman dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas I (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sd-mi-kelas-i-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."},{"title":"Panduan Guru Seni Tari Kelas I (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-tari-untuk-sd-mi-kelas-i-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan menggambar pengalaman dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar menggambar pengalaman. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Objek gambar. Hal yang dipilih untuk diamati atau digambarkan. Contoh: Anak memilih sepatu sebagai objek"},{"type":"text","body":"2. Detail. Bagian kecil yang membantu memperjelas gambaran. Contoh: Tali dan lubang sepatu diamati bentuknya"},{"type":"text","body":"3. Sketsa. Gambar awal untuk merencanakan bentuk atau susunan. Contoh: Goresan ringan membantu mencoba letak objek"},{"type":"text","body":"4. Ekspresi. Cara menyampaikan pengalaman atau perasaan melalui karya. Contoh: Anak memilih garis dan warna untuk menyampaikan suasana"},{"type":"text","body":"5. Pilihan pribadi. Keputusan pencipta yang membuat karya mempunyai ciri sendiri. Contoh: Dua anak boleh menggambar pengalaman sama dengan cara berbeda"},{"type":"text","body":"Contoh dan penalaran: Anak memilih sepatu sebagai objek Kita mengenal objek gambar sebagai hal yang dipilih untuk diamati atau digambarkan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Gambarkan satu pengalaman yang nyaman untuk diceritakan. Pilih warna dan bentuk menurut maksudmu."},{"type":"text","body":"Rangkuman: Objek gambar: Hal yang dipilih untuk diamati atau digambarkan; Detail: Bagian kecil yang membantu memperjelas gambaran; Sketsa: Gambar awal untuk merencanakan bentuk atau susunan; Ekspresi: Cara menyampaikan pengalaman atau perasaan melalui karya; Pilihan pribadi: Keputusan pencipta yang membuat karya mempunyai ciri sendiri."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('0486f3ab-1295-5f2f-809e-ccaec01ed029','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Bunyi dan irama sederhana','belajar-seni-budaya-kelas-1-unit-4',1,'A','Bab 4','sedang','draft',8,'{"summary":"Bunyi dan irama sederhana. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan bunyi dan irama sederhana dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas I (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sd-mi-kelas-i-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."},{"title":"Panduan Guru Seni Tari Kelas I (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-tari-untuk-sd-mi-kelas-i-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan bunyi dan irama sederhana dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar bunyi dan irama sederhana. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Bunyi. Getaran yang dapat didengar melalui medium. Contoh: Tepukan tangan menghasilkan bunyi"},{"type":"text","body":"2. Ketukan. Denyut teratur yang menjadi acuan waktu musik. Contoh: Anak menepuk dengan jarak waktu yang tetap"},{"type":"text","body":"3. Irama. Pola panjang-pendek dan penempatan bunyi terhadap waktu. Contoh: Tepuk singkat dan panjang disusun menjadi pola"},{"type":"text","body":"4. Diam dalam musik. Bagian waktu tanpa bunyi yang disengaja. Contoh: Peserta berhenti satu ketukan sesuai pola"},{"type":"text","body":"5. Tempo. Cepat atau lambatnya acuan ketukan musik. Contoh: Pola yang sama dapat dilakukan perlahan atau lebih cepat"},{"type":"text","body":"Contoh dan penalaran: Tepukan tangan menghasilkan bunyi Kita mengenal bunyi sebagai getaran yang dapat didengar melalui medium. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat pola tepuk pendek dengan jeda. Gunakan volume wajar agar tidak mengganggu atau menyakiti telinga."},{"type":"text","body":"Rangkuman: Bunyi: Getaran yang dapat didengar melalui medium; Ketukan: Denyut teratur yang menjadi acuan waktu musik; Irama: Pola panjang-pendek dan penempatan bunyi terhadap waktu; Diam dalam musik: Bagian waktu tanpa bunyi yang disengaja; Tempo: Cepat atau lambatnya acuan ketukan musik."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('ffa4c648-c6cb-550f-9f66-a57f7ea0a2c6','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Gerak tubuh dan ruang','belajar-seni-budaya-kelas-1-unit-5',1,'A','Bab 5','sedang','draft',8,'{"summary":"Gerak tubuh dan ruang. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan gerak tubuh dan ruang dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas I (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sd-mi-kelas-i-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."},{"title":"Panduan Guru Seni Tari Kelas I (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-tari-untuk-sd-mi-kelas-i-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan gerak tubuh dan ruang dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar gerak tubuh dan ruang. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Gerak. Perubahan posisi tubuh atau bagian tubuh. Contoh: Tangan bergerak membentuk lengkungan"},{"type":"text","body":"2. Ruang gerak. Tempat dan arah yang dipakai tubuh ketika bergerak. Contoh: Anak memberi jarak aman dari temannya"},{"type":"text","body":"3. Tenaga. Kualitas penggunaan kekuatan dalam gerak. Contoh: Gerak dapat dilakukan ringan atau lebih tegas"},{"type":"text","body":"4. Waktu gerak. Hubungan durasi dan kecepatan gerakan. Contoh: Gerakan lambat membutuhkan waktu lebih panjang"},{"type":"text","body":"5. Kesadaran tubuh. Perhatian pada kemampuan dan keadaan tubuh sendiri. Contoh: Anak berhenti saat merasa gerak tidak nyaman"},{"type":"text","body":"Contoh dan penalaran: Tangan bergerak membentuk lengkungan Kita mengenal gerak sebagai perubahan posisi tubuh atau bagian tubuh. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Coba gerak kecil di tempat yang cukup luas bersama pendamping. Sesuaikan dengan kemampuan tubuhmu."},{"type":"text","body":"Rangkuman: Gerak: Perubahan posisi tubuh atau bagian tubuh; Ruang gerak: Tempat dan arah yang dipakai tubuh ketika bergerak; Tenaga: Kualitas penggunaan kekuatan dalam gerak; Waktu gerak: Hubungan durasi dan kecepatan gerakan; Kesadaran tubuh: Perhatian pada kemampuan dan keadaan tubuh sendiri."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('bacdb77d-a371-5f4d-8c5f-1418a594cc5b','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Bercerita melalui peran','belajar-seni-budaya-kelas-1-unit-6',1,'A','Bab 6','sedang','draft',8,'{"summary":"Bercerita melalui peran. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan bercerita melalui peran dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas I (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sd-mi-kelas-i-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."},{"title":"Panduan Guru Seni Tari Kelas I (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-tari-untuk-sd-mi-kelas-i-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan bercerita melalui peran dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar bercerita melalui peran. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Tokoh. Sosok yang diperankan dalam cerita atau pertunjukan. Contoh: Anak memerankan penjaga taman rekaan"},{"type":"text","body":"2. Ekspresi wajah. Perubahan raut untuk menyampaikan keadaan tokoh. Contoh: Tokoh tampak heran melalui raut wajahnya"},{"type":"text","body":"3. Gestur. Gerak tubuh yang membantu menyampaikan maksud. Contoh: Tokoh menunjuk arah untuk memberi petunjuk"},{"type":"text","body":"4. Dialog. Percakapan antartokoh. Contoh: Dua tokoh saling bertanya dan menjawab"},{"type":"text","body":"5. Imajinasi. Kemampuan membayangkan keadaan atau kemungkinan. Contoh: Kursi dibayangkan sebagai halte dalam permainan peran"},{"type":"text","body":"Contoh dan penalaran: Anak memerankan penjaga taman rekaan Kita mengenal tokoh sebagai sosok yang diperankan dalam cerita atau pertunjukan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Perankan tokoh rekaan yang meminta bantuan dengan sopan. Semua peserta boleh memilih tidak memerankan hal yang tidak nyaman."},{"type":"text","body":"Rangkuman: Tokoh: Sosok yang diperankan dalam cerita atau pertunjukan; Ekspresi wajah: Perubahan raut untuk menyampaikan keadaan tokoh; Gestur: Gerak tubuh yang membantu menyampaikan maksud; Dialog: Percakapan antartokoh; Imajinasi: Kemampuan membayangkan keadaan atau kemungkinan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('9944fc85-df03-5914-bf79-7968213df2cd','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Bentuk, warna, dan tekstur','belajar-seni-budaya-kelas-2-unit-1',2,'A','Bab 1','dasar','draft',8,'{"summary":"Bentuk, warna, dan tekstur. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan bentuk, warna, dan tekstur dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas II (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sd-mi-kelas-ii-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."},{"title":"Panduan Guru Seni Teater Kelas II (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-teater-untuk-sd-mi-kelas-ii-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan bentuk, warna, dan tekstur dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar bentuk, warna, dan tekstur. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Tekstur. Sifat permukaan yang dapat dirasakan atau digambarkan. Contoh: Permukaan kain dapat halus atau berumbai"},{"type":"text","body":"2. Kolase. Karya yang menyusun dan menempel potongan bahan pada bidang. Contoh: Potongan kertas bersih disusun menjadi taman"},{"type":"text","body":"3. Cetak sederhana. Membuat jejak bentuk dari permukaan yang diberi warna. Contoh: Cap aman pada kertas meninggalkan bentuk berulang"},{"type":"text","body":"4. Susunan. Cara menempatkan bagian-bagian dalam karya. Contoh: Potongan besar dan kecil disusun sebelum ditempel"},{"type":"text","body":"5. Percobaan bahan. Menguji kemungkinan bahan secara aman sebelum dipakai. Contoh: Anak mencoba sisa kertas pada bidang kecil"},{"type":"text","body":"Contoh dan penalaran: Permukaan kain dapat halus atau berumbai Kita mengenal tekstur sebagai sifat permukaan yang dapat dirasakan atau digambarkan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat gambar yang memakai dua tekstur dan beberapa bentuk. Gunakan bahan yang bersih serta aman."},{"type":"text","body":"Rangkuman: Tekstur: Sifat permukaan yang dapat dirasakan atau digambarkan; Kolase: Karya yang menyusun dan menempel potongan bahan pada bidang; Cetak sederhana: Membuat jejak bentuk dari permukaan yang diberi warna; Susunan: Cara menempatkan bagian-bagian dalam karya; Percobaan bahan: Menguji kemungkinan bahan secara aman sebelum dipakai."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('a90c0069-8e7a-5593-9a19-e77c5321bfa4','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Kolase dan cetak sederhana','belajar-seni-budaya-kelas-2-unit-2',2,'A','Bab 2','dasar','draft',8,'{"summary":"Kolase dan cetak sederhana. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan kolase dan cetak sederhana dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas II (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sd-mi-kelas-ii-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."},{"title":"Panduan Guru Seni Teater Kelas II (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-teater-untuk-sd-mi-kelas-ii-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan kolase dan cetak sederhana dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar kolase dan cetak sederhana. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Tekstur. Sifat permukaan yang dapat dirasakan atau digambarkan. Contoh: Permukaan kain dapat halus atau berumbai"},{"type":"text","body":"2. Kolase. Karya yang menyusun dan menempel potongan bahan pada bidang. Contoh: Potongan kertas bersih disusun menjadi taman"},{"type":"text","body":"3. Cetak sederhana. Membuat jejak bentuk dari permukaan yang diberi warna. Contoh: Cap aman pada kertas meninggalkan bentuk berulang"},{"type":"text","body":"4. Susunan. Cara menempatkan bagian-bagian dalam karya. Contoh: Potongan besar dan kecil disusun sebelum ditempel"},{"type":"text","body":"5. Percobaan bahan. Menguji kemungkinan bahan secara aman sebelum dipakai. Contoh: Anak mencoba sisa kertas pada bidang kecil"},{"type":"text","body":"Contoh dan penalaran: Permukaan kain dapat halus atau berumbai Kita mengenal tekstur sebagai sifat permukaan yang dapat dirasakan atau digambarkan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat kolase dari sisa kertas atau cap dengan alat aman. Susun bentuk sebelum direkatkan."},{"type":"text","body":"Rangkuman: Tekstur: Sifat permukaan yang dapat dirasakan atau digambarkan; Kolase: Karya yang menyusun dan menempel potongan bahan pada bidang; Cetak sederhana: Membuat jejak bentuk dari permukaan yang diberi warna; Susunan: Cara menempatkan bagian-bagian dalam karya; Percobaan bahan: Menguji kemungkinan bahan secara aman sebelum dipakai."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('45b64f9b-1d31-5be1-a618-36238614b3bc','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Mengamati karya teman','belajar-seni-budaya-kelas-2-unit-3',2,'A','Bab 3','dasar','draft',8,'{"summary":"Mengamati karya teman. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan mengamati karya teman dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas II (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sd-mi-kelas-ii-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."},{"title":"Panduan Guru Seni Teater Kelas II (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-teater-untuk-sd-mi-kelas-ii-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan mengamati karya teman dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar mengamati karya teman. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Apresiasi. Mengamati, memahami, dan menghargai karya. Contoh: Anak memperhatikan pilihan warna teman sebelum menanggapi"},{"type":"text","body":"2. Deskripsi karya. Penjelasan tentang hal yang benar-benar tampak atau terdengar. Contoh: Anak menyebut garis melengkung dalam gambar"},{"type":"text","body":"3. Tanggapan santun. Komentar yang membahas karya tanpa merendahkan penciptanya. Contoh: Anak mengatakan bagian yang menarik beserta alasannya"},{"type":"text","body":"4. Alasan penilaian. Penjelasan yang mendukung suatu pendapat tentang karya. Contoh: Komentar menyebut hubungan warna dengan suasana"},{"type":"text","body":"5. Perbedaan tafsir. Kemungkinan orang memahami karya dengan cara berbeda. Contoh: Dua penonton dapat mempunyai kesan berbeda terhadap gambar"},{"type":"text","body":"Contoh dan penalaran: Anak memperhatikan pilihan warna teman sebelum menanggapi Kita mengenal apresiasi sebagai mengamati, memahami, dan menghargai karya. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Amati karya teman. Sebut satu hal yang terlihat dan satu hal yang menarik beserta alasannya."},{"type":"text","body":"Rangkuman: Apresiasi: Mengamati, memahami, dan menghargai karya; Deskripsi karya: Penjelasan tentang hal yang benar-benar tampak atau terdengar; Tanggapan santun: Komentar yang membahas karya tanpa merendahkan penciptanya; Alasan penilaian: Penjelasan yang mendukung suatu pendapat tentang karya; Perbedaan tafsir: Kemungkinan orang memahami karya dengan cara berbeda."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('72e6dddf-ef75-5d9e-9601-4240ee70f5ec','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Pola irama','belajar-seni-budaya-kelas-2-unit-4',2,'A','Bab 4','sedang','draft',8,'{"summary":"Pola irama. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan pola irama dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas II (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sd-mi-kelas-ii-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."},{"title":"Panduan Guru Seni Teater Kelas II (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-teater-untuk-sd-mi-kelas-ii-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan pola irama dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar pola irama. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Bunyi. Getaran yang dapat didengar melalui medium. Contoh: Tepukan tangan menghasilkan bunyi"},{"type":"text","body":"2. Ketukan. Denyut teratur yang menjadi acuan waktu musik. Contoh: Anak menepuk dengan jarak waktu yang tetap"},{"type":"text","body":"3. Irama. Pola panjang-pendek dan penempatan bunyi terhadap waktu. Contoh: Tepuk singkat dan panjang disusun menjadi pola"},{"type":"text","body":"4. Diam dalam musik. Bagian waktu tanpa bunyi yang disengaja. Contoh: Peserta berhenti satu ketukan sesuai pola"},{"type":"text","body":"5. Tempo. Cepat atau lambatnya acuan ketukan musik. Contoh: Pola yang sama dapat dilakukan perlahan atau lebih cepat"},{"type":"text","body":"Contoh dan penalaran: Tepukan tangan menghasilkan bunyi Kita mengenal bunyi sebagai getaran yang dapat didengar melalui medium. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Tepuk pola dua ketukan dan empat ketukan. Tunjukkan bagian diam tanpa mempercepat ketukan."},{"type":"text","body":"Rangkuman: Bunyi: Getaran yang dapat didengar melalui medium; Ketukan: Denyut teratur yang menjadi acuan waktu musik; Irama: Pola panjang-pendek dan penempatan bunyi terhadap waktu; Diam dalam musik: Bagian waktu tanpa bunyi yang disengaja; Tempo: Cepat atau lambatnya acuan ketukan musik."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('74289229-2692-589c-a628-a0fe5da4622e','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Gerak mengikuti irama','belajar-seni-budaya-kelas-2-unit-5',2,'A','Bab 5','sedang','draft',8,'{"summary":"Gerak mengikuti irama. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan gerak mengikuti irama dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas II (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sd-mi-kelas-ii-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."},{"title":"Panduan Guru Seni Teater Kelas II (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-teater-untuk-sd-mi-kelas-ii-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan gerak mengikuti irama dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar gerak mengikuti irama. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Gerak. Perubahan posisi tubuh atau bagian tubuh. Contoh: Tangan bergerak membentuk lengkungan"},{"type":"text","body":"2. Ruang gerak. Tempat dan arah yang dipakai tubuh ketika bergerak. Contoh: Anak memberi jarak aman dari temannya"},{"type":"text","body":"3. Tenaga. Kualitas penggunaan kekuatan dalam gerak. Contoh: Gerak dapat dilakukan ringan atau lebih tegas"},{"type":"text","body":"4. Waktu gerak. Hubungan durasi dan kecepatan gerakan. Contoh: Gerakan lambat membutuhkan waktu lebih panjang"},{"type":"text","body":"5. Kesadaran tubuh. Perhatian pada kemampuan dan keadaan tubuh sendiri. Contoh: Anak berhenti saat merasa gerak tidak nyaman"},{"type":"text","body":"Contoh dan penalaran: Tangan bergerak membentuk lengkungan Kita mengenal gerak sebagai perubahan posisi tubuh atau bagian tubuh. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Hubungkan dua gerak sederhana dengan ketukan. Hindari gerak yang menyakitkan atau memaksa kelenturan."},{"type":"text","body":"Rangkuman: Gerak: Perubahan posisi tubuh atau bagian tubuh; Ruang gerak: Tempat dan arah yang dipakai tubuh ketika bergerak; Tenaga: Kualitas penggunaan kekuatan dalam gerak; Waktu gerak: Hubungan durasi dan kecepatan gerakan; Kesadaran tubuh: Perhatian pada kemampuan dan keadaan tubuh sendiri."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('4607adfe-9df0-5181-be89-3af7319b5c5c','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Ekspresi tokoh sederhana','belajar-seni-budaya-kelas-2-unit-6',2,'A','Bab 6','sedang','draft',8,'{"summary":"Ekspresi tokoh sederhana. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan ekspresi tokoh sederhana dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas II (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sd-mi-kelas-ii-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."},{"title":"Panduan Guru Seni Teater Kelas II (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-teater-untuk-sd-mi-kelas-ii-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan ekspresi tokoh sederhana dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar ekspresi tokoh sederhana. Gunakan benda atau gambar. Minta pendamping membacakan bagian yang belum kamu pahami. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Tokoh. Sosok yang diperankan dalam cerita atau pertunjukan. Contoh: Anak memerankan penjaga taman rekaan"},{"type":"text","body":"2. Ekspresi wajah. Perubahan raut untuk menyampaikan keadaan tokoh. Contoh: Tokoh tampak heran melalui raut wajahnya"},{"type":"text","body":"3. Gestur. Gerak tubuh yang membantu menyampaikan maksud. Contoh: Tokoh menunjuk arah untuk memberi petunjuk"},{"type":"text","body":"4. Dialog. Percakapan antartokoh. Contoh: Dua tokoh saling bertanya dan menjawab"},{"type":"text","body":"5. Imajinasi. Kemampuan membayangkan keadaan atau kemungkinan. Contoh: Kursi dibayangkan sebagai halte dalam permainan peran"},{"type":"text","body":"Contoh dan penalaran: Anak memerankan penjaga taman rekaan Kita mengenal tokoh sebagai sosok yang diperankan dalam cerita atau pertunjukan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Gunakan wajah dan gerak tangan untuk memerankan tokoh rekaan. Jangan menirukan identitas orang lain untuk mengejek."},{"type":"text","body":"Rangkuman: Tokoh: Sosok yang diperankan dalam cerita atau pertunjukan; Ekspresi wajah: Perubahan raut untuk menyampaikan keadaan tokoh; Gestur: Gerak tubuh yang membantu menyampaikan maksud; Dialog: Percakapan antartokoh; Imajinasi: Kemampuan membayangkan keadaan atau kemungkinan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('605bc3ba-8fac-5a44-8bc4-ab40eb56c5d9','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Unsur rupa dalam lingkungan','belajar-seni-budaya-kelas-3-unit-1',3,'B','Bab 1','dasar','draft',12,'{"summary":"Unsur rupa dalam lingkungan. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan unsur rupa dalam lingkungan dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas III (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sdmi-kelas-iii-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan unsur rupa dalam lingkungan dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar unsur rupa dalam lingkungan. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Garis. Jejak yang memanjang dan dapat berbeda arah atau sifat. Contoh: Goresan pensil dapat lurus, melengkung, atau berkelok"},{"type":"text","body":"2. Bentuk. Rupa bidang atau benda yang dapat dikenali. Contoh: Potongan kertas dapat berbentuk lingkaran"},{"type":"text","body":"3. Titik. Unsur rupa kecil yang dapat disusun menjadi pola. Contoh: Beberapa titik disusun membentuk jejak"},{"type":"text","body":"4. Arah. Orientasi gerak atau letak unsur rupa. Contoh: Garis dapat menuju atas, samping, atau diagonal"},{"type":"text","body":"5. Pengamatan visual. Memperhatikan ciri yang terlihat sebelum menggambar. Contoh: Anak mengamati bentuk daun tanpa memetiknya"},{"type":"text","body":"Contoh dan penalaran: Goresan pensil dapat lurus, melengkung, atau berkelok Kita mengenal garis sebagai jejak yang memanjang dan dapat berbeda arah atau sifat. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Amati unsur rupa di satu benda sekitar. Buat sketsa dan jelaskan pilihan garis atau bentuknya."},{"type":"text","body":"Rangkuman: Garis: Jejak yang memanjang dan dapat berbeda arah atau sifat; Bentuk: Rupa bidang atau benda yang dapat dikenali; Titik: Unsur rupa kecil yang dapat disusun menjadi pola; Arah: Orientasi gerak atau letak unsur rupa; Pengamatan visual: Memperhatikan ciri yang terlihat sebelum menggambar."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('f81e9e6c-9f58-5592-9284-2c5ceb4e2739','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Komposisi dan pola','belajar-seni-budaya-kelas-3-unit-2',3,'B','Bab 2','dasar','draft',12,'{"summary":"Komposisi dan pola. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan komposisi dan pola dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas III (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sdmi-kelas-iii-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan komposisi dan pola dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar komposisi dan pola. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Komposisi. Pengaturan unsur agar membentuk hubungan dalam karya. Contoh: Bentuk besar ditempatkan bersama bentuk kecil secara sengaja"},{"type":"text","body":"2. Keseimbangan. Hubungan bobot visual yang terasa teratur dalam susunan. Contoh: Warna gelap kecil dapat diimbangi unsur lain"},{"type":"text","body":"3. Pusat perhatian. Bagian yang sengaja dibuat paling menarik perhatian. Contoh: Warna yang berbeda menonjolkan satu objek"},{"type":"text","body":"4. Pengulangan. Pemakaian unsur yang berulang untuk membentuk irama visual. Contoh: Motif daun diulang pada tepian"},{"type":"text","body":"5. Ruang. Bagian bidang atau kedalaman yang digunakan atau dibiarkan. Contoh: Area kosong membantu objek utama terbaca"},{"type":"text","body":"Contoh dan penalaran: Bentuk besar ditempatkan bersama bentuk kecil secara sengaja Kita mengenal komposisi sebagai pengaturan unsur agar membentuk hubungan dalam karya. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Susun motif sederhana yang berulang. Coba dua komposisi sebelum memilih."},{"type":"text","body":"Rangkuman: Komposisi: Pengaturan unsur agar membentuk hubungan dalam karya; Keseimbangan: Hubungan bobot visual yang terasa teratur dalam susunan; Pusat perhatian: Bagian yang sengaja dibuat paling menarik perhatian; Pengulangan: Pemakaian unsur yang berulang untuk membentuk irama visual; Ruang: Bagian bidang atau kedalaman yang digunakan atau dibiarkan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('b4013f72-696a-5cf3-87a1-91c55f2edaf9','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Karya dua dan tiga dimensi','belajar-seni-budaya-kelas-3-unit-3',3,'B','Bab 3','dasar','draft',12,'{"summary":"Karya dua dan tiga dimensi. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan karya dua dan tiga dimensi dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas III (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sdmi-kelas-iii-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan karya dua dan tiga dimensi dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar karya dua dan tiga dimensi. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Dua dimensi. Karya yang terutama mempunyai ukuran panjang dan lebar. Contoh: Gambar pada kertas merupakan karya bidang"},{"type":"text","body":"2. Tiga dimensi. Karya yang mempunyai panjang, lebar, dan tinggi atau kedalaman. Contoh: Model dari bahan aman dapat dilihat dari beberapa arah"},{"type":"text","body":"3. Volume rupa. Kesan atau isi ruang pada bentuk tiga dimensi. Contoh: Model kotak mempunyai bagian yang menempati ruang"},{"type":"text","body":"4. Sambungan. Cara menghubungkan bagian bahan menjadi satu karya. Contoh: Potongan kertas dihubungkan dengan perekat aman"},{"type":"text","body":"5. Kestabilan. Keadaan karya dapat berdiri atau tersusun dengan aman. Contoh: Dasar yang cukup membantu model tidak mudah roboh"},{"type":"text","body":"Contoh dan penalaran: Gambar pada kertas merupakan karya bidang Kita mengenal dua dimensi sebagai karya yang terutama mempunyai ukuran panjang dan lebar. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat gambar bidang dan model kecil dari bahan aman. Jelaskan bagaimana cara melihat keduanya berbeda."},{"type":"text","body":"Rangkuman: Dua dimensi: Karya yang terutama mempunyai ukuran panjang dan lebar; Tiga dimensi: Karya yang mempunyai panjang, lebar, dan tinggi atau kedalaman; Volume rupa: Kesan atau isi ruang pada bentuk tiga dimensi; Sambungan: Cara menghubungkan bagian bahan menjadi satu karya; Kestabilan: Keadaan karya dapat berdiri atau tersusun dengan aman."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('9a031e68-f53f-5fb5-8d6b-ce2c38684843','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Irama dan suara','belajar-seni-budaya-kelas-3-unit-4',3,'B','Bab 4','sedang','draft',12,'{"summary":"Irama dan suara. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan irama dan suara dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas III (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sdmi-kelas-iii-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan irama dan suara dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar irama dan suara. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Bunyi. Getaran yang dapat didengar melalui medium. Contoh: Tepukan tangan menghasilkan bunyi"},{"type":"text","body":"2. Ketukan. Denyut teratur yang menjadi acuan waktu musik. Contoh: Anak menepuk dengan jarak waktu yang tetap"},{"type":"text","body":"3. Irama. Pola panjang-pendek dan penempatan bunyi terhadap waktu. Contoh: Tepuk singkat dan panjang disusun menjadi pola"},{"type":"text","body":"4. Diam dalam musik. Bagian waktu tanpa bunyi yang disengaja. Contoh: Peserta berhenti satu ketukan sesuai pola"},{"type":"text","body":"5. Tempo. Cepat atau lambatnya acuan ketukan musik. Contoh: Pola yang sama dapat dilakukan perlahan atau lebih cepat"},{"type":"text","body":"Contoh dan penalaran: Tepukan tangan menghasilkan bunyi Kita mengenal bunyi sebagai getaran yang dapat didengar melalui medium. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat pola bunyi dengan tepuk atau benda yang aman. Jaga volume, ketukan, dan bagian diam."},{"type":"text","body":"Rangkuman: Bunyi: Getaran yang dapat didengar melalui medium; Ketukan: Denyut teratur yang menjadi acuan waktu musik; Irama: Pola panjang-pendek dan penempatan bunyi terhadap waktu; Diam dalam musik: Bagian waktu tanpa bunyi yang disengaja; Tempo: Cepat atau lambatnya acuan ketukan musik."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('36fdfc48-d51f-581d-a4c0-d40deb69e1db','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Gerak dan cerita','belajar-seni-budaya-kelas-3-unit-5',3,'B','Bab 5','sedang','draft',12,'{"summary":"Gerak dan cerita. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan gerak dan cerita dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas III (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sdmi-kelas-iii-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan gerak dan cerita dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar gerak dan cerita. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Rangkaian gerak. Susunan beberapa gerakan yang saling berkaitan. Contoh: Langkah kecil dihubungkan dengan gerak tangan"},{"type":"text","body":"2. Level. Tinggi-rendah posisi tubuh dalam gerak. Contoh: Gerak dapat dilakukan pada posisi tinggi atau rendah sesuai kemampuan"},{"type":"text","body":"3. Pola lantai. Jalur atau susunan posisi penari dalam ruang. Contoh: Kelompok bergerak pada jalur lurus atau melengkung"},{"type":"text","body":"4. Ekspresi gerak. Cara menyampaikan suasana atau gagasan melalui gerakan. Contoh: Gerak ringan digunakan untuk menggambarkan kegembiraan"},{"type":"text","body":"5. Kerja kelompok tari. Penyesuaian gerak dan ruang dengan anggota lain. Contoh: Peserta menjaga jarak dan mengikuti kesepakatan awal"},{"type":"text","body":"Contoh dan penalaran: Langkah kecil dihubungkan dengan gerak tangan Kita mengenal rangkaian gerak sebagai susunan beberapa gerakan yang saling berkaitan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Susun tiga gerak untuk menceritakan kejadian rekaan. Beri ruang aman kepada peserta."},{"type":"text","body":"Rangkuman: Rangkaian gerak: Susunan beberapa gerakan yang saling berkaitan; Level: Tinggi-rendah posisi tubuh dalam gerak; Pola lantai: Jalur atau susunan posisi penari dalam ruang; Ekspresi gerak: Cara menyampaikan suasana atau gagasan melalui gerakan; Kerja kelompok tari: Penyesuaian gerak dan ruang dengan anggota lain."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('8c56e895-d12d-5543-90f4-e75da98830e3','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Apresiasi karya dengan bahasa santun','belajar-seni-budaya-kelas-3-unit-6',3,'B','Bab 6','sedang','draft',12,'{"summary":"Apresiasi karya dengan bahasa santun. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan apresiasi karya dengan bahasa santun dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas III (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sdmi-kelas-iii-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan apresiasi karya dengan bahasa santun dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar apresiasi karya dengan bahasa santun. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Apresiasi. Mengamati, memahami, dan menghargai karya. Contoh: Anak memperhatikan pilihan warna teman sebelum menanggapi"},{"type":"text","body":"2. Deskripsi karya. Penjelasan tentang hal yang benar-benar tampak atau terdengar. Contoh: Anak menyebut garis melengkung dalam gambar"},{"type":"text","body":"3. Tanggapan santun. Komentar yang membahas karya tanpa merendahkan penciptanya. Contoh: Anak mengatakan bagian yang menarik beserta alasannya"},{"type":"text","body":"4. Alasan penilaian. Penjelasan yang mendukung suatu pendapat tentang karya. Contoh: Komentar menyebut hubungan warna dengan suasana"},{"type":"text","body":"5. Perbedaan tafsir. Kemungkinan orang memahami karya dengan cara berbeda. Contoh: Dua penonton dapat mempunyai kesan berbeda terhadap gambar"},{"type":"text","body":"Contoh dan penalaran: Anak memperhatikan pilihan warna teman sebelum menanggapi Kita mengenal apresiasi sebagai mengamati, memahami, dan menghargai karya. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Berikan tanggapan karya berdasarkan hal yang diamati. Hindari menilai kemampuan atau harga diri penciptanya."},{"type":"text","body":"Rangkuman: Apresiasi: Mengamati, memahami, dan menghargai karya; Deskripsi karya: Penjelasan tentang hal yang benar-benar tampak atau terdengar; Tanggapan santun: Komentar yang membahas karya tanpa merendahkan penciptanya; Alasan penilaian: Penjelasan yang mendukung suatu pendapat tentang karya; Perbedaan tafsir: Kemungkinan orang memahami karya dengan cara berbeda."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('e79403a2-ca00-5904-b260-76bb1d7b75e2','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Bentuk dan komposisi','belajar-seni-budaya-kelas-4-unit-1',4,'B','Bab 1','dasar','draft',12,'{"summary":"Bentuk dan komposisi. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan bentuk dan komposisi dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas IV (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sd-mi-kelas-iv-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan bentuk dan komposisi dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar bentuk dan komposisi. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Komposisi. Pengaturan unsur agar membentuk hubungan dalam karya. Contoh: Bentuk besar ditempatkan bersama bentuk kecil secara sengaja"},{"type":"text","body":"2. Keseimbangan. Hubungan bobot visual yang terasa teratur dalam susunan. Contoh: Warna gelap kecil dapat diimbangi unsur lain"},{"type":"text","body":"3. Pusat perhatian. Bagian yang sengaja dibuat paling menarik perhatian. Contoh: Warna yang berbeda menonjolkan satu objek"},{"type":"text","body":"4. Pengulangan. Pemakaian unsur yang berulang untuk membentuk irama visual. Contoh: Motif daun diulang pada tepian"},{"type":"text","body":"5. Ruang. Bagian bidang atau kedalaman yang digunakan atau dibiarkan. Contoh: Area kosong membantu objek utama terbaca"},{"type":"text","body":"Contoh dan penalaran: Bentuk besar ditempatkan bersama bentuk kecil secara sengaja Kita mengenal komposisi sebagai pengaturan unsur agar membentuk hubungan dalam karya. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat dua susunan bentuk yang mempunyai pusat perhatian berbeda. Jelaskan keputusan penempatannya."},{"type":"text","body":"Rangkuman: Komposisi: Pengaturan unsur agar membentuk hubungan dalam karya; Keseimbangan: Hubungan bobot visual yang terasa teratur dalam susunan; Pusat perhatian: Bagian yang sengaja dibuat paling menarik perhatian; Pengulangan: Pemakaian unsur yang berulang untuk membentuk irama visual; Ruang: Bagian bidang atau kedalaman yang digunakan atau dibiarkan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('d16dcdd3-2fb8-5339-8142-de5836a16652','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Teknik dan bahan berkarya','belajar-seni-budaya-kelas-4-unit-2',4,'B','Bab 2','dasar','draft',12,'{"summary":"Teknik dan bahan berkarya. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan teknik dan bahan berkarya dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas IV (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sd-mi-kelas-iv-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan teknik dan bahan berkarya dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar teknik dan bahan berkarya. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Bahan alam. Bahan yang berasal dari alam dan digunakan dengan bertanggung jawab. Contoh: Daun gugur yang bersih dipakai tanpa memetik tanaman"},{"type":"text","body":"2. Bahan buatan. Bahan yang diolah manusia untuk kebutuhan tertentu. Contoh: Kertas dibuat melalui proses pengolahan"},{"type":"text","body":"3. Guna ulang. Memakai bahan yang masih layak untuk kebutuhan lain. Contoh: Kotak bersih dijadikan wadah alat"},{"type":"text","body":"4. Teknik. Cara menggunakan alat atau bahan untuk menghasilkan karya. Contoh: Melipat dan menempel adalah teknik yang berbeda"},{"type":"text","body":"5. Keselamatan kerja. Tindakan menjaga diri, orang lain, dan ruang selama berkarya. Contoh: Alat tajam hanya digunakan sesuai usia dengan pendampingan"},{"type":"text","body":"Contoh dan penalaran: Daun gugur yang bersih dipakai tanpa memetik tanaman Kita mengenal bahan alam sebagai bahan yang berasal dari alam dan digunakan dengan bertanggung jawab. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Coba teknik melipat atau menyusun pada bahan sisa yang bersih. Pilih alat sesuai usia dengan pendamping."},{"type":"text","body":"Rangkuman: Bahan alam: Bahan yang berasal dari alam dan digunakan dengan bertanggung jawab; Bahan buatan: Bahan yang diolah manusia untuk kebutuhan tertentu; Guna ulang: Memakai bahan yang masih layak untuk kebutuhan lain; Teknik: Cara menggunakan alat atau bahan untuk menghasilkan karya; Keselamatan kerja: Tindakan menjaga diri, orang lain, dan ruang selama berkarya."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('1b8053a5-66bb-57f7-b4ad-242db2b2b21f','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Motif dan karya lingkungan','belajar-seni-budaya-kelas-4-unit-3',4,'B','Bab 3','dasar','draft',12,'{"summary":"Motif dan karya lingkungan. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan motif dan karya lingkungan dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas IV (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sd-mi-kelas-iv-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan motif dan karya lingkungan dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar motif dan karya lingkungan. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Objek gambar. Hal yang dipilih untuk diamati atau digambarkan. Contoh: Anak memilih sepatu sebagai objek"},{"type":"text","body":"2. Detail. Bagian kecil yang membantu memperjelas gambaran. Contoh: Tali dan lubang sepatu diamati bentuknya"},{"type":"text","body":"3. Sketsa. Gambar awal untuk merencanakan bentuk atau susunan. Contoh: Goresan ringan membantu mencoba letak objek"},{"type":"text","body":"4. Ekspresi. Cara menyampaikan pengalaman atau perasaan melalui karya. Contoh: Anak memilih garis dan warna untuk menyampaikan suasana"},{"type":"text","body":"5. Pilihan pribadi. Keputusan pencipta yang membuat karya mempunyai ciri sendiri. Contoh: Dua anak boleh menggambar pengalaman sama dengan cara berbeda"},{"type":"text","body":"Contoh dan penalaran: Anak memilih sepatu sebagai objek Kita mengenal objek gambar sebagai hal yang dipilih untuk diamati atau digambarkan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Kembangkan motif dari pengamatan lingkungan tanpa merusak objek atau menyalin simbol bermakna khusus sembarangan."},{"type":"text","body":"Rangkuman: Objek gambar: Hal yang dipilih untuk diamati atau digambarkan; Detail: Bagian kecil yang membantu memperjelas gambaran; Sketsa: Gambar awal untuk merencanakan bentuk atau susunan; Ekspresi: Cara menyampaikan pengalaman atau perasaan melalui karya; Pilihan pribadi: Keputusan pencipta yang membuat karya mempunyai ciri sendiri."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('239d9aa0-5892-5a06-8618-9023e4023c30','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Melodi dan irama sederhana','belajar-seni-budaya-kelas-4-unit-4',4,'B','Bab 4','sedang','draft',12,'{"summary":"Melodi dan irama sederhana. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan melodi dan irama sederhana dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas IV (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sd-mi-kelas-iv-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan melodi dan irama sederhana dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar melodi dan irama sederhana. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Nada. Bunyi dengan tinggi tertentu. Contoh: Suara yang dinyanyikan dapat terdengar lebih tinggi atau rendah"},{"type":"text","body":"2. Melodi. Rangkaian nada yang tersusun menjadi gagasan musikal. Contoh: Urutan nada membentuk bagian lagu"},{"type":"text","body":"3. Dinamika. Kuat-lemahnya bunyi dalam penyajian musik. Contoh: Bagian musik dinyanyikan lembut sesuai maksud"},{"type":"text","body":"4. Frasa musik. Kelompok bunyi atau nada yang terasa sebagai satu bagian. Contoh: Penyanyi memberi jeda pada akhir gagasan musikal"},{"type":"text","body":"5. Mendengar aktif. Memperhatikan hubungan bunyi sebelum menanggapi atau meniru. Contoh: Anak menyimak pola sebelum mencoba membunyikannya"},{"type":"text","body":"Contoh dan penalaran: Suara yang dinyanyikan dapat terdengar lebih tinggi atau rendah Kita mengenal nada sebagai bunyi dengan tinggi tertentu. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Tirukan pola nada pendek dari pendamping pada tinggi suara yang nyaman. Dengarkan dan beri jeda sesuai frasa."},{"type":"text","body":"Rangkuman: Nada: Bunyi dengan tinggi tertentu; Melodi: Rangkaian nada yang tersusun menjadi gagasan musikal; Dinamika: Kuat-lemahnya bunyi dalam penyajian musik; Frasa musik: Kelompok bunyi atau nada yang terasa sebagai satu bagian; Mendengar aktif: Memperhatikan hubungan bunyi sebelum menanggapi atau meniru."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('10a37c60-1866-51b8-9ea8-f408a47504f9','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Gerak tari dan kerja kelompok','belajar-seni-budaya-kelas-4-unit-5',4,'B','Bab 5','sedang','draft',12,'{"summary":"Gerak tari dan kerja kelompok. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan gerak tari dan kerja kelompok dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas IV (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sd-mi-kelas-iv-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan gerak tari dan kerja kelompok dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar gerak tari dan kerja kelompok. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Rangkaian gerak. Susunan beberapa gerakan yang saling berkaitan. Contoh: Langkah kecil dihubungkan dengan gerak tangan"},{"type":"text","body":"2. Level. Tinggi-rendah posisi tubuh dalam gerak. Contoh: Gerak dapat dilakukan pada posisi tinggi atau rendah sesuai kemampuan"},{"type":"text","body":"3. Pola lantai. Jalur atau susunan posisi penari dalam ruang. Contoh: Kelompok bergerak pada jalur lurus atau melengkung"},{"type":"text","body":"4. Ekspresi gerak. Cara menyampaikan suasana atau gagasan melalui gerakan. Contoh: Gerak ringan digunakan untuk menggambarkan kegembiraan"},{"type":"text","body":"5. Kerja kelompok tari. Penyesuaian gerak dan ruang dengan anggota lain. Contoh: Peserta menjaga jarak dan mengikuti kesepakatan awal"},{"type":"text","body":"Contoh dan penalaran: Langkah kecil dihubungkan dengan gerak tangan Kita mengenal rangkaian gerak sebagai susunan beberapa gerakan yang saling berkaitan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Susun gerak kelompok dengan jalur dan level yang sesuai kemampuan setiap peserta."},{"type":"text","body":"Rangkuman: Rangkaian gerak: Susunan beberapa gerakan yang saling berkaitan; Level: Tinggi-rendah posisi tubuh dalam gerak; Pola lantai: Jalur atau susunan posisi penari dalam ruang; Ekspresi gerak: Cara menyampaikan suasana atau gagasan melalui gerakan; Kerja kelompok tari: Penyesuaian gerak dan ruang dengan anggota lain."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('daef3777-29c5-5de2-b5a1-56e390acddd4','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Cerita dan permainan peran','belajar-seni-budaya-kelas-4-unit-6',4,'B','Bab 6','sedang','draft',12,'{"summary":"Cerita dan permainan peran. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan cerita dan permainan peran dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas IV (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sd-mi-kelas-iv-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan cerita dan permainan peran dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar cerita dan permainan peran. Amati contoh, jelaskan alasanmu, lalu coba contoh lain. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Alur dramatik. Rangkaian kejadian yang membangun tindakan dalam pertunjukan. Contoh: Tokoh menghadapi masalah lalu mencoba menyelesaikannya"},{"type":"text","body":"2. Motivasi tokoh. Alasan yang mendorong tindakan tokoh. Contoh: Tokoh mencari buku karena ingin mengembalikannya"},{"type":"text","body":"3. Improvisasi. Pengembangan tindakan atau ucapan secara spontan dalam batas kesepakatan. Contoh: Pemain menanggapi kejadian rekaan tanpa naskah rinci"},{"type":"text","body":"4. Properti. Benda yang digunakan untuk mendukung tindakan dalam pertunjukan. Contoh: Kotak aman digunakan sebagai barang bawaan tokoh"},{"type":"text","body":"5. Kesepakatan bermain. Batas dan aturan yang menjaga permainan peran tetap aman. Contoh: Peserta sepakat tidak memakai kekerasan nyata atau mengejek identitas"},{"type":"text","body":"Contoh dan penalaran: Tokoh menghadapi masalah lalu mencoba menyelesaikannya Kita mengenal alur dramatik sebagai rangkaian kejadian yang membangun tindakan dalam pertunjukan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat adegan pendek dengan awal, dialog, dan akhir. Sepakati batas aman sebelum bermain."},{"type":"text","body":"Rangkuman: Alur dramatik: Rangkaian kejadian yang membangun tindakan dalam pertunjukan; Motivasi tokoh: Alasan yang mendorong tindakan tokoh; Improvisasi: Pengembangan tindakan atau ucapan secara spontan dalam batas kesepakatan; Properti: Benda yang digunakan untuk mendukung tindakan dalam pertunjukan; Kesepakatan bermain: Batas dan aturan yang menjaga permainan peran tetap aman."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('a4da1bb1-9269-548d-b4ff-88fafea3ca61','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Rancangan karya dan pesan','belajar-seni-budaya-kelas-5-unit-1',5,'C','Bab 1','dasar','draft',12,'{"summary":"Rancangan karya dan pesan. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan rancangan karya dan pesan dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas V (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sd-mi-kelas-v-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."},{"title":"Panduan Guru Seni Musik Kelas V (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-musik-untuk-sdmi-kelas-v-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan rancangan karya dan pesan dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar rancangan karya dan pesan. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Gagasan karya. Ide yang ingin diwujudkan pencipta. Contoh: Anak ingin membuat poster merawat buku"},{"type":"text","body":"2. Tujuan karya. Hal yang ingin dikomunikasikan atau dicapai. Contoh: Poster dirancang untuk mengajak pembaca melakukan tindakan"},{"type":"text","body":"3. Rancangan. Rencana bentuk, bahan, dan susunan sebelum berkarya. Contoh: Anak membuat beberapa sketsa pilihan"},{"type":"text","body":"4. Revisi. Perubahan untuk memperbaiki hubungan bentuk dengan tujuan. Contoh: Tulisan diperbesar agar pesan lebih mudah dibaca"},{"type":"text","body":"5. Refleksi proses. Penilaian terhadap langkah dan keputusan selama berkarya. Contoh: Pencipta menjelaskan perubahan yang dilakukan dan alasannya"},{"type":"text","body":"Contoh dan penalaran: Anak ingin membuat poster merawat buku Kita mengenal gagasan karya sebagai ide yang ingin diwujudkan pencipta. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Rancang karya yang menyampaikan pesan pilihanmu. Buat dua sketsa dan jelaskan alasan memilihnya."},{"type":"text","body":"Rangkuman: Gagasan karya: Ide yang ingin diwujudkan pencipta; Tujuan karya: Hal yang ingin dikomunikasikan atau dicapai; Rancangan: Rencana bentuk, bahan, dan susunan sebelum berkarya; Revisi: Perubahan untuk memperbaiki hubungan bentuk dengan tujuan; Refleksi proses: Penilaian terhadap langkah dan keputusan selama berkarya."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('6a2aab64-c584-5441-b470-7a40c8f83106','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Eksplorasi bahan dan teknik','belajar-seni-budaya-kelas-5-unit-2',5,'C','Bab 2','dasar','draft',12,'{"summary":"Eksplorasi bahan dan teknik. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan eksplorasi bahan dan teknik dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas V (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sd-mi-kelas-v-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."},{"title":"Panduan Guru Seni Musik Kelas V (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-musik-untuk-sdmi-kelas-v-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan eksplorasi bahan dan teknik dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar eksplorasi bahan dan teknik. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Bahan alam. Bahan yang berasal dari alam dan digunakan dengan bertanggung jawab. Contoh: Daun gugur yang bersih dipakai tanpa memetik tanaman"},{"type":"text","body":"2. Bahan buatan. Bahan yang diolah manusia untuk kebutuhan tertentu. Contoh: Kertas dibuat melalui proses pengolahan"},{"type":"text","body":"3. Guna ulang. Memakai bahan yang masih layak untuk kebutuhan lain. Contoh: Kotak bersih dijadikan wadah alat"},{"type":"text","body":"4. Teknik. Cara menggunakan alat atau bahan untuk menghasilkan karya. Contoh: Melipat dan menempel adalah teknik yang berbeda"},{"type":"text","body":"5. Keselamatan kerja. Tindakan menjaga diri, orang lain, dan ruang selama berkarya. Contoh: Alat tajam hanya digunakan sesuai usia dengan pendampingan"},{"type":"text","body":"Contoh dan penalaran: Daun gugur yang bersih dipakai tanpa memetik tanaman Kita mengenal bahan alam sebagai bahan yang berasal dari alam dan digunakan dengan bertanggung jawab. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Eksplorasi dua bahan aman untuk maksud sama. Catat kelebihan, keterbatasan, dan sisa bahannya."},{"type":"text","body":"Rangkuman: Bahan alam: Bahan yang berasal dari alam dan digunakan dengan bertanggung jawab; Bahan buatan: Bahan yang diolah manusia untuk kebutuhan tertentu; Guna ulang: Memakai bahan yang masih layak untuk kebutuhan lain; Teknik: Cara menggunakan alat atau bahan untuk menghasilkan karya; Keselamatan kerja: Tindakan menjaga diri, orang lain, dan ruang selama berkarya."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('4b8df909-7341-5ea7-b982-4ab72554867f','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Karya dari lingkungan','belajar-seni-budaya-kelas-5-unit-3',5,'C','Bab 3','dasar','draft',12,'{"summary":"Karya dari lingkungan. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan karya dari lingkungan dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas V (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sd-mi-kelas-v-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."},{"title":"Panduan Guru Seni Musik Kelas V (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-musik-untuk-sdmi-kelas-v-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan karya dari lingkungan dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar karya dari lingkungan. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Bahan alam. Bahan yang berasal dari alam dan digunakan dengan bertanggung jawab. Contoh: Daun gugur yang bersih dipakai tanpa memetik tanaman"},{"type":"text","body":"2. Bahan buatan. Bahan yang diolah manusia untuk kebutuhan tertentu. Contoh: Kertas dibuat melalui proses pengolahan"},{"type":"text","body":"3. Guna ulang. Memakai bahan yang masih layak untuk kebutuhan lain. Contoh: Kotak bersih dijadikan wadah alat"},{"type":"text","body":"4. Teknik. Cara menggunakan alat atau bahan untuk menghasilkan karya. Contoh: Melipat dan menempel adalah teknik yang berbeda"},{"type":"text","body":"5. Keselamatan kerja. Tindakan menjaga diri, orang lain, dan ruang selama berkarya. Contoh: Alat tajam hanya digunakan sesuai usia dengan pendampingan"},{"type":"text","body":"Contoh dan penalaran: Daun gugur yang bersih dipakai tanpa memetik tanaman Kita mengenal bahan alam sebagai bahan yang berasal dari alam dan digunakan dengan bertanggung jawab. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat karya dari bahan sekitar yang bersih dan diizinkan. Utamakan guna ulang tanpa mengambil benda berbahaya."},{"type":"text","body":"Rangkuman: Bahan alam: Bahan yang berasal dari alam dan digunakan dengan bertanggung jawab; Bahan buatan: Bahan yang diolah manusia untuk kebutuhan tertentu; Guna ulang: Memakai bahan yang masih layak untuk kebutuhan lain; Teknik: Cara menggunakan alat atau bahan untuk menghasilkan karya; Keselamatan kerja: Tindakan menjaga diri, orang lain, dan ruang selama berkarya."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('62ba6ddc-5a45-5aaa-bf70-149e1bb23336','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Musik dan ekspresi','belajar-seni-budaya-kelas-5-unit-4',5,'C','Bab 4','sedang','draft',12,'{"summary":"Musik dan ekspresi. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan musik dan ekspresi dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas V (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sd-mi-kelas-v-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."},{"title":"Panduan Guru Seni Musik Kelas V (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-musik-untuk-sdmi-kelas-v-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan musik dan ekspresi dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar musik dan ekspresi. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Ansambel. Permainan musik bersama beberapa pemain. Contoh: Kelompok membawakan pola bunyi yang saling melengkapi"},{"type":"text","body":"2. Peran musikal. Tugas bunyi yang dipegang anggota dalam kelompok. Contoh: Satu kelompok menjaga ketukan, kelompok lain memberi pola"},{"type":"text","body":"3. Koordinasi. Penyesuaian tindakan dengan anggota lain. Contoh: Peserta mulai dan berhenti menurut aba-aba"},{"type":"text","body":"4. Keseimbangan bunyi. Pengaturan agar bagian penting tetap terdengar. Contoh: Pemain tidak menutupi suara teman dengan bunyi terlalu kuat"},{"type":"text","body":"5. Evaluasi musik. Pembahasan hasil penyajian untuk menentukan perbaikan. Contoh: Kelompok membahas apakah ketukan tetap terjaga"},{"type":"text","body":"Contoh dan penalaran: Kelompok membawakan pola bunyi yang saling melengkapi Kita mengenal ansambel sebagai permainan musik bersama beberapa pemain. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat pola bunyi kelompok yang menyampaikan suasana. Atur ketukan, dinamika, dan giliran masuk."},{"type":"text","body":"Rangkuman: Ansambel: Permainan musik bersama beberapa pemain; Peran musikal: Tugas bunyi yang dipegang anggota dalam kelompok; Koordinasi: Penyesuaian tindakan dengan anggota lain; Keseimbangan bunyi: Pengaturan agar bagian penting tetap terdengar; Evaluasi musik: Pembahasan hasil penyajian untuk menentukan perbaikan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('565cf72a-7113-59d3-8a85-ad755d69e17f','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Tari dan pola gerak','belajar-seni-budaya-kelas-5-unit-5',5,'C','Bab 5','sedang','draft',12,'{"summary":"Tari dan pola gerak. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan tari dan pola gerak dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas V (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sd-mi-kelas-v-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."},{"title":"Panduan Guru Seni Musik Kelas V (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-musik-untuk-sdmi-kelas-v-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan tari dan pola gerak dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar tari dan pola gerak. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Rangkaian gerak. Susunan beberapa gerakan yang saling berkaitan. Contoh: Langkah kecil dihubungkan dengan gerak tangan"},{"type":"text","body":"2. Level. Tinggi-rendah posisi tubuh dalam gerak. Contoh: Gerak dapat dilakukan pada posisi tinggi atau rendah sesuai kemampuan"},{"type":"text","body":"3. Pola lantai. Jalur atau susunan posisi penari dalam ruang. Contoh: Kelompok bergerak pada jalur lurus atau melengkung"},{"type":"text","body":"4. Ekspresi gerak. Cara menyampaikan suasana atau gagasan melalui gerakan. Contoh: Gerak ringan digunakan untuk menggambarkan kegembiraan"},{"type":"text","body":"5. Kerja kelompok tari. Penyesuaian gerak dan ruang dengan anggota lain. Contoh: Peserta menjaga jarak dan mengikuti kesepakatan awal"},{"type":"text","body":"Contoh dan penalaran: Langkah kecil dihubungkan dengan gerak tangan Kita mengenal rangkaian gerak sebagai susunan beberapa gerakan yang saling berkaitan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Susun gerak dengan variasi arah dan level. Jelaskan hubungan gerak dengan gagasan tanpa memaksakan bentuk tubuh."},{"type":"text","body":"Rangkuman: Rangkaian gerak: Susunan beberapa gerakan yang saling berkaitan; Level: Tinggi-rendah posisi tubuh dalam gerak; Pola lantai: Jalur atau susunan posisi penari dalam ruang; Ekspresi gerak: Cara menyampaikan suasana atau gagasan melalui gerakan; Kerja kelompok tari: Penyesuaian gerak dan ruang dengan anggota lain."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('c068f868-cbaa-51b4-8d8b-cc2df3e7bac6','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Teater dan refleksi karya','belajar-seni-budaya-kelas-5-unit-6',5,'C','Bab 6','sedang','draft',12,'{"summary":"Teater dan refleksi karya. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan teater dan refleksi karya dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas V (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sd-mi-kelas-v-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."},{"title":"Panduan Guru Seni Musik Kelas V (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-musik-untuk-sdmi-kelas-v-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan teater dan refleksi karya dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar teater dan refleksi karya. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Alur dramatik. Rangkaian kejadian yang membangun tindakan dalam pertunjukan. Contoh: Tokoh menghadapi masalah lalu mencoba menyelesaikannya"},{"type":"text","body":"2. Motivasi tokoh. Alasan yang mendorong tindakan tokoh. Contoh: Tokoh mencari buku karena ingin mengembalikannya"},{"type":"text","body":"3. Improvisasi. Pengembangan tindakan atau ucapan secara spontan dalam batas kesepakatan. Contoh: Pemain menanggapi kejadian rekaan tanpa naskah rinci"},{"type":"text","body":"4. Properti. Benda yang digunakan untuk mendukung tindakan dalam pertunjukan. Contoh: Kotak aman digunakan sebagai barang bawaan tokoh"},{"type":"text","body":"5. Kesepakatan bermain. Batas dan aturan yang menjaga permainan peran tetap aman. Contoh: Peserta sepakat tidak memakai kekerasan nyata atau mengejek identitas"},{"type":"text","body":"Contoh dan penalaran: Tokoh menghadapi masalah lalu mencoba menyelesaikannya Kita mengenal alur dramatik sebagai rangkaian kejadian yang membangun tindakan dalam pertunjukan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Mainkan adegan rekaan dengan motivasi tokoh yang jelas. Setelahnya bahas keputusan dan perbaikan."},{"type":"text","body":"Rangkuman: Alur dramatik: Rangkaian kejadian yang membangun tindakan dalam pertunjukan; Motivasi tokoh: Alasan yang mendorong tindakan tokoh; Improvisasi: Pengembangan tindakan atau ucapan secara spontan dalam batas kesepakatan; Properti: Benda yang digunakan untuk mendukung tindakan dalam pertunjukan; Kesepakatan bermain: Batas dan aturan yang menjaga permainan peran tetap aman."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('497157f8-b497-5512-a055-8c99188e39ed','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Merancang dan merevisi karya','belajar-seni-budaya-kelas-6-unit-1',6,'C','Bab 1','dasar','draft',12,'{"summary":"Merancang dan merevisi karya. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan merancang dan merevisi karya dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas VI (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sdmi-kelas-vi-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan merancang dan merevisi karya dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar merancang dan merevisi karya. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Gagasan karya. Ide yang ingin diwujudkan pencipta. Contoh: Anak ingin membuat poster merawat buku"},{"type":"text","body":"2. Tujuan karya. Hal yang ingin dikomunikasikan atau dicapai. Contoh: Poster dirancang untuk mengajak pembaca melakukan tindakan"},{"type":"text","body":"3. Rancangan. Rencana bentuk, bahan, dan susunan sebelum berkarya. Contoh: Anak membuat beberapa sketsa pilihan"},{"type":"text","body":"4. Revisi. Perubahan untuk memperbaiki hubungan bentuk dengan tujuan. Contoh: Tulisan diperbesar agar pesan lebih mudah dibaca"},{"type":"text","body":"5. Refleksi proses. Penilaian terhadap langkah dan keputusan selama berkarya. Contoh: Pencipta menjelaskan perubahan yang dilakukan dan alasannya"},{"type":"text","body":"Contoh dan penalaran: Anak ingin membuat poster merawat buku Kita mengenal gagasan karya sebagai ide yang ingin diwujudkan pencipta. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Pilih karya yang pernah dibuat. Revisi satu keputusan bentuk atau susunan berdasarkan tujuan yang ingin disampaikan."},{"type":"text","body":"Rangkuman: Gagasan karya: Ide yang ingin diwujudkan pencipta; Tujuan karya: Hal yang ingin dikomunikasikan atau dicapai; Rancangan: Rencana bentuk, bahan, dan susunan sebelum berkarya; Revisi: Perubahan untuk memperbaiki hubungan bentuk dengan tujuan; Refleksi proses: Penilaian terhadap langkah dan keputusan selama berkarya."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('eaa64f95-027c-57fc-9941-d59bc92f4a75','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Komposisi dan pilihan teknik','belajar-seni-budaya-kelas-6-unit-2',6,'C','Bab 2','dasar','draft',12,'{"summary":"Komposisi dan pilihan teknik. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan komposisi dan pilihan teknik dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas VI (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sdmi-kelas-vi-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan komposisi dan pilihan teknik dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar komposisi dan pilihan teknik. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Komposisi. Pengaturan unsur agar membentuk hubungan dalam karya. Contoh: Bentuk besar ditempatkan bersama bentuk kecil secara sengaja"},{"type":"text","body":"2. Keseimbangan. Hubungan bobot visual yang terasa teratur dalam susunan. Contoh: Warna gelap kecil dapat diimbangi unsur lain"},{"type":"text","body":"3. Pusat perhatian. Bagian yang sengaja dibuat paling menarik perhatian. Contoh: Warna yang berbeda menonjolkan satu objek"},{"type":"text","body":"4. Pengulangan. Pemakaian unsur yang berulang untuk membentuk irama visual. Contoh: Motif daun diulang pada tepian"},{"type":"text","body":"5. Ruang. Bagian bidang atau kedalaman yang digunakan atau dibiarkan. Contoh: Area kosong membantu objek utama terbaca"},{"type":"text","body":"Contoh dan penalaran: Bentuk besar ditempatkan bersama bentuk kecil secara sengaja Kita mengenal komposisi sebagai pengaturan unsur agar membentuk hubungan dalam karya. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Bandingkan dua pilihan teknik atau komposisi. Jelaskan bagaimana pilihan tersebut memengaruhi pesan."},{"type":"text","body":"Rangkuman: Komposisi: Pengaturan unsur agar membentuk hubungan dalam karya; Keseimbangan: Hubungan bobot visual yang terasa teratur dalam susunan; Pusat perhatian: Bagian yang sengaja dibuat paling menarik perhatian; Pengulangan: Pemakaian unsur yang berulang untuk membentuk irama visual; Ruang: Bagian bidang atau kedalaman yang digunakan atau dibiarkan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('df68bffe-ddb1-5edb-8817-98c2f34cfbfd','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Apresiasi dan pameran sederhana','belajar-seni-budaya-kelas-6-unit-3',6,'C','Bab 3','dasar','draft',12,'{"summary":"Apresiasi dan pameran sederhana. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan apresiasi dan pameran sederhana dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas VI (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sdmi-kelas-vi-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan apresiasi dan pameran sederhana dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar apresiasi dan pameran sederhana. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Kurasi sederhana. Memilih dan menyusun karya berdasarkan tujuan penyajian. Contoh: Kelompok memilih karya yang menunjukkan proses belajar"},{"type":"text","body":"2. Label karya. Keterangan yang membantu pengunjung memahami karya. Contoh: Judul dan bahan dicatat tanpa data pribadi berlebihan"},{"type":"text","body":"3. Penyajian. Cara menempatkan atau membawakan karya kepada penonton. Contoh: Karya diletakkan agar aman dan dapat dilihat"},{"type":"text","body":"4. Peran penonton. Sikap menyimak dan menghargai penyajian karya. Contoh: Pengunjung tidak menyentuh karya tanpa izin"},{"type":"text","body":"5. Refleksi pameran. Pembahasan pengalaman menyajikan serta menerima tanggapan. Contoh: Pencipta mencatat bagian penyajian yang perlu diperbaiki"},{"type":"text","body":"Contoh dan penalaran: Kelompok memilih karya yang menunjukkan proses belajar Kita mengenal kurasi sederhana sebagai memilih dan menyusun karya berdasarkan tujuan penyajian. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Siapkan pameran kecil dengan label yang menjaga privasi. Minta izin sebelum memajang atau merekam karya orang lain."},{"type":"text","body":"Rangkuman: Kurasi sederhana: Memilih dan menyusun karya berdasarkan tujuan penyajian; Label karya: Keterangan yang membantu pengunjung memahami karya; Penyajian: Cara menempatkan atau membawakan karya kepada penonton; Peran penonton: Sikap menyimak dan menghargai penyajian karya; Refleksi pameran: Pembahasan pengalaman menyajikan serta menerima tanggapan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('1de6952f-df34-5743-9bfa-bacd157aa3ea','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Karya musik kelompok','belajar-seni-budaya-kelas-6-unit-4',6,'C','Bab 4','sedang','draft',12,'{"summary":"Karya musik kelompok. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan karya musik kelompok dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas VI (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sdmi-kelas-vi-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan karya musik kelompok dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar karya musik kelompok. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Ansambel. Permainan musik bersama beberapa pemain. Contoh: Kelompok membawakan pola bunyi yang saling melengkapi"},{"type":"text","body":"2. Peran musikal. Tugas bunyi yang dipegang anggota dalam kelompok. Contoh: Satu kelompok menjaga ketukan, kelompok lain memberi pola"},{"type":"text","body":"3. Koordinasi. Penyesuaian tindakan dengan anggota lain. Contoh: Peserta mulai dan berhenti menurut aba-aba"},{"type":"text","body":"4. Keseimbangan bunyi. Pengaturan agar bagian penting tetap terdengar. Contoh: Pemain tidak menutupi suara teman dengan bunyi terlalu kuat"},{"type":"text","body":"5. Evaluasi musik. Pembahasan hasil penyajian untuk menentukan perbaikan. Contoh: Kelompok membahas apakah ketukan tetap terjaga"},{"type":"text","body":"Contoh dan penalaran: Kelompok membawakan pola bunyi yang saling melengkapi Kita mengenal ansambel sebagai permainan musik bersama beberapa pemain. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Rancang penyajian musik kelompok singkat. Berlatih memberi aba-aba, menjaga keseimbangan bunyi, dan mengevaluasi hasil."},{"type":"text","body":"Rangkuman: Ansambel: Permainan musik bersama beberapa pemain; Peran musikal: Tugas bunyi yang dipegang anggota dalam kelompok; Koordinasi: Penyesuaian tindakan dengan anggota lain; Keseimbangan bunyi: Pengaturan agar bagian penting tetap terdengar; Evaluasi musik: Pembahasan hasil penyajian untuk menentukan perbaikan."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('693712bc-2546-589b-aa71-6c226305da2d','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Penyajian tari sederhana','belajar-seni-budaya-kelas-6-unit-5',6,'C','Bab 5','sedang','draft',12,'{"summary":"Penyajian tari sederhana. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan penyajian tari sederhana dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas VI (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sdmi-kelas-vi-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan penyajian tari sederhana dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar penyajian tari sederhana. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Rangkaian gerak. Susunan beberapa gerakan yang saling berkaitan. Contoh: Langkah kecil dihubungkan dengan gerak tangan"},{"type":"text","body":"2. Level. Tinggi-rendah posisi tubuh dalam gerak. Contoh: Gerak dapat dilakukan pada posisi tinggi atau rendah sesuai kemampuan"},{"type":"text","body":"3. Pola lantai. Jalur atau susunan posisi penari dalam ruang. Contoh: Kelompok bergerak pada jalur lurus atau melengkung"},{"type":"text","body":"4. Ekspresi gerak. Cara menyampaikan suasana atau gagasan melalui gerakan. Contoh: Gerak ringan digunakan untuk menggambarkan kegembiraan"},{"type":"text","body":"5. Kerja kelompok tari. Penyesuaian gerak dan ruang dengan anggota lain. Contoh: Peserta menjaga jarak dan mengikuti kesepakatan awal"},{"type":"text","body":"Contoh dan penalaran: Langkah kecil dihubungkan dengan gerak tangan Kita mengenal rangkaian gerak sebagai susunan beberapa gerakan yang saling berkaitan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Sajikan rangkaian tari sederhana yang aman dan inklusif. Sesuaikan ruang serta gerak dengan kebutuhan peserta."},{"type":"text","body":"Rangkuman: Rangkaian gerak: Susunan beberapa gerakan yang saling berkaitan; Level: Tinggi-rendah posisi tubuh dalam gerak; Pola lantai: Jalur atau susunan posisi penari dalam ruang; Ekspresi gerak: Cara menyampaikan suasana atau gagasan melalui gerakan; Kerja kelompok tari: Penyesuaian gerak dan ruang dengan anggota lain."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('6698968a-1010-5eb6-b6ce-9729c320fe50','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Pementasan dan refleksi proses','belajar-seni-budaya-kelas-6-unit-6',6,'C','Bab 6','sedang','draft',12,'{"summary":"Pementasan dan refleksi proses. Belajar melalui penjelasan, contoh, aktivitas, dan latihan konsep.","video_url":null,"review_status":"needs_teacher_review","editorial_notice":"Draf materi orisinal Petualangan Ilmu. Belum ditinjau guru; bukan buku resmi atau pemetaan CP yang disahkan.","objectives":["Menjelaskan pementasan dan refleksi proses dengan contoh.","Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."],"source_refs":[{"title":"Panduan Guru Seni Rupa Kelas VI (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-seni-rupa-untuk-sdmi-kelas-vi-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; bukan salinan atau adaptasi halaman tertentu."}],"curriculum_note":"Pilihan cabang seni disesuaikan sekolah; panduan awal didominasi Seni Rupa.","enrichment":false,"blocks":[{"type":"text","body":"Tujuan belajar: Menjelaskan pementasan dan refleksi proses dengan contoh. Menerapkan konsep pada aktivitas sesuai usia dan menceritakan alasannya."},{"type":"text","body":"Mari belajar pementasan dan refleksi proses. Bandingkan contoh dan jelaskan alasan dengan informasi yang kamu temukan. Kita akan menggunakan lima gagasan berikut. Hubungkan setiap gagasan dengan contoh; jangan hanya menghafal namanya."},{"type":"text","body":"1. Alur dramatik. Rangkaian kejadian yang membangun tindakan dalam pertunjukan. Contoh: Tokoh menghadapi masalah lalu mencoba menyelesaikannya"},{"type":"text","body":"2. Motivasi tokoh. Alasan yang mendorong tindakan tokoh. Contoh: Tokoh mencari buku karena ingin mengembalikannya"},{"type":"text","body":"3. Improvisasi. Pengembangan tindakan atau ucapan secara spontan dalam batas kesepakatan. Contoh: Pemain menanggapi kejadian rekaan tanpa naskah rinci"},{"type":"text","body":"4. Properti. Benda yang digunakan untuk mendukung tindakan dalam pertunjukan. Contoh: Kotak aman digunakan sebagai barang bawaan tokoh"},{"type":"text","body":"5. Kesepakatan bermain. Batas dan aturan yang menjaga permainan peran tetap aman. Contoh: Peserta sepakat tidak memakai kekerasan nyata atau mengejek identitas"},{"type":"text","body":"Contoh dan penalaran: Tokoh menghadapi masalah lalu mencoba menyelesaikannya Kita mengenal alur dramatik sebagai rangkaian kejadian yang membangun tindakan dalam pertunjukan. Periksa ciri tersebut sebelum mengambil kesimpulan."},{"type":"tip","body":"Jika bingung, kembali ke ciri atau informasi pada contoh. Jelaskan alasan pilihanmu; jawaban berbeda boleh dibahas bersama pendamping."},{"type":"text","body":"Ayo mencoba: Buat pertunjukan singkat dengan tugas pemain dan pendukung. Catat hasil refleksi proses, bukan hanya penilaian penonton."},{"type":"text","body":"Rangkuman: Alur dramatik: Rangkaian kejadian yang membangun tindakan dalam pertunjukan; Motivasi tokoh: Alasan yang mendorong tindakan tokoh; Improvisasi: Pengembangan tindakan atau ucapan secara spontan dalam batas kesepakatan; Properti: Benda yang digunakan untuk mendukung tindakan dalam pertunjukan; Kesepakatan bermain: Batas dan aturan yang menjaga permainan peran tetap aman."},{"type":"text","body":"Refleksi: apa yang sudah bisa kamu jelaskan? Bagian mana yang masih membingungkan? Tunjukkan satu contoh baru dan ceritakan alasanmu. Aktivitas praktik perlu diamati pendamping; latihan pilihan ganda hanya memeriksa sebagian pemahaman."}]}'::jsonb) on conflict(id) do nothing;
